'use client'

import Link from 'next/link'
import Image from 'next/image'

import { useCallback, useEffect, useState } from 'react'
import { ArrowLeft, Plus, Trash2, Loader2, AlertCircle, Upload, Images, X } from 'lucide-react'
import AdminShell from '@/components/admin/AdminShell'

interface AlbumItem {
  id: number
  title: string
  description: string | null
  coverUrl: string | null
  mediaCount: number
  date: string | null
}

interface MediaItem {
  id: number
  url: string
  mimeType: string
  size: number
  width: number | null
  height: number | null
  thumbnailUrl?: string | null
  previewUrl?: string | null
}

interface AlbumDetail extends AlbumItem {
  media: MediaItem[]
}

export default function AdminAlbumsPage() {
  const [albums, setAlbums] = useState<AlbumItem[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [creating, setCreating] = useState(false)
  const [title, setTitle] = useState('')
  const [description, setDescription] = useState('')
  const [travelId, setTravelId] = useState<number | ''>('')
  const [travels, setTravels] = useState<{ id: number; title: string }[]>([])

  const [selected, setSelected] = useState<number | null>(null)
  const [detail, setDetail] = useState<AlbumDetail | null>(null)
  const [uploading, setUploading] = useState(false)
  const [uploadError, setUploadError] = useState('')

  const fetchAlbums = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/admin/albums')
      if (res.ok) {
        const data = await res.json()
        setAlbums(data.albums || [])
      }
    } catch {} finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => { fetchAlbums() }, [fetchAlbums])

  // 加载旅行列表（v3.1 M1-A1：相册绑定旅行）
  useEffect(() => {
    fetch('/api/admin/travels')
      .then((r) => r.json())
      .then((j) => setTravels((j.travels || []).map((t: any) => ({ id: t.id, title: t.title }))))
      .catch(() => {})
  }, [])

  const fetchDetail = useCallback(async (id: number) => {
    const res = await fetch(`/api/admin/albums/${id}`)
    if (res.ok) {
      const data = await res.json()
      setDetail(data.album || null)
    }
  }, [])

  useEffect(() => {
    if (selected !== null) fetchDetail(selected)
  }, [selected, fetchDetail])

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    if (!title.trim()) {
      setError('请输入相册名称')
      return
    }
    setCreating(true)
    try {
      const res = await fetch('/api/admin/albums', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: title.trim(), description, travelId: travelId === '' ? undefined : travelId }),
      })
      const data = await res.json().catch(() => ({}))
      if (!res.ok) {
        setError(data.error || '创建失败')
        return
      }
      setTitle(''); setDescription(''); setTravelId('')
      await fetchAlbums()
      setSelected(data.id)
    } catch {
      setError('网络错误')
    } finally {
      setCreating(false)
    }
  }

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!selected || !e.target.files?.length) return
    setUploading(true)
    setUploadError('')
    const fd = new FormData()
    for (const file of Array.from(e.target.files)) fd.append('files', file)
    try {
      const res = await fetch(`/api/admin/albums/${selected}/media`, { method: 'POST', body: fd })
      const data = await res.json().catch(() => ({}))
      if (!res.ok) {
        setUploadError(data.error || '上传失败')
      } else {
        await fetchDetail(selected)
        await fetchAlbums()
      }
    } catch {
      setUploadError('网络错误')
    } finally {
      setUploading(false)
      e.target.value = ''
    }
  }

  const handleRemoveMedia = async (mediaId: number) => {
    if (!selected) return
    const res = await fetch(`/api/admin/albums/${selected}/media`, {
      method: 'DELETE',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ mediaId }),
    })
    if (res.ok) {
      await fetchDetail(selected)
      await fetchAlbums()
    }
  }

  const handleDeleteAlbum = async () => {
    if (!selected || !confirm('确定删除该相册及其全部照片？')) return
    const res = await fetch(`/api/admin/albums/${selected}`, { method: 'DELETE' })
    if (res.ok) {
      setSelected(null)
      setDetail(null)
      await fetchAlbums()
    }
  }

  return (
    <AdminShell title="相册管理">
      <div className="mx-auto max-w-5xl">
        <Link
          href="/admin"
          className="inline-flex items-center gap-1.5 text-sm text-warm-500 dark:text-warm-400 hover:text-travel-accent dark:hover:text-travel-accentSoft transition-colors mb-4"
        >
          <ArrowLeft className="w-4 h-4" />
          返回后台
        </Link>
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-warm-900 dark:text-white mb-1">相册管理</h1>
        <p className="text-sm text-warm-500 dark:text-warm-400">
          创建纪念相册并上传照片（支持批量、自动压缩与元数据清理）
        </p>
      </div>

      <div className="grid lg:grid-cols-2 gap-6">
        {/* 左：相册列表 + 创建 */}
        <div>
          <form onSubmit={handleCreate} className="card p-5 mb-4">
            <h2 className="text-base font-semibold text-warm-900 dark:text-warm-100 mb-3 flex items-center gap-2">
              <Plus className="w-4 h-4 text-travel-accentSoft" />
              新建相册
            </h2>
            <div className="flex gap-2 mb-2">
              <input
                type="text"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder="相册名称"
                className="flex-1 px-3 py-2 border border-warm-300 dark:border-warm-600 rounded-lg bg-white dark:bg-warm-800 text-warm-900 dark:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-travel-accentSoft"
              />
              <button
                type="submit"
                disabled={creating}
                className="px-4 py-2 bg-travel-accent hover:bg-travel-accentStrong disabled:opacity-50 text-white rounded-lg text-sm transition-colors"
              >
                {creating ? '创建中...' : '创建'}
              </button>
            </div>
            <input
              type="text"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="简介（可选）"
              className="w-full px-3 py-2 border border-warm-300 dark:border-warm-600 rounded-lg bg-white dark:bg-warm-800 text-warm-900 dark:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-travel-accentSoft"
            />
            <select
              value={travelId}
              onChange={(e) => setTravelId(e.target.value === '' ? '' : Number(e.target.value))}
              className="w-full mt-2 px-3 py-2 border border-warm-300 dark:border-warm-600 rounded-lg bg-white dark:bg-warm-800 text-warm-900 dark:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-travel-accentSoft"
            >
              <option value="">关联旅行（可选）</option>
              {travels.map((t) => (
                <option key={t.id} value={t.id}>{t.title}</option>
              ))}
            </select>
            {error && (
              <p className="flex items-center gap-1 mt-2 text-xs text-red-500">
                <AlertCircle className="w-3.5 h-3.5" /> {error}
              </p>
            )}
          </form>

          {loading ? (
            <div className="text-center py-10 text-warm-500">加载中...</div>
          ) : albums.length === 0 ? (
            <div className="card p-6 text-center text-warm-500">还没有相册</div>
          ) : (
            <div className="space-y-2">
              {albums.map((a) => (
                <button
                  key={a.id}
                  type="button"
                  onClick={() => setSelected(a.id)}
                  className={`w-full flex items-center gap-3 p-3 rounded-xl text-left transition-colors ${
                    selected === a.id
                      ? 'bg-travel-sakura/50 dark:bg-travel-accent/20 border border-travel-sakura dark:border-travel-accent/40'
                      : 'bg-white dark:bg-warm-800 border border-warm-200 dark:border-warm-700 hover:border-travel-sakura'
                  }`}
                >
                  <div className="relative w-12 h-12 rounded-lg overflow-hidden bg-warm-100 dark:bg-warm-700 flex-shrink-0">
                    {a.coverUrl ? (
                      // eslint-disable-next-line @next/next/no-img-element
                      <Image src={a.coverUrl} alt={a.title} fill sizes="48px" className="object-cover" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-warm-400">
                        <Images className="w-5 h-5" />
                      </div>
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="font-medium text-warm-900 dark:text-warm-100 truncate">{a.title}</p>
                    <p className="text-xs text-warm-500">{a.mediaCount} 张照片</p>
                  </div>
                </button>
              ))}
            </div>
          )}
        </div>

        {/* 右：相册详情 */}
        <div className="card p-5">
          {!selected || !detail ? (
            <div className="text-center py-16 text-warm-500">选择一个相册查看与管理照片</div>
          ) : (
            <>
              <div className="flex items-start justify-between mb-4">
                <div>
                  <h2 className="text-lg font-semibold text-warm-900 dark:text-warm-100">{detail.title}</h2>
                  {detail.description && (
                    <p className="text-sm text-warm-500">{detail.description}</p>
                  )}
                  <p className="text-xs text-warm-400 mt-1">{detail.mediaCount} 张照片</p>
                </div>
                <button
                  type="button"
                  onClick={handleDeleteAlbum}
                  className="inline-flex items-center gap-1 px-3 py-1.5 text-sm text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                >
                  <Trash2 className="w-4 h-4" />
                  删除相册
                </button>
              </div>

              <label className="flex items-center justify-center gap-2 px-4 py-3 border-2 border-dashed border-warm-300 dark:border-warm-600 rounded-xl text-sm text-warm-500 hover:border-travel-accentSoft cursor-pointer mb-4">
                <Upload className="w-4 h-4" />
                {uploading ? '上传中...' : '点击上传照片（支持多选）'}
                <input type="file" accept="image/jpeg,image/png,image/webp" multiple className="hidden" onChange={handleUpload} disabled={uploading} />
              </label>
              {uploadError && (
                <p className="text-xs text-red-500 mb-3">{uploadError}</p>
              )}

              {detail.media.length === 0 ? (
                <div className="text-center py-10 text-warm-400">还没有照片，上传第一张吧</div>
              ) : (
                <div className="grid grid-cols-3 gap-2">
                  {detail.media.map((m) => (
                    <div key={m.id} className="relative group aspect-square rounded-lg overflow-hidden">
                      {/* eslint-disable-next-line @next/next/no-img-element */}
                      <Image src={m.thumbnailUrl ?? m.url} alt="" fill sizes="100vw" className="object-cover" />
                      <button
                        type="button"
                        onClick={() => handleRemoveMedia(m.id)}
                        className="absolute top-1 right-1 p-1 bg-black/60 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                      >
                        <X className="w-3 h-3" />
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </>
          )}
        </div>
      </div>
      </div>
    </AdminShell>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { Lock, Eye, EyeOff, AlertTriangle, CheckCircle } from 'lucide-react'

/**
 * 首登强制改密页（P0-2 迁移）。
 *
 * 旧实现调用已删除的管理员强改密端点 —— 该端点「只校验登录、不校验旧密码」，
 * 任意登录用户（包括新注册用户、甚至相册令牌）都能改掉 id 最小用户（站长）的密码，
 * 是账号接管链的一环，已整体删除。
 * 现在改走 /api/admin/settings/password：要求「当前密码 + 新密码」，
 * 且 siteService 严格按当前登录用户名定位（P0-3），只可能改到自己。
 */
export default function ForceChangePasswordPage() {
  const router = useRouter()
  const [currentPassword, setCurrentPassword] = useState('')
  const [newPassword, setNewPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const [showPassword, setShowPassword] = useState(false)
  const [success, setSuccess] = useState(false)

  useEffect(() => {
    checkAuth()
  }, [])

  const checkAuth = async () => {
    try {
      const res = await fetch('/api/admin/check')
      if (!res.ok) {
        router.push('/admin/login')
        return
      }
      const data = await res.json()
      if (!data.authenticated) {
        router.push('/admin/login')
      }
    } catch {
      router.push('/admin/login')
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')

    if (!currentPassword) {
      setError('请输入当前密码')
      return
    }
    if (newPassword.length < 8) {
      setError('新密码至少 8 位')
      return
    }
    if (newPassword !== confirmPassword) {
      setError('两次输入的密码不一致')
      return
    }
    setLoading(true)
    try {
      const res = await fetch('/api/admin/settings/password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ currentPassword, newPassword }),
      })

      if (res.ok) {
        setSuccess(true)
        setTimeout(() => {
          router.push('/admin')
        }, 1500)
      } else {
        const data = await res.json().catch(() => ({}))
        setError(data.error || '修改失败')
      }
    } catch {
      setError('网络错误，请重试')
    } finally {
      setLoading(false)
    }
  }

  if (success) {
    return (
      <div className="min-h-dvh flex items-center justify-center bg-travel-cream dark:bg-shell-bg">
        <div className="absolute inset-0 overflow-hidden">
          <div className="absolute -top-40 -right-40 w-80 h-80 bg-primary-500/20 rounded-full blur-3xl" />
          <div className="absolute -bottom-40 -left-40 w-80 h-80 bg-purple-500/20 rounded-full blur-3xl" />
        </div>
        <div className="relative z-10 w-full max-w-md mx-4">
          <div className="rounded-3xl border border-white/70 bg-white/85 p-8 shadow-[0_30px_80px_rgba(90,102,112,0.25)] backdrop-blur-2xl dark:border-white/10 dark:bg-shell-bg/90 text-center">
            <div className="w-16 h-16 rounded-2xl bg-emerald-100 dark:bg-emerald-500/15 flex items-center justify-center mx-auto mb-4">
              <CheckCircle className="w-8 h-8 text-emerald-500" />
            </div>
            <h1 className="text-2xl font-bold text-[#2D3842] dark:text-shell-text mb-2">密码修改成功</h1>
            <p className="text-sm text-travel-ink/80 dark:text-shell-muted">正在跳转到管理后台...</p>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-dvh flex items-center justify-center bg-travel-cream dark:bg-shell-bg">
      <div className="absolute inset-0 overflow-hidden">
        <div className="absolute -top-40 -right-40 w-80 h-80 bg-primary-500/20 rounded-full blur-3xl" />
        <div className="absolute -bottom-40 -left-40 w-80 h-80 bg-purple-500/20 rounded-full blur-3xl" />
      </div>

      <div className="relative z-10 w-full max-w-md mx-4">
        <div className="rounded-3xl border border-white/70 bg-white/85 p-8 shadow-[0_30px_80px_rgba(90,102,112,0.25)] backdrop-blur-2xl dark:border-white/10 dark:bg-shell-bg/90">
          <div className="text-center mb-8">
            <div className="w-16 h-16 rounded-2xl bg-amber-100 dark:bg-amber-500/15 flex items-center justify-center mx-auto mb-4">
              <AlertTriangle className="w-8 h-8 text-amber-500" />
            </div>
            <h1 className="text-2xl font-bold text-[#2D3842] dark:text-shell-text">首次登录请修改密码</h1>
            <p className="text-sm text-travel-ink/80 dark:text-shell-muted mt-2">
              您正在使用初始密码，请设置一个新密码以确保账户安全
            </p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            <div>
              <label className="block mb-2 block text-sm font-medium text-travel-ink dark:text-shell-muted">当前密码</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-[#9A958F]" />
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={currentPassword}
                  onChange={(e) => setCurrentPassword(e.target.value)}
                  className="w-full rounded-xl border border-travel-line bg-white/70 py-3 pl-11 pr-4 text-travel-ink transition-all placeholder-[#9A958F] focus-visible:border-transparent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-travel-accentSoft/50 dark:border-shell-line dark:bg-shell-surface2/80 dark:text-shell-text dark:placeholder-[#6E6A64]"
                  placeholder="请输入当前密码"
                  autoComplete="current-password"
                  required
                />
              </div>
            </div>

            <div>
              <label className="block mb-2 block text-sm font-medium text-travel-ink dark:text-shell-muted">新密码</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-[#9A958F]" />
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  className="w-full rounded-xl border border-travel-line bg-white/70 py-3 pl-11 pr-12 text-travel-ink transition-all placeholder-[#9A958F] focus-visible:border-transparent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-travel-accentSoft/50 dark:border-shell-line dark:bg-shell-surface2/80 dark:text-shell-text dark:placeholder-[#6E6A64]"
                  placeholder="至少 8 位"
                  autoComplete="new-password"
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-[#9A958F] transition-colors hover:text-travel-accent"
                >
                  {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
              </div>
            </div>

            <div>
              <label className="block mb-2 block text-sm font-medium text-travel-ink dark:text-shell-muted">确认新密码</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-[#9A958F]" />
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  className="w-full rounded-xl border border-travel-line bg-white/70 py-3 pl-11 pr-4 text-travel-ink transition-all placeholder-[#9A958F] focus-visible:border-transparent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-travel-accentSoft/50 dark:border-shell-line dark:bg-shell-surface2/80 dark:text-shell-text dark:placeholder-[#6E6A64]"
                  placeholder="再次输入新密码"
                  autoComplete="new-password"
                  required
                />
              </div>
            </div>

            {error && (
              <div className="rounded-xl border border-travel-bloom/50 bg-travel-sakura/40 px-4 py-3 text-sm text-travel-accent dark:border-shell-line dark:bg-shell-surface/70 dark:text-travel-bloom">
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full py-3 rounded-xl bg-gradient-to-r from-travel-accent to-travel-accentSoft py-3 font-semibold text-white shadow-lg shadow-travel-accent/25 transition-all hover:shadow-xl active:scale-[0.98] disabled:opacity-60"
            >
              {loading ? '修改中...' : '确认修改并进入后台'}
            </button>
          </form>
        </div>

        <p className="text-center mt-6 text-center text-xs text-[#9A958F] dark:text-shell-faint">
          为了您的账户安全，初始密码首次登录必须修改
        </p>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter, useParams } from 'next/navigation'
import { XCircle, Video } from 'lucide-react'
import TravelPreviewModal from '@/components/TravelPreviewModal'
import PostEditorHeader from '@/components/admin/editor/PostEditorHeader'
import PostTitleInput from '@/components/admin/editor/PostTitleInput'
import PostMetaPanel from '@/components/admin/editor/PostMetaPanel'
import ImageUploader from '@/components/admin/editor/ImageUploader'
import VideoUploader, { VideoItem } from '@/components/admin/editor/VideoUploader'
import MarkdownEditor from '@/components/admin/editor/MarkdownEditor'
import DocumentImporter, { ImportedDocument } from '@/components/admin/editor/DocumentImporter'
import { usePostForm, PostFormData } from '@/components/admin/editor/hooks/usePostForm'
import AdminShell from '@/components/admin/AdminShell'

type TabMode = 'manual' | 'import'

export default function AdminEditPage() {
  const router = useRouter()
  const params = useParams()
  const idParam = Array.isArray(params.id) ? params.id[0] : params.id
  const isNew = !idParam || idParam === 'new'

  const { formData, setFormData, setField } = usePostForm()

  const [tabMode, setTabMode] = useState<TabMode>('manual')
  const [preview, setPreview] = useState(false)
  const [videoPreview, setVideoPreview] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    if (!isNew) {
      fetchPost()
    }
  }, [isNew])

  // Cmd/Ctrl + S 快捷保存
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 's') {
        e.preventDefault()
        if (loading) return
        const form = document.getElementById('post-form') as HTMLFormElement | null
        if (form) {
          form.requestSubmit()
        }
      }
    }
    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [loading])

  const fetchPost = async () => {
    try {
      const res = await fetch(`/api/admin/posts/${idParam}`)
      if (res.ok) {
        const data = await res.json()
        const post = data.data?.post
        const videosData: VideoItem[] = Array.isArray(post.videos)
          ? post.videos.map((v: any) => {
              if (typeof v === 'string') return { url: v }
              return { url: v.url, thumbnail: v.thumbnail, duration: v.duration }
            })
          : []

        setFormData({
          title: post.title,
          slug: post.slug,
          content: post.content,
          date: new Date(post.date).toISOString().split('T')[0],
          cover: post.cover || '',
          images: post.images || [],
          videos: videosData,
          tags: post.tags
            ? Array.isArray(post.tags)
              ? post.tags.join(', ')
              : JSON.parse(post.tags).join(', ')
            : '',
          location: post.location || '',
          type: post.type,
          summary: post.summary || '',
          published: post.published,
          isPublic: post.isPublic ?? false,
        })
      }
    } catch {
      console.error('Failed to fetch post')
    }
  }

  const generateSlugFromTitle = (title: string): string => {
    const timestamp = Date.now().toString(36)
    const englishPart = title
      .toLowerCase()
      .replace(/[\u4e00-\u9fa5]/g, ' ')
      .replace(/[^\w\s-]/g, '')
      .trim()
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .replace(/^-+|-+$/g, '')

    if (englishPart && englishPart.length >= 2) {
      return `${englishPart}-${timestamp}`
    }
    return `post-${timestamp}`
  }

  const generateSlug = () => {
    const slug = generateSlugFromTitle(formData.title)
    setField('slug', slug)
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)

    const tagsArray = formData.tags
      .split(',')
      .map((t) => t.trim())
      .filter(Boolean)

    const finalSlug = formData.slug || generateSlugFromTitle(formData.title)

    const payload = {
      title: formData.title,
      slug: finalSlug,
      content: formData.content,
      cover: formData.cover,
      images: formData.images,
      videos: formData.videos,
      tags: tagsArray,
      location: formData.location,
      type: formData.type,
      summary: formData.summary,
      published: formData.published,
      isPublic: formData.isPublic,
      date: new Date(formData.date),
    }

    try {
      let res: Response
      if (isNew) {
        res = await fetch('/api/admin/posts', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        })
      } else {
        res = await fetch(`/api/admin/posts/${idParam}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        })
      }

      if (!res.ok) {
        const err = await res.json().catch(() => ({}))
        throw new Error(err.error || `保存失败 (HTTP ${res.status})`)
      }

      router.push('/admin')
      router.refresh()
    } catch (error: any) {
      alert(error.message || '保存失败')
    } finally {
      setLoading(false)
    }
  }

  const handleImageUploaded = (urls: string[]) => {
    setFormData((prev) => ({
      ...prev,
      images: [...prev.images, ...urls],
      cover: prev.cover || urls[0] || '',
    }))
  }

  const handleImageRemoved = (index: number) => {
    const imageUrl = formData.images[index]
    const newImages = formData.images.filter((_, i) => i !== index)

    setFormData((prev) => ({
      ...prev,
      images: newImages,
      cover: prev.cover === imageUrl ? newImages[0] || '' : prev.cover,
    }))

    if (imageUrl.startsWith('/api/images/')) {
      fetch('/api/upload', {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: imageUrl }),
      }).catch(() => {})
    }
  }

  const handleSetCover = (index: number) => {
    setField('cover', formData.images[index] || '')
  }

  const handleVideoUploaded = (videos: VideoItem[]) => {
    setFormData((prev) => ({
      ...prev,
      videos: [...prev.videos, ...videos],
    }))
  }

  const handleVideoRemoved = (index: number) => {
    const video = formData.videos[index]
    const newVideos = formData.videos.filter((_, i) => i !== index)

    setFormData((prev) => ({ ...prev, videos: newVideos }))

    if (video && video.url.startsWith('/uploads/videos/')) {
      fetch('/api/admin/videos/upload', {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: video.url }),
      }).catch(() => {})
    }
  }

  const handleImported = (doc: ImportedDocument) => {
    const patch: Partial<PostFormData> = {
      title: doc.title,
      slug: doc.slug,
      content: doc.content,
      date: doc.date || formData.date,
      summary: doc.description || '',
      cover: doc.cover || '',
      tags: Array.isArray(doc.tags) ? doc.tags.join(', ') : '',
    }
    setFormData((prev) => ({ ...prev, ...patch }))
    setTabMode('manual')
  }

  return (
    <AdminShell title={isNew ? '新建文章' : '编辑文章'}>
      <PostEditorHeader
        isNew={isNew}
        onPreview={() => setPreview(true)}
        loading={loading}
      />

      <main className="mx-auto max-w-7xl">
        <div className="mb-6 flex gap-2">
          <button
            type="button"
            onClick={() => setTabMode('manual')}
            className={`px-5 py-2 rounded-xl text-sm font-medium transition-all ${
              tabMode === 'manual'
                ? 'bg-gradient-to-r from-travel-accent to-travel-accentSoft text-white shadow-md shadow-travel-accent/25'
                : 'border border-white/70 bg-white/80 text-travel-ink shadow-sm backdrop-blur-xl hover:text-travel-accent dark:border-white/10 dark:bg-white/5 dark:text-warm-300'
            }`}
          >
            手动编辑
          </button>
          <button
            type="button"
            onClick={() => setTabMode('import')}
            className={`px-5 py-2 rounded-xl text-sm font-medium transition-all ${
              tabMode === 'import'
                ? 'bg-gradient-to-r from-travel-accent to-travel-accentSoft text-white shadow-md shadow-travel-accent/25'
                : 'border border-white/70 bg-white/80 text-travel-ink shadow-sm backdrop-blur-xl hover:text-travel-accent dark:border-white/10 dark:bg-white/5 dark:text-warm-300'
            }`}
          >
            文档导入发布
          </button>
        </div>

        {tabMode === 'manual' ? (
          <form id="post-form" onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-6">
              <PostTitleInput
                title={formData.title}
                slug={formData.slug}
                date={formData.date}
                onChange={(field, value) => setField(field as keyof PostFormData, value)}
                onGenerateSlug={generateSlug}
              />

              <MarkdownEditor
                content={formData.content}
                onChange={(value) => setField('content', value)}
              />

              {formData.type === 'travel' && (
                <>
                  <ImageUploader
                    images={formData.images}
                    postId={!isNew && idParam ? idParam : undefined}
                    onUploaded={handleImageUploaded}
                    onRemoved={handleImageRemoved}
                    onReordered={(imgs) => setField('images', imgs)}
                    onSetCover={handleSetCover}
                    cover={formData.cover}
                  />
                  <VideoUploader
                    videos={formData.videos}
                    onUploaded={handleVideoUploaded}
                    onRemoved={handleVideoRemoved}
                    onReordered={(vids) => setField('videos', vids)}
                  />
                </>
              )}
            </div>

            <div className="space-y-6">
              <PostMetaPanel
                type={formData.type}
                tags={formData.tags}
                location={formData.location}
                cover={formData.cover}
                summary={formData.summary}
                published={formData.published}
                isPublic={formData.isPublic}
                imagesCount={formData.images.length}
                videosCount={formData.videos.length}
                onChange={(field, value) => setField(field as keyof PostFormData, value)}
              />
            </div>
          </form>
        ) : (
          <DocumentImporter onImported={handleImported} />
        )}
      </main>

      <TravelPreviewModal
        isOpen={preview}
        onClose={() => setPreview(false)}
        formData={formData}
      />

      {videoPreview && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm"
          onClick={() => setVideoPreview(null)}
        >
          <button
            type="button"
            onClick={() => setVideoPreview(null)}
            className="absolute top-4 right-4 p-2 text-white hover:bg-white/20 rounded-full transition-colors"
          >
            <XCircle className="w-8 h-8" />
          </button>
          <video
            src={videoPreview}
            className="max-w-[90vw] max-h-[90vh] rounded-lg shadow-2xl"
            controls
            autoPlay
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
    </AdminShell>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { Sparkles, Trash2, Send, Loader2, Inbox } from 'lucide-react'
import AdminShell from '@/components/admin/AdminShell'
import { AdminInput, AdminTextarea, AdminButton, AdminCard } from '@/components/admin/ui'

interface MomentItem {
  id: number
  content: string
  tags: string[] | null
  createdAt: string
}

interface MomentsResponse {
  data?: {
    data?: MomentItem[]
    total?: number
    hasMore?: boolean
  }
}

function formatTime(iso: string): string {
  const d = new Date(iso)
  const pad = (n: number) => String(n).padStart(2, '0')
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`
}

export default function AdminMomentsPage() {
  const router = useRouter()
  const [moments, setMoments] = useState<MomentItem[]>([])
  const [content, setContent] = useState('')
  const [tagsInput, setTagsInput] = useState('')
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [deletingId, setDeletingId] = useState<number | null>(null)
  const [total, setTotal] = useState(0)
  const [message, setMessage] = useState<{ type: 'ok' | 'err'; text: string } | null>(null)

  const fetchMoments = useCallback(async () => {
    try {
      const res = await fetch('/api/admin/moments?page=1&pageSize=100')
      if (res.status === 401) {
        router.push('/admin/login')
        return
      }
      if (res.ok) {
        const json: MomentsResponse = await res.json()
        setMoments(json.data?.data || [])
        setTotal(json.data?.total || 0)
      }
    } catch {}
    setLoading(false)
  }, [router])

  useEffect(() => {
    fetchMoments()
  }, [fetchMoments])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!content.trim()) return
    setSubmitting(true)
    setMessage(null)
    try {
      const tags = tagsInput
        .split(',')
        .map((t) => t.trim())
        .filter(Boolean)
      const res = await fetch('/api/admin/moments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ content, tags }),
      })
      const json = await res.json()
      if (!res.ok) {
        setMessage({ type: 'err', text: json.error || '发布失败' })
        return
      }
      setContent('')
      setTagsInput('')
      setMessage({ type: 'ok', text: '发布成功' })
      fetchMoments()
    } catch {
      setMessage({ type: 'err', text: '发布失败，请重试' })
    } finally {
      setSubmitting(false)
    }
  }

  const handleDelete = async (id: number) => {
    if (!window.confirm('确定删除这条碎碎念吗？')) return
    setDeletingId(id)
    try {
      const res = await fetch(`/api/admin/moments/${id}`, { method: 'DELETE' })
      if (res.ok) {
        fetchMoments()
      } else {
        setMessage({ type: 'err', text: '删除失败' })
      }
    } catch {
      setMessage({ type: 'err', text: '删除失败' })
    } finally {
      setDeletingId(null)
    }
  }

  return (
    <AdminShell title="碎碎念管理">


      <main className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {message && (
          <div className={`mb-6 px-4 py-3 rounded-lg text-sm ${message.type === 'ok' ? 'bg-green-50 dark:bg-green-900/20 text-green-600 dark:text-green-400' : 'bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400'}`}>
            {message.text}
          </div>
        )}

        <form onSubmit={handleSubmit} className="mb-8">
          <AdminCard title="发布一条碎碎念" icon={Sparkles}>
            <AdminTextarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              rows={4}
              maxLength={2000}
              placeholder="记录此刻的想法、灵感或小确幸..."
            />
            <div className="mt-3 flex items-center justify-between gap-3 flex-wrap">
              <AdminInput
                type="text"
                value={tagsInput}
                onChange={(e) => setTagsInput(e.target.value)}
                placeholder="标签（用逗号分隔，可选）"
                className="flex-1 min-w-[180px]"
              />
              <AdminButton
                type="submit"
                disabled={submitting || !content.trim()}
              >
                {submitting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
                发布
              </AdminButton>
            </div>
            <p className="mt-2 text-xs text-travel-ink/50 dark:text-warm-400">{content.length}/2000</p>
          </AdminCard>
        </form>

        <div className="mb-4 text-sm text-travel-ink/60 dark:text-warm-400">
          共 {total} 条碎碎念
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-16 text-travel-ink/50 dark:text-warm-500">
            <Loader2 className="h-6 w-6 animate-spin" />
            加载中...
          </div>
        ) : moments.length === 0 ? (
          <div className="rounded-2xl border-2 border-dashed border-travel-bloom/50 bg-white/50 p-14 text-center dark:border-shell-line dark:bg-white/5">
            <Inbox className="mx-auto mb-4 h-12 w-12 opacity-30 text-travel-accentSoft" />
            <p className="text-travel-ink/80 dark:text-warm-400">还没有碎碎念，发布第一条吧~</p>
          </div>
        ) : (
          <div className="space-y-3">
            {moments.map((moment) => (
              <div key={moment.id} className="rounded-2xl border border-travel-line/50 bg-white/80 p-5 shadow-soft dark:border-shell-line dark:bg-shell-bg/80 flex items-start gap-4">
                <div className="flex-1 min-w-0">
                  <p className="text-travel-ink dark:text-warm-200 text-sm leading-relaxed whitespace-pre-wrap break-words">
                    {moment.content}
                  </p>
                  <div className="flex items-center gap-2 mt-3 flex-wrap">
                    <span className="text-xs text-travel-ink/50 dark:text-warm-400">{formatTime(moment.createdAt)}</span>
                    {moment.tags && moment.tags.length > 0 && (
                      <span className="flex gap-1.5 flex-wrap">
                        {moment.tags.map((tag) => (
                          <span key={tag} className="text-xs px-2 py-0.5 rounded-full bg-travel-sakura/50 dark:bg-travel-accent/15 text-travel-accent dark:text-travel-accentSoft">
                            #{tag}
                          </span>
                        ))}
                      </span>
                    )}
                  </div>
                </div>
                <button
                  type="button"
                  onClick={() => handleDelete(moment.id)}
                  disabled={deletingId === moment.id}
                  className="p-2 rounded-lg text-travel-ink/50 hover:text-travel-danger hover:bg-travel-danger/10 transition-colors disabled:opacity-50"
                  title="删除"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            ))}
          </div>
        )}
      </main>
    </AdminShell>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import Image from 'next/image'
import { motion } from 'motion/react'
import {
  Plus, Edit2, Trash2, MapPin, Search, Filter, Eye, Calendar, Tag,
  Globe2, Lock, Loader2, X, FileText, Sparkles, ExternalLink,
} from 'lucide-react'
import AdminShell from '@/components/admin/AdminShell'
import { Modal } from '@/components/ui/Modal'
import { Select } from '@/components/ui/Select'

interface Post {
  id: number
  slug: string
  title: string
  date: string
  summary: string | null
  cover: string | null
  images: string[] | null
  tags: string[] | null
  location: string | null
  type: string
  published: boolean
  isPublic?: boolean
  circleShared?: boolean
  createdAt: string
}

const typeLabels: Record<string, string> = { travel: '旅行记录' }
const typeIconBg: Record<string, string> = {
  travel: 'from-travel-accentSoft to-pink-400',
}

const listVariants = {
  hidden: {},
  show: { transition: { staggerChildren: 0.06 } },
}

const cardVariants = {
