export default function AdminDashboard() {
  const router = useRouter()
  const [posts, setPosts] = useState<Post[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [filterType, setFilterType] = useState<string>('')
  const [deleteId, setDeleteId] = useState<number | null>(null)
  const [togglingId, setTogglingId] = useState<number | null>(null)
  const [deleting, setDeleting] = useState(false)
  // 内容管理 2.0：旅行圈分享（解耦于文章可见性）
  const [sharePost, setSharePost] = useState<Post | null>(null)
  const [shareTravelId, setShareTravelId] = useState<number | null>(null)
  const [shareScope, setShareScope] = useState<'PUBLIC' | 'SPACE'>('PUBLIC')
  const [shareError, setShareError] = useState('')
  const [sharing, setSharing] = useState<number | null>(null)
  const [travels, setTravels] = useState<Array<{ id: number; title: string }>>([])

  useEffect(() => {
    checkAuth()
    fetchPosts()
    fetchTravels()
  }, [])

  const checkAuth = async () => {
    try {
      const res = await fetch('/api/admin/check')
      const data = await res.json()
      if (!res.ok || !data.authenticated) router.push('/admin/login')
    } catch {
      router.push('/admin/login')
    }
  }

  const fetchPosts = async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/admin/posts')
      const data = await res.json()
      setPosts(data.data?.posts || [])
    } catch {
      console.error('Failed to fetch posts')
    } finally {
      setLoading(false)
    }
  }

  const fetchTravels = async () => {
    try {
      const res = await fetch('/api/admin/travels')
      const data = await res.json()
      setTravels(data.travels || [])
    } catch {
      setTravels([])
    }
  }

  const handleDelete = async () => {
    if (!deleteId) return
    setDeleting(true)
    try {
      await fetch(`/api/admin/posts/${deleteId}`, { method: 'DELETE' })
      setDeleteId(null)
      fetchPosts()
    } catch {
      console.error('Failed to delete post')
    } finally {
      setDeleting(false)
    }
  }

  const togglePublic = async (post: Post) => {
    setTogglingId(post.id)
    try {
      const res = await fetch(`/api/admin/posts/${post.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ isPublic: !post.isPublic }),
      })
      if (res.ok) {
        // 服务端已确认写入 isPublic，就地更新该卡片（避免整页网格闪骨架屏）
        setPosts((prev) => prev.map((p) => (p.id === post.id ? { ...p, isPublic: !post.isPublic } : p)))
      }
    } catch {
      console.error('Failed to toggle public')
    } finally {
      setTogglingId(null)
    }
  }

  // ---- 内容管理 2.0：旅行圈分享 ----
  const openShare = (post: Post) => {
    setSharePost(post)
    setShareTravelId(null)
    setShareScope('PUBLIC')
    setShareError('')
  }
  const closeShare = () => {
    setSharePost(null)
    setShareError('')
  }
  const confirmShare = async () => {
    if (!sharePost) return
    setSharing(sharePost.id)
    setShareError('')
    try {
      const res = await fetch(`/api/admin/posts/${sharePost.id}/share`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ travelId: shareTravelId, visibility: shareScope }),
      })
      if (res.ok) {
        closeShare()
        await fetchPosts()
      } else {
        const j = await res.json().catch(() => ({}))
        setShareError(j?.error || '分享失败，请重试')
      }
    } catch {
      setShareError('网络错误，请重试')
    } finally {
      setSharing(null)
    }
  }
  const confirmUnshare = async () => {
    if (!sharePost) return
    setSharing(sharePost.id)
    setShareError('')
    try {
      const res = await fetch(`/api/admin/posts/${sharePost.id}/share`, { method: 'DELETE' })
      if (res.ok) {
        closeShare()
        await fetchPosts()
      } else {
        const j = await res.json().catch(() => ({}))
        setShareError(j?.error || '取消分享失败，请重试')
      }
    } catch {
      setShareError('网络错误，请重试')
    } finally {
      setSharing(null)
    }
  }

  const filteredPosts = posts.filter((post) => {
    const q = searchQuery.toLowerCase()
    const matchesSearch =
      post.title.toLowerCase().includes(q) || (post.summary || '').toLowerCase().includes(q)
    const matchesType = !filterType || post.type === filterType
    return matchesSearch && matchesType
  })

  const glassInput =
    'w-full rounded-xl border border-white/70 bg-white/75 dark:border-white/10 dark:bg-white/5 px-4 py-2.5 text-sm text-travel-ink dark:text-shell-text placeholder-warm-400 shadow-sm backdrop-blur-xl transition-all focus-visible:border-transparent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-travel-accentSoft/50'

  return (
    <AdminShell title="文章管理">
      {/* 页头 */}
      <div className="mb-8 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <div className="inline-flex items-center gap-2 rounded-full bg-travel-sakura/70 px-3 py-1 text-xs font-medium text-travel-accent dark:bg-shell-surface/70 dark:text-travel-bloom">
            <Sparkles className="h-3 w-3" />
            甜途内容中心
          </div>
          <h1 className="mt-3 text-2xl font-bold text-warm-800 dark:text-shell-text sm:text-3xl">文章管理</h1>
          <p className="mt-1 text-sm text-travel-ink/80 dark:text-shell-muted">共 {posts.length} 篇文章，像明信片一样整理你们的回忆</p>
        </div>
        <Link
          href="/admin/new"
          className="inline-flex items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-travel-accent to-travel-accentSoft px-5 py-2.5 text-sm font-semibold text-white shadow-lg shadow-travel-accent/25 transition-all hover:shadow-xl hover:-translate-y-0.5 active:scale-95"
        >
          <Plus className="h-4 w-4" />
          新建文章
        </Link>
      </div>

      {/* 工具栏 */}
      <div className="mb-8 flex flex-col gap-3 sm:flex-row">
        <div className="relative flex-1 sm:max-w-md">
          <Search className="absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-warm-400" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="搜索标题或摘要..."
            className={`${glassInput} pl-10`}
          />
        </div>
        <div className="relative">
          <Filter className="absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-warm-400" />
          <select
            value={filterType}
            onChange={(e) => setFilterType(e.target.value)}
            className={`${glassInput} appearance-none pl-10 pr-10`}
          >
            <option value="">全部分类</option>
            <option value="travel">旅行记录</option>
          </select>
        </div>
      </div>

      {/* 瀑布流卡片 */}
      {loading ? (
        <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 xl:grid-cols-3">
          {Array.from({ length: 6 }).map((_, i) => (
            <div key={i} className="h-72 animate-pulse rounded-3xl bg-white/60 dark:bg-white/5" />
          ))}
        </div>
      ) : filteredPosts.length === 0 ? (
        <div className="rounded-3xl border-2 border-dashed border-travel-bloom/50 bg-white/50 p-14 text-center dark:border-shell-line dark:bg-white/5">
          <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-2xl bg-gradient-to-br from-travel-sakura to-travel-bloom/60 dark:from-warm-800 dark:to-warm-700">
            <FileText className="h-8 w-8 text-travel-accent dark:text-travel-bloom" />
          </div>
          <h3 className="text-lg font-semibold text-travel-ink dark:text-shell-text">
            {posts.length === 0 ? '还没有文章' : '没有匹配的文章'}
          </h3>
          <p className="mt-1 text-sm text-travel-ink/80 dark:text-shell-muted">
            {posts.length === 0 ? '从第一篇游记开始，收藏你们的旅程' : '换个关键词试试吧'}
          </p>
          {posts.length === 0 && (
            <Link
              href="/admin/new"
              className="mt-5 inline-flex items-center gap-2 rounded-xl bg-gradient-to-r from-travel-accent to-travel-accentSoft px-5 py-2.5 text-sm font-medium text-white shadow-lg shadow-travel-accent/25 transition-all hover:-translate-y-0.5 active:scale-95"
            >
              <Plus className="h-4 w-4" />
              新建文章
            </Link>
          )}
        </div>
      ) : (
        <motion.div
          variants={listVariants}
          initial="hidden"
          animate="show"
          className="columns-1 gap-5 sm:columns-2 xl:columns-3"
        >
          {filteredPosts.map((post) => {
            const Icon = typeIconBg[post.type]
              ? null
              : MapPin
            return (
              <motion.article
                key={post.id}
                variants={cardVariants}
                className="group mb-5 break-inside-avoid overflow-hidden rounded-3xl border border-white/70 bg-white/85 shadow-[0_12px_40px_-12px_rgba(90,102,112,0.18)] backdrop-blur-xl transition-all duration-300 hover:-translate-y-1.5 hover:shadow-[0_24px_60px_-16px_rgba(167,78,97,0.35)] dark:border-white/10 dark:bg-shell-bg/90"
              >
                {/* 封面 */}
                <Link href={`/${post.type}/${post.slug}`} target="_blank" className="relative block aspect-video w-full overflow-hidden bg-gradient-to-br from-travel-sakura via-travel-bloom/30 to-travel-sakura dark:from-warm-800 dark:via-warm-700 dark:to-warm-900">
                  {post.cover ? (
                    <Image
                      src={post.cover}
                      alt={post.title}
                      fill
                      sizes="(max-width: 640px) 100vw, 33vw"
                      className="object-cover transition-transform duration-500 group-hover:scale-105"
                      onError={(e) => {
                        const t = e.target as HTMLImageElement
                        t.style.display = 'none'
                      }}
                    />
                  ) : (
                    <div className="flex h-full w-full items-center justify-center">
                      {Icon && <Icon className="h-10 w-10 text-travel-accent/40 dark:text-travel-bloom/30" />}
                    </div>
                  )}
                  {/* 类型角标 */}
                  <span className="absolute left-3 top-3 inline-flex items-center gap-1 rounded-full bg-black/35 px-2.5 py-1 text-xs font-medium text-white backdrop-blur">
                    {typeLabels[post.type] || post.type}
                  </span>
                  {/* 悬停查看 */}
                  <span className="absolute inset-0 flex items-center justify-center bg-black/0 opacity-0 transition-all duration-300 group-hover:bg-black/25 group-hover:opacity-100">
                    <span className="inline-flex items-center gap-1.5 rounded-full bg-white/90 px-4 py-2 text-xs font-medium text-travel-ink shadow-lg">
                      <Eye className="h-3.5 w-3.5" />
                      查看游记
                    </span>
                  </span>
                </Link>

                {/* 内容 */}
                <div className="p-5">
                  <Link href={`/${post.type}/${post.slug}`} target="_blank" className="block">
                    <h3 className="text-base font-bold leading-snug text-warm-800 transition-colors group-hover:text-travel-accent dark:text-shell-text dark:group-hover:text-travel-bloom">
                      {post.title}
                    </h3>
                  </Link>
                  <p className="mt-2 line-clamp-3 text-sm leading-relaxed text-travel-ink/80 dark:text-shell-muted">
                    {post.summary || '还没有摘要，点击编辑为这篇文章写一句引言吧。'}
                  </p>

                  {/* 元信息 */}
                  <div className="mt-3 flex flex-wrap items-center gap-2 text-xs text-warm-400">
                    <span className="inline-flex items-center gap-1">
                      <Calendar className="h-3.5 w-3.5" />
                      {new Date(post.date).toLocaleDateString('zh-CN')}
                    </span>
                    {post.location && (
                      <span className="inline-flex items-center gap-1">
                        <MapPin className="h-3.5 w-3.5" />
                        {post.location}
                      </span>
                    )}
                  </div>

                  {post.tags && post.tags.length > 0 && (
                    <div className="mt-3 flex flex-wrap gap-1.5">
                      {post.tags.slice(0, 4).map((tag) => (
                        <span key={tag} className="rounded-full bg-travel-sakura/60 px-2 py-0.5 text-xs text-travel-accent dark:bg-shell-surface/80 dark:text-travel-bloom">
                          # {tag}
                        </span>
                      ))}
                    </div>
                  )}

                  {/* 状态与操作 */}
                  <div className="mt-4 flex items-center justify-between border-t border-warm-100 pt-3.5 dark:border-white/5">
                    <div className="flex items-center gap-1.5">
                      <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${
                        post.published
                          ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-500/15 dark:text-emerald-300'
                          : 'bg-warm-100 text-warm-500 dark:bg-white/10 dark:text-warm-400'
                      }`}>
                        {post.published ? '已发布' : '草稿'}
                      </span>
                      <button
                        onClick={() => togglePublic(post)}
                        disabled={togglingId === post.id}
                        title={post.isPublic ? '点击设为仅自己可见' : '点击公开分享（所有人可见）'}
                        className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium transition-all active:scale-95 disabled:opacity-60 ${
                          post.isPublic
                            ? 'bg-sky-100 text-sky-600 hover:bg-sky-200 dark:bg-sky-500/15 dark:text-sky-300'
                            : 'bg-warm-100 text-warm-500 hover:bg-amber-100 hover:text-amber-600 dark:bg-white/10 dark:text-warm-400'
                        }`}
                      >
                        {togglingId === post.id ? (
                          <Loader2 className="h-3 w-3 animate-spin" />
                        ) : post.isPublic ? (
                          <Globe2 className="h-3 w-3" />
                        ) : (
                          <Lock className="h-3 w-3" />
                        )}
                        {post.isPublic ? '公开' : '私密'}
                      </button>
                    </div>

                    <div className="flex items-center gap-1">
                      <Link
                        href={`/${post.type}/${post.slug}`}
                        target="_blank"
                        title="查看"
                        className="rounded-lg p-2 text-warm-400 transition-all hover:bg-travel-sakura/60 hover:text-travel-accent active:scale-90"
                      >
                        <ExternalLink className="h-4 w-4" />
                      </Link>
                      <Link
                        href={`/admin/edit/${post.id}`}
                        title="编辑"
                        className="rounded-lg p-2 text-warm-400 transition-all hover:bg-travel-mist/60 hover:text-travel-accentStrong active:scale-90"
                      >
                        <Edit2 className="h-4 w-4" />
                      </Link>
                      <button
                        onClick={() => setDeleteId(post.id)}
                        title="删除"
                        className="rounded-lg p-2 text-warm-400 transition-all hover:bg-red-50 hover:text-red-500 active:scale-90 dark:hover:bg-red-500/10"
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </div>
                  </div>

                  {/* 旅行圈分享状态与操作（内容管理 2.0，与文章可见性解耦） */}
                  <div className="mt-3 flex items-center justify-between gap-2 border-t border-warm-100 pt-3 dark:border-white/5">
                    <button
                      type="button"
                      onClick={() => openShare(post)}
                      disabled={sharing === post.id || togglingId === post.id}
                      title={post.circleShared ? '管理旅行圈分享' : '分享到旅行圈'}
                      className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium transition-all active:scale-95 disabled:opacity-60 ${
                        post.circleShared
                          ? 'bg-emerald-100 text-emerald-700 hover:bg-emerald-200 dark:bg-emerald-500/15 dark:text-emerald-300'
                          : 'bg-travel-sakura/70 text-travel-accent hover:bg-travel-sakura dark:bg-shell-surface/80 dark:text-travel-bloom'
                      }`}
                    >
                      {sharing === post.id ? (
                        <Loader2 className="h-3 w-3 animate-spin" />
                      ) : (
                        <Globe2 className="h-3 w-3" />
                      )}
                      {post.circleShared ? '已分享到旅行圈' : '分享到旅行圈'}
                    </button>
                    <span className="text-xs text-warm-400">
                      {post.circleShared ? '可在旅行圈浏览' : '尚未分享到旅行圈'}
                    </span>
                  </div>
                </div>
              </motion.article>
            )
          })}
        </motion.div>
      )}

      {/* 移动端新建 FAB */}
      <Link
        href="/admin/new"
        className="fixed bottom-6 right-6 z-40 flex h-14 w-14 items-center justify-center rounded-2xl bg-gradient-to-br from-travel-accent to-travel-accentSoft text-white shadow-xl shadow-travel-accent/35 transition-all hover:scale-105 active:scale-95 lg:hidden"
        aria-label="新建文章"
      >
        <Plus className="h-6 w-6" />
      </Link>

      {/* 删除确认（玻璃弹窗） */}
      {deleteId !== null && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/45 p-4 backdrop-blur-sm" onClick={() => setDeleteId(null)}>
          <motion.div
            initial={{ opacity: 0, scale: 0.94, y: 12 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            transition={{ duration: 0.25, ease: [0.23, 1, 0.32, 1] }}
            onClick={(e) => e.stopPropagation()}
            className="w-full max-w-sm rounded-3xl border border-white/70 bg-white/95 p-6 shadow-2xl backdrop-blur-2xl dark:border-white/10 dark:bg-shell-bg/95"
          >
            <div className="mb-4 flex items-start justify-between">
              <div className="flex items-center gap-3">
                <div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-red-50 dark:bg-red-500/10">
                  <Trash2 className="h-5 w-5 text-red-500" />
                </div>
                <h3 className="text-base font-semibold text-warm-800 dark:text-shell-text">删除这篇文章？</h3>
              </div>
              <button onClick={() => setDeleteId(null)} className="rounded-lg p-1.5 text-warm-400 hover:bg-black/5 dark:hover:bg-white/10" aria-label="关闭">
                <X className="h-4 w-4" />
              </button>
            </div>
            <p className="text-sm leading-relaxed text-travel-ink/80 dark:text-shell-muted">
              删除后不可恢复，确定要删除这篇游记吗？
            </p>
            <div className="mt-6 flex gap-3">
              <button
                onClick={() => setDeleteId(null)}
                className="flex-1 rounded-xl border border-warm-200 py-2.5 text-sm font-medium text-travel-ink transition-all hover:bg-black/5 dark:border-white/10 dark:text-warm-300 dark:hover:bg-white/5"
              >
                取消
              </button>
              <button
                onClick={handleDelete}
                disabled={deleting}
                className="flex flex-1 items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-red-500 to-travel-accent py-2.5 text-sm font-semibold text-white shadow-lg shadow-red-500/25 transition-all hover:shadow-xl active:scale-95 disabled:opacity-60"
              >
                {deleting && <Loader2 className="h-4 w-4 animate-spin" />}
                确认删除
              </button>
            </div>
          </motion.div>
        </div>
      )}

      {/* 旅行圈分享对话框（内容管理 2.0） */}
      <Modal
        open={!!sharePost}
        onClose={closeShare}
        title={sharePost?.circleShared ? '管理旅行圈分享' : '分享到旅行圈'}
        footer={
          <>
            <button
              type="button"
              onClick={closeShare}
              className="rounded-xl border border-warm-200 px-4 py-2.5 text-sm font-medium text-travel-ink transition-all hover:bg-black/5 dark:border-white/10 dark:text-warm-300 dark:hover:bg-white/5"
            >
              取消
            </button>
            {sharePost?.circleShared && (
              <button
                type="button"
                onClick={confirmUnshare}
                disabled={sharing === sharePost?.id}
                className="flex items-center gap-1.5 rounded-xl bg-red-50 px-4 py-2.5 text-sm font-medium text-red-500 transition-all hover:bg-red-100 disabled:opacity-60 dark:bg-red-500/10"
              >
                {sharing === sharePost?.id && <Loader2 className="h-4 w-4 animate-spin" />}
                取消分享
              </button>
            )}
            <button
              type="button"
              onClick={confirmShare}
              disabled={sharing === sharePost?.id}
              className="flex items-center gap-2 rounded-xl bg-gradient-to-r from-travel-accent to-travel-accentSoft px-4 py-2.5 text-sm font-semibold text-white shadow-lg shadow-travel-accent/25 transition-all hover:shadow-xl disabled:opacity-60"
            >
              {sharing === sharePost?.id && <Loader2 className="h-4 w-4 animate-spin" />}
              {sharePost?.circleShared ? '保存' : '分享到旅行圈'}
            </button>
          </>
        }
      >
        {sharePost && (
          <div className="space-y-4">
            <div className="rounded-2xl bg-travel-sakura/30 p-4">
              <p className="text-sm font-semibold text-travel-ink">{sharePost.title}</p>
              <p className="mt-1 line-clamp-2 text-xs leading-relaxed text-travel-ink/80">
                {sharePost.summary || '这篇旅行记录即将分享给其他旅行者。'}
              </p>
            </div>

            <Select
              label="所属旅行"
              value={shareTravelId ?? ''}
              onChange={(e) => setShareTravelId(e.target.value ? Number(e.target.value) : null)}
              hint="可选：将分享关联到某次旅行（仅用于归档展示）"
            >
              <option value="">不关联旅行</option>
              {travels.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.title}
                </option>
              ))}
            </Select>

            <fieldset className="space-y-1.5">
              <legend className="mb-1.5 text-sm font-medium text-travel-ink dark:text-shell-muted">分享范围</legend>
              <label className="flex cursor-pointer items-center gap-2 rounded-xl border border-travel-line/60 bg-white/80 px-3 py-2.5 text-sm text-travel-ink dark:border-shell-line dark:bg-white/5 dark:text-shell-text">
                <input
                  type="radio"
                  name="share-scope"
                  value="PUBLIC"
                  checked={shareScope === 'PUBLIC'}
                  onChange={() => setShareScope('PUBLIC')}
                  className="accent-travel-accent"
                />
                公开（所有人可见）
              </label>
              <label className="flex cursor-pointer items-center gap-2 rounded-xl border border-travel-line/60 bg-white/80 px-3 py-2.5 text-sm text-travel-ink dark:border-shell-line dark:bg-white/5 dark:text-shell-text">
                <input
                  type="radio"
                  name="share-scope"
                  value="SPACE"
                  checked={shareScope === 'SPACE'}
                  onChange={() => setShareScope('SPACE')}
                  className="accent-travel-accent"
                />
                仅空间成员
              </label>
            </fieldset>

            {shareError && <p className="rounded-xl bg-red-50 px-3 py-2 text-xs text-red-500 dark:bg-red-500/10">{shareError}</p>}
          </div>
        )}
      </Modal>
    </AdminShell>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { ArrowLeft, KeyRound, CheckCircle, AlertCircle, Loader2 } from 'lucide-react'

export default function AdminSetupPage() {
  const router = useRouter()
  const [username, setUsername] = useState('admin')
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const [done, setDone] = useState(false)

  useEffect(() => {
    checkExistingSetup()
  }, [])

  const checkExistingSetup = async () => {
    try {
      const res = await fetch('/api/admin/check')
      const data = await res.json()
      if (data.authenticated) {
        router.push('/admin')
      }
    } catch {}
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')

    if (!username.trim()) {
      setError('请输入用户名')
      return
    }
    if (password.length < 8) {
      setError('密码至少需要 8 位字符')
      return
    }
    if (password !== confirmPassword) {
      setError('两次密码不一致')
      return
    }

    setLoading(true)
    try {
      const res = await fetch('/api/admin/setup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: username.trim(), password }),
      })

      const data = await res.json().catch(() => ({}))
      if (!res.ok) {
        setError(data.error || '初始化失败，请稍后重试')
        setLoading(false)
        return
      }

      setDone(true)
    } catch {
      setError('网络错误，请稍后重试')
      setLoading(false)
    }
  }

  if (done) {
    return (
      <div className="min-h-dvh bg-warm-50 dark:bg-warm-900 flex items-center justify-center px-4">
        <div className="bg-white dark:bg-warm-800 rounded-2xl shadow-sm p-8 max-w-md w-full text-center">
          <div className="flex items-center justify-center gap-2 text-green-600 dark:text-green-400 mb-3">
            <CheckCircle className="w-6 h-6" />
            <h1 className="text-xl font-bold text-warm-900 dark:text-white">初始化完成</h1>
          </div>
          <p className="text-sm text-warm-500 dark:text-warm-400 mb-6">
            管理员账号已创建，初始化入口已关闭。请使用新账号登录后台。
          </p>
          <button
            onClick={() => router.push('/admin/login')}
            className="w-full py-3 bg-primary-500 hover:bg-primary-600 text-white font-medium rounded-lg transition-colors"
          >
            前往登录
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-dvh bg-warm-50 dark:bg-warm-900">
      <div className="max-w-2xl mx-auto px-4 py-12">
        <div className="mb-8">
          <Link
            href="/admin/login"
            className="inline-flex items-center gap-2 text-warm-500 dark:text-warm-400 hover:text-warm-700 dark:hover:text-warm-300 text-sm"
          >
            <ArrowLeft className="w-4 h-4" />
            返回登录
          </Link>
        </div>

        <form onSubmit={handleSubmit} className="bg-white dark:bg-warm-800 rounded-2xl shadow-sm p-8">
          <div className="flex items-center gap-3 mb-6">
            <div className="w-12 h-12 bg-primary-100 dark:bg-primary-900/30 rounded-xl flex items-center justify-center">
              <KeyRound className="w-6 h-6 text-primary-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-warm-900 dark:text-white">初始化管理员</h1>
              <p className="text-sm text-warm-500 dark:text-warm-400">首次启动：设置管理员账户</p>
            </div>
          </div>

          <div className="space-y-5">
            <div>
              <label className="block text-sm font-medium text-warm-700 dark:text-warm-300 mb-2">用户名</label>
              <input
                type="text"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                className="w-full px-4 py-2.5 bg-warm-50 dark:bg-warm-700 border border-warm-300 dark:border-warm-600 rounded-lg text-warm-900 dark:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-500"
                placeholder="admin"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-warm-700 dark:text-warm-300 mb-2">密码</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-2.5 bg-warm-50 dark:bg-warm-700 border border-warm-300 dark:border-warm-600 rounded-lg text-warm-900 dark:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-500"
                placeholder="至少 8 位"
              />
              <p className="mt-1 text-xs text-warm-400">建议包含大小写字母、数字与符号</p>
            </div>

            <div>
              <label className="block text-sm font-medium text-warm-700 dark:text-warm-300 mb-2">确认密码</label>
              <input
                type="password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                className="w-full px-4 py-2.5 bg-warm-50 dark:bg-warm-700 border border-warm-300 dark:border-warm-600 rounded-lg text-warm-900 dark:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-500"
                placeholder="再次输入密码"
              />
            </div>

            {error && (
              <div className="flex items-center gap-2 px-4 py-3 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 rounded-lg text-sm">
                <AlertCircle className="w-4 h-4 shrink-0" />
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full py-3 bg-primary-500 hover:bg-primary-600 disabled:opacity-50 text-white font-medium rounded-lg transition-colors flex items-center justify-center gap-2"
            >
              {loading && <Loader2 className="w-4 h-4 animate-spin" />}
              {loading ? '创建中...' : '创建管理员'}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import AdminShell from '@/components/admin/AdminShell'
import { Loader2, Flag, Heart, MessageCircle, Bookmark, FileText } from 'lucide-react'

type Tab = 'posts' | 'comments' | 'reports'

export default function AdminSocialPage() {
  const [data, setData] = useState<any>(null)
  const [tab, setTab] = useState<Tab>('posts')
  const [loading, setLoading] = useState(true)
  const [processing, setProcessing] = useState<number | null>(null)
  const [notice, setNotice] = useState('')

  const load = () => {
    fetch('/api/admin/social').then((r) => r.json()).then((j) => setData(j)).catch(() => {})
  }

  useEffect(() => {
    fetch('/api/admin/social').then((r) => r.json()).then((j) => setData(j)).catch(() => {}).finally(() => setLoading(false))
  }, [])

  // v3.1 M3-B2：处理举报（驳回/下架/隐藏评论/封禁警告）
  const handleReport = async (reportId: number, action: string) => {
    if (processing) return
    const label = { DISMISS: '驳回举报', TAKEDOWN_POST: '下架帖子', HIDE_COMMENT: '隐藏评论', BAN_USER: '封禁警告' } as Record<string, string>
    if (!window.confirm(`确认执行「${label[action] || action}」？`)) return
    setProcessing(reportId)
    setNotice('')
    try {
      const res = await fetch('/api/admin/social/reports', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reportId, action }),
      })
      const j = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(j.error || '处理失败')
      setNotice(j.message || '处理成功')
      load()
    } catch (e: any) {
      setNotice(e.message || '处理失败')
    } finally {
      setProcessing(null)
    }
  }

  const stats = data?.stats

  const statCards = stats ? [
    { label: '公开旅行', value: stats.postCount, icon: FileText },
    { label: '点赞', value: stats.likeCount, icon: Heart },
    { label: '评论', value: stats.commentCount, icon: MessageCircle },
    { label: '收藏', value: stats.favoriteCount, icon: Bookmark },
    { label: '举报(待处理)', value: stats.reportCount + ' / ' + stats.pendingReportCount, icon: Flag },
  ] : []

  const tabs: { key: Tab; label: string }[] = [
    { key: 'posts', label: '帖子' },
    { key: 'comments', label: '评论' },
    { key: 'reports', label: '举报' },
  ]

  return (
    <AdminShell title="社交管理" accent="from-travel-accent to-travel-bloom">
      <div className="space-y-6">
        {loading ? (
          <div className="py-20 text-center text-warm-400"><Loader2 className="mx-auto h-6 w-6 animate-spin" /></div>
        ) : !data ? (
          <p className="py-20 text-center text-warm-400">加载失败</p>
        ) : (
          <>
            <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5">
              {statCards.map((s) => (
                <div key={s.label} className="rounded-2xl border border-travel-line/50 bg-white/80 p-4 backdrop-blur shadow-soft dark:border-shell-line dark:bg-white/5">
                  <div className="flex items-center gap-2 text-xs text-travel-ink/60 dark:text-warm-400"><s.icon className="h-4 w-4 text-travel-accentSoft" />{s.label}</div>
                  <div className="mt-2 text-2xl font-bold text-travel-ink dark:text-warm-100">{s.value}</div>
                </div>
              ))}
            </div>

            <div className="flex gap-2">
              {tabs.map((t) => (
                <button key={t.key} onClick={() => setTab(t.key)}
                  className={tab === t.key ? 'rounded-full bg-travel-accent px-4 py-1.5 text-sm font-medium text-white shadow-sm shadow-travel-accent/25' : 'rounded-full bg-white/70 px-4 py-1.5 text-sm text-travel-ink/80 hover:bg-travel-sakura/40 dark:bg-white/5 dark:text-warm-300'}>
                  {t.label}
                </button>
              ))}
            </div>

            {tab === 'posts' && (
              <div className="overflow-hidden rounded-2xl border border-travel-line/50 dark:border-shell-line">
                {(data.posts || []).length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-16 text-center text-travel-ink/50 dark:text-warm-400">
                    <FileText className="mb-3 h-10 w-10 opacity-30 text-travel-accentSoft" />
                    <p>还没有公开的旅行帖子</p>
                  </div>
                ) : (
                  // 表格在窄屏会溢出：外套 overflow-x-auto 让内容可横向滚动，
                  // 而不是把卡片撑破（审计页已有此处理，此处补齐保持一致）。
                  <div className="overflow-x-auto">
                  <table className="w-full min-w-[560px] text-left text-sm">
                    <thead className="bg-travel-sakura/40 text-xs text-travel-ink/80 dark:bg-white/5 dark:text-warm-400">
                      <tr><th className="px-4 py-2.5">标题</th><th className="px-4 py-2.5">作者</th><th className="px-4 py-2.5">点赞/评论/收藏</th><th className="px-4 py-2.5">发布时间</th></tr>
                    </thead>
                    <tbody className="divide-y divide-travel-line/40 dark:divide-white/5">
                      {(data.posts || []).map((p: any) => (
                        <tr key={p.id} className="text-travel-ink dark:text-warm-200">
                          <td className="px-4 py-2.5"><Link href={'/circle/' + p.id} className="hover:text-travel-accent">{p.title}</Link></td>
                          <td className="px-4 py-2.5">{p.author?.username || '-'}</td>
                          <td className="px-4 py-2.5 tabular-nums">{p.likeCount}/{p.commentCount}/{p.favoriteCount}</td>
                          <td className="px-4 py-2.5 text-xs text-travel-ink/50">{p.publishedAt ? new Date(p.publishedAt).toLocaleDateString('zh-CN') : '-'}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  </div>
                )}
              </div>
            )}

            {tab === 'comments' && (
              <div className="space-y-2">
                {(data.comments || []).map((c: any) => (
                  <div key={c.id} className="rounded-2xl border border-travel-line/50 bg-white/70 p-3.5 dark:border-shell-line dark:bg-white/5">
                    <div className="flex items-center gap-2 text-xs text-travel-ink/60 dark:text-warm-400">
                      <span className="font-medium text-travel-ink dark:text-warm-200">{c.user?.username || '-'}</span>
                      <span>· 评论了 <Link href={'/circle/' + c.post?.id} className="text-travel-accent">{c.post?.title || '#' + c.postId}</Link></span>
                      <span>· {c.status}</span>
                    </div>
                    <p className="mt-1.5 text-sm text-travel-ink dark:text-warm-200">{c.content}</p>
                  </div>
                ))}
                {(data.comments || []).length === 0 && <p className="py-10 text-center text-travel-ink/50">暂无评论</p>}
              </div>
            )}

            {tab === 'reports' && (
              <div className="space-y-2">
                {notice && <p className="rounded-xl bg-travel-success/10 px-3 py-2 text-sm text-travel-success">{notice}</p>}
                {(data.reports || []).map((r: any) => (
                  <div key={r.id} className="rounded-2xl border border-travel-line/50 bg-white/70 p-3.5 dark:border-shell-line dark:bg-white/5">
                    <div className="flex items-center gap-2 text-xs text-travel-ink/60 dark:text-warm-400">
                      <span className="font-medium text-travel-ink dark:text-warm-200">{r.reporter?.username || '-'}</span>
                      <span>举报了 <Link href={'/circle/' + r.post?.id} className="text-travel-accent">{r.post?.title || '#' + r.postId}</Link></span>
                      <span className="rounded-full bg-travel-warning/15 px-2 py-0.5 text-travel-warning">{r.status}</span>
                    </div>
                    <p className="mt-1.5 text-sm text-travel-ink dark:text-warm-200">{r.reason}</p>
                    {r.status === 'PENDING' && (
                      <div className="mt-2.5 flex flex-wrap gap-1.5">
                        {[
                          ['DISMISS', '驳回'],
                          ['TAKEDOWN_POST', '下架帖子'],
                          ['HIDE_COMMENT', '隐藏评论'],
                          ['BAN_USER', '封禁警告'],
                        ].map(([action, label]) => (
                          <button
                            key={action}
                            type="button"
                            onClick={() => handleReport(r.id, action)}
                            disabled={processing === r.id}
                            className={`rounded-full px-3 py-1 text-xs transition disabled:opacity-50 ${
                              action === 'DISMISS'
                                ? 'bg-white/70 text-travel-ink/80 hover:bg-travel-sakura/40 dark:bg-white/5 dark:text-warm-300'
                                : action === 'BAN_USER'
                                  ? 'bg-travel-danger/10 text-travel-danger hover:bg-travel-danger/20 dark:bg-red-500/10 dark:text-red-300'
                                  : 'bg-travel-sakura/60 text-travel-accent hover:bg-travel-sakura dark:bg-travel-accent/15'
                            }`}
                          >
                            {processing === r.id ? '处理中...' : label}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>
                ))}
                {(data.reports || []).length === 0 && <p className="py-10 text-center text-travel-ink/50">暂无举报</p>}
              </div>
            )}
          </>
        )}
      </div>
    </AdminShell>
  )
}

'use client'

import Link from 'next/link'

import { useCallback, useEffect, useState } from 'react'
import { ArrowLeft, Plus, Trash2, Loader2, MapPin, Wallet, CalendarDays, X } from 'lucide-react'
import AdminShell from '@/components/admin/AdminShell'
import { AdminInput, AdminButton, AdminCard } from '@/components/admin/ui'
import { EXPENSE_CATEGORIES, EXPENSE_LABELS } from '@/lib/modules/travel/expense-categories'

interface TravelSummary {
  id: number
  title: string
  slug: string
  description: string | null
  startDate: string | null
  endDate: string | null
  status: string
  dayCount: number
  expenseTotal: number
}

interface ItineraryItem {
  id: number
  title: string
  startTime: string | null
  endTime: string | null
  type: string
  notes: string | null
  locationName: string | null
}

interface TravelDay {
  id: number
  date: string | null
  title: string | null
  summary: string | null
  sortOrder: number
  itinerary: ItineraryItem[]
}

interface Expense {
  id: number
  amount: number
  currency: string
  category: string
  payer: string | null
  note: string | null
  happenedAt: string | null
}

interface TravelDetail {
  id: number
  title: string
  slug: string
  description: string | null
  startDate: string | null
  endDate: string | null
  status: string
  days: TravelDay[]
  expenses: Expense[]
}

const ITINERARY_TYPES = ['SPOT', 'RESTAURANT', 'HOTEL', 'TRANSPORT', 'ACTIVITY', 'OTHER']
const ITINERARY_LABELS: Record<string, string> = {
  SPOT: '景点', RESTAURANT: '餐厅', HOTEL: '住宿', TRANSPORT: '交通', ACTIVITY: '活动', OTHER: '其他',
}
// 分类与文案走共享常量（前台花销 tab 用同一份，避免两处漂移）
// EXPENSE_CATEGORIES / EXPENSE_LABELS 见下方 import
const TRAVEL_TYPES: { value: string; label: string }[] = [
  { value: 'ALONE', label: '独旅' },
  { value: 'COUPLE', label: '情侣' },
  { value: 'FAMILY', label: '家庭' },
  { value: 'FRIENDS', label: '朋友' },
  { value: 'BFF', label: '闺蜜/兄弟' },
  { value: 'GROUP', label: '结伴' },
  { value: 'OTHER', label: '其他' },
]
const MAX_COMPANIONS = 10

interface Companion {
  name: string
  relation: string
}

export default function AdminTravelsPage() {
  const [travels, setTravels] = useState<TravelSummary[]>([])
  const [loading, setLoading] = useState(true)
  const [selected, setSelected] = useState<number | null>(null)
  const [detail, setDetail] = useState<TravelDetail | null>(null)

  // create
  const [createTitle, setCreateTitle] = useState('')
  const [createStart, setCreateStart] = useState('')
  const [createEnd, setCreateEnd] = useState('')
  const [createTravelType, setCreateTravelType] = useState('ALONE')
  const [createCompanions, setCreateCompanions] = useState<Companion[]>([])
  const [companionName, setCompanionName] = useState('')
  const [companionRelation, setCompanionRelation] = useState('')
  const [creating, setCreating] = useState(false)
  const [error, setError] = useState('')

  const addCompanion = () => {
    const name = companionName.trim()
    if (!name || createCompanions.length >= MAX_COMPANIONS) return
    setCreateCompanions([...createCompanions, { name, relation: companionRelation.trim() }])
    setCompanionName('')
    setCompanionRelation('')
  }

  // day form
  const [dayDate, setDayDate] = useState('')
  const [dayTitle, setDayTitle] = useState('')

  // itinerary form
  const [itineraryDay, setItineraryDay] = useState<number | null>(null)
  const [itineraryTitle, setItineraryTitle] = useState('')
  const [itineraryType, setItineraryType] = useState('SPOT')
  const [itineraryTime, setItineraryTime] = useState('')

  // expense form
  const [expenseAmount, setExpenseAmount] = useState('')
  const [expenseCategory, setExpenseCategory] = useState('TRANSPORT')
  const [expensePayer, setExpensePayer] = useState('')

  const fetchList = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/admin/travels')
      if (res.ok) {
        const data = await res.json()
        setTravels(data.travels || [])
      }
    } catch {} finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => { fetchList() }, [fetchList])

  const fetchDetail = useCallback(async (id: number) => {
    const res = await fetch(`/api/admin/travels/${id}`)
    if (res.ok) {
      const data = await res.json()
      setDetail(data.travel || null)
    }
  }, [])

  useEffect(() => {
    if (selected !== null) fetchDetail(selected)
  }, [selected, fetchDetail])

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    if (!createTitle.trim()) { setError('请输入旅行名称'); return }
    setCreating(true)
    try {
      const res = await fetch('/api/admin/travels', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: createTitle.trim(),
          startDate: createStart || undefined,
          endDate: createEnd || undefined,
          travelType: createTravelType,
          companions: createCompanions.length > 0 ? createCompanions : undefined,
        }),
      })
      const data = await res.json().catch(() => ({}))
      if (!res.ok) { setError(data.error || '创建失败'); return }
      setCreateTitle(''); setCreateStart(''); setCreateEnd(''); setCreateTravelType('ALONE'); setCreateCompanions([])
      await fetchList()
      setSelected(data.id)
    } catch { setError('网络错误') } finally { setCreating(false) }
  }

  const handleDeleteTravel = async () => {
    if (!selected || !confirm('确定删除该旅行规划（含天数/行程/花费）？')) return
    const res = await fetch(`/api/admin/travels/${selected}`, { method: 'DELETE' })
    if (res.ok) { setSelected(null); setDetail(null); await fetchList() }
  }

  const handleAddDay = async () => {
    if (!selected) return
    const res = await fetch(`/api/admin/travels/${selected}/days`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ date: dayDate || undefined, title: dayTitle || undefined }),
    })
    if (res.ok) { setDayDate(''); setDayTitle(''); await fetchDetail(selected) }
  }

  const handleDeleteDay = async (dayId: number) => {
    if (!selected) return
    const res = await fetch(`/api/admin/travels/${selected}/days/${dayId}`, { method: 'DELETE' })
    if (res.ok) await fetchDetail(selected)
  }

  const handleAddItinerary = async () => {
    if (!selected || itineraryDay === null || !itineraryTitle.trim()) return
    const res = await fetch(`/api/admin/travels/${selected}/itinerary`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        dayId: itineraryDay,
        title: itineraryTitle.trim(),
        type: itineraryType,
        startTime: itineraryTime ? `${itineraryTime}:00` : undefined,
      }),
    })
    if (res.ok) { setItineraryTitle(''); setItineraryTime(''); await fetchDetail(selected) }
  }

  const handleDeleteItinerary = async (itemId: number) => {
    if (!selected) return
    const res = await fetch(`/api/admin/travels/${selected}/itinerary/${itemId}`, { method: 'DELETE' })
    if (res.ok) await fetchDetail(selected)
  }

  const handleAddExpense = async () => {
    if (!selected) return
    const res = await fetch(`/api/admin/travels/${selected}/expenses`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        amount: parseFloat(expenseAmount),
        category: expenseCategory,
        payer: expensePayer || undefined,
      }),
    })
    if (res.ok) { setExpenseAmount(''); setExpensePayer(''); await fetchDetail(selected) }
  }

  const handleDeleteExpense = async (expenseId: number) => {
    if (!selected) return
    const res = await fetch(`/api/admin/travels/${selected}/expenses/${expenseId}`, { method: 'DELETE' })
    if (res.ok) await fetchDetail(selected)
  }

  const totalExpense = detail?.expenses.reduce((s, e) => s + e.amount, 0) || 0

  return (
    <AdminShell title="旅行规划">
      <div className="mx-auto max-w-6xl">
        <Link
          href="/admin"
          className="inline-flex items-center gap-1.5 text-sm text-warm-500 dark:text-warm-400 hover:text-travel-accent dark:hover:text-travel-accentSoft transition-colors mb-4"
        >
          <ArrowLeft className="w-4 h-4" />
          返回后台
        </Link>
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-travel-inkStrong dark:text-white mb-1">旅行规划</h1>
        <p className="text-sm text-travel-ink/60 dark:text-warm-400">
          管理一段旅行的天数、每日行程与花费
        </p>
      </div>

      <div className="grid lg:grid-cols-3 gap-6">
        {/* 左列：旅行列表 */}
        <div>
          <form onSubmit={handleCreate} className="card p-5 mb-4">
            <h2 className="text-base font-semibold text-travel-ink dark:text-warm-100 mb-3 flex items-center gap-2">
              <Plus className="w-4 h-4 text-travel-accentSoft" />
              新建旅行
            </h2>
            <AdminInput
              type="text"
              value={createTitle}
              onChange={(e) => setCreateTitle(e.target.value)}
              placeholder="旅行名称，如：东京 · 2026"
              className="mb-2"
            />
            <div className="grid grid-cols-2 gap-2 mb-2">
              <AdminInput type="date" value={createStart} onChange={(e) => setCreateStart(e.target.value)} />
              <AdminInput type="date" value={createEnd} onChange={(e) => setCreateEnd(e.target.value)} />
            </div>
            <div className="mb-2">
              <span className="mb-1 block text-xs text-travel-ink/60 dark:text-warm-400">这次旅行是？</span>
              <div className="flex flex-wrap gap-1.5">
                {TRAVEL_TYPES.map((t) => (
                  <button
                    key={t.value}
                    type="button"
                    onClick={() => setCreateTravelType(t.value)}
                    className={`rounded-full px-2.5 py-1 text-xs font-medium transition ${
                      createTravelType === t.value
                        ? 'bg-travel-accent text-white'
                        : 'bg-travel-dim/40 text-travel-ink/80 hover:bg-travel-dim/70 dark:bg-white/10 dark:text-warm-300'
                    }`}
                  >
                    {t.label}
                  </button>
                ))}
              </div>
            </div>
            <div className="mb-2">
              <span className="mb-1 block text-xs text-travel-ink/60 dark:text-warm-400">
                和谁一起去的？<span className="text-travel-ink/40 dark:text-warm-500">（可选，最多 {MAX_COMPANIONS} 人）</span>
              </span>
              <div className="flex gap-1.5">
                <AdminInput
                  type="text"
                  value={companionName}
                  onChange={(e) => setCompanionName(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); addCompanion() } }}
                  placeholder="姓名"
                  className="!w-24 shrink-0"
                />
                <AdminInput
                  type="text"
                  value={companionRelation}
                  onChange={(e) => setCompanionRelation(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); addCompanion() } }}
                  placeholder="关系（可选）"
                  className="flex-1"
                />
                <button
                  type="button"
                  onClick={addCompanion}
                  disabled={!companionName.trim() || createCompanions.length >= MAX_COMPANIONS}
                  className="shrink-0 rounded-lg border border-travel-line/70 px-2.5 py-1.5 text-xs font-medium text-travel-ink/80 transition hover:bg-travel-dim/50 disabled:opacity-40 dark:border-shell-line dark:text-warm-300"
                >
                  + 添加
                </button>
              </div>
              {createCompanions.length > 0 && (
                <div className="mt-1.5 flex flex-wrap gap-1.5">
                  {createCompanions.map((c, i) => (
                    <span
                      key={`${c.name}-${i}`}
                      className="inline-flex items-center gap-1 rounded-full bg-travel-sakura/50 px-2.5 py-0.5 text-xs text-travel-ink dark:bg-white/10 dark:text-warm-200"
                    >
                      {c.name}
                      {c.relation ? <span className="text-travel-ink/50 dark:text-warm-400">· {c.relation}</span> : null}
                      <button
                        type="button"
                        onClick={() => setCreateCompanions(createCompanions.filter((_, j) => j !== i))}
                        aria-label={`移除 ${c.name}`}
                        className="ml-0.5 rounded-full p-0.5 text-travel-ink/50 hover:text-travel-ink dark:text-warm-400"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </span>
                  ))}
                </div>
              )}
            </div>
            {error && <p className="text-xs text-travel-danger mb-2">{error}</p>}
            <AdminButton type="submit" disabled={creating} className="w-full">
              {creating ? '创建中...' : '创建旅行'}
            </AdminButton>
          </form>

          {loading ? (
            <div className="py-10 text-center text-travel-ink/50 dark:text-warm-500">加载中...</div>
          ) : travels.length === 0 ? (
            <div className="rounded-2xl border-2 border-dashed border-travel-bloom/50 bg-white/50 p-6 text-center text-travel-ink/60 dark:border-shell-line dark:bg-white/5">还没有旅行规划</div>
          ) : (
            <div className="space-y-2">
              {travels.map((t) => (
                <button
