    const valid = await verifyVerificationCode(email, code)
    if (!valid) {
      return NextResponse.json({ error: '验证码错误或已过期' }, { status: 401 })
    }

    await consumeVerificationCode(email)

    const siteService = getSiteService()
    // P0-3：必须传当前登录用户名 —— 不传时旧实现会回退「首个用户」，
