    }

    return NextResponse.json({
      success: true,
      email,
      emailVerified: true,
    })
  } catch (error) {
    if (error instanceof ApiError) return errorResponse(error, getRequestId(request))
    return NextResponse.json({ error: '绑定失败' }, { status: 500 })
  }
}

