import { NextResponse } from 'next/server'
import { z } from 'zod'
import { prisma } from '@/lib/db'
import { hashPassword } from '@/lib/auth-utils'
import { getSiteSettings, updateCredentials } from '@/lib/auth'
import { rateLimit } from '@/lib/infrastructure/rate-limit'
import { getClientIp } from '@/lib/request-utils'
import { PasswordSchema } from '@/lib/validators/auth.validator'
import { ApiError, errorResponse } from '@/lib/api-response'
import { parseBody, getRequestId } from '@/lib/api/handler'

const USERNAME_RE = /^[a-zA-Z0-9_\u4e00-\u9fa5]{3,50}$/

/** 初始化请求体（P1-12/P1-17）：用户名规则 + 与注册/重置/改密同一套密码策略 */
const SetupSchema = z.object({
  username: z.string().trim().regex(USERNAME_RE, '用户名需为 3-50 位字母、数字、下划线或中文'),
  password: PasswordSchema,
})

/**
 * 首次启动初始化：创建管理员账号。
 * - 仅当系统尚未配置任何密码时允许（初始化入口随完成自动关闭）
 * - 带 IP 限流，防止暴力占用初始化
 */
export async function POST(request: Request) {
  const requestId = getRequestId(request)
  try {
    const ip = getClientIp(request)
    const limit = rateLimit({ prefix: 'setup:ip', key: ip || 'unknown', limit: 5, windowMs: 10 * 60 * 1000 })
    if (!limit.ok) {
      return NextResponse.json(
        { error: '尝试过于频繁，请稍后再试', code: 'RATE_LIMITED', retryAfterSeconds: limit.retryAfterSeconds, requestId },
        { status: 429 }
      )
    }

    const { username, password } = await parseBody(request, SetupSchema)

    // 仅允许在未初始化时创建管理员
    const settings = await getSiteSettings()
    if (settings.passwordHash) {
      throw new ApiError('ALREADY_INITIALIZED', '系统已完成初始化，初始化入口已关闭', 409)
    }

    const passwordHash = await hashPassword(password)
    const existing = await prisma.siteSetting.findFirst({ orderBy: { id: 'asc' } })

    if (existing) {
      await prisma.siteSetting.update({
        where: { id: existing.id },
        data: { username, passwordHash, requirePasswordChange: false },
      })
    } else {
      await prisma.siteSetting.create({
        data: { username, passwordHash, requirePasswordChange: false },
      })
    }

    // 使缓存失效，让登录立刻可用
    await updateCredentials(username, passwordHash, null, true).catch(() => {})

    return NextResponse.json({ success: true })
  } catch (error: any) {
    if (error instanceof ApiError) {
      const res = errorResponse(error, requestId)
      res.headers.set('X-Request-Id', requestId)
      return res
    }
    console.error('[Setup] Error:', error?.message)
    const res = errorResponse(new ApiError('SETUP_FAILED', '初始化失败，请稍后重试', 500), requestId)
    res.headers.set('X-Request-Id', requestId)
    return res
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { requireAuth } from '@/lib/auth-middleware'
import { requireCapability } from '@/lib/capability-guard'
import { handleReport, listReportsForAdmin, type ReportAction } from '@/lib/modules/social/moderation.service'
import { ApiError, errorResponse } from '@/lib/api-response'
import { parseBody, getRequestId } from '@/lib/api/handler'
import { ReportActionSchema, ReportListQuerySchema } from '@/lib/api/schemas/admin'

export const dynamic = 'force-dynamic'

/**
 * v3.1 M3-B2：举报治理处理。
 * GET  /api/admin/social/reports?status=PENDING&page=1&pageSize=20 → 举报列表（含帖子/作者）
 * POST /api/admin/social/reports/{id} { action } → 处理举报（驳回/下架/隐藏评论/封禁警告）
 */
export async function GET(request: NextRequest) {
  const auth = await requireAuth(request)
  if (!auth.authenticated) return NextResponse.json({ error: '未授权' }, { status: 401 })
  const denied = await requireCapability(auth.payload?.userId, 'canManageSocial')
  if (denied) return denied
  try {
    // P1-17：query 用 zod（status 枚举、page/pageSize coerce 正整数）
    const { searchParams } = new URL(request.url)
    const parsedQuery = ReportListQuerySchema.safeParse(Object.fromEntries(searchParams))
    if (!parsedQuery.success) {
      return errorResponse(new ApiError('INVALID_QUERY', '查询参数不合法', 400), getRequestId(request))
    }
    const status = parsedQuery.data.status
    const page = parsedQuery.data.page ?? 1
    const pageSize = parsedQuery.data.pageSize ?? 20
    const result = await listReportsForAdmin(status, page, pageSize)
    return NextResponse.json({ success: true, ...result })
  } catch (e) {
    console.error('[GET /api/admin/social/reports]', (e as Error)?.message)
    return NextResponse.json({ error: '获取举报列表失败' }, { status: 500 })
  }
}

export async function POST(request: NextRequest) {
  const auth = await requireAuth(request)
  if (!auth.authenticated) return NextResponse.json({ error: '未授权' }, { status: 401 })
  const denied = await requireCapability(auth.payload?.userId, 'canManageSocial')
  if (denied) return denied
  try {
    // P1-17：body 用 zod（reportId 正整数、action 枚举）
    const { reportId, action } = await parseBody(request, ReportActionSchema)
    const result = await handleReport(action as ReportAction, reportId)
    return NextResponse.json({ success: true, ...result })
  } catch (e: any) {
    if (e instanceof ApiError) return errorResponse(e, getRequestId(request))
    const msg = e?.message || '处理失败'
    return NextResponse.json({ error: msg }, { status: msg.includes('已处理') ? 409 : 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { requireAuth } from '@/lib/auth-middleware'
import { requireCapability } from '@/lib/capability-guard'
import { updateDay, deleteDay, findTravelIdByDayId, canManageTravel } from '@/lib/modules/travel/travel.service'
import { ApiError, errorResponse } from '@/lib/api-response'
import { parseBody, getRequestId } from '@/lib/api/handler'
import { IdSchema, TravelDayUpdateSchema } from '@/lib/api/schemas/admin'

export async function PUT(request: NextRequest, { params }: { params: Promise<{ id: string; dayId: string }> }) {
  const auth = await requireAuth(request)
  if (!auth.authenticated) {
    return NextResponse.json({ error: '未授权' }, { status: 401 })
  }
  const denied = await requireCapability(auth.payload?.userId, 'canManageContent')
  if (denied) return denied
  const { dayId } = await params
  const idParsed = IdSchema.safeParse(dayId)
  if (!idParsed.success) return errorResponse(new ApiError('INVALID_ID', '无效 ID', 400), getRequestId(request))
  const id = idParsed.data
  const travelId = await findTravelIdByDayId(id)
  if (!travelId || !(await canManageTravel(travelId, auth.payload?.userId))) {
    return NextResponse.json({ error: '旅行不存在或无权操作' }, { status: 404 })
  }
  try {
    // P1-17：更新 body 用 zod（date/title/summary 可选）
    const body = await parseBody(request, TravelDayUpdateSchema)
    await updateDay(id, body)
    return NextResponse.json({ success: true })
  } catch (error: any) {
    if (error instanceof ApiError) return errorResponse(error, getRequestId(request))
    return NextResponse.json({ error: error.message || '更新失败' }, { status: 400 })
  }
