import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { requireAuth } from '@/lib/auth-middleware'
import { requireCapability } from '@/lib/capability-guard'
import { listTravels, createTravel } from '@/lib/modules/travel/travel.service'
import { isSpaceContentEditor } from '@/lib/modules/access/space-scope'
import { writeAuditLog } from '@/lib/modules/audit/audit-log.service'
import { ApiError } from '@/lib/api-response'
import { withAuth, parseBody } from '@/lib/api/handler'
import { prisma } from '@/lib/db'
import { readIdempotencyKey, withIdempotency } from '@/lib/api/idempotency'

const TRAVEL_TYPES = ['ALONE', 'COUPLE', 'FAMILY', 'FRIENDS', 'BFF', 'GROUP', 'OTHER'] as const

/**
 * 创建旅行的请求体 schema（P1-17）：此前全靠手写 if，字段类型/长度/数组上限分散且易漏。
 * 成功响应保持不变（{ success, id, slug } 201）。
 */
const CompanionSchema = z.object({
  name: z.string().max(40).optional(),
  relation: z.string().max(20).optional(),
})

const CreateTravelSchema = z.object({
  title: z.string().trim().min(1, '请输入旅行名称').max(255, '旅行名称过长'),
  travelType: z.enum(TRAVEL_TYPES, { message: '旅行类型无效' }).optional().nullable(),
  companions: z.array(CompanionSchema).max(10, '同行者最多 10 人').optional().nullable(),
  spaceId: z.union([z.number(), z.string(), z.null()]).optional(),
  visibility: z.string().optional().nullable(),
  description: z.string().max(50_000, '描述过长').optional().nullable(),
  startDate: z.string().optional().nullable(),
  endDate: z.string().optional().nullable(),
  location: z.string().max(200).optional().nullable(),
})

/** 校验并归一化目的地：可选，最长 120 字（DB 列 255），去掉首尾空白 */
function normalizeLocation(raw: unknown): string | undefined {
  if (raw === undefined || raw === null) return undefined
  const v = String(raw).trim().slice(0, 120)
  return v || undefined
}

/** 校验并归一化同行者列表：[{ name, relation? }]，最多 10 人（空名条目不落库） */
function normalizeCompanions(raw: unknown): unknown[] | undefined {
  if (raw === undefined || raw === null) return undefined
  if (!Array.isArray(raw)) throw new ApiError('INVALID_COMPANIONS', '同行者格式无效', 400)
  if (raw.length > 10) throw new ApiError('INVALID_COMPANIONS', '同行者最多 10 人', 400)
  const out: { name: string; relation?: string }[] = []
  for (const item of raw) {
    const name = String((item as any)?.name || '').trim().slice(0, 40)
    if (!name) continue
    const relation = String((item as any)?.relation || '').trim().slice(0, 20)
    out.push(relation ? { name, relation } : { name })
  }
  return out.length > 0 ? out : undefined
}

export async function GET(request: NextRequest) {
  const auth = await requireAuth(request)
  if (!auth.authenticated) {
    return NextResponse.json({ error: '未授权' }, { status: 401 })
  }
  try {
    const travels = await listTravels(auth.payload?.userId)
    return NextResponse.json({ travels })
  } catch {
    return NextResponse.json({ travels: [] })
  }
}

export const POST = withAuth(async (request, ctx) => {
  const denied = await requireCapability(ctx.userId, 'canManageContent')
  if (denied) return denied

  const body = await parseBody(request, CreateTravelSchema)
  const companions = normalizeCompanions(body.companions)

  /**
   * 创建时就归属到某个空间（「一键加入空间」的落点）。
   * 必须校验我在该空间是 OWNER/MEMBER —— 只读成员不能往里塞内容，非成员更不能。
   */
  let spaceId: number | null = null
  if (body.spaceId !== undefined && body.spaceId !== null && body.spaceId !== '') {
    const n = Number(body.spaceId)
    if (!Number.isFinite(n) || n <= 0) {
      throw new ApiError('INVALID_SPACE_ID', '无效的空间 ID', 400)
    }
    const canPut = await isSpaceContentEditor(n, ctx.userId, ctx.username || '')
    if (!canPut) {
      throw new ApiError('SPACE_READONLY', '你在这个空间里是只读成员，不能往里添加内容', 403)
    }
    spaceId = n
  }

  const VISIBILITIES = ['PRIVATE', 'SPACE', 'PUBLIC']
  const rawVisibility = body.visibility ? String(body.visibility).toUpperCase() : ''
  const visibility = VISIBILITIES.includes(rawVisibility)
    ? (rawVisibility as 'PRIVATE' | 'SPACE' | 'PUBLIC')
    : // 未指定时：放进空间的默认「空间可见」，否则默认「仅自己」（与表单默认一致，更安全）
      spaceId
      ? 'SPACE'
      : 'PRIVATE'

  // B4：离线队列重试会带同一个 Idempotency-Key；命中直接返回首次创建的主键（绝不重复建旅行）
  const idempotencyKey = readIdempotencyKey(request)

  try {
    const idem = await withIdempotency({
      key: idempotencyKey,
      userId: ctx.userId,
      entityType: 'Travel',
      run: async () => {
        const result = await createTravel({
          title: body.title,
          description: body.description ? String(body.description) : undefined,
          startDate: body.startDate || undefined,
          endDate: body.endDate || undefined,
          location: normalizeLocation(body.location),
          ownerId: ctx.userId,
          isPublic: visibility === 'PUBLIC',
          visibility,
          spaceId,
          travelType: (body.travelType as any) || undefined,
          companions,
        })
        return { entityId: result.id, value: result.slug }
      },
    })

    if (idem.replayed) {
      // 重放：ClientMutation 只存 entityId，slug 回查一次（成功响应结构保持不变）
      const existing =
        idem.entityId != null
          ? await prisma.travel
              .findUnique({ where: { id: idem.entityId }, select: { slug: true } })
              .catch(() => null)
          : null
      return NextResponse.json({ success: true, id: idem.entityId, slug: existing?.slug ?? '' }, { status: 201 })
    }

    const entityId = idem.entityId as number
    writeAuditLog({
      username: ctx.username || 'unknown',
      action: 'CREATE',
      resourceType: 'Travel',
      resourceId: String(entityId),
      spaceId,
      metadata: { title: body.title, location: normalizeLocation(body.location) ?? null, visibility },
    }).catch(() => {})
    // 回传 slug：前台新建后直接跳 /travel/<slug>
    return NextResponse.json({ success: true, id: entityId, slug: idem.value ?? '' }, { status: 201 })
  } catch (error: any) {
    throw new ApiError('CREATE_FAILED', error?.message || '创建失败', 400)
  }
})

import { NextRequest, NextResponse } from 'next/server'
import { randomUUID } from 'crypto'
import fs from 'fs'
import os from 'os'
import path from 'path'
import { requireAuth } from '@/lib/auth-middleware'
import { isSiteOwner } from '@/lib/site-owner'
import { rateLimit } from '@/lib/infrastructure/rate-limit'
import { getClientIp } from '@/lib/request-utils'
import { validateVideoBuffer, MAX_VIDEO_SIZE } from '@/lib/infrastructure/media-validation'
import {
  RESUMABLE_CHUNK_SIZE,
  RESUMABLE_SESSION_TTL_MS,
  TRANSCODE_MIN_SIZE,
  isValidUploadId,
  totalChunksFor,
} from '@/lib/infrastructure/video-upload-shared'
import { enqueueTranscode, sweepAndEnqueue } from '@/lib/infrastructure/video-transcode'
import { writeAuditLog } from '@/lib/modules/audit/audit-log.service'
import { z } from 'zod'
import { ApiError, errorResponse } from '@/lib/api-response'
import { parseBody, getRequestId } from '@/lib/api/handler'

/** uploadId 仅接受 UUID 形态（防路径穿越）；与 video-upload-shared.isValidUploadId 同一判定 */
const UploadIdSchema = z.string().refine(isValidUploadId, { message: '无效 uploadId' })

/** 分片上传（multipart）：只校验字段形状，范围（< totalChunks）在读 meta 后判定 */
const ResumableChunkFormSchema = z.object({
  uploadId: UploadIdSchema,
  index: z.coerce.number().int('分片索引越界').min(0, '分片索引越界'),
  chunk: z.custom<File>((v) => v instanceof File, { message: '分片为空' }).refine((f) => f.size > 0, { message: '分片为空' }),
})

/** JSON 动作：action 判别联合（init/status/complete/abort/transcode-status） */
const ResumableJsonSchema = z.discriminatedUnion('action', [
  z.object({
    action: z.literal('init'),
    filename: z.string().max(255).optional(),
    // size 由路由内按字节范围校验（需保留中文文案），这里只要求是数字/数字字符串
    size: z.union([z.number(), z.string()]).optional(),
    mimeType: z.string().max(100).optional(),
  }),
  z.object({ action: z.literal('status'), uploadId: UploadIdSchema }),
  z.object({ action: z.literal('complete'), uploadId: UploadIdSchema }),
  z.object({ action: z.literal('abort'), uploadId: UploadIdSchema }),
  z.object({ action: z.literal('transcode-status'), filename: z.string().max(255).optional() }),
])

export const dynamic = 'force-dynamic'

/**
 * 视频断点续传（五动作单路由，action 区分）：
 * - init     JSON  { filename, size, mimeType } → { uploadId, chunkSize, totalChunks }
 * - status   JSON  { uploadId } → { uploaded: number[], totalChunks }（断点续传先问状态再续片）
 * - chunk    FormData { uploadId, index, chunk: File } → { received: true }
 * - complete JSON  { uploadId } → { url, filename, size, mimeType, transcode }
 * - abort    JSON  { uploadId } → 清理临时目录
 * - transcode-status JSON { filename } → { status, url? }（编辑器轮询，完成后切变体）
 *
 * 安全：uploadId 仅接受 UUID 形态（防路径穿越）；分片索引越界拒绝；完整文件过 Magic Number 校验；
 * 临时目录 24h TTL，init 时顺带清理过期会话。
 */
const VIDEO_DIR = path.join(process.cwd(), 'public', 'uploads', 'videos')
// 分片临时目录放容器本地盘：COSFS 是对象存储语义（unlink 后目录列表有最终一致性延迟，
// rmdir 会 ENOTEMPTY），且分片是纯瞬态数据——只有拼装完成的成品才写 COS。
const TMP_ROOT = path.join(os.tmpdir(), 'tn-vuploads')

function tmpDirOf(uploadId: string): string {
  return path.join(TMP_ROOT, uploadId)
}

interface SessionMeta {
  filename: string
  size: number
  mimeType: string
  chunkSize: number
  totalChunks: number
  createdAt: number
  username: string
}

function readMeta(uploadId: string): SessionMeta | null {
  try {
    const raw = fs.readFileSync(path.join(tmpDirOf(uploadId), 'meta.json'), 'utf8')
    return JSON.parse(raw) as SessionMeta
  } catch {
    return null
  }
}

function uploadedChunks(uploadId: string, totalChunks: number): number[] {
  try {
    return fs
      .readdirSync(tmpDirOf(uploadId))
      .filter((n) => n.endsWith('.part'))
      .map((n) => parseInt(n.replace('.part', ''), 10))
      .filter((n) => Number.isInteger(n) && n >= 0 && n < totalChunks)
      .sort((a, b) => a - b)
  } catch {
    return []
  }
}

function cleanupStaleSessions(): void {
  try {
    if (!fs.existsSync(TMP_ROOT)) return
    const now = Date.now()
    for (const dir of fs.readdirSync(TMP_ROOT)) {
      const meta = readMeta(dir)
      if (meta && now - meta.createdAt > RESUMABLE_SESSION_TTL_MS) {
        fs.rmSync(path.join(TMP_ROOT, dir), { recursive: true, force: true })
      }
    }
  } catch {
    // 清理失败不影响主流程
  }
}

function sanitizeBase(filename: string): string {
  return path.basename(filename).replace(/[^\w.\-\u4e00-\u9fa5]+/g, '_').slice(0, 120)
}

export async function POST(request: NextRequest) {
  const auth = await requireAuth(request)
  if (!auth.authenticated) {
    return NextResponse.json({ error: '未授权' }, { status: 401 })
  }
  // P0：站点级视频上传只允许站点主人
  if (!(await isSiteOwner(auth.payload?.userId))) {
    return NextResponse.json({ error: '当前角色无权执行该操作' }, { status: 403 })
  }

  const ip = getClientIp(request)
  const contentType = request.headers.get('content-type') || ''

  try {
    // ---------- 分片上传（multipart） ----------
    if (contentType.includes('multipart/form-data')) {
      const limit = rateLimit({ prefix: 'vchunk:ip', key: ip || 'unknown', limit: 600, windowMs: 15 * 60 * 1000 })
      if (!limit.ok) {
        return NextResponse.json({ error: '上传过于频繁，请稍后再试' }, { status: 429 })
      }
      // P1-17：multipart 不套 parseBody(JSON)，按字段形状做 zod 校验
      const form = await request.formData()
      const parsedForm = ResumableChunkFormSchema.safeParse({
        uploadId: form.get('uploadId'),
        index: form.get('index'),
        chunk: form.get('chunk'),
      })
      if (!parsedForm.success) {
        return errorResponse(
          new ApiError('VALIDATION_ERROR', parsedForm.error.issues[0]?.message || '无效 uploadId', 400),
          getRequestId(request),
        )
      }
      const uploadId = parsedForm.data.uploadId
      const index = parsedForm.data.index
      const chunk = parsedForm.data.chunk
      const meta = readMeta(uploadId)
      if (!meta) return NextResponse.json({ error: '会话不存在或已过期，请重新上传' }, { status: 404 })
      if (!Number.isInteger(index) || index < 0 || index >= meta.totalChunks) {
        return NextResponse.json({ error: '分片索引越界' }, { status: 400 })
      }
      if (!chunk || chunk.size === 0) {
        return NextResponse.json({ error: '分片为空' }, { status: 400 })
      }
      const dir = tmpDirOf(uploadId)
      fs.writeFileSync(path.join(dir, `${index}.part`), Buffer.from(await chunk.arrayBuffer()))
      return NextResponse.json({ received: true, index })
    }

    // ---------- JSON 动作 ----------
    // P1-17：action 用 zod 判别联合统一校验（uploadId 必须是合法 UUID）
    const body = await parseBody(request, ResumableJsonSchema)
    const action = body.action

    if (action === 'init') {
      const limit = rateLimit({ prefix: 'vinit:ip', key: ip || 'unknown', limit: 60, windowMs: 15 * 60 * 1000 })
      if (!limit.ok) {
        return NextResponse.json({ error: '上传过于频繁，请稍后再试' }, { status: 429 })
      }
      const size = Number(body.action === 'init' ? body.size : NaN)
      const filename = sanitizeBase(String(body.action === 'init' ? body.filename || 'video' : 'video'))
      if (!Number.isFinite(size) || size <= 0 || size > MAX_VIDEO_SIZE) {
        return NextResponse.json(
          { error: `视频大小非法（需 0 < size ≤ ${Math.round(MAX_VIDEO_SIZE / 1024 / 1024)}MB）` },
          { status: 400 },
        )
      }
      cleanupStaleSessions()
      sweepAndEnqueue()
      fs.mkdirSync(TMP_ROOT, { recursive: true })
      const uploadId = randomUUID()
      const meta: SessionMeta = {
        filename,
        size,
        mimeType: String(body.mimeType || 'video/mp4').slice(0, 100),
        chunkSize: RESUMABLE_CHUNK_SIZE,
        totalChunks: totalChunksFor(size),
        createdAt: Date.now(),
        username: auth.username || 'unknown',
      }
      fs.mkdirSync(tmpDirOf(uploadId), { recursive: true })
      fs.writeFileSync(path.join(tmpDirOf(uploadId), 'meta.json'), JSON.stringify(meta))
      return NextResponse.json({ uploadId, chunkSize: meta.chunkSize, totalChunks: meta.totalChunks })
    }

    if (action === 'status') {
      if (body.action !== 'status') return NextResponse.json({ error: '未知 action' }, { status: 400 })
      const meta = readMeta(body.uploadId)
      if (!meta) return NextResponse.json({ exists: false })
      return NextResponse.json({
        exists: true,
        totalChunks: meta.totalChunks,
        uploaded: uploadedChunks(body.uploadId, meta.totalChunks),
      })
    }

    if (action === 'complete') {
      if (body.action !== 'complete') return NextResponse.json({ error: '未知 action' }, { status: 400 })
      const meta = readMeta(body.uploadId)
      if (!meta) return NextResponse.json({ error: '会话不存在或已过期' }, { status: 404 })
      const dir = tmpDirOf(body.uploadId)
      const uploaded = uploadedChunks(body.uploadId, meta.totalChunks)
      if (uploaded.length !== meta.totalChunks) {
        return NextResponse.json(
          { error: `分片不完整（${uploaded.length}/${meta.totalChunks}）`, uploaded },
          { status: 400 },
        )
      }

      fs.mkdirSync(VIDEO_DIR, { recursive: true })
      const extMap: Record<string, string> = { 'video/mp4': 'mp4', 'video/webm': 'webm', 'video/ogg': 'ogg' }
      const ext = extMap[meta.mimeType] || 'mp4'
      const finalName = `${Date.now()}-${sanitizeBase(meta.filename).replace(/\.(mp4|webm|ogg)$/i, '')}-${randomUUID().slice(0, 8)}.${ext}`
      const finalPath = path.join(VIDEO_DIR, finalName)

      // 顺序拼装 + Magic Number 校验（读头部，不整文件入内存）
      const write = fs.createWriteStream(finalPath)
      for (let i = 0; i < meta.totalChunks; i++) {
        const partPath = path.join(dir, `${i}.part`)
        await new Promise<void>((resolve, reject) => {
          const rs = fs.createReadStream(partPath)
          rs.on('error', reject)
          rs.on('end', resolve)
          rs.pipe(write, { end: false })
        })
      }
      await new Promise<void>((resolve) => write.end(resolve))

      let realMime = meta.mimeType
      try {
        const fd = fs.openSync(finalPath, 'r')
        const header = Buffer.alloc(4096)
        fs.readSync(fd, header, 0, 4096, 0)
        fs.closeSync(fd)
        realMime = validateVideoBuffer(header, meta.mimeType)
      } catch (err: any) {
        try { fs.unlinkSync(finalPath) } catch {}
        try { fs.rmSync(dir, { recursive: true, force: true }) } catch {}
        return NextResponse.json({ error: `文件校验失败: ${err.message}` }, { status: 400 })
      }

      try { fs.rmSync(dir, { recursive: true, force: true }) } catch (e) {
        // 清理是尽力而为（本地盘）；残留会话由 init 的 24h TTL 清扫兜底
        console.warn('[Video Resumable] 临时目录清理失败:', (e as Error).message)
      }
      const stat = fs.statSync(finalPath)

      let transcode: 'queued' | 'skipped' = 'skipped'
      if (stat.size >= TRANSCODE_MIN_SIZE) {
        enqueueTranscode(finalName)
        transcode = 'queued'
      }

      writeAuditLog({
        username: auth.username || 'unknown',
        action: 'UPLOAD_MEDIA',
        resourceType: 'Video',
        resourceId: finalName,
        ip,
        metadata: { size: stat.size, resumable: true },
      }).catch(() => {})

      return NextResponse.json({
        url: `/uploads/videos/${finalName}`,
        filename: finalName,
        size: stat.size,
        mimeType: realMime,
        transcode,
      })
    }

    if (action === 'abort') {
      if (body.action !== 'abort') return NextResponse.json({ error: '未知 action' }, { status: 400 })
      fs.rmSync(tmpDirOf(body.uploadId), { recursive: true, force: true })
      return NextResponse.json({ aborted: true })
    }

    if (action === 'transcode-status') {
      const filename = path.basename(String(body.action === 'transcode-status' ? body.filename || '' : ''))
      if (!filename) return NextResponse.json({ status: 'none' })
      // 直接复用 transcode 模块的状态判定
      const { getTranscodeStatus } = await import('@/lib/infrastructure/video-transcode')
      return NextResponse.json(getTranscodeStatus(filename))
    }

    return NextResponse.json({ error: '未知 action' }, { status: 400 })
  } catch (error: any) {
    if (error instanceof ApiError) return errorResponse(error, getRequestId(request))
    console.error('[Video Resumable] Error:', error?.message, error?.stack)
    return NextResponse.json({ error: error.message || '上传失败' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { randomUUID } from 'crypto'
import { requireAuth } from '@/lib/auth-middleware'
import { isSiteOwner } from '@/lib/site-owner'
import { logger } from '@/lib/infrastructure/logger'
import fs from 'fs'
import path from 'path'
import { pipeline } from 'stream/promises'
import { Readable } from 'stream'
import {
  validateVideoBuffer,
  MAX_VIDEO_SIZE,
  MAX_VIDEO_COUNT,
} from '@/lib/infrastructure/media-validation'
import { rateLimit } from '@/lib/infrastructure/rate-limit'
import { getClientIp } from '@/lib/request-utils'
import { writeAuditLog } from '@/lib/modules/audit/audit-log.service'
import { enqueueTranscode, sweepAndEnqueue } from '@/lib/infrastructure/video-transcode'
import { TRANSCODE_MIN_SIZE } from '@/lib/infrastructure/video-upload-shared'
import { z } from 'zod'
import { ApiError, errorResponse } from '@/lib/api-response'
import { parseBody, getRequestId } from '@/lib/api/handler'

/** 批量视频上传：multipart 表单，只校验 files 形状（魔数/大小由 media-validation 校验） */
const VideoUploadSchema = z.object({
  files: z
    .array(z.custom<File>((v) => v instanceof File, { message: '文件格式无效' }))
    .min(1, '未上传任何文件')
    .max(MAX_VIDEO_COUNT, `单次最多上传 ${MAX_VIDEO_COUNT} 个视频`),
})

/** 删除视频：只接受本地上传目录下的路径 */
const VideoDeleteSchema = z.object({
  url: z.string().min(1, '无效的文件路径').regex(/^\/uploads\/videos\//, '无效的文件路径'),
})

function getVideoDir(): string {
  const cwd = process.cwd()
  return path.join(cwd, 'public', 'uploads', 'videos')
}

function formatDuration(seconds: number): string {
  if (seconds <= 0) return '00:00'
  const h = Math.floor(seconds / 3600)
  const m = Math.floor((seconds % 3600) / 60)
  const s = Math.floor(seconds % 60)
  if (h > 0) {
    return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
  }
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
}

/** 读取文件头部若干字节用于 Magic Number 校验，避免整文件载入内存 */
async function readFileHeader(file: File, bytes = 4096): Promise<Buffer> {
  const slice = file.slice(0, bytes)
  return Buffer.from(await slice.arrayBuffer())
}

export async function POST(request: NextRequest) {
  const auth = await requireAuth(request)
  if (!auth.authenticated) {
    return NextResponse.json({ error: '未授权' }, { status: 401 })
  }
  // P0：站点级视频上传只允许站点主人（普通用户的旅行视频走 travel 媒体管线）
  if (!(await isSiteOwner(auth.payload?.userId))) {
    return NextResponse.json({ error: '当前角色无权执行该操作' }, { status: 403 })
  }

  try {
    // 上传限流：IP 每 15 分钟最多 60 次视频上传请求
    const ip = getClientIp(request)
    const limit = rateLimit({ prefix: 'video-upload:ip', key: ip || 'unknown', limit: 60, windowMs: 15 * 60 * 1000 })
    if (!limit.ok) {
      return NextResponse.json(
        { error: '上传过于频繁，请稍后再试', retryAfterSeconds: limit.retryAfterSeconds },
        { status: 429 }
      )
    }

    // P1-17：multipart 不套 parseBody(JSON)，按字段形状做 zod 校验
    const formData = await request.formData()
    const parsedForm = VideoUploadSchema.safeParse({ files: formData.getAll('files') })
    if (!parsedForm.success) {
      return errorResponse(
        new ApiError('VALIDATION_ERROR', parsedForm.error.issues[0]?.message || '未上传任何文件', 400),
        getRequestId(request),
      )
    }
    const files = parsedForm.data.files

    const videoDir = getVideoDir()
    if (!fs.existsSync(videoDir)) {
      fs.mkdirSync(videoDir, { recursive: true })
    }

    const results: Array<{
      url: string
      filename: string
      size: number
      duration?: string
      mimeType: string
    }> = []

    const timestamp = Date.now()

    for (let i = 0; i < files.length; i++) {
      const file = files[i]
      logger.info('video-upload', 'processing', { name: file.name, type: file.type, size: file.size })

      if (file.size > MAX_VIDEO_SIZE) {
        return NextResponse.json(
          { error: `视频文件过大: ${file.name} 超过 ${Math.round(MAX_VIDEO_SIZE / 1024 / 1024)}MB` },
          { status: 400 }
        )
      }

      if (file.size === 0) {
        return NextResponse.json(
          { error: `文件为空: ${file.name}` },
          { status: 400 }
        )
      }

      // Magic Number 校验：不信任客户端 MIME
      let realMime: string
      try {
        const header = await readFileHeader(file)
        realMime = validateVideoBuffer(header, file.type || undefined)
      } catch (err: any) {
        return NextResponse.json(
          { error: `${file.name}: ${err.message}` },
          { status: 400 }
        )
      }

      const extMap: Record<string, string> = {
        'video/mp4': 'mp4',
        'video/webm': 'webm',
        'video/ogg': 'ogg',
      }

      const ext = extMap[realMime] || 'mp4'
      const filename = `${timestamp}-${i}-${randomUUID().slice(0, 8)}.${ext}`
      const filePath = path.join(videoDir, filename)

      const stream = file.stream()
      const readable = Readable.fromWeb(stream as any)
      const writeStream = fs.createWriteStream(filePath)

      await pipeline(readable, writeStream)

      const stat = fs.statSync(filePath)
      const url = `/uploads/videos/${filename}`

      results.push({
        url,
        filename,
        size: stat.size,
        mimeType: realMime,
      })

      logger.info('video-upload', 'saved', { url, size: stat.size })

      // 转码管线：大视频入队生成 720p 变体（后台执行，不阻塞响应）
      if (stat.size >= TRANSCODE_MIN_SIZE) {
        enqueueTranscode(filename)
      }
    }

    sweepAndEnqueue()

    writeAuditLog({
      username: auth.username || 'unknown',
      action: 'UPLOAD_MEDIA',
      resourceType: 'Video',
      ip,
      metadata: { count: results.length },
    }).catch(() => {})
    return NextResponse.json({
      success: true,
      videos: results,
    })
  } catch (error: any) {
    logger.error('video-upload', 'error', { message: error?.message, stack: error?.stack })
    return NextResponse.json(
      { error: error.message || '视频上传失败' },
      { status: 500 }
    )
  }
}

export async function DELETE(request: NextRequest) {
  const auth = await requireAuth(request)
  if (!auth.authenticated) {
    return NextResponse.json({ error: '未授权' }, { status: 401 })
  }
  // P0：站点级视频上传只允许站点主人（普通用户的旅行视频走 travel 媒体管线）
  if (!(await isSiteOwner(auth.payload?.userId))) {
    return NextResponse.json({ error: '当前角色无权执行该操作' }, { status: 403 })
  }

  try {
    // P1-17：body 用 zod（只接受 /uploads/videos/ 前缀，防路径穿越/任意删文件）
    const { url } = await parseBody(request, VideoDeleteSchema)

    const videoDir = getVideoDir()
    const filePath = path.join(videoDir, path.basename(url))

    logger.info('video-upload', 'delete-start', { filePath })

    if (fs.existsSync(filePath)) {
      fs.unlinkSync(filePath)
      logger.info('video-upload', 'deleted')
    } else {
      logger.warn('video-upload', 'delete-miss', { filePath })
    }

    return NextResponse.json({ success: true })
  } catch (error: any) {
    if (error instanceof ApiError) return errorResponse(error, getRequestId(request))
    logger.error('video-upload', 'delete-error', { message: error?.message })
    return NextResponse.json(
      { error: error.message || '删除失败' },
      { status: 500 }
    )
  }
}

import { NextResponse } from 'next/server'
import { getPostService } from '@/lib/container'
import { listAlbums } from '@/lib/modules/album/album.service'
import { findProvinceByLocation } from '@/lib/province-map'
import { findCityByName } from '@/data/cities'
import { verifyAlbumToken, ALBUM_COOKIE } from '@/lib/album-auth'
import { getCurrentUser } from '@/lib/current-user'
import { applyCacheControl } from '@/lib/http-cache'

export const dynamic = 'force-dynamic'

interface CityDay {
  date: string
  title: string
  images: string[]
  /** 内部去重用，响应前剥离 */
  seen: Set<string>
}

interface CityAlbumPayload {
  name: string
  province: string
  provinceId: string
  images: string[]
  date: string
  postSlug: string
  days: CityDay[]
  /** 内部去重用，响应前剥离 */
  seen: Set<string>
}

export async function GET(request: Request) {
  const cookieHeader = request.headers.get('cookie') || ''
  const tokenMatch = cookieHeader.match(new RegExp(`${ALBUM_COOKIE}=([^;]+)`))
  const token = tokenMatch ? decodeURIComponent(tokenMatch[1]) : undefined

  const isValid = await verifyAlbumToken(token)
  if (!isValid) {
    return NextResponse.json({ error: '相册已上锁，请先在登录页解锁' }, { status: 403 })
  }

  try {
    const postService = getPostService()
    const currentUser = await getCurrentUser()
    const userId = currentUser?.id ?? null
    const posts = await postService.getPostsHybrid('travel', userId)

    const cityMap = new Map<string, CityAlbumPayload>()

    for (const post of posts) {
      if (!post.location) continue

      const city = findCityByName(post.location)
      const province = findProvinceByLocation(post.location)
      if (!city) continue

      const seen = new Set<string>()
      const images: string[] = []
      if (post.cover) {
        seen.add(post.cover)
        images.push(post.cover)
      }
      if (post.images && post.images.length > 0) {
        for (const img of post.images) {
          if (img && !seen.has(img)) {
            seen.add(img)
            images.push(img)
          }
        }
      }
      if (images.length === 0) continue

      const key = city.name
      const day: CityDay = {
        date: post.date,
        title: post.title || `旅行记录`,
        images,
        seen: new Set(images),
      }

      if (!cityMap.has(key)) {
        cityMap.set(key, {
          name: city.name,
          province: province?.name || '',
          provinceId: province?.id || '',
          images: [...images],
          date: post.date,
          postSlug: post.slug,
          days: [day],
          seen: new Set(images),
        })
      } else {
        const existing = cityMap.get(key)!
        for (const img of images) {
          if (!existing.seen.has(img)) {
            existing.seen.add(img)
            existing.images.push(img)
          }
        }
        const sameDay = existing.days.find((d) => d.date === post.date)
        if (sameDay) {
          for (const img of images) {
            if (!sameDay.seen.has(img)) {
              sameDay.seen.add(img)
              sameDay.images.push(img)
            }
          }
        } else {
          existing.days.push(day)
        }
      }
    }

    // 每个城市的 DAY 按日期升序排列（从旅行第一天到最后一天）
    for (const city of Array.from(cityMap.values())) {
      city.days.sort((a: CityDay, b: CityDay) => new Date(a.date).getTime() - new Date(b.date).getTime())
    }

    const cities = Array.from(cityMap.values())
      .map((c) => ({
        name: c.name,
        province: c.province,
        provinceId: c.provinceId,
        images: c.images,
        date: c.date,
        postSlug: c.postSlug,
        days: c.days.map(({ seen, ...d }) => d),
      }))
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())

    const albums = await listAlbums(userId, currentUser?.username)

    const res = NextResponse.json({
      cities,
      albums,
      totalPosts: posts.length,
    })
    // 相册为私人内容（纪念日锁保护），只允许浏览器私有缓存，不进共享缓存
    return applyCacheControl(res, 'private', !!userId)
  } catch (error) {
    console.error('[Album API] Failed:', error)
    return NextResponse.json({ error: '获取相册数据失败' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { getCurrentUserId } from '@/lib/current-user'
import { listAnniversaries } from '@/lib/modules/anniversary/anniversary.service'

export const dynamic = 'force-dynamic'

/**
 * 纪念日列表（P1-14）。
 *
 * 此前：不传 userId 调用 listAnniversaries()，scopedWhere(undefined) 返回 {} = 不限制，
 * 匿名请求能拿到全部纪念日的标题/日期/描述（评审 S-13）。
 * 现在：登录用户返回「自己的 + 公开的」，匿名只返回 isPublic 的。
 * 登录门的封条日期改走 /api/anniversaries/seal（只给 month/day）。
 */
