import { NextResponse } from 'next/server'
import { prisma } from '@/lib/db'
import { skipDbOnBuild } from '@/lib/db-guard'

export const dynamic = 'force-dynamic'

/**
 * 登录门封条日期（P1-14 新增）：只返回**最早一条公开纪念日**的 month/day。
 *
 * 为什么不复用 /api/anniversaries：那里的最小粒度是整条记录（标题/描述/完整日期），
 * 而登录门只需要「月.日」来盖章。独立端点把信息面收到最小：
 * 不返回标题、不返回描述、不返回年份（年份本身能推断关系开始时间）。
 * 没有公开纪念日时返回 month/day = null，前端回退「启程」。
 */
export async function GET() {
  try {
    // 构建期无数据库：返回 null，前端回退默认封条
    if (skipDbOnBuild()) return NextResponse.json({ month: null, day: null })

    const first = await prisma.anniversary.findFirst({
      where: { isPublic: true },
      orderBy: { date: 'asc' },
      select: { date: true },
    })
    if (!first) return NextResponse.json({ month: null, day: null })
    return NextResponse.json({ month: first.date.getMonth() + 1, day: first.date.getDate() })
  } catch (error: any) {
    console.error('[GET /api/anniversaries/seal] Error:', error?.message)
    return NextResponse.json({ month: null, day: null })
  }
}

import { NextResponse } from 'next/server'
import { requireAuth } from '@/lib/auth-middleware'
import { getAuthService } from '@/lib/container'
import { sessionCookieOptions } from '@/lib/auth-utils'
import { isAppClientRequest } from '@/lib/request-utils'
import { APP_SESSION_SECONDS, APP_SESSION_RENEW_BEFORE_SECONDS } from '@/lib/services/auth-service'

export const dynamic = 'force-dynamic'

/**
 * 登录态探测 + App 会话静默续期（P1-10）。
 *
 * 背景：App 登录会话 TTL 从 365 天收紧到 90 天后，若不续期，用户每 90 天被踢出一次
 * （真机体验不可接受）。这里在**会话仍然有效**且剩余 < 30 天时，用同一 sid
 * 重签 JWT 并 Set-Cookie，同时延长数据库会话有效期 —— 客户端无感，撤销语义不变。
 *
 * 仅对 App 客户端续期（Web 会话 5h/7d，不需要也不应该被延长到 90 天）；
 * 客户端判定见 lib/request-utils.ts:isAppClientRequest（无请求体的 GET 无法读 clientType，
 * 用 Origin/X-Client-Type/查询参数识别 Capacitor 壳）。
 */
export async function GET(request: Request) {
  const auth = await requireAuth(request as any)
  if (!auth.authenticated) {
    // 数据库不可用是「暂时无法判断」而不是「未登录」：返回 503，避免客户端误清登录态
    if (auth.databaseUnavailable) {
      return NextResponse.json({ authenticated: false, error: '服务暂时不可用' }, { status: 503 })
    }
    return NextResponse.json({ authenticated: false }, { status: 200 })
  }

  const response = NextResponse.json({ authenticated: true, username: auth.username })

  const sid = auth.payload?.sid
  const exp = typeof auth.payload?.exp === 'number' ? auth.payload.exp : 0
  const remainingMs = exp * 1000 - Date.now()
  const appClient = isAppClientRequest(request)

  if (appClient && sid && remainingMs > 0 && remainingMs < APP_SESSION_RENEW_BEFORE_SECONDS * 1000) {
    try {
      const token = await getAuthService().renewSession(sid, APP_SESSION_SECONDS)
      if (token) {
        // Cookie 属性与 app/api/login/route.ts 的 App 分支完全一致（SameSite=None + Secure）
        response.cookies.set('admin_session', token, sessionCookieOptions('app', APP_SESSION_SECONDS))
        response.headers.set('X-Session-Renewed', '1')
      }
    } catch (error) {
      // 续期失败不影响本次登录态判定（本次请求已通过认证），下次 check-auth 再试
      console.error('[GET /api/check-auth] App 会话续期失败:', (error as Error)?.message || error)
    }
  }

  return response
}

import { NextRequest } from 'next/server'
import { prisma } from '@/lib/db'
import { ok, fail, unauthorized } from '@/lib/api-response'
import { requireAuth } from '@/lib/auth-middleware'
import { applyCacheControl } from '@/lib/http-cache'
import { rateLimit } from '@/lib/infrastructure/rate-limit'
import { getClientIp } from '@/lib/request-utils'
import { z } from 'zod'
import { ApiError, errorResponse } from '@/lib/api-response'
import { parseBody, getRequestId } from '@/lib/api/handler'
import { IdSchema } from '@/lib/api/schemas/admin'

/** 发弹幕：内容非空 ≤50 字，颜色仅接受 #RGB/#RRGGBB（防注入样式） */
const DanmakuCreateSchema = z.object({
  text: z.string().trim().min(1, '留言内容不能为空').max(50, '留言内容不能超过50字'),
  color: z
    .string()
    .regex(/^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/, '颜色格式不合法')
    .optional(),
})

// 公开接口：获取全部弹幕（从最近到最早）
export async function GET() {
  try {
    const list = await prisma.danmaku.findMany({
      orderBy: { createdAt: 'desc' },
      take: 200,
    })

    const danmakus = list.map((d) => ({
      id: d.id.toString(),
      text: d.text,
      color: d.color,
      timestamp: d.createdAt.getTime(),
    }))

    const res = ok({ danmakus })
    return applyCacheControl(res, 'public', false)
  } catch (error: any) {
    console.error('[GET /api/danmaku] Error:', error?.message)
    return ok({ danmakus: [] })
  }
}

// 公开接口：写入一条新弹幕
export async function POST(request: NextRequest) {
  try {
    // 阶段 A · A6：公开写接口按 IP 限流，防止刷弹幕
    const ip = getClientIp(request)
    const limit = rateLimit({ prefix: 'danmaku:ip', key: ip || 'unknown', limit: 10, windowMs: 60_000 })
    if (!limit.ok) {
      return fail('发送过于频繁，请稍后再试', 429)
    }

    // P1-17：body 用 zod（内容非空/≤50 字、颜色白名单格式）
    const body = await parseBody(request, DanmakuCreateSchema)
    const text = body.text
    const color = body.color || '#E4B478'

    const created = await prisma.danmaku.create({
      data: {
        text,
        color,
      },
    })

    return ok({
      danmaku: {
        id: created.id.toString(),
        text: created.text,
        color: created.color,
        timestamp: created.createdAt.getTime(),
      },
    })
  } catch (error: any) {
    if (error instanceof ApiError) return errorResponse(error, getRequestId(request))
    console.error('[POST /api/danmaku] Error:', error?.message)
    return fail(error.message || '发送失败', 500)
  }
}

// 需认证：删除一条弹幕
export async function DELETE(request: NextRequest) {
  const auth = await requireAuth(request)
  if (!auth.authenticated) {
    return unauthorized('未授权')
  }

  try {
    // P1-17：DELETE 无 body，用 query schema（id coerce 正整数）
    const { searchParams } = new URL(request.url)
    const idParsed = IdSchema.safeParse(searchParams.get('id'))
    if (!idParsed.success) {
      return errorResponse(new ApiError('INVALID_ID', '缺少弹幕ID', 400), getRequestId(request))
    }
    const id = idParsed.data

    await prisma.danmaku.delete({ where: { id } })
    return ok({ deleted: true })
  } catch (error: any) {
    if (error instanceof ApiError) return errorResponse(error, getRequestId(request))
    console.error('[DELETE /api/danmaku] Error:', error?.message)
    return fail(error.message || '删除失败', 500)
  }
}

