import { NextRequest } from 'next/server'
import { prismaImageRepository } from '@/lib/repositories/image-repository'
import { parseExif, toPublicExif, type PublicExifData } from '@/lib/exif'
import { checkPostImageVisibility } from '../image-visibility'
import { ok, fail, serverError, notFound } from '@/lib/api-response'

export const dynamic = 'force-dynamic'

// 简单内存缓存：EXIF 解析结果复用，避免重复读取大图字节。
// 只缓存**白名单化之后**的数据（PublicExifData）：即便将来解析器新增字段，
// 也不会把 GPS / 设备序列号之类的隐私字段带出去（P0-4）。
const cache = new Map<string, PublicExifData | null>()
const CACHE_MAX = 500

export async function GET(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id: idParam } = await params
    const id = parseInt(idParam, 10)
    if (isNaN(id)) {
      return fail('无效的图片 ID')
    }

    const image = await prismaImageRepository.findById(id)
    if (!image) {
      return notFound('图片不存在')
    }

    // P0-4：与 /api/images/[id] 同一可见性口径 —— 草稿/私密文章的图，
    // 匿名与其他用户都拿不到（统一 404，不泄露存在性）
    const visibility = await checkPostImageVisibility(request, image.postId)
    if (!visibility.allowed) {
      return notFound('图片不存在')
    }

    const cacheKey = 'exif:' + id
    if (cache.has(cacheKey)) {
      return ok({ exif: cache.get(cacheKey) })
    }

    let exif: PublicExifData | null = null
    try {
      // 白名单化：只保留宽高 / 方向 / 拍摄时间，GPS 与设备序列号一律不下发
      exif = toPublicExif(parseExif(image.data))
    } catch {
      exif = null
    }

    if (cache.size >= CACHE_MAX) {
      const firstKey = cache.keys().next().value
      if (firstKey) cache.delete(firstKey)
    }
    cache.set(cacheKey, exif)

    return ok({ exif })
  } catch (error: any) {
    console.error('[GET /api/images/[id]/meta] Error:', error?.message || error)
    return serverError()
  }
}

import { NextRequest } from 'next/server'
import { getLikeService } from '@/lib/container'
import { ok, fail, serverError, ApiError, errorResponse } from '@/lib/api-response'
import { parseBody, getRequestId } from '@/lib/api/handler'
import { z } from 'zod'

export const dynamic = 'force-dynamic'

const TargetTypeSchema = z.enum(['post', 'moment'], { message: '参数不完整：targetType/targetId 必填' })
/** targetId 兼容数字/字符串（旧客户端两种都传），统一转字符串 */
const TargetIdSchema = z.union([z.string().min(1), z.number()]).transform((v) => String(v))

/** 点赞切换（POST） */
const LikeToggleSchema = z.object({
  targetType: TargetTypeSchema,
  targetId: TargetIdSchema,
  visitorId: z.string().trim().min(1, '缺少访客标识').max(128, '访客标识过长'),
})

/** 点赞状态查询（GET query） */
const LikeStateQuerySchema = z.object({
  targetType: TargetTypeSchema,
  targetId: TargetIdSchema,
  visitorId: z.string().trim().max(128).optional(),
})

export async function GET(request: NextRequest) {
  try {
    // P1-17：query 用 zod（targetType 枚举、targetId 非空）
    const { searchParams } = new URL(request.url)
    const parsedQuery = LikeStateQuerySchema.safeParse(Object.fromEntries(searchParams))
    if (!parsedQuery.success) {
      return errorResponse(
        new ApiError('VALIDATION_ERROR', parsedQuery.error.issues[0]?.message || '参数不完整：targetType/targetId 必填', 400),
        getRequestId(request),
      )
    }
    const { targetType, targetId, visitorId } = parsedQuery.data

    const likeService = getLikeService()
    const state = await likeService.getState(targetType, targetId, visitorId)
    return ok(state)
  } catch (error: any) {
    console.error('[GET /api/likes] Error:', error?.message || error)
    return serverError()
  }
}

export async function POST(request: NextRequest) {
  try {
    // P1-17：body 用 zod（targetType 枚举、targetId 非空、visitorId 必填）
    const { targetType, targetId, visitorId } = await parseBody(request, LikeToggleSchema)

    const likeService = getLikeService()
    const state = await likeService.toggle(targetType, targetId, visitorId)
    return ok(state)
  } catch (error: any) {
    if (error instanceof ApiError) return errorResponse(error, getRequestId(request))
    console.error('[POST /api/likes] Error:', error?.message || error)
    if (error?.message?.includes('访客标识')) {
      return fail(error.message)
    }
    return serverError()
  }
}

import { NextRequest } from 'next/server'
import { mkdir, writeFile, unlink } from 'fs/promises'
import path from 'path'
import sharp from 'sharp'
import { getCurrentUserId } from '@/lib/current-user'
import { updateMyAvatar, getMyProfile } from '@/lib/modules/social/profile.service'
import { avatarFilePaths } from '@/lib/modules/social/avatar-variants'
import { ok, unauthorized, serverError, ApiError, errorResponse } from '@/lib/api-response'
import { getRequestId } from '@/lib/api/handler'
import { z } from 'zod'

export const dynamic = 'force-dynamic'

const MAX_AVATAR_BYTES = 5 * 1024 * 1024

/** 头像上传：multipart 表单，只校验文件形状/类型/大小（内容由 sharp 重编码） */
const AvatarFormSchema = z.object({
  avatar: z
    .custom<File>((v) => v instanceof File, { message: '请选择头像图片' })
    .refine((f) => f.type.startsWith('image/'), { message: '仅支持图片文件' })
    .refine((f) => f.size > 0, { message: '图片为空' })
    .refine((f) => f.size <= MAX_AVATAR_BYTES, { message: '头像图片不能超过 5MB' }),
})

export async function POST(request: NextRequest) {
  const userId = await getCurrentUserId()
  if (!userId) return unauthorized()

  try {
    // P1-17：multipart 不套 parseBody(JSON)，按字段形状做 zod 校验（类型/大小）
    const formData = await request.formData()
    const parsedForm = AvatarFormSchema.safeParse({ avatar: formData.get('avatar') })
    if (!parsedForm.success) {
      throw new ApiError('VALIDATION_ERROR', parsedForm.error.issues[0]?.message || '请选择头像图片', 400)
    }
    const file = parsedForm.data.avatar
    const buffer = Buffer.from(await file.arrayBuffer())

    const dir = path.join(process.cwd(), 'public', 'uploads', 'avatars')
    await mkdir(dir, { recursive: true })

    // 主图 256×256（列表/评论），preview 1024×1024（个人主页高分屏），blur 16px（低质占位）
    const [main, preview, blur] = await Promise.all([
      sharp(buffer)
        .rotate()
        .resize(256, 256, { fit: 'cover', position: 'attention' })
        .webp({ quality: 82 })
        .toBuffer(),
      sharp(buffer)
        .rotate()
        .resize(1024, 1024, { fit: 'cover', position: 'attention' })
        .webp({ quality: 88 })
        .toBuffer(),
      sharp(buffer)
        .rotate()
        .resize(16, 16, { fit: 'cover', position: 'attention' })
        .jpeg({ quality: 60 })
        .toBuffer(),
    ])

    const fileName = 'avatar-' + userId + '-' + Date.now()
    await Promise.all([
      writeFile(path.join(dir, fileName + '.webp'), main),
      writeFile(path.join(dir, fileName + '-preview.webp'), preview),
      writeFile(path.join(dir, fileName + '-blur.jpg'), blur),
    ])
    const avatarUrl = '/uploads/avatars/' + fileName + '.webp'

    const previous = await getMyProfile(userId)
    if (previous?.avatarUrl && previous.avatarUrl.startsWith('/uploads/avatars/')) {
      avatarFilePaths(previous.avatarUrl).forEach((urlPath) => {
        // 去掉前导 / 再拼 public 目录（path.join 遇绝对路径会重置）
        const relFile = urlPath.replace(/^\//, '')
        unlink(path.join(process.cwd(), 'public', relFile)).catch(() => {})
      })
    }

    const data = await updateMyAvatar(userId, avatarUrl)
    return ok(data)
  } catch (e: any) {
    if (e instanceof ApiError) return errorResponse(e, getRequestId(request))
    console.error('[POST /api/me/avatar]', e?.message || e)
    return serverError()
  }
}

