import { NextRequest } from 'next/server'
import { z } from 'zod'
import { updateMyProfile } from '@/lib/modules/social/profile.service'
import { ok, unauthorized, ApiError } from '@/lib/api-response'
import { withAuth, parseBody } from '@/lib/api/handler'

export const dynamic = 'force-dynamic'

/** 资料编辑请求体（P1-17）：字段可选，但类型必须是字符串/空 */
const UpdateProfileSchema = z.object({
  nickname: z.string().max(64).nullable().optional(),
  bio: z.string().max(1_000).nullable().optional(),
})

export const PATCH = withAuth(async (request, ctx) => {
  if (!ctx.userId) return unauthorized()
  const body = await parseBody(request, UpdateProfileSchema)
  try {
    const data = await updateMyProfile(ctx.userId, { nickname: body.nickname, bio: body.bio })
    return ok(data)
  } catch (e: any) {
    // 业务校验错误（昵称/签名/用户不存在）→ 400，其余按未预期异常（500，细节只进日志）
    if (e?.message && /昵称|签名|用户不存在/.test(e.message)) {
      throw new ApiError('VALIDATION_ERROR', e.message, 400)
    }
    throw e
  }
})

import { NextRequest } from 'next/server'
import { getMyProfile } from '@/lib/modules/social/profile.service'
import { ok, unauthorized, notFound, ApiError } from '@/lib/api-response'
import { withAuth } from '@/lib/api/handler'

export const dynamic = 'force-dynamic'

/**
 * 当前用户资料（P1-10 验收路径）：
 * 走 withAuth 后，数据库不可用会返回 503 而不是「未登录 401 放行」，
 * 会话被撤销/过期则 401 —— 这也是验收「撤销 session 后 /api/me 401」的入口。
 */
export const GET = withAuth(async (_request: NextRequest, ctx) => {
  if (!ctx.userId) return unauthorized()
  const profile = await getMyProfile(ctx.userId)
  if (!profile) throw new ApiError('NOT_FOUND', '用户不存在', 404)
  return ok(profile)
})

import { NextRequest, NextResponse } from 'next/server'
import { requireAuth } from '@/lib/auth-middleware'
import { parseBody, withAuth } from '@/lib/api/handler'
import { memoryService } from '@/lib/modules/memory/memory.service'
import { parseIdParam, toApiError } from '@/lib/api/schemas/common'
import { UpdateMemorySchema } from '@/lib/api/schemas/memory'

export async function GET(_request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const auth = await requireAuth(_request)
  if (!auth.authenticated || !auth.username) {
    return NextResponse.json({ error: '未授权' }, { status: 401 })
  }
  const { id } = await params
  const memoryId = parseInt(id, 10)
  if (isNaN(memoryId)) {
    return NextResponse.json({ error: '无效的回忆 ID' }, { status: 400 })
  }
  try {
    const memory = await memoryService.getMemory(auth.username, memoryId)
    return NextResponse.json({ memory })
  } catch (error: any) {
    return NextResponse.json({ error: error.message || '获取失败' }, { status: 403 })
  }
}

/** P1-17：路径 id 与 PATCH body 都由 zod 校验；权限仍由 memory.service 的 RBAC 判定。 */
export const PATCH = withAuth(async (request, ctx, routeContext) => {
  const { params } = routeContext as { params: Promise<{ id: string }> }
  const { id } = await params
  const memoryId = parseIdParam(id, '回忆 ID')
  const body = await parseBody(request, UpdateMemorySchema)
  try {
    const memory = await memoryService.updateMemory(ctx.username || '', memoryId, {
      title: body.title,
      content: body.content,
      happenedAt: body.happenedAt,
      travelId: body.travelId,
      travelDayId: body.travelDayId,
      locationId: body.locationId,
      mood: body.mood,
      visibility: body.visibility,
    })
    return NextResponse.json({ success: true, memory })
  } catch (error) {
    throw toApiError(error, '更新失败')
  }
})

