export const DELETE = withAuth(async (_request, ctx, routeContext) => {
  const { params } = routeContext as { params: Promise<{ id: string }> }
  const { id } = await params
  const travelId = parseTravelId(id)
  try {
    await travelService.deleteTravel(ctx.username || '', travelId, ctx.userId)
    return NextResponse.json({ success: true })
  } catch (error: any) {
    const msg = error?.message || '删除失败'
    /**
     * 「旅行不存在」用 404 表达（此前统一 400）。
     *
     * 为什么重要：本地还留着行、但云端已经删掉的情况很常见
     * （用户删过一次、或先离线删后联网）。客户端据此把 404 当作
     * **"目标状态已达成"**处理并完成本地清理，而不是弹"删除失败"
     * 让用户反复点 —— 真机反馈「新建的几篇显示待同步、删除不了」即此。
     */
    throw new ApiError(msg.includes('不存在') ? 'NOT_FOUND' : 'DELETE_FAILED', msg, msg.includes('不存在') ? 404 : 400)
  }
})

import { NextRequest, NextResponse } from 'next/server'
import { getPostService } from '@/lib/container'
import { getCurrentUser } from '@/lib/current-user'
import { applyCacheControl } from '@/lib/http-cache'
import { listTravels } from '@/lib/modules/travel/travel.service'

export const dynamic = 'force-dynamic'

/**
 * 旅行记录列表（面向 /travel 前台地图与列表）。
 *
 * 数据源合并（修复"前台新建旅行不出现在列表"）：
 * - Travel 模型：TravelComposer（Web/移动端新建入口）与后台 /admin/travels 写入的行。
 * - Post(type=travel)：历史数据源（首页 /api/home、数据看板同源）。
 *
 * 历史：v3.1 曾因"Travel 表为空导致地图/统计为 0"整体回退到 Post——但 TravelComposer
 * 写的是 Travel 模型，用户前台新建的旅行从此不再出现在列表（E2E 冒烟抓到）。
 * 现改为双源合并：Travel 行映射为 post 形状排在前面，slug 去重防止同主题重复；
 * Travel 行 id 加固定偏移（1_000_000）避免与 Post 自增 id 撞 React key（跳转链接用 slug，不受影响）。
 */
export async function GET(_request: NextRequest) {
  try {
    const user = await getCurrentUser()
    const userId = user?.id ?? null
    const postService = getPostService()
    const [posts, travels] = await Promise.all([
      postService.getPostsHybrid('travel', userId),
      // username 一并传入：空间成员关系按 (spaceId, username) 与 userId 双键查（P0 修复）
      listTravels(userId, user?.username).catch(() => []),
    ])

    const travelPosts = travels.map((t) => ({
      id: 1_000_000 + t.id,
      slug: t.slug,
      title: t.title,
      date: t.startDate ?? '',
      description: t.description ?? undefined,
      // cover 已由 listTravels 规范化为封面缩略图/原图 URL（coverMedia 优先，回退 legacy cover 绝对化）
      cover: t.cover ?? undefined,
      // 旅行内回忆照片（缩略图优先），填充旅行地图左侧照片轮播
      images: (t.photos ?? []) as string[],
      videos: [] as unknown[],
      tags: t.tags ?? [],
      location: t.location ?? undefined,
      type: 'travel',
      published: true,
    }))
    const travelSlugs = new Set(travelPosts.map((p) => p.slug).filter(Boolean))
    const merged = [...travelPosts, ...posts.filter((p: { slug?: string }) => !travelSlugs.has(p.slug || ''))]

    const res = NextResponse.json({ posts: merged })
    return applyCacheControl(res, 'user', !!userId)
  } catch (error) {
    console.error('[GET /api/travels]', error)
    return NextResponse.json({ error: '获取旅行记录失败' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getImageService } from '@/lib/container'
import { rateLimit } from '@/lib/infrastructure/rate-limit'
import { getClientIp } from '@/lib/request-utils'
import { writeAuditLog } from '@/lib/modules/audit/audit-log.service'
import { ApiError } from '@/lib/api-response'
import { withAuth, parseBody } from '@/lib/api/handler'
import { MediaAccessError } from '@/lib/services/image-service'
import { isSiteOwner } from '@/lib/site-owner'

/** 删除图片请求体（P1-17） */
const DeleteImageSchema = z.object({
  url: z.string().min(1, '缺少 url 参数'),
})

/**
 * 上传图片（multipart，P1-17：用 withAuth 统一 401/503/异常格式；文件内容由
 * media-validation 做魔数校验，不属于 JSON body schema）。
 */
export const POST = withAuth(async (request, ctx) => {
  // 上传限流：IP 每 15 分钟最多 120 次上传请求
  const ip = getClientIp(request)
  const limit = rateLimit({ prefix: 'upload:ip', key: ip || 'unknown', limit: 120, windowMs: 15 * 60 * 1000 })
  if (!limit.ok) {
    throw new ApiError('RATE_LIMITED', '上传过于频繁，请稍后再试', 429)
  }

  const formData = await request.formData()
  const files = formData.getAll('files') as File[]
  const postIdStr = formData.get('postId') as string | null

  if (!files || files.length === 0) {
    throw new ApiError('NO_FILES', '未上传任何文件', 400)
  }
  if (!postIdStr) {
    throw new ApiError('MISSING_POST_ID', '缺少文章 ID，请先保存文章后再上传图片', 400)
  }
  const postId = parseInt(postIdStr, 10)
  if (isNaN(postId)) {
    throw new ApiError('INVALID_POST_ID', '无效的文章 ID', 400)
  }

  /**
   * P0-4：归属校验所需的执行者身份。
   *
   * 站点主人（站长）可管理全站图片；普通用户只能管理**自己文章**下的图片。
   * 判定放在服务层（image-service），这里只负责把身份传下去 —— 避免"路由忘了判权"重演。
   */
  const actor = { userId: ctx.userId ?? null, isSiteOwner: await isSiteOwner(ctx.userId) }

  const imageFiles = await Promise.all(
    files.map(async (file) => ({
      name: file.name,
      buffer: Buffer.from(await file.arrayBuffer()),
      mimeType: file.type,
    })),
  )

  try {
    const imageService = getImageService()
    const result = await imageService.upload(postId, imageFiles, actor)
    // 审计是旁路：失败要留痕，但不能让上传失败
    try {
      await writeAuditLog({
        username: ctx.username || 'unknown',
        action: 'UPLOAD_MEDIA',
        resourceType: 'PostImage',
        resourceId: String(postId),
        ip,
        metadata: { count: imageFiles.length },
      })
    } catch (auditError) {
      console.error('[Upload] 审计写入失败', { postId, auditError })
    }
    return NextResponse.json(result)
  } catch (error: any) {
    console.error('[Upload] Error:', error?.message)
    if (error instanceof MediaAccessError) {
      // 无权与不存在同文案：403 + 统一提示，不给存在性探测
      throw new ApiError('FORBIDDEN', error.message, 403)
    }
    // 上传失败原因（格式不支持/过大等）是用户可据此修正的提示，保留原文
    throw new ApiError('UPLOAD_FAILED', error?.message || '上传失败', 500)
  }
})

export const DELETE = withAuth(async (request, ctx) => {
  const body = await parseBody(request, DeleteImageSchema)
  // P0-4：删除同样要判归属（原先任意登录用户可凭 URL 删任何人的图）
  const actor = { userId: ctx.userId ?? null, isSiteOwner: await isSiteOwner(ctx.userId) }
  try {
    const imageService = getImageService()
    await imageService.delete(body.url, actor)
    return NextResponse.json({ success: true })
  } catch (error: any) {
    console.error('[Upload DELETE] Error:', error?.message)
    if (error?.message === '无效的资源路径' || error?.message === '无效的图片 ID') {
      throw new ApiError('INVALID_PATH', error.message, 400)
    }
    if (error instanceof MediaAccessError) {
      // 无权与不存在统一 404：两账号互删时互相探测不到
      throw new ApiError('NOT_FOUND', '图片不存在', 404)
    }
    if (error?.message === '图片不存在') {
      throw new ApiError('NOT_FOUND', error.message, 404)
    }
    throw new ApiError('DELETE_FAILED', error?.message || '删除失败', 500)
  }
})

import { NextRequest, NextResponse } from 'next/server'
import fs from 'fs'
import path from 'path'
import { Readable } from 'stream'
import { ensureLocalUrlVariants } from '@/lib/infrastructure/media-variants'

/**
 * 运行时文件服务：从本地磁盘按需读取 /uploads/** 资源（图片/视频）。
 *
 * Next.js 的 public/ 静态目录只会在构建/容器启动时预建文件清单，
 * 运行期新生成的图片变体（如按需生成的 -thumbnail/-preview/-blur.jpg）
 * 直接走 /uploads/xxx 会 404，必须重启容器才能访问。
 * 本路由在请求时从磁盘读取并返回，使运行期生成的变体立即可用。
 * 对「变体文件尚未生成」的情况，先按需生成（并发信号量保护）再返回，避免 404。
 */

function uploadDir(): string {
  return process.env.UPLOAD_DIR || 'public/uploads'
}

/** 变体文件未生成时，从变体路径反推出原图 URL（/uploads/<base>.<ext>）供按需生成。 */
const VARIANT_RE = /-(thumbnail|preview|blur)\.(jpg|jpeg|png|webp)$/i
function originalUploadUrlFromVariant(filePath: string): string | null {
  const m = VARIANT_RE.exec(path.basename(filePath))
  if (!m) return null
  const rel = path.relative(uploadDir(), filePath).split('\\').join('/')
  const stem = rel.replace(/-(thumbnail|preview|blur)(\.\w+)$/i, '$2')
  return '/uploads/' + stem
}

const MIME: Record<string, string> = {
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.png': 'image/png',
  '.webp': 'image/webp',
  '.gif': 'image/gif',
  '.avif': 'image/avif',
  '.mp4': 'video/mp4',
  '.webm': 'video/webm',
  '.mov': 'video/quicktime',
  '.ico': 'image/x-icon',
}
// 注：不放行 .svg —— SVG 可携带脚本，且上传校验本就不允许 SVG 入库

// 扩展名白名单： uploads 目录内的非媒体文件(.sql/.db/.bak/.env 等)一律 404，不对外提供
const ALLOWED_EXTS = new Set(Object.keys(MIME))

function safeResolve(segments: string[]): string | null {
  // 拒绝路径穿越：任何一段都不能是 .. 或包含 / 或 \\
  for (const seg of segments) {
    if (!seg || seg === '.' || seg === '..' || seg.includes('/') || seg.includes('\\')) return null
  }
  const filePath = path.join(uploadDir(), ...segments)
  // 归一化后再校验一次，确保最终路径落在 uploadDir 之内
  const resolved = path.resolve(filePath)
  const root = path.resolve(uploadDir())
  if (resolved !== root && !resolved.startsWith(root + path.sep)) return null
  return resolved
}

export async function GET(request: NextRequest, context: { params: Promise<{ path: string[] }> }) {
  const { path: segments } = await context.params
  const filePath = safeResolve(segments)
  if (!filePath) {
    return new NextResponse('Forbidden', { status: 403 })
  }

  // 变体文件尚未生成：先按需生成（并发信号量保护），生成后立即服务，避免首访 404
  if (!fs.existsSync(filePath) && VARIANT_RE.test(path.basename(filePath))) {
    const origUrl = originalUploadUrlFromVariant(filePath)
    if (origUrl) {
      try {
        await ensureLocalUrlVariants(origUrl)
      } catch (e) {
        console.error('[uploads] on-demand variant generation failed', filePath, e)
      }
    }
  }

  try {
    const stat = await fs.promises.stat(filePath)
    if (!stat.isFile()) {
      return new NextResponse('Not Found', { status: 404 })
    }

    const ext = path.extname(filePath).toLowerCase()
    if (!ALLOWED_EXTS.has(ext)) {
      // 非白名单类型：按不存在处理，不暴露 uploads 内的非媒体文件
      return new NextResponse('Not Found', { status: 404 })
    }
    const mime = MIME[ext]

    const isImmutableVariant = /-(thumbnail|preview|blur)\.(jpg|jpeg|png|webp)$/.test(filePath)

    // 阶段 A · A4：可选 nginx X-Accel-Redirect 直出（媒体不经过 Node 流式拷贝）。
    // 设置 UPLOAD_X_ACCEL=1 时，这里只返回内部重定向头，由 nginx 直接读盘回包
    // （视频 Range/seek 也由 nginx 原生处理）。需 nginx 配置 internal location
    // /internal-uploads/（见 docs/nginx.conf.example），并让 nginx 可读上传目录。
    if (process.env.UPLOAD_X_ACCEL === '1') {
      const rel = path.relative(uploadDir(), filePath).split('\\').join('/')
      const xh = new Headers()
      xh.set('Content-Type', mime)
      xh.set('Accept-Ranges', 'bytes')
      xh.set('Cache-Control', isImmutableVariant ? 'public, max-age=31536000, immutable' : 'public, max-age=86400')
      xh.set('X-Accel-Redirect', '/internal-uploads/' + rel)
      return new NextResponse(null, { status: 200, headers: xh })
    }

    const baseHeaders = (): Headers => {
      const h = new Headers()
      h.set('Content-Type', mime)
      h.set('Accept-Ranges', 'bytes')
      h.set('X-Content-Type-Options', 'nosniff')
      h.set(
        'Cache-Control',
        isImmutableVariant ? 'public, max-age=31536000, immutable' : 'public, max-age=86400'
      )
      return h
    }

    // 单段 Range 支持（视频 seek / 断点续传），`bytes=start-end` 与 `bytes=-suffix`
    const range = request.headers.get('range')
    const rangeMatch = range ? /^bytes=(\d*)-(\d*)$/.exec(range.trim()) : null
    if (rangeMatch && (rangeMatch[1] !== '' || rangeMatch[2] !== '')) {
      const size = stat.size
      let start: number
      let end: number
      if (rangeMatch[1] === '') {
        const suffix = parseInt(rangeMatch[2], 10)
        if (suffix <= 0) {
          return new NextResponse('Range Not Satisfiable', {
            status: 416,
            headers: { 'Content-Range': `bytes */${size}` },
          })
        }
        start = Math.max(0, size - suffix)
        end = size - 1
      } else {
        start = parseInt(rangeMatch[1], 10)
        end = rangeMatch[2] === '' ? size - 1 : parseInt(rangeMatch[2], 10)
      }
      if (Number.isNaN(start) || Number.isNaN(end) || start > end || start >= size || end >= size) {
        return new NextResponse('Range Not Satisfiable', {
          status: 416,
          headers: { 'Content-Range': `bytes */${size}` },
        })
      }
      const headers = baseHeaders()
      headers.set('Content-Range', `bytes ${start}-${end}/${size}`)
      headers.set('Content-Length', String(end - start + 1))
      const stream = Readable.toWeb(fs.createReadStream(filePath, { start, end })) as ReadableStream
      return new NextResponse(stream, { status: 206, headers })
    }

    const headers = baseHeaders()
    headers.set('Content-Length', String(stat.size))
    const stream = Readable.toWeb(fs.createReadStream(filePath)) as ReadableStream
    return new NextResponse(stream, { status: 200, headers })
  } catch (error: any) {
    if (error?.code === 'ENOENT') {
      return new NextResponse('Not Found', { status: 404 })
    }
    console.error('[uploads] error serving', filePath, error)
    return new NextResponse('Internal Server Error', { status: 500 })
  }
}

