 * 密码与邮箱（跳对应流程）、通知与数据（复用已有页面）、导出与退出。
 */

interface MeInfo {
  username: string
  nickname: string | null
  bio: string | null
  accountId: string | null
  email?: string | null
  capabilities: {
    isOwner: boolean
    canManageSettings: boolean
  }
}

export default function MeSettingsPage() {
  const router = useRouter()
  const native = isMobileShell()
  /**
   * 用统一取数层：它把「中间件 307 → /login」归一成 401 ApiError，
   * 于是会话失效能被 `useSessionRedirect` 识别并送去登录页（手写 fetch 会漏掉这一步）。
   */
  const { data, error: loadError, loading, reload } = useApi<MeInfo>(apiUrl('/api/me'))
  const expired = useSessionRedirect(loadError)

  const info = data ?? null
  const [nickname, setNickname] = useState('')
  const [bio, setBio] = useState('')
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')

  useEffect(() => {
    if (!data) return
    setNickname(data.nickname ?? '')
    setBio(data.bio ?? '')
  }, [data])

  const save = async () => {
    setSaving(true)
    setError('')
    try {
      const res = await fetch(apiUrl('/api/me/profile'), {
        method: 'PATCH',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ nickname, bio }),
      })
      const json = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(json?.error || '保存失败')
      toast.success('已保存')
      reload()
    } catch (e) {
      setError(e instanceof Error ? e.message : '保存失败')
    } finally {
      setSaving(false)
    }
  }

  /**
   * 退出登录（M-1 / P1-22）。
   *
   * 顺序刻意如此：**先清本地，再注销会话**。
   *  - 本地 SQLite 是全局单库，不清就会出现"换账号后仍能看到上一个账号的旅行"；
   *  - 待同步队列若留着，会带着**下一个账号的 Cookie** 上传（数据污染）；
   *  - 每一步都包 try/catch：本地存储异常（插件坏、磁盘满）不能把用户困在登录态里。
   */
  const logout = async () => {
    try {
      stopSyncEngine()
    } catch {}
    try {
      await purgeOfflineForLogout()
    } catch {}
    try {
      resetAccountScopeCache()
    } catch {}
    try {
      await fetch(apiUrl('/api/logout'), { method: 'POST', credentials: 'include' })
    } catch {}
    router.push('/login')
  }

  return (
    <div className="min-h-dvh bg-[var(--ui-social-bg)] pb-[calc(96px+env(safe-area-inset-bottom))] text-[var(--ui-social-text)]">
      <EdgeSwipeBack />
      <div className="pointer-events-none fixed inset-x-0 top-0 h-[320px] bg-[radial-gradient(55%_60%_at_50%_-10%,rgba(232,179,106,0.09),transparent_65%)]" />
      <div className="m-safe-top-16 relative mx-auto max-w-2xl px-4 pb-8 sm:px-6 sm:py-8">
        <LargeTitle title="账号设置" subtitle="资料、安全与账号" back="/me" />

        {loading ? (
          <div className="flex items-center justify-center gap-2 py-20 text-[var(--ui-social-muted)]">
            <Icon icon={Loader2} size="md" className="animate-spin" />
            <span className="text-sm">加载中…</span>
          </div>
        ) : (
          <>
            {/* 资料 */}
            <section className="mt-6 rounded-[1.4rem] bg-[var(--ui-social-surface)] p-5 ring-1 ring-[var(--ui-social-line)]">
              <div className="flex items-center gap-2">
                <Icon icon={User} size="sm" tone="accent" />
                <h2 className="text-sm font-semibold">资料</h2>
              </div>

              <div className="mt-4 space-y-1">
                <p className="text-xs text-[var(--ui-social-muted)]">账号名（不可在此修改）</p>
                <p className="text-sm">@{info?.username}</p>
                {info?.accountId && (
                  <p className="text-xs text-[var(--ui-social-muted)]">ID {info.accountId}</p>
                )}
              </div>

              <label className="mt-4 block text-xs text-[var(--ui-social-muted)]">昵称</label>
              <input
                value={nickname}
                onChange={(e) => setNickname(e.target.value)}
                maxLength={24}
                placeholder="输入 1-24 位昵称"
                className="mt-1.5 w-full rounded-xl bg-[var(--ui-social-bg)] px-4 py-3 text-sm outline-none ring-1 ring-[var(--ui-social-line)] focus-visible:ring-[var(--ui-social-accent)]"
              />

              <label className="mt-4 block text-xs text-[var(--ui-social-muted)]">个性签名</label>
              <input
                value={bio}
                onChange={(e) => setBio(e.target.value)}
                maxLength={120}
                placeholder="写一句话，成为你的旅行签名"
                className="mt-1.5 w-full rounded-xl bg-[var(--ui-social-bg)] px-4 py-3 text-sm outline-none ring-1 ring-[var(--ui-social-line)] focus-visible:ring-[var(--ui-social-accent)]"
              />

              {error && <p className="mt-3 text-sm text-[var(--danger-soft)]">{error}</p>}

              <button
                type="button"
                onClick={save}
                disabled={saving || !nickname.trim()}
                className="mt-4 inline-flex h-11 w-full items-center justify-center gap-2 rounded-full bg-[var(--ui-social-accent)] text-sm font-semibold text-[var(--ui-social-on-accent)] transition active:scale-[0.98] disabled:opacity-50"
              >
                {saving ? <Icon icon={Loader2} size="sm" className="animate-spin" /> : <Icon icon={Save} size="sm" />}
                {saving ? '保存中…' : '保存资料'}
              </button>
            </section>

            {/* 安全 */}
            <ListSection title="安全" className="mt-6">
              <ListRow icon={KeyRound} tone="sun" title="修改密码" description="定期更换更安全" href="/admin/change-password" />
              <ListRow icon={Mail} tone="clay" title="邮箱" description={info?.email || '未绑定（用于找回密码）'} href="/admin/settings" />
            </ListSection>

            {/* 内容与数据 */}
            <ListSection title="内容与数据" className="mt-6">
              <ListRow icon={Bell} tone="accent" title="通知" description="评论、点赞与关注" href="/me/notifications" />
              <ListRow
                icon={Download}
                tone="clay"
                title="导出记忆档案"
                description="旅行 / 回忆 / 碎碎念 / 照片打包下载"
                onClick={async () => {
                  try {
                    const res = await fetch(apiUrl('/api/export/archive'), { credentials: 'include' })
                    if (!res.ok) throw new Error('导出失败')
                    const blob = await res.blob()
                    const url = URL.createObjectURL(blob)
                    const a = document.createElement('a')
                    a.href = url
                    a.download = 'tiantu-archive.zip'
                    document.body.appendChild(a)
                    a.click()
                    a.remove()
                    URL.revokeObjectURL(url)
                  } catch {
                    toast.error('导出失败，请稍后重试')
                  }
                }}
              />
              {/* 管理后台只在 Web 构建里存在（原生壳没打包 /admin） */}
              {info?.capabilities?.isOwner && !native && (
                <ListRow icon={ShieldCheck} tone="accent" title="管理后台" description="内容、成员与审计日志" href="/admin" />
              )}
            </ListSection>

            {/*
              关于：应用商店（小米《APP备案编号的应用内展示指南》/ 华为 / OPPO / vivo / 应用宝）
              要求 App 在「设置 - 关于」这类显著位置展示 App 备案编号，且编号可跳转工信部备案系统。
            */}
            <ListSection title="关于" className="mt-6">
              <div className="px-4 py-3.5">
                <div className="flex items-center justify-between gap-4 text-sm">
                  <span className="text-[var(--ui-social-muted)]">版本</span>
                  <span className="font-medium">甜途 v{APP_VERSION}（build {APP_BUILD_NUMBER}）</span>
                </div>
                <div className="mt-3 border-t border-[var(--ui-social-line)] pt-3">
                  <IcpLicense
                    className="text-xs text-[var(--ui-social-muted)]"
                    numberClassName="text-[var(--ui-social-muted)] hover:text-[var(--ui-social-accent)]"
                    linkClassName="text-[var(--ui-social-muted)] hover:text-[var(--ui-social-accent)]"
                  />
                </div>
              </div>
            </ListSection>

            <button
              type="button"
              onClick={logout}
              className="mt-6 flex w-full items-center justify-center gap-2 rounded-[1.4rem] bg-[var(--ui-social-surface)] py-3.5 text-sm font-medium text-[var(--ui-social-muted)] ring-1 ring-[var(--ui-social-line)] transition active:scale-[0.99]"
            >
              <Icon icon={LogOut} size="sm" />
              退出登录
            </button>

            <p className="mt-4 text-center text-[11px] text-[var(--ui-social-muted)]">
              想改头像与档案头图？回<Link href="/me" className="mx-1 underline underline-offset-2">我的</Link>页直接点即可
            </p>
