'use client'

import { useState, useRef, useCallback } from 'react'
import Image from 'next/image'
import { Upload, ZoomIn, ChevronUp, ChevronDown, Trash2, XCircle, ImageOff } from 'lucide-react'
import { apiUrl } from '@/lib/api-base'

export interface ImageUploaderProps {
  images: string[]
  postId?: number | string
  onUploaded: (urls: string[]) => void
  onRemoved: (index: number) => void
  onReordered: (images: string[]) => void
  onSetCover: (index: number) => void
  cover?: string
}

export default function ImageUploader({
  images,
  postId,
  onUploaded,
  onRemoved,
  onReordered,
  onSetCover,
  cover = '',
}: ImageUploaderProps) {
  const [uploading, setUploading] = useState(false)
  const [dragOver, setDragOver] = useState(false)
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null)
  const [imageErrors, setImageErrors] = useState<Set<string>>(new Set())
  const [imagePreview, setImagePreview] = useState<string | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleImageError = (imgUrl: string) => {
    setImageErrors((prev) => new Set(prev).add(imgUrl))
  }

  const handleFileUpload = async (files: FileList | File[]) => {
    const fileArray = Array.from(files)
    if (fileArray.length === 0) return

    setUploading(true)
    try {
      const formUpload = new FormData()
      fileArray.forEach((file) => {
        formUpload.append('files', file)
      })

      if (postId) {
        formUpload.append('postId', String(postId))
      }

      const res = await fetch(apiUrl('/api/upload'), {
        method: 'POST',
        body: formUpload,
      })

      if (!res.ok) {
        const err = await res.json()
        throw new Error(err.error || '上传失败')
      }

      const data = await res.json()
      onUploaded(data.urls)
    } catch (error: any) {
      alert(error.message || '图片上传失败')
    } finally {
      setUploading(false)
      if (fileInputRef.current) {
        fileInputRef.current.value = ''
      }
    }
  }

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault()
      setDragOver(false)
      const files = e.dataTransfer.files
      if (files.length > 0) {
        handleFileUpload(files)
      }
    },
    []
  )

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setDragOver(true)
  }, [])

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setDragOver(false)
  }, [])

  const handleDragStart = (index: number) => {
    setDraggedIndex(index)
  }

  const handleDragEnd = () => {
    setDraggedIndex(null)
  }

  const handleDragOverImage = (e: React.DragEvent, index: number) => {
    e.preventDefault()
    if (draggedIndex === null || draggedIndex === index) return
    const newImages = [...images]
    const [removed] = newImages.splice(draggedIndex, 1)
    newImages.splice(index, 0, removed)
    onReordered(newImages)
    setDraggedIndex(index)
  }

  const moveImage = (index: number, direction: 'up' | 'down') => {
    const newImages = [...images]
    const targetIndex = direction === 'up' ? index - 1 : index + 1
    if (targetIndex < 0 || targetIndex >= newImages.length) return
    ;[newImages[index], newImages[targetIndex]] = [newImages[targetIndex], newImages[index]]
    onReordered(newImages)
  }

  return (
    <div className="bg-white dark:bg-warm-800 rounded-xl shadow-sm p-6">
      <div className="flex items-center justify-between mb-4">
        <label className="block text-sm font-medium text-warm-700 dark:text-warm-300">
          旅行照片管理
        </label>
        <span className="text-xs text-warm-500">{images.length} 张照片</span>
      </div>

      <div
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onClick={() => fileInputRef.current?.click()}
        className={`relative border-2 border-dashed rounded-xl p-8 text-center cursor-pointer transition-colors ${
          dragOver
            ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20'
            : 'border-warm-300 dark:border-warm-600 hover:border-primary-400 hover:bg-warm-50 dark:hover:bg-warm-700/50'
        }`}
      >
        <input
          ref={fileInputRef}
          type="file"
          multiple
          accept="image/*"
          className="hidden"
          onChange={(e) => {
            if (e.target.files && e.target.files.length > 0) {
              handleFileUpload(e.target.files)
            }
          }}
        />
        {uploading ? (
          <div className="flex flex-col items-center gap-2">
            <div className="w-8 h-8 border-3 border-primary-500 border-t-transparent rounded-full animate-spin" />
            <p className="text-sm text-warm-500">上传中...</p>
          </div>
        ) : (
          <div className="flex flex-col items-center gap-2">
            <Upload className="w-10 h-10 text-warm-400" />
            <p className="text-sm text-warm-600 dark:text-warm-300">
              点击或拖拽图片到此处上传
            </p>
            <p className="text-xs text-warm-400">
              支持多张图片同时上传，JPG / PNG / GIF / WEBP
            </p>
          </div>
        )}
      </div>

      {images.length > 0 && (
        <div className="mt-4 grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
          {images.map((img, index) => (
            <div
              key={`${img}-${index}`}
              draggable
              onDragStart={() => handleDragStart(index)}
              onDragEnd={handleDragEnd}
              onDragOver={(e) => handleDragOverImage(e, index)}
              className={`group relative h-32 rounded-lg overflow-hidden border-2 transition-all bg-gradient-to-br from-warm-100 to-warm-200 ${
                cover === img
                  ? 'border-sky-500 ring-2 ring-sky-500/30'
                  : 'border-transparent'
              } ${draggedIndex === index ? 'opacity-50' : ''} cursor-move`}
            >
              {img && !imageErrors.has(img) && (
                <Image
                  src={img}
                  alt={`图片 ${index + 1}`}
                  fill
                  sizes="128px"
                  className="object-cover cursor-pointer"
                  onClick={() => setImagePreview(img)}
                  onError={() => handleImageError(img)}
                />
              )}
              {imageErrors.has(img) && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-gradient-to-br from-red-50 to-orange-50 text-red-500">
                  <ImageOff className="w-8 h-8 mb-1" />
                  <span className="text-xs">加载失败</span>
                </div>
              )}

              <div className="absolute inset-0 bg-black/0 group-hover:bg-black/40 transition-colors flex items-center justify-center opacity-0 group-hover:opacity-100">
                <div className="flex gap-1">
                  <button
                    type="button"
                    onClick={() => setImagePreview(img)}
                    className="p-1.5 bg-white/90 rounded text-warm-700 hover:bg-white transition-colors"
                    title="预览"
                  >
                    <ZoomIn className="w-4 h-4" />
                  </button>
                  <button
                    type="button"
                    onClick={() => onSetCover(index)}
                    className={`px-2 py-1 text-xs rounded transition-colors ${
                      cover === img
                        ? 'bg-primary-500 text-white'
                        : 'bg-white/90 text-warm-700 hover:bg-white'
                    }`}
                    title="设为封面"
                  >
                    封面
                  </button>
                  <button
                    type="button"
                    onClick={() => moveImage(index, 'up')}
                    disabled={index === 0}
                    className="p-1.5 bg-white/90 rounded text-warm-700 hover:bg-white disabled:opacity-30"
                    title="上移"
                  >
                    <ChevronUp className="w-4 h-4" />
                  </button>
                  <button
                    type="button"
                    onClick={() => moveImage(index, 'down')}
                    disabled={index === images.length - 1}
                    className="p-1.5 bg-white/90 rounded text-warm-700 hover:bg-white disabled:opacity-30"
                    title="下移"
                  >
                    <ChevronDown className="w-4 h-4" />
                  </button>
                  <button
                    type="button"
                    onClick={() => onRemoved(index)}
                    className="p-1.5 bg-red-500 rounded text-white hover:bg-red-600 transition-colors"
                    title="删除"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {imagePreview && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm"
          onClick={() => setImagePreview(null)}
        >
          <button
            type="button"
            onClick={() => setImagePreview(null)}
            className="absolute top-4 right-4 p-2 text-white hover:bg-white/20 rounded-full transition-colors"
          >
            <XCircle className="w-8 h-8" />
          </button>
          <Image
            src={imagePreview}
            alt="预览"
            fill
            sizes="100vw"
            className="object-contain rounded-lg shadow-2xl"
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useRef, useEffect } from 'react'
import { Upload, Play, ChevronUp, ChevronDown, Trash2, Video, Eye } from 'lucide-react'
import { uploadVideoResumable } from '@/lib/upload/resumable-upload'
import { apiUrl } from '@/lib/api-base'

export interface VideoItem {
  url: string
  thumbnail?: string
  duration?: number
}

export interface VideoUploaderProps {
  videos: VideoItem[]
  onUploaded: (videos: VideoItem[]) => void
  onRemoved: (index: number) => void
  onReordered: (videos: VideoItem[]) => void
}

interface UploadState {
  label: string
  percent: number
}

export default function VideoUploader({
  videos,
  onUploaded,
  onRemoved,
  onReordered,
}: VideoUploaderProps) {
  const [videoUploading, setVideoUploading] = useState(false)
  const [uploadState, setUploadState] = useState<UploadState | null>(null)
  const [videoDraggedIndex, setVideoDraggedIndex] = useState<number | null>(null)
  const [videoPreview, setVideoPreview] = useState<string | null>(null)
  const videoFileInputRef = useRef<HTMLInputElement>(null)
  // 转码轮询完成后要把列表里的原始 URL 换成变体，用 ref 拿最新列表避免闭包过期
  const videosRef = useRef(videos)
  useEffect(() => {
    videosRef.current = videos
  }, [videos])

  const pollTranscode = (originalUrl: string, filename: string) => {
    const started = Date.now()
    const timer = setInterval(async () => {
      try {
        const res = await fetch(apiUrl('/api/admin/videos/resumable'), {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'transcode-status', filename }),
        })
        const st = await res.json()
        if (st?.status === 'done' && st.url) {
          clearInterval(timer)
          onUploaded(videosRef.current.map((v) => (v.url === originalUrl ? { ...v, url: st.url } : v)))
        } else if (st?.status === 'skipped' || st?.status === 'none' || Date.now() - started > 15 * 60_000) {
          clearInterval(timer)
        }
      } catch {
        // 网络抖动轮询下一轮继续
      }
    }, 3_000)
  }

  const handleVideoUpload = async (files: FileList | File[]) => {
    const fileArray = Array.from(files)
    if (fileArray.length === 0) return

    setVideoUploading(true)
    try {
      for (let i = 0; i < fileArray.length; i++) {
        const file = fileArray[i]
        setUploadState({ label: fileArray.length > 1 ? `视频 ${i + 1}/${fileArray.length} 上传中` : '视频上传中', percent: 0 })
        const r = await uploadVideoResumable(file, {
          onProgress: (percent) => setUploadState((s) => (s ? { ...s, percent } : s)),
        })
        onUploaded([...videosRef.current, { url: r.url }])
        setUploadState({ label: '转码优化中…（完成后自动切换流畅版）', percent: 100 })
        if (r.transcode === 'queued') pollTranscode(r.url, r.filename)
      }
    } catch (error: any) {
      alert(error.message || '视频上传失败')
    } finally {
      setVideoUploading(false)
      setUploadState(null)
      if (videoFileInputRef.current) {
        videoFileInputRef.current.value = ''
      }
    }
  }

  const moveVideo = (index: number, direction: 'up' | 'down') => {
    const newVideos = [...videos]
    const targetIndex = direction === 'up' ? index - 1 : index + 1
    if (targetIndex < 0 || targetIndex >= newVideos.length) return
    ;[newVideos[index], newVideos[targetIndex]] = [newVideos[targetIndex], newVideos[index]]
    onReordered(newVideos)
  }

  const handleVideoDragStart = (index: number) => {
    setVideoDraggedIndex(index)
  }

  const handleVideoDragEnd = () => {
    setVideoDraggedIndex(null)
  }

  const handleDragOverVideo = (e: React.DragEvent, index: number) => {
    e.preventDefault()
    if (videoDraggedIndex === null || videoDraggedIndex === index) return
    const newVideos = [...videos]
    const [removed] = newVideos.splice(videoDraggedIndex, 1)
    newVideos.splice(index, 0, removed)
    onReordered(newVideos)
    setVideoDraggedIndex(index)
  }

  return (
    <div className="bg-white dark:bg-warm-800 rounded-xl shadow-sm p-6">
      <div className="flex items-center justify-between mb-4">
        <label className="block text-sm font-medium text-warm-700 dark:text-warm-300">
          旅行视频管理
        </label>
        <span className="text-xs text-warm-500">{videos.length} 个视频</span>
      </div>

      <div
        onClick={() => videoFileInputRef.current?.click()}
        className={`relative border-2 border-dashed rounded-xl p-8 text-center cursor-pointer transition-colors ${
          videoUploading
            ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20'
            : 'border-warm-300 dark:border-warm-600 hover:border-primary-400 hover:bg-warm-50 dark:hover:bg-warm-700/50'
        }`}
      >
        <input
          ref={videoFileInputRef}
          type="file"
          multiple
          accept="video/*"
          className="hidden"
          onChange={(e) => {
            if (e.target.files && e.target.files.length > 0) {
              handleVideoUpload(e.target.files)
            }
          }}
        />
        {videoUploading ? (
          <div className="flex flex-col items-center gap-2">
            <div className="w-8 h-8 border-3 border-primary-500 border-t-transparent rounded-full animate-spin" />
            <p className="text-sm text-warm-500">{uploadState?.label || '视频上传中...'}</p>
            <div className="w-56 h-1.5 rounded-full bg-warm-200 dark:bg-warm-700 overflow-hidden">
              <div
                className="h-full rounded-full bg-primary-500 transition-all duration-300"
                style={{ width: `${uploadState?.percent ?? 0}%` }}
              />
            </div>
            <p className="text-xs text-warm-400">{uploadState?.percent ?? 0}% · 支持断点续传，中断后重新选择同一文件可续传</p>
          </div>
        ) : (
          <div className="flex flex-col items-center gap-2">
            <Upload className="w-10 h-10 text-warm-400" />
            <p className="text-sm text-warm-600 dark:text-warm-300">
              点击上传视频文件
            </p>
            <p className="text-xs text-warm-400">
              支持 MP4 / WebM / MOV 等格式，单个最大 500MB · 分片断点续传 · 完成后自动转 720p 流畅版
            </p>
          </div>
        )}
      </div>

      {videos.length > 0 && (
        <div className="mt-4 grid grid-cols-1 sm:grid-cols-2 gap-3">
          {videos.map((video, index) => (
            <div
              key={`video-${index}`}
              draggable
              onDragStart={() => handleVideoDragStart(index)}
              onDragEnd={handleVideoDragEnd}
              onDragOver={(e) => handleDragOverVideo(e, index)}
              className={`group relative rounded-lg overflow-hidden border-2 transition-all bg-warm-900 ${
                videoDraggedIndex === index ? 'opacity-50' : ''
              } cursor-move`}
            >
              <div className="aspect-video bg-gradient-to-br from-warm-800 to-warm-900 relative">
                <video
                  src={video.url}
                  poster={video.thumbnail}
                  className="w-full h-full object-cover"
                  muted
                  loop
                  playsInline
                  preload="metadata"
                  onMouseEnter={(e) => {
                    const v = e.target as HTMLVideoElement
                    v.play().catch(() => {})
                  }}
                  onMouseLeave={(e) => {
                    const v = e.target as HTMLVideoElement
                    v.pause()
                    v.currentTime = 0
                  }}
                />
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                  <div className="w-10 h-10 rounded-full bg-white/20 backdrop-blur-sm flex items-center justify-center">
                    <Play className="w-5 h-5 text-white ml-0.5" />
                  </div>
                </div>
              </div>

              <div className="absolute top-2 right-2 flex gap-1">
                <button
                  type="button"
                  onClick={() => setVideoPreview(video.url)}
                  className="p-1.5 bg-white/80 rounded text-warm-700 hover:bg-white opacity-0 group-hover:opacity-100 transition-opacity"
                  title="预览"
                >
                  <Eye className="w-4 h-4" />
                </button>
                <button
                  type="button"
                  onClick={() => moveVideo(index, 'up')}
                  disabled={index === 0}
                  className="p-1.5 bg-white/80 rounded text-warm-700 hover:bg-white disabled:opacity-30 opacity-0 group-hover:opacity-100 transition-opacity"
                  title="上移"
                >
                  <ChevronUp className="w-4 h-4" />
                </button>
                <button
                  type="button"
                  onClick={() => moveVideo(index, 'down')}
                  disabled={index === videos.length - 1}
                  className="p-1.5 bg-white/80 rounded text-warm-700 hover:bg-white disabled:opacity-30 opacity-0 group-hover:opacity-100 transition-opacity"
                  title="下移"
                >
                  <ChevronDown className="w-4 h-4" />
                </button>
                <button
                  type="button"
                  onClick={() => onRemoved(index)}
                  className="p-1.5 bg-red-500 rounded text-white hover:bg-red-600 opacity-0 group-hover:opacity-100 transition-opacity"
                  title="删除"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>

              <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-2">
                <p className="text-xs text-white/80 truncate">
                  {video.url.split('/').pop() || `视频 ${index + 1}`}
                </p>
              </div>
            </div>
          ))}
        </div>
      )}

      {videoPreview && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm"
          onClick={() => setVideoPreview(null)}
        >
          <button
            type="button"
            onClick={() => setVideoPreview(null)}
            className="absolute top-4 right-4 p-2 text-white hover:bg-white/20 rounded-full transition-colors"
          >
            <Video className="w-8 h-8" />
          </button>
          <video
            src={videoPreview}
            className="max-w-[90vw] max-h-[90vh] rounded-lg shadow-2xl"
            controls
            autoPlay
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
    </div>
  )
}

