'use client'

import { useEffect, useRef, useState, useCallback } from 'react'
import { Send, Loader2, Clock, MessageCircle, ImageIcon, X, BookOpen } from 'lucide-react'
import { Icon } from '@/components/mobile/Icon'
import PixelDeskBackground from './PixelDeskBackground'
import { apiUrl } from '@/lib/api-base'
import { useModalLayer } from '@/hooks/use-modal-layer'

interface Message {
  id: number
  imageKey: string
  content: string
  createdAt: string
}

interface PixelPhotoChatProps {
  image: string
  imageKey: string
  cityName?: string
  date?: string
  onBack: () => void
}

function formatTime(iso: string): string {
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return ''
  const pad = (n: number) => String(n).padStart(2, '0')
  return `${pad(d.getHours())}:${pad(d.getMinutes())}`
}

function todayText(): string {
  const days = ['周日', '周一', '周二', '周三', '周四', '周五', '周六']
  const d = new Date()
  return `${d.getMonth() + 1}月${d.getDate()}日${days[d.getDay()]}`
}

/**
 * 像素书卷聊天视图（SavePoint 风格）：
 * 打开一本羊皮纸书，左侧是照片 + 留言记录（横线纸上），右侧是留言面板。
 * 每张照片独立会话（imageKey 隔离），点击底片可预览大图。
 */
export default function PixelPhotoChat({ image, imageKey, cityName, date, onBack }: PixelPhotoChatProps) {
  const [messages, setMessages] = useState<Message[]>([])
  const [input, setInput] = useState('')
  const [loading, setLoading] = useState(true)
  const [sending, setSending] = useState(false)
  const [error, setError] = useState('')
  const [previewOpen, setPreviewOpen] = useState(false)
  const listRef = useRef<HTMLDivElement>(null)

  const loadMessages = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch(apiUrl(`/api/photo-messages?image=${encodeURIComponent(imageKey)}`))
      if (res.ok) {
        const json = await res.json()
        setMessages(Array.isArray(json.data) ? json.data : [])
      }
    } catch {
      // 忽略加载失败
    } finally {
      setLoading(false)
    }
  }, [imageKey])

  useEffect(() => {
    loadMessages()
  }, [loadMessages])

  useEffect(() => {
    if (listRef.current) {
      listRef.current.scrollTop = listRef.current.scrollHeight
    }
  }, [messages])

  // P2-B2：大图预览是弹层，ESC / 焦点 / 滚动锁由 useModalLayer 处理；
  // 未打开大图时 ESC 仍等于「返回相册」。
  const panelRef = useRef<HTMLDivElement>(null)
  useModalLayer({ open: previewOpen, onClose: () => setPreviewOpen(false), panelRef })

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && !previewOpen) onBack()
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [previewOpen, onBack])

  const handleSend = async () => {
    const content = input.trim()
    if (!content || sending) return
    setSending(true)
    setError('')
    try {
      const res = await fetch(apiUrl('/api/photo-messages'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ image: imageKey, content }),
      })
      const json = await res.json()
      if (!res.ok) {
        setError(json.error || '发送失败')
        return
      }
      setMessages((prev) => [...prev, json.data as Message])
      setInput('')
    } catch {
      setError('网络异常，请重试')
    } finally {
      setSending(false)
    }
  }

  return (
    <div className="fixed inset-0 z-[110] overflow-y-auto bg-album-bg1">
      {/* 像素木屋桌面背景 */}
      <PixelDeskBackground className="fixed inset-0" />

      {/* 顶部像素导航 */}
      <header className="sticky top-0 z-40 h-14 flex items-center justify-between px-4 md:px-8 border-b-4 border-black bg-black/45">
        <button
          type="button"
          onClick={onBack}
          className="pixel-btn pixel-border-stone px-3 py-1.5 text-xs font-bold rounded-sm"
        >
          ← 返回相册
        </button>
        <div className="font-zpix text-album-accent text-sm font-bold tracking-widest drop-shadow-[2px_2px_0_rgba(0,0,0,0.8)]">
          旅行相册 · 存档
        </div>
        <div className="w-20 md:w-24" aria-hidden="true" />
      </header>

      {/* 书本容器 */}
      <div className="relative z-10 min-h-[calc(100vh-56px)] flex items-center justify-center p-4 md:p-8">
        <div className="w-full max-w-[900px] pixel-book-container flex flex-col md:flex-row relative rounded-sm min-h-[640px]">
          {/* 金色书角 */}
          <div className="pixel-corner-gold-tl" />
          <div className="pixel-corner-gold-tr" />
          <div className="pixel-corner-gold-bl" />
          <div className="pixel-corner-gold-br" />
          {/* 中缝书脊 */}
          <div className="hidden md:block pixel-book-spine" />
          {/* 悬挂书签 */}
          <div className="bookmark-ribbon" />

          {/* 左页：照片 + 留言记录 */}
          <div className="w-full md:w-1/2 p-4 md:pr-8 border-b-4 md:border-b-0 md:border-r border-pixel-lineLight relative">
            <div className="absolute top-2 left-2 w-2 h-2 border-t border-l border-pixel-lineLight" />
            <div className="absolute bottom-2 left-2 w-2 h-2 border-b border-l border-pixel-lineLight" />

            <div className="flex flex-col h-[620px]">
              {/* 头部：像素精灵 */}
              <div className="flex items-center justify-between pb-2 mb-2 border-b border-album-warm/35 select-none">
                <div className="flex items-center gap-2">
                  {/* 黄色像素机器人 */}
                  <div className="w-6 h-6 flex items-center justify-center bg-pixel-goldLight border border-black shadow-[1px_1px_0_#000] rounded-sm p-0.5">
                    <svg viewBox="0 0 16 16" className="w-full h-full text-black fill-current" xmlns="http://www.w3.org/2000/svg" style={{ imageRendering: 'pixelated' }}>
                      <rect x="7" y="0" width="2" height="2" />
                      <rect x="6" y="2" width="4" height="1" />
                      <rect x="1" y="6" width="1" height="4" />
                      <rect x="14" y="6" width="1" height="4" />
                      <rect x="4" y="7" width="2" height="2" />
                      <rect x="10" y="7" width="2" height="2" />
                      <rect x="5" y="11" width="6" height="1" />
                    </svg>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-xs font-bold text-pixel-panel">照片守候精灵</span>
                    <span className="text-xs text-pixel-online flex items-center gap-1 leading-none font-bold">
                      <span className="w-1.5 h-1.5 bg-pixel-online rounded-full inline-block" />
                      在线 · 这张照片在等待你的留言
                    </span>
                  </div>
                </div>
                <button
                  type="button"
                  onClick={onBack}
                  className="pixel-close-btn"
                  aria-label="关闭留言"
                  title="合上书本"
                >
                  <Icon icon={X} size="sm" />
                </button>
              </div>

              {/* 大图拍立得（约占书页 2/3） */}
              <div className="flex flex-col items-center pb-2 mb-2 select-none">
                <div
                  className="polaroid-frame w-[72%] max-w-[300px] cursor-pointer transition-transform hover:scale-[1.02] hover:rotate-1"
                  onClick={() => setPreviewOpen(true)}
                  title="点击预览大图"
                >
                  <img src={image} alt={cityName || '照片'} width={400} height={300} loading="lazy" decoding="async" className="w-full aspect-[4/3] object-cover border border-black/70" />
                  <div className="pt-1.5 text-center">
                    <span className="text-xs text-pixel-ink font-bold truncate block">{cityName || '记忆'}</span>
                    {date && <span className="text-xs text-pixel-muted mt-0.5 block">{date}</span>}
                  </div>
                </div>
                <p className="text-xs text-album-warm mt-1.5 font-bold">点击照片预览大图 · 留言仅与当前照片绑定</p>
              </div>

              {/* 聊天记录区（横线纸） */}
              <div
                ref={listRef}
                className="flex-grow overflow-y-auto mc-scrollbar pr-2 mb-2 pixel-paper-rules-chat rounded-sm border border-pixel-lineLight p-2 space-y-3"
              >
                {loading ? (
                  <div className="flex items-center justify-center h-full py-10">
                    <Icon icon={Loader2} size="md" className="text-pixel-muted animate-spin" />
                  </div>
                ) : messages.length === 0 ? (
                  <div className="flex flex-col items-center justify-center h-full gap-2 text-center py-10">
                    <Icon icon={BookOpen} size="lg" className="text-pixel-muted opacity-60" />
                    <p className="text-xs text-album-warm font-bold leading-relaxed">
                      还没有留言，
                      <br />
                      写下第一句吧
                    </p>
                  </div>
                ) : (
                  messages.map((msg) => (
                    <div key={msg.id} className="flex flex-col w-full">
                      <div className="text-xs text-album-warm mb-1 font-bold text-right select-none">
                        你 at {formatTime(msg.createdAt)}
                      </div>
                      <div className="p-2 max-w-[90%] border-2 border-black shadow-[2px_2px_0_rgba(0,0,0,0.15)] text-xs leading-relaxed bg-pixel-bubble text-black self-end whitespace-pre-wrap break-words">
                        {msg.content}
                      </div>
                    </div>
                  ))
                )}
              </div>

              {/* 底部输入区 */}
              <div className="pt-2 border-t border-album-warm/35">
                {error && (
                  <p className="text-xs text-pixel-error font-bold mb-1.5">{error}</p>
                )}
                <div className="flex gap-1.5 w-full items-stretch h-9">
                  <input
                    type="text"
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        e.preventDefault()
                        handleSend()
                      }
                    }}
                    placeholder="写下一句留言..."
                    maxLength={500}
                    disabled={sending}
                    className="flex-grow pixel-input min-w-0 text-xs"
                  />
                  <button
                    type="button"
                    onClick={handleSend}
                    disabled={sending || !input.trim()}
                    className="pixel-btn pixel-border-green px-3 text-xs font-bold rounded-sm"
                    style={{ flexShrink: 0 }}
                  >
                    {sending ? <Icon icon={Loader2} size="sm" className="animate-spin" /> : <Icon icon={Send} size="sm" />}
                    发送
                  </button>
                </div>
                <p className="text-xs text-pixel-muted mt-1.5 text-center select-none">
                  Enter 发送 · 留言仅与当前照片绑定
                </p>
              </div>
            </div>

            {/* 页码 */}
            <div className="text-xs text-pixel-muted text-center mt-2 font-bold select-none">第 1 页</div>
          </div>

          {/* 右页：留言面板 */}
          <div className="w-full md:w-1/2 p-4 md:pl-8 relative">
            <div className="absolute top-2 right-2 w-2 h-2 border-t border-r border-pixel-lineLight" />
            <div className="absolute bottom-2 right-2 w-2 h-2 border-b border-r border-pixel-lineLight" />

            <div className="flex flex-col h-[620px] justify-between">
              {/* 日期 */}
              <div className="flex justify-end items-center pb-2 border-b border-album-warm/35 text-pixel-muted text-xs font-bold select-none">
                <span className="flex items-center gap-1 text-pixel-ink">
                  <Icon icon={Clock} size="sm" /> {todayText()}
                </span>
              </div>

              {/* 面板主体 */}
              <div className="flex-1 flex flex-col items-center justify-center px-4 text-center select-none">
                <div className="w-14 h-10 text-pixel-muted mb-3 opacity-70">
                  <svg viewBox="0 0 24 24" className="w-full h-full fill-none stroke-current stroke-2" xmlns="http://www.w3.org/2000/svg">
                    <path d="M12 21V5a3 3 0 0 0-3-3H2v16h7a3 3 0 0 1 3 3Z" />
                    <path d="M12 21v-16a3 3 0 0 1 3-3h7v16h-7a3 3 0 0 0-3 3Z" />
                  </svg>
                </div>
                <h4 className="text-xs font-bold text-pixel-ink mb-3 tracking-wider">—— 留言面板 ——</h4>

                {/* 照片底片 */}
                <div
                  className="photo-negative-container w-28 h-28 select-none cursor-pointer hover:brightness-110 hover:scale-105 active:scale-95 transition-all"
                  onClick={() => setPreviewOpen(true)}
                  title="点击预览大图"
                >
                  <div className="photo-negative-tag">寄照底片</div>
                  <img src={image} alt="记忆底片" width={112} height={112} loading="lazy" decoding="async" className="w-full h-full object-cover" />
                </div>

                <p className="text-xs text-album-warm mt-3 font-bold">
                  {messages.length > 0 ? `已收集 ${messages.length} 条留言` : '等待第一条留言'}
                </p>
                <p className="text-xs text-pixel-muted mt-1.5 leading-relaxed max-w-[240px]">
                  点击左侧照片或底片可预览大图，也可以返回相册继续翻阅其它记忆。
                </p>
              </div>

              {/* 底部按钮 */}
              <div className="flex justify-between items-end pt-2 border-t border-album-warm/35 gap-2">
                <button
                  type="button"
                  onClick={() => setPreviewOpen(true)}
                  className="flex-1 mc-button mc-button-gold !py-1.5 text-xs font-bold flex items-center justify-center gap-1"
                >
                  <Icon icon={ImageIcon} size="sm" className="shrink-0" />
                  预览大图
                </button>
                <button
                  type="button"
                  onClick={onBack}
                  className="flex-1 mc-button mc-button-parchment !py-1.5 text-xs font-bold flex items-center justify-center gap-1"
                >
                  <Icon icon={MessageCircle} size="sm" className="shrink-0" />
                  返回相册
                </button>
              </div>
            </div>

            {/* 页码 */}
            <div className="text-xs text-pixel-muted text-center mt-2 font-bold select-none">第 2 页</div>
          </div>
        </div>
      </div>

      {/* 大图预览 */}
      {previewOpen && (
        <div
          className="fixed inset-0 z-[120] bg-black/95 flex items-center justify-center p-4"
          onClick={() => setPreviewOpen(false)}
          ref={panelRef}
          tabIndex={-1}
          role="dialog"
          aria-modal="true"
          aria-label="照片大图预览"
        >
          <button
            type="button"
            onClick={() => setPreviewOpen(false)}
            className="pixel-close-btn absolute top-4 right-4 z-10"
            aria-label="关闭预览"
          >
            <Icon icon={X} size="sm" />
          </button>
          <div className="max-w-4xl w-full max-h-full" onClick={(e) => e.stopPropagation()}>
            <img
              src={image}
              alt={`${cityName || '旅行记忆'} 大图预览`}
              loading="eager"
              decoding="async"
              className="w-full max-h-[85vh] object-contain border-4 border-black shadow-[8px_8px_0_rgba(0,0,0,0.6)]"
            />
            <p className="text-center text-xs text-album-warm mt-3 font-bold select-none">
              点击任意处关闭 · Esc 关闭
            </p>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { cn } from '@/lib/utils'

export interface TravelStarMapCity {
  name: string
  lat: number
  lng: number
  date?: string
  count?: number
}

interface TravelStarMapProps {
  cities: TravelStarMapCity[]
  stats?: { cities?: number; days?: number; photos?: number }
  className?: string
  onSelectCity?: (city: TravelStarMapCity) => void
}

// 中国经纬度范围（与旧 SVG 投影一致）
const LON_MIN = 73
const LON_MAX = 135
const LAT_MIN = 18
const LAT_MAX = 53

// 仿 3D 相机：绕 X 轴俯仰，北侧远离视角，形成「倾斜星盘」的近大远小透视
const TILT = 0.94
const CAMERA_D = 3.6
const BASE_R = 4.5
const MIN_SCALE = 0.45
const MAX_SCALE = 5

const clamp = (v: number, min: number, max: number) => Math.max(min, Math.min(max, v))

interface Projected {
  city: TravelStarMapCity
  x: number
  y: number
  s: number
}

/** 经纬度 -> 倾斜星盘上的透视投影（含按照片数的悬浮高度） */
function projectCity(city: TravelStarMapCity, maxCount: number): { x: number; y: number; s: number } {
  const nx = (city.lng - LON_MIN) / (LON_MAX - LON_MIN)
  const ny = (LAT_MAX - city.lat) / (LAT_MAX - LAT_MIN)
  const wx = nx * 2 - 1
  const wy = ny * 2 - 1
  // 悬浮高度：照片越多，星点越「浮起」、越靠近镜头
  const lift = 0.1 + 0.2 * (maxCount > 0 ? clamp((city.count ?? 0) / maxCount, 0, 1) : 0)
  const cosT = Math.cos(TILT)
  const sinT = Math.sin(TILT)
  const y = wy * cosT - lift * sinT
  const z = wy * sinT + lift * cosT
  const depth = CAMERA_D - z
  const s = CAMERA_D / depth
  return { x: wx * s, y: y * s, s }
}

/** 世界坐标 -> 屏幕坐标（含缩放/平移），r 为星点半径 */
function toScreen(p: Projected, W: number, H: number, scale: number, ox: number, oy: number) {
  const k = Math.min(W, H) * 0.44 * scale
  return {
    x: W / 2 + p.x * k + ox,
    y: H / 2 + p.y * k + oy,
    r: clamp(BASE_R * p.s * scale, 2.4, 13),
  }
}

interface Star {
  wx: number
  wy: number
  par: number
  r: number
  alpha: number
  phase: number
}

/** 背景星点：确定性伪随机，避免重渲染跳动；透明度上限 0.5（不喧宾夺主） */
function buildStars(count: number): Star[] {
  const stars: Star[] = []
  let seed = 7
  const rand = () => {
    seed = (seed * 16807) % 2147483647
    return (seed - 1) / 2147483646
  }
  for (let i = 0; i < count; i++) {
    stars.push({
      wx: rand() * 3 - 1.5,
      wy: rand() * 2.4 - 1.2,
      par: 0.25 + rand() * 0.35,
      r: 0.4 + rand() * 1.1,
      alpha: 0.08 + rand() * 0.3,
      phase: rand() * Math.PI * 2,
    })
  }
  return stars
}

const STARS = buildStars(110)

/** 城市星点光晕 sprite（预热一次，避免每帧建渐变） */
function getGlow(ref: { current: HTMLCanvasElement | null }): HTMLCanvasElement {
  if (!ref.current) {
    const size = 96
    const cv = document.createElement('canvas')
    cv.width = cv.height = size
    const c = cv.getContext('2d')!
    const g = c.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
    g.addColorStop(0, 'rgba(232,176,106,0.5)')
    g.addColorStop(0.4, 'rgba(232,176,106,0.16)')
    g.addColorStop(1, 'rgba(232,176,106,0)')
    c.fillStyle = g
    c.fillRect(0, 0, size, size)
    ref.current = cv
  }
  return ref.current
}

export default function TravelStarMap({ cities, stats, className, onSelectCity }: TravelStarMapProps) {
  const wrapRef = useRef<HTMLDivElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const glowRef = useRef<HTMLCanvasElement | null>(null)

  const [selected, setSelected] = useState<{ city: TravelStarMapCity; x: number; y: number } | null>(null)

  const viewRef = useRef({ scale: 1, ox: 0, oy: 0 })
  const velRef = useRef({ x: 0, y: 0 })
  const reducedMotionRef = useRef(false)
  const selectedNameRef = useRef<string | null>(null)

  const pointersRef = useRef(new Map<number, { x: number; y: number }>())
  const pinchDistRef = useRef(0)
  const prevMidRef = useRef({ x: 0, y: 0 })
  const dragRef = useRef<{ x: number; y: number; ox: number; oy: number; moved: number; t: number } | null>(null)
  const lastDragPosRef = useRef<{ x: number; y: number } | null>(null)
  const draggingRef = useRef(false)

  const points: Projected[] = useMemo(() => {
    const valid = cities.filter((c) => Number.isFinite(c.lat) && Number.isFinite(c.lng))
    const maxCount = Math.max(1, ...valid.map((c) => c.count ?? 0))
    return valid.map((city) => ({ city, ...projectCity(city, maxCount) }))
  }, [cities])

  const draw = useCallback((now: number) => {
    const canvas = canvasRef.current
    const wrap = wrapRef.current
    if (!canvas || !wrap) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    const dpr = Math.min(window.devicePixelRatio || 1, 2)
    const W = wrap.clientWidth
    const H = wrap.clientHeight
    if (W === 0 || H === 0) return
    const bw = Math.round(W * dpr)
    const bh = Math.round(H * dpr)
    if (canvas.width !== bw) canvas.width = bw
    if (canvas.height !== bh) canvas.height = bh
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    ctx.clearRect(0, 0, W, H)

    const { scale, ox, oy } = viewRef.current
    const k = Math.min(W, H) * 0.44
    const selName = selectedNameRef.current

    // 1) 背景星点（视差小，营造纵深；克制，透明度 ≤ 0.5）
    for (const st of STARS) {
      const tw = reducedMotionRef.current ? 0.5 : 0.5 + 0.5 * Math.sin(now * 0.0007 + st.phase)
      const sx = W / 2 + st.wx * k * 1.3 * (1 + (scale - 1) * 0.35) + ox * st.par
      const sy = H / 2 + st.wy * k * 1.3 * (1 + (scale - 1) * 0.35) + oy * st.par
      ctx.globalAlpha = clamp(st.alpha * tw, 0.03, 0.5)
      ctx.fillStyle = '#eef2ff'
      ctx.beginPath()
      ctx.arc(sx, sy, st.r, 0, Math.PI * 2)
      ctx.fill()
    }
    ctx.globalAlpha = 1

    // 2) 星际航线（按时间顺序连线，缓慢流光）
    if (points.length > 1) {
      const pts = points.map((p) => toScreen(p, W, H, scale, ox, oy))
      ctx.lineJoin = 'round'
      ctx.lineCap = 'round'
      ctx.strokeStyle = 'rgba(232,176,106,0.10)'
      ctx.lineWidth = 2.5
      ctx.setLineDash([])
      ctx.beginPath()
      pts.forEach((s, i) => (i === 0 ? ctx.moveTo(s.x, s.y) : ctx.lineTo(s.x, s.y)))
      ctx.stroke()
      ctx.strokeStyle = 'rgba(232,176,106,0.30)'
      ctx.lineWidth = 1.1
      ctx.setLineDash([3, 7])
      ctx.lineDashOffset = reducedMotionRef.current ? 0 : -(now * 0.006)
      ctx.beginPath()
      pts.forEach((s, i) => (i === 0 ? ctx.moveTo(s.x, s.y) : ctx.lineTo(s.x, s.y)))
      ctx.stroke()
      ctx.setLineDash([])
    }

    // 3) 城市星点 + 名称标签
    const glow = getGlow(glowRef)
    ctx.textAlign = 'center'
    ctx.textBaseline = 'top'
    for (const p of points) {
      const s = toScreen(p, W, H, scale, ox, oy)
      const isSel = selName === p.city.name
      const gsize = s.r * (isSel ? 5 : 3.4)
      ctx.globalAlpha = isSel ? 0.85 : 0.5
      ctx.drawImage(glow, s.x - gsize / 2, s.y - gsize / 2, gsize, gsize)
      ctx.globalAlpha = 1
      ctx.fillStyle = isSel ? '#f5c97e' : '#e8b06a'
      ctx.beginPath()
      ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2)
      ctx.fill()
      if (isSel) {
        ctx.strokeStyle = 'rgba(245,201,126,0.65)'
        ctx.lineWidth = 1
        ctx.beginPath()
        ctx.arc(s.x, s.y, s.r + 4, 0, Math.PI * 2)
        ctx.stroke()
      }
      ctx.globalAlpha = 0.62
      ctx.fillStyle = '#c9d2e0'
      ctx.font = "11px 'PingFang SC','Microsoft YaHei',sans-serif"
      ctx.fillText(p.city.name, s.x, s.y + s.r + 5)
      ctx.globalAlpha = 1
    }
  }, [points])

  // 渲染循环（含惯性缓动 + 后台暂停）
  useEffect(() => {
    reducedMotionRef.current = window.matchMedia('(prefers-reduced-motion: reduce)').matches
    let raf = 0
    let running = true
    let last = performance.now()

    const tick = (now: number) => {
      if (!running) return
      const dt = Math.min(0.05, (now - last) / 1000)
      last = now
      if (!reducedMotionRef.current && !draggingRef.current) {
        const vx = velRef.current.x
        const vy = velRef.current.y
        if (Math.abs(vx) > 0.02 || Math.abs(vy) > 0.02) {
          viewRef.current.ox += vx
          viewRef.current.oy += vy
          velRef.current.x = vx * 0.88
          velRef.current.y = vy * 0.88
        } else {
          velRef.current.x = 0
          velRef.current.y = 0
        }
      }
      draw(now)
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)

    const onVis = () => {
      if (document.hidden) {
        running = false
        cancelAnimationFrame(raf)
      } else if (!running) {
        running = true
        last = performance.now()
        raf = requestAnimationFrame(tick)
      }
    }
    document.addEventListener('visibilitychange', onVis)
    return () => {
      running = false
      cancelAnimationFrame(raf)
      document.removeEventListener('visibilitychange', onVis)
    }
  }, [draw])

  // 手势 / 键鼠事件
  useEffect(() => {
    const canvas = canvasRef.current
    const wrap = wrapRef.current
    if (!canvas) return

    const hitTest = (px: number, py: number): Projected | null => {
      if (!wrap) return null
      const W = wrap.clientWidth
      const H = wrap.clientHeight
      const { scale, ox, oy } = viewRef.current
      for (let i = points.length - 1; i >= 0; i--) {
        const s = toScreen(points[i], W, H, scale, ox, oy)
        if (Math.hypot(px - s.x, py - s.y) <= Math.max(s.r + 7, 20)) return points[i]
      }
      return null
    }

    const select = (p: Projected) => {
      selectedNameRef.current = p.city.name
      if (!wrap) {
        setSelected({ city: p.city, x: 0, y: 0 })
        return
      }
      const W = wrap.clientWidth
      const H = wrap.clientHeight
      const s = toScreen(p, W, H, viewRef.current.scale, viewRef.current.ox, viewRef.current.oy)
      const cardX = clamp(s.x, 96, Math.max(96, W - 96))
      const cardY = s.y > 104 ? clamp(s.y - 82, 6, H - 84) : clamp(s.y + 20, 6, H - 84)
      setSelected({ city: p.city, x: cardX, y: cardY })
      onSelectCity?.(p.city)
    }

    const clearSelect = () => {
      selectedNameRef.current = null
      setSelected(null)
    }

    const zoomAt = (px: number, py: number, factor: number) => {
      const next = clamp(viewRef.current.scale * factor, MIN_SCALE, MAX_SCALE)
      const real = next / viewRef.current.scale
      if (real === 1) return
      viewRef.current.ox = px - (px - viewRef.current.ox) * real
      viewRef.current.oy = py - (py - viewRef.current.oy) * real
      viewRef.current.scale = next
    }

    const onPointerDown = (e: PointerEvent) => {
      canvas.setPointerCapture?.(e.pointerId)
      pointersRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY })
      if (pointersRef.current.size === 1) {
        dragRef.current = { x: e.clientX, y: e.clientY, ox: viewRef.current.ox, oy: viewRef.current.oy, moved: 0, t: performance.now() }
        lastDragPosRef.current = { x: e.clientX, y: e.clientY }
        draggingRef.current = true
        velRef.current = { x: 0, y: 0 }
      } else if (pointersRef.current.size === 2) {
        dragRef.current = null
        draggingRef.current = true
        const pts = Array.from(pointersRef.current.values())
        pinchDistRef.current = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y)
        prevMidRef.current = { x: (pts[0].x + pts[1].x) / 2, y: (pts[0].y + pts[1].y) / 2 }
      }
    }

    const onPointerMove = (e: PointerEvent) => {
      if (!pointersRef.current.has(e.pointerId)) return
      pointersRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY })
      if (pointersRef.current.size >= 2) {
        const pts = Array.from(pointersRef.current.values())
        const mid = { x: (pts[0].x + pts[1].x) / 2, y: (pts[0].y + pts[1].y) / 2 }
        const dist = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y)
        if (pinchDistRef.current > 0 && dist > 0) {
          const rect = canvas.getBoundingClientRect()
          zoomAt(mid.x - rect.left, mid.y - rect.top, dist / pinchDistRef.current)
          viewRef.current.ox += mid.x - prevMidRef.current.x
          viewRef.current.oy += mid.y - prevMidRef.current.y
        }
        pinchDistRef.current = dist
        prevMidRef.current = mid
        clearSelect()
        return
      }
      const ds = dragRef.current
      if (!ds) return
      const dx = e.clientX - ds.x
      const dy = e.clientY - ds.y
      ds.moved = Math.max(ds.moved, Math.abs(dx) + Math.abs(dy))
      viewRef.current.ox = ds.ox + dx
      viewRef.current.oy = ds.oy + dy
      if (lastDragPosRef.current) {
        velRef.current.x = (e.clientX - lastDragPosRef.current.x) * 0.6
        velRef.current.y = (e.clientY - lastDragPosRef.current.y) * 0.6
      }
      lastDragPosRef.current = { x: e.clientX, y: e.clientY }
      if (ds.moved > 6) clearSelect()
    }

    const onPointerUp = (e: PointerEvent) => {
      pointersRef.current.delete(e.pointerId)
      if (pointersRef.current.size < 2) pinchDistRef.current = 0
      if (pointersRef.current.size === 0) {
        draggingRef.current = false
        const ds = dragRef.current
        if (ds) {
          const dt = performance.now() - ds.t
          if (ds.moved < 6 && dt < 500) {
            const rect = canvas.getBoundingClientRect()
            const hit = hitTest(e.clientX - rect.left, e.clientY - rect.top)
            if (hit) select(hit)
            else clearSelect()
          }
          dragRef.current = null
          lastDragPosRef.current = null
        }
      }
    }

    const onWheel = (e: WheelEvent) => {
      e.preventDefault()
      const rect = canvas.getBoundingClientRect()
      zoomAt(e.clientX - rect.left, e.clientY - rect.top, e.deltaY > 0 ? 0.88 : 1.14)
      clearSelect()
    }

    const onDblClick = () => {
      viewRef.current = { scale: 1, ox: 0, oy: 0 }
      velRef.current = { x: 0, y: 0 }
      clearSelect()
    }

    const onKeyDown = (e: KeyboardEvent) => {
      const cx = (wrap?.clientWidth ?? 0) / 2
      const cy = (wrap?.clientHeight ?? 0) / 2
      if (e.key === '+' || e.key === '=') { e.preventDefault(); zoomAt(cx, cy, 1.15); clearSelect() }
      else if (e.key === '-' || e.key === '_') { e.preventDefault(); zoomAt(cx, cy, 0.87); clearSelect() }
      else if (e.key === 'ArrowLeft') { e.preventDefault(); viewRef.current.ox -= 24; clearSelect() }
      else if (e.key === 'ArrowRight') { e.preventDefault(); viewRef.current.ox += 24; clearSelect() }
      else if (e.key === 'ArrowUp') { e.preventDefault(); viewRef.current.oy -= 24; clearSelect() }
      else if (e.key === 'ArrowDown') { e.preventDefault(); viewRef.current.oy += 24; clearSelect() }
      else if (e.key === '0') { e.preventDefault(); viewRef.current = { scale: 1, ox: 0, oy: 0 }; clearSelect() }
    }

    canvas.addEventListener('pointerdown', onPointerDown)
    window.addEventListener('pointermove', onPointerMove, { passive: true })
    window.addEventListener('pointerup', onPointerUp)
    window.addEventListener('pointercancel', onPointerUp)
    canvas.addEventListener('wheel', onWheel, { passive: false })
    canvas.addEventListener('dblclick', onDblClick)
    canvas.addEventListener('keydown', onKeyDown)

    return () => {
      canvas.removeEventListener('pointerdown', onPointerDown)
      window.removeEventListener('pointermove', onPointerMove)
      window.removeEventListener('pointerup', onPointerUp)
      window.removeEventListener('pointercancel', onPointerUp)
      canvas.removeEventListener('wheel', onWheel)
      canvas.removeEventListener('dblclick', onDblClick)
      canvas.removeEventListener('keydown', onKeyDown)
    }
  }, [points, onSelectCity])

  if (points.length === 0) {
    return (
      <div className={cn('flex min-h-[320px] items-center justify-center rounded-[1.4rem] text-album-text2', className)}>
        还没有可绘制的城市足迹
      </div>
    )
  }

  return (
    <div className={cn('select-none', className)}>
      <div
        ref={wrapRef}
        className="relative h-[min(72vh,620px)] w-full overflow-hidden rounded-[1.4rem] bg-[radial-gradient(60%_60%_at_50%_40%,rgba(40,30,60,0.35),rgba(5,5,8,0)_75%)]"
      >
        <canvas
          ref={canvasRef}
          tabIndex={0}
          role="img"
          aria-label="旅行星图（可缩放、平移）"
          className="block h-full w-full touch-none outline-none focus-visible:ring-1 focus-visible:ring-album-accent/40"
        />

        {/* 手势提示 */}
        <div className="pointer-events-none absolute bottom-3 left-1/2 -translate-x-1/2 whitespace-nowrap text-[10px] tracking-[0.2em] text-album-text3">
          双指缩放 · 拖拽平移 · 双击复位
        </div>

        {/* 选中城市信息卡（点击进入该城市相册档案） */}
        {selected && (
          <div className="absolute z-10 -translate-x-1/2" style={{ left: selected.x, top: selected.y }}>
            <button
              type="button"
              onClick={() => onSelectCity?.(selected.city)}
              className="space-glass cursor-pointer rounded-xl px-3.5 py-2 text-center hover:scale-[1.03]"
            >
              <div className="text-xs font-bold tracking-widest text-album-text1">{selected.city.name}</div>
              {(selected.city.date || selected.city.count != null) && (
                <div className="mt-1 whitespace-nowrap text-[10px] text-album-text2">
                  {selected.city.date}
                  {selected.city.count != null ? ' · ' + selected.city.count + ' 张' : ''}
                </div>
              )}
              <div className="mt-1 text-[10px] tracking-widest text-album-accent">查看档案 →</div>
            </button>
          </div>
        )}
      </div>

      {stats && (
        <p className="mt-3 text-center font-zpix text-xs text-album-accent">
          {stats.days !== undefined || stats.photos !== undefined
            ? '走过 ' + (stats.cities ?? points.length) + ' 城 · ' + (stats.days ?? 0) + ' 天 · ' + (stats.photos ?? 0) + ' 张照片'
            : '走过 ' + points.length + ' 个城市'}
        </p>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { formatDay } from '@/lib/modules/album/presentation'
import type { BookPage, BookPhotoRef } from '@/lib/modules/album/book/types'
import { LazyArtImage } from './LazyArtImage'

/* ==========================================================================
   Book Sheet —— 新版画册页渲染（Album 2.0 M1/M2）
   与旧 reader/ArtPage.tsx 的关系：
     · 视觉语言（纸纹、油角、Source Serif、folio）**完全继承** ArtPage，不换皮；
     · 数据结构换成 lib/modules/album/book/types 的 BookPage / BookSpread：
       页面模板不再自己凑对开配平，出血方向由 paginate 写入的 `side` 决定。
   ========================================================================== */

/* ---------- 封面（布面 + 书名 + 封面照） ---------- */
function CoverPage({ page }: { page: BookPage }) {
  const photo = page.photos[0]
  return (
    <div className="art-page cloth">
      <h2 className="cover-title">{page.title}</h2>
      {page.subtitle && <p className="cover-subtitle">{page.subtitle}</p>}
      {photo && (photo.previewUrl || photo.thumbnailUrl) && (
        <figure className="cover-plate">
          {/* 封面是首屏图：eager + 高优先级，不等 IntersectionObserver */}
          <LazyArtImage
            src={photo.previewUrl || photo.thumbnailUrl}
            alt={page.title ?? '旅行画册封面'}
            placeholderUrl={photo.blurUrl}
            eager
            fetchPriority="high"
          />
        </figure>
      )}
      <p className="cover-foot">{page.takenAt ? formatDay(page.takenAt) : 'Tiantu'}</p>
    </div>
  )
}

/* ---------- 前言 / 结尾（同版式，内容不同） ---------- */
function TextPage({ page }: { page: BookPage }) {
  const isEnd = page.type === 'ENDING'
  return (
    <div className={`art-page ${isEnd ? 'endpaper' : 'paper'} chapter-intro`}>
      <span className="oil-edge oil-faint oil-tl" aria-hidden="true" />
      <span className="oil-edge oil-faint oil-br" aria-hidden="true" />
      <div className="chapter-intro-inner">
        {page.title && <h2 className="chapter-title">{page.title}</h2>}
        {page.subtitle && <p className="chapter-date">{page.subtitle}</p>}
        {page.body && <p className="chapter-summary">{page.body}</p>}
      </div>
      {isEnd && <span className="back-mark">Tiantu</span>}
    </div>
  )
}

/* ---------- DAY 引导页（行程 + 章节信息） ---------- */
function DayOpeningPage({ page }: { page: BookPage }) {
  const day = String(page.dayIndex ?? 0).padStart(2, '0')
  return (
    <div className="art-page paper chapter-intro">
      <span className="oil-edge oil-faint oil-tl" aria-hidden="true" />
      <span className="oil-edge oil-faint oil-br" aria-hidden="true" />
      <div className="chapter-intro-inner">
        <p className="chapter-kicker">DAY · {day}</p>
        <h2 className="chapter-title">{page.title || `DAY ${day}`}</h2>
        {page.takenAt && <p className="chapter-date">{formatDay(page.takenAt)}</p>}
        {page.caption && <p className="chapter-summary">{page.caption}</p>}
        {page.body && (
          <section className="chapter-section" aria-label="行程">
            <h3>行程</h3>
            <ul className="chapter-itinerary">
              {page.body.split(' / ').slice(0, 8).map((line, i) => (
