interface TurnState {
  dir: Dir
  from: number
  to: number
  t: number
  strips: HTMLDivElement[]
}

/* 弯曲纸几何（沿用参考站参数） */
const N = 18
const SPAN = 0.449
const BETA = 0.60
/* 书倾斜 / 缩放 */
const TILT_X = 4.5
const TILT_Y = 7
const ZOOM_MIN = 0.9
const ZOOM_MAX = 1.5
/* 放大镜 */
const MAG = 2.3

function clamp(v: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, v))
}
function div(cls: string): HTMLDivElement {
  const e = document.createElement('div')
  e.className = cls
  return e
}

export default function Sketchbook({ book, onBack, onToggleBook }: { book: Book; onBack: () => void; onToggleBook?: () => void }) {
  const spreads = useMemo(() => buildSpreads(book), [book])

  const [idx, setIdx] = useState(0)
  const [sketch, setSketch] = useState(false)
  const [indexOpen, setIndexOpen] = useState(false)
  const [loupeOn, setLoupeOn] = useState(false)
  const [showHint, setShowHint] = useState(true)
  const [viewer, setViewer] = useState<Spread | null>(null)

  // P2-B2：统一弹层基座（焦点圈定/恢复、背景 inert、滚动锁、ESC/返回键）
  const panelRef = useRef<HTMLDivElement>(null)
  useModalLayer({
    open: Boolean(viewer),
    onClose: () => setViewer(null),
    panelRef,
  })

  const rootRef = useRef<HTMLDivElement>(null)
  const threeDRef = useRef<HTMLDivElement>(null)
  const tiltRef = useRef<HTMLDivElement>(null)
  const bookRef = useRef<HTMLDivElement>(null)
  const loupeRef = useRef<HTMLDivElement>(null)
  const zoomWrapRef = useRef<HTMLDivElement>(null)
  const zoomInnerRef = useRef<HTMLDivElement>(null)
  const zoomReadRef = useRef<HTMLSpanElement>(null)
  const zInRef = useRef<HTMLButtonElement>(null)
  const zOutRef = useRef<HTMLButtonElement>(null)

  const idxRef = useRef(0)
  const turnRef = useRef<TurnState | null>(null)
  const springRef = useRef<any>(null)
  const dragRef = useRef<any>(null)
  const loupeRefState = useRef<any>({ x: null, y: null, grab: null, target: null })
  const viewRef = useRef({ rx: 0, ry: 0, z: 1, trx: 0, try_: 0, tz: 1 })
  const lastZ = useRef(1)
  const rafRef = useRef<number | null>(null)
  const lastTs = useRef(0)
  const reducedRef = useRef(false)
  const hintTimer = useRef<number | null>(null)
  /* ---------- 图片预取缓存（避免翻页时旧图重叠/空白） ---------- */
  const imgCacheRef = useRef<Map<string, HTMLImageElement>>(new Map())
  // 缓存上限：超大画册翻完全书会把全部解码位图常驻内存，超限按插入序淘汰最旧
  const IMG_CACHE_MAX = 600

  useEffect(() => {
    reducedRef.current = typeof window !== 'undefined' && window.matchMedia?.('(prefers-reduced-motion: reduce)').matches
    const hide = () => setShowHint(false)
    hintTimer.current = window.setTimeout(hide, 4200)
    return () => {
      if (hintTimer.current) window.clearTimeout(hintTimer.current)
    }
  }, [])

  /* ---------- 几何 ---------- */
  const bookBox = useCallback(() => {
    const el = bookRef.current
    if (!el) return { w: 0, h: 0 }
    return { w: el.clientWidth, h: el.clientHeight }
  }, [])

  const loupeSize = useCallback(() => {
    // 书宽的 23.5%（165-262 取整），此前 `?? 0 * 0.235` 优先级写反使比例失效
    return Math.round(Math.max(165, Math.min(262, (bookRef.current?.clientWidth ?? 0) * 0.235)))
  }, [])

  /* ---------- 图片预取（立即发送请求 + 判断/等待解码） ---------- */
  const warmImage = useCallback((url: string): HTMLImageElement | null => {
    if (!url) return null
    let img = imgCacheRef.current.get(url)
    if (!img) {
      img = new Image()
      img.decoding = 'async'
      img.loading = 'eager'
      img.src = url
      imgCacheRef.current.set(url, img)
      if (imgCacheRef.current.size > IMG_CACHE_MAX) {
        const oldest = imgCacheRef.current.keys().next().value
        if (oldest !== undefined && oldest !== url) imgCacheRef.current.delete(oldest)
      }
    }
    return img
  }, [])

  const isImageReady = useCallback((url: string): boolean => {
    const img = imgCacheRef.current.get(url)
    if (!img) return false
    return img.complete && img.naturalWidth > 0
  }, [])

  const waitImageReady = useCallback((url: string, timeout = 3000): Promise<void> => {
    if (!url) return Promise.resolve()
    const img = warmImage(url)
    if (!img) return Promise.resolve()
    if (img.complete && img.naturalWidth > 0) return Promise.resolve()
    return new Promise((resolve) => {
      let settled = false
      const finish = () => {
        if (settled) return
        settled = true
        img.removeEventListener('load', finish)
        img.removeEventListener('error', finish)
        clearTimeout(timer)
        resolve()
      }
      const timer = setTimeout(finish, timeout)
      img.addEventListener('load', finish)
      img.addEventListener('error', finish)
    })
  }, [warmImage])

  /* ---------- 书内容绘制（幂等：每次清空重建） ---------- */
  const paint = useCallback(() => {
    const bookEl = bookRef.current
    if (!bookEl) return
    bookEl.textContent = ''
    const turn = turnRef.current

    const setSketch = (img: HTMLImageElement) => {
      if (sketch) img.classList.add('sk-sketch')
    }

    /* 一页书页（左右半页其一）：模糊占位(仅当图未就绪) + 半页图 + 中缝阴影 + 外侧纸边 */
    const page = (pos: 'left' | 'right', sp: Spread) => {
      const p = div('sk-half ' + pos)
      let blur: HTMLDivElement | null = null
      // 图已就绪则不创建模糊占位，杜绝"加载完仍残留模糊层次"
      const ready = isImageReady(sp.image)
      if (!ready && sp.blur && sp.blur !== sp.image) {
        blur = div('sk-blur')
        blur.style.backgroundImage = 'url(' + sp.blur + ')'
        p.appendChild(blur)
      }
      const img = new Image()
      img.src = sp.image
      img.alt = sp.title
      img.draggable = false
      img.decoding = 'async'
      img.className = 'sk-half-img' + (pos === 'right' ? ' right' : '')
      setSketch(img)
      let blurCleared = false
      const clearBlur = () => {
        if (!blur || blurCleared) return
        blurCleared = true
        blur.style.opacity = '0'
        window.setTimeout(() => { if (blur.parentNode === p) blur.remove() }, 360)
      }
      if (blur) {
        // 图就绪后淡出/移除模糊占位；若缓存图同步可用则立即清除
        img.addEventListener('load', clearBlur, { once: true })
        img.addEventListener('error', clearBlur, { once: true })
        if (img.complete && img.naturalWidth > 0) clearBlur()
      }
      p.appendChild(img)
      p.appendChild(div('sk-gutter-shade ' + pos))
      p.appendChild(div('sk-page-edge ' + (pos === 'left' ? 'l' : 'r')))
      return p
    }

    if (!turn) {
      // 静止：打开的素描本（左右两页并排，图片跨页铺满）
      const open = div('sk-open')
      const sp = spreads[idxRef.current]
      if (sp) {
        open.appendChild(page('left', sp))
        open.appendChild(page('right', sp))
        if (sp.kind === 'cover') {
          // 封面：跨页书目信息（书名/地点/日期），压在图片上方成书封
          const overlay = div('sk-cover')
          overlay.innerHTML =
            '<div class="sk-cover-kicker">Tiantu · 旅行画册</div>' +
            '<div class="sk-cover-title"></div>' +
            '<div class="sk-cover-sub"></div>'
          overlay.querySelector('.sk-cover-title')!.textContent = book.title
          const sub = overlay.querySelector('.sk-cover-sub')!
          const parts: string[] = []
          if (book.location) parts.push(book.location)
          if (book.startDate) parts.push(formatDotDate(book.startDate))
          sub.textContent = parts.join(' · ')
          open.appendChild(overlay)
        } else if (sp.kind === 'summary') {
          const overlay = div('sk-summary')
          overlay.innerHTML =
            '<div class="sk-sum-kicker">End · 旅行总结</div>' +
            '<div class="sk-sum-title"></div>' +
            '<div class="sk-sum-stats"><div><b></b><span>天数</span></div><div><b></b><span>照片</span></div></div>' +
            '<div class="sk-sum-close">谢谢翻阅，收藏这段路上的时光。</div>'
          overlay.querySelector('.sk-sum-title')!.textContent = sp.title
          const stats = overlay.querySelectorAll('.sk-sum-stats b')
          stats[0].textContent = String(book.dayCount || spreads.length - 2)
          stats[1].textContent = String(sp.count)
          open.appendChild(overlay)
        }
      }
      bookEl.style.setProperty('--shade', '0')
      bookEl.appendChild(open)
    } else {
      // 翻页：左页不动，右页（或左页）抬起，另一页露出
      const next = turn.dir === 'next'
      const fromSp = spreads[turn.from]
      const toSp = spreads[turn.to]
      const open = div('sk-open')
      if (fromSp) open.appendChild(page('left', next ? fromSp : toSp))
      if (toSp) open.appendChild(page('right', next ? toSp : fromSp))
      bookEl.appendChild(open)

      const curl = buildCurl(turn, fromSp, toSp)
      bookEl.appendChild(curl)
      applyTurn(turn.t)
    }

    syncZoomLayer()
    placeLoupe()
  }, [sketch, spreads, isImageReady])

  /* ---------- 弯曲纸：嵌套条带 ---------- */
  const buildCurl = (turn: TurnState, fromSp?: Spread, toSp?: Spread) => {
    const c = div('sk-curl ' + turn.dir)
    c.style.setProperty('--n', String(N))
    c.style.setProperty('--span', String(SPAN))
    let host = c as HTMLDivElement
    const strips: HTMLDivElement[] = []
    for (let i = 0; i < N; i++) {
      const s = div('sk-strip')
      s.style.setProperty('--i', String(i))
      const gut = 'calc(var(--bw) * 0.5)'
      const sw = 'calc(var(--bw) * ' + SPAN + ' / ' + N + ')'
      const A = 'calc(-1 * (' + gut + ' + ' + i + ' * ' + sw + '))'
      const B = 'calc((' + (i + 1) + ' * ' + sw + ') - ' + gut + ')'
      const front = div('sk-face front')
      const back = div('sk-face back')
      const dress = (face: HTMLDivElement, url: string, px: string) => {
        face.style.backgroundImage = 'url(' + url + ')'
        face.style.backgroundPositionX = px
      }
      // 目标图未就绪时用模糊占位，避免翻页瞬间露出上一张/空白造成重叠
      const displayUrl = (sp: Spread | undefined): string => {
        if (!sp) return ''
        warmImage(sp.image)
        if (sp.blur && sp.blur !== sp.image) warmImage(sp.blur)
        return isImageReady(sp.image) ? sp.image : (sp.blur || sp.image)
      }
      const fromUrl = displayUrl(fromSp)
      const toUrl = displayUrl(toSp)
      const useFrom = turn.dir === 'next'
      dress(front, useFrom ? fromUrl : toUrl, useFrom ? A : B)
      dress(back, useFrom ? toUrl : fromUrl, useFrom ? B : A)
      front.appendChild(div('sk-sh'))
      front.appendChild(div('sk-gl'))
      back.appendChild(div('sk-sh'))
      back.appendChild(div('sk-gl'))
      s.appendChild(front)
      s.appendChild(back)
      if (i === N - 1) s.classList.add('edge')
      host.appendChild(s)
      host = s
      strips.push(s)
    }
    turn.strips = strips
    return c
  }

  const applyTurn = useCallback((t: number) => {
    const turn = turnRef.current
    const tilt = tiltRef.current
    if (!turn || !tilt) return
    const th = Math.PI * t
    const beta = BETA * Math.sin(Math.PI * t)
    const D = 180 / Math.PI
    const tt = th + beta
    const td = (2 * beta) / N
    tilt.style.setProperty('--tt', (tt * D).toFixed(2) + 'deg')
    tilt.style.setProperty('--td', (td * D).toFixed(3) + 'deg')
    tilt.style.setProperty('--shade', Math.sin(Math.PI * t).toFixed(3))
    // 逐条明暗
    for (let i = 0; i < turn.strips.length; i++) {
      const l1 = Math.abs(Math.cos(tt - i * td))
      const l2 = Math.abs(Math.cos(tt - (i + 1) * td))
      const st = turn.strips[i].style
      st.setProperty('--lit', l1.toFixed(3))
      st.setProperty('--a1', ((1 - l1) * 0.62).toFixed(3))
      st.setProperty('--a2', ((1 - l2) * 0.62).toFixed(3))
    }
  }, [])

  /* ---------- 放大镜 ---------- */
  const placeLoupe = useCallback(() => {
    const loupe = loupeRef.current
    const zoomWrap = zoomWrapRef.current
    const zoomInner = zoomInnerRef.current
    const ls = loupeRefState.current
    const B = bookBox()
    if (!loupe || !zoomWrap || !zoomInner || !B.w || ls.x === null) return
    const R = loupeSize() / 2
    const bez = R * 2 * 0.058
    loupe.style.setProperty('--lr', R * 2 + 'px')
    loupe.style.transform = 'translate3d(' + (ls.x - R).toFixed(1) + 'px,' + (ls.y - R).toFixed(1) + 'px,0)'
    if (loupeOn) loupe.classList.add('on')
    else loupe.classList.remove('on')

    const z = viewRef.current.z
    const cx = B.w / 2
    const cy = B.h / 2
    const x0 = cx + (B.w * 0.051 - cx) * z
    const x1 = cx + (B.w * 0.949 - cx) * z
    const y0 = cy + (B.h * 0.218 - cy) * z
    const y1 = cy + (B.h * 0.782 - cy) * z
    const nx = Math.max(x0, Math.min(ls.x, x1))
    const ny = Math.max(y0, Math.min(ls.y, y1))
    const inside = ls.x > x0 && ls.x < x1 && ls.y > y0 && ls.y < y1
      ? Math.min(ls.x - x0, x1 - ls.x, ls.y - y0, y1 - ls.y)
      : -Math.hypot(ls.x - nx, ls.y - ny)
    const k = clamp((inside + R * 0.3) / (R * 0.55), 0, 1)
    zoomWrap.style.opacity = (loupeOn ? k : 0).toFixed(3)
    if (k <= 0.002) return
    const r = (R - bez).toFixed(1)
    const mask = 'radial-gradient(circle ' + r + 'px at ' + ls.x.toFixed(1) + 'px ' + ls.y.toFixed(1) + 'px, #000 calc(100% - 1px), transparent 100%)'
    zoomWrap.style.webkitMaskImage = mask
    zoomWrap.style.maskImage = mask
    const px = cx + (ls.x - cx) / z
    const py = cy + (ls.y - cy) / z
    const s = MAG * z
    zoomInner.style.transform = 'translate(' + (ls.x - px * s).toFixed(1) + 'px,' + (ls.y - py * s).toFixed(1) + 'px) scale(' + s.toFixed(4) + ')'
  }, [bookBox, loupeOn, loupeSize])

  const restLoupe = useCallback(() => {
    const B = bookBox()
    if (!B.w) return
    loupeRefState.current.x = B.w * 0.88
    loupeRefState.current.y = B.h * 0.855
    placeLoupe()
  }, [bookBox, placeLoupe])

  const shoveLoupe = useCallback((dir: Dir) => {
    const ls = loupeRefState.current
    const B = bookBox()
    if (!loupeOn || ls.x === null || ls.grab || !B.w) return
    const nx = (B.w / 2 + (ls.x - B.w / 2) / viewRef.current.z) / B.w
    const ny = (B.h / 2 + (ls.y - B.h / 2) / viewRef.current.z) / B.h
    if (nx < 0.02 || nx > 0.98 || ny < 0.17 || ny > 0.83) return
    ls.target = { x: B.w * (dir === 'next' ? 0.12 : 0.88), y: B.h * 0.855 }
  }, [bookBox, loupeOn])

  const syncZoomLayer = useCallback(() => {
    const zoomInner = zoomInnerRef.current
    const book = bookRef.current
    if (!zoomInner || !book) return
    zoomInner.textContent = ''
    for (const c of Array.from(book.children)) {
      zoomInner.appendChild(c.cloneNode(true))
    }
  }, [])

  /* ---------- 倾斜 / 缩放 ---------- */
  const applyView = useCallback(() => {
    const tilt = tiltRef.current
    const v = viewRef.current
    if (!tilt) return
    tilt.style.setProperty('--rx', v.rx.toFixed(2) + 'deg')
    tilt.style.setProperty('--ry', v.ry.toFixed(2) + 'deg')
    tilt.style.setProperty('--zoom', v.z.toFixed(3))
    if (v.z !== lastZ.current) {
      lastZ.current = v.z
      if (zoomReadRef.current) zoomReadRef.current.textContent = Math.round(v.z * 100) + '%'
      if (zInRef.current) zInRef.current.disabled = v.z >= ZOOM_MAX - 0.001
      if (zOutRef.current) zOutRef.current.disabled = v.z <= ZOOM_MIN + 0.001
      placeLoupe()
    }
  }, [placeLoupe])

  const setView = useCallback((rx: number, ry: number, z: number) => {
    const v = viewRef.current
    v.trx = clamp(rx, -TILT_X, TILT_X)
    v.try_ = clamp(ry, -TILT_Y, TILT_Y)
    v.tz = clamp(z, ZOOM_MIN, ZOOM_MAX)
    viewActive.current = true
    kick()
  }, [])

  const viewSpring = useCallback((): boolean => {
    const e = 0.14
    const v = viewRef.current
    let moved = false

    for (const [k, t] of [['rx', 'trx'], ['ry', 'try_'], ['z', 'tz']] as [keyof typeof v, keyof typeof v][]) {
      const target = v[t]
      const cur = v[k]
      if (Math.abs(target - cur) > 0.0006) {
        ;(v as any)[k] = cur + (target - cur) * e
        moved = true
      } else {
        ;(v as any)[k] = target
      }
    }
    if (moved) applyView()
    viewActive.current = moved
    return moved
  }, [applyView])

  const tiltTo = useCallback((cx: number, cy: number) => {
    if (dragRef.current) return
    const book = bookRef.current
    if (!book) return
    const r = book.getBoundingClientRect()
    if (!r.width) return
    const nx = clamp((cx - (r.left + r.width / 2)) / (r.width * 0.62), -1, 1)
    const ny = clamp((cy - (r.top + r.height / 2)) / (r.height * 0.9), -1, 1)
    setView(-ny * TILT_X, nx * TILT_Y, viewRef.current.z)
  }, [setView])

  /* ---------- 翻页 ---------- */
  /** 处理进行中的翻页：已过半视为翻成，未过半视为弹回。
   *  此前一律按“已完成”取 turn.to，拖拽弹回动画中点按钮会跳过一页。 */
  const settleTurn = useCallback((): void => {
    const turn = turnRef.current
    if (!turn) return
    idxRef.current = (turn.t ?? 0) > 0.5 ? turn.to : turn.from
    turnRef.current = null
    paint()
  }, [paint])

  const goTo = useCallback((i: number) => {
    const total = spreads.length
    if (i === idxRef.current || i < 0 || i >= total) return
    settleTurn()
    const fwd = (i - idxRef.current + total) % total
    const back = (idxRef.current - i + total) % total
    if (Math.min(fwd, back) === 1) {
      step(fwd === 1 ? 'next' : 'prev')
    } else {
      idxRef.current = i
      setIdx(i)
      turnRef.current = null
      paint()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [spreads.length, paint, settleTurn])

  const startTurn = useCallback(async (dir: Dir, t: number, awaitReady = false) => {
    springRef.current = null
    settleTurn()
    const from = idxRef.current
    const total = spreads.length
    const to = dir === 'next' ? (from + 1) % total : (from - 1 + total) % total
    const toSp = spreads[to]
    // 按钮/键盘翻页：等目标图解码完成再开翻（拖拽翻页不等待，用模糊占位兜底）
    if (awaitReady && toSp) {
      await waitImageReady(toSp.image)
      if (toSp.blur && toSp.blur !== toSp.image) await waitImageReady(toSp.blur)
      if (idxRef.current !== from) return
    }
    shoveLoupe(dir)
    turnRef.current = { dir, from, to, t: t || 0, strips: [] }
    paint()
  }, [paint, shoveLoupe, spreads.length, settleTurn, waitImageReady])

  const commit = useCallback(() => {
    const turn = turnRef.current
    if (!turn) return
    if (reducedRef.current) {
      idxRef.current = turn.to
      setIdx(turn.to)
      turnRef.current = null
      paint()
      return
    }
    animateTo(1, () => {
      idxRef.current = turn.to
      setIdx(turn.to)
      turnRef.current = null
      paint()
    }, 170, 26)
  }, [paint])

  const cancel = useCallback(() => {
    if (!turnRef.current) return
    animateTo(0, () => {
      turnRef.current = null
      paint()
    }, 150, 24)
  }, [paint])

  const step = useCallback((dir: Dir) => {
    settleTurn()
    startTurn(dir, 0, true).then(() => commit())
  }, [settleTurn, startTurn, commit])

  const animateTo = useCallback((target: number, onDone: () => void, stiff: number, damp: number) => {
    springRef.current = { kind: 'spring', v: 0, target, done: onDone, k: stiff || 150, c: damp || 22 }
    kick()
  }, [])

  /* ---------- 弹簧/动画循环 ---------- */
  const viewActive = useRef(false)
  const kick = useCallback(() => {
    if (rafRef.current === null) {
      lastTs.current = performance.now()
      rafRef.current = requestAnimationFrame(tick)
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const loupeEase = useCallback((): boolean => {
    const ls = loupeRefState.current
    if (!ls.target) return false
    if (ls.grab) {
      ls.target = null
      return false
    }
    const dx = ls.target.x - ls.x
    const dy = ls.target.y - ls.y
    if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5) {
      ls.x = ls.target.x
      ls.y = ls.target.y
      ls.target = null
      placeLoupe()
      return false
    }
    ls.x += dx * 0.17
    ls.y += dy * 0.17
    placeLoupe()
    return true
  }, [placeLoupe])
  const tick = useCallback((now: number) => {
    rafRef.current = null
    const dt = Math.min(0.032, (now - lastTs.current) / 1000 || 0.016)
    lastTs.current = now

    const s = springRef.current
    if (s && turnRef.current) {
      if (s.kind === 'tween') {
        s.e += dt
        const k = Math.min(1, s.e / s.dur)
        turnRef.current.t = s.from + (s.target - s.from) * k
        applyTurn(turnRef.current.t)
        if (k >= 1) {
          springRef.current = null
          const d = s.done
          d && d()
        }
      } else {
        const x = turnRef.current.t - s.target
        s.v += (-s.k * x - s.c * s.v) * dt
        turnRef.current.t += s.v * dt
        if (Math.abs(turnRef.current.t - s.target) < 0.002 && Math.abs(s.v) < 0.02) {
          turnRef.current.t = s.target
          springRef.current = null
          applyTurn(turnRef.current.t)
          const d = s.done
          d && d()
        } else {
          applyTurn(turnRef.current.t)
        }
      }
    }

    viewSpring()
    const lmoved = loupeEase()
    if ((springRef.current || viewActive.current || lmoved) && rafRef.current === null) {
      rafRef.current = requestAnimationFrame(tick)
    }
  }, [applyTurn, loupeEase, viewSpring])


  /* ---------- 布局 ---------- */
  const layout = useCallback(() => {
    const book = bookRef.current
    if (!book) return
    book.style.setProperty('--bw', book.clientWidth + 'px')
    loupeRefState.current.x = null
    restLoupe()
  }, [restLoupe])

  useEffect(() => {
    layout()
    const onResize = () => layout()
    window.addEventListener('resize', onResize)
    return () => window.removeEventListener('resize', onResize)
  }, [layout])

  /* ---------- 切换画册时清空图片缓存 ---------- */
  useEffect(() => {
    imgCacheRef.current.clear()
  }, [book])

  useEffect(() => {
    paint()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [paint])

  /* ---------- 预取相邻图版：翻页那一刻图片已就绪 ---------- */
  useEffect(() => {
    const total = spreads.length
    if (total === 0) return
    for (const offset of [-1, 0, 1]) {
      const sp = spreads[(idxRef.current + offset + total) % total]
      if (!sp) continue
      warmImage(sp.image)
      if (sp.blur && sp.blur !== sp.image) warmImage(sp.blur)
    }
  }, [idx, spreads, warmImage])

  /* ---------- 指针交互（翻页 + 倾斜 + 放大镜拖拽） ---------- */
  const onPointerDown = useCallback((e: React.PointerEvent) => {
    if (e.button !== 0) return
    if (dragRef.current) return // 手势进行中（触屏多指），忽略后续手指
    const target = e.target as HTMLElement
    if (target.closest('.sk-loupe, .sk-tools, button, .sk-index, a')) return
    e.preventDefault()
    const stage = e.currentTarget as HTMLElement
    stage.setPointerCapture(e.pointerId)
    setShowHint(false)
    const book = bookRef.current
    if (book && !loupeRefState.current.grab) {
      const r = book.getBoundingClientRect()
      const dir: Dir = (e.clientX - r.left) / r.width > 0.5 ? 'next' : 'prev'
      startTurn(dir, 0)
      dragRef.current = {
        dir,
        x0: e.clientX,
        y0: e.clientY,
        w: r.width,
        moved: 0,
        driftY: 0,
        vel: 0,
        tPrev: performance.now(),
        pointerId: e.pointerId,
        pointerType: e.pointerType,
      }
    }
  }, [startTurn])

  const onPointerMove = useCallback((e: React.PointerEvent) => {
    const d = dragRef.current
    if (e.pointerType === 'touch') {
      // 触屏：只跟随发起翻页的那根手指，横向拖拽驱动翻页（纵向留给页面滚动）
      if (!d || d.pointerId !== e.pointerId) return
      const dx = e.clientX - d.x0
      d.driftY = Math.max(d.driftY, Math.abs(e.clientY - d.y0))
      d.moved = Math.max(d.moved, Math.abs(dx))
      if (!turnRef.current) return
      const raw = (d.dir === 'next' ? -dx : dx) / (d.w * 0.62)
      const t = clamp(raw, 0, 1)
      const now = performance.now()
      const dt = Math.max(0.001, (now - d.tPrev) / 1000)
      // 平滑瞬时速度：低通滤波，避免末端抖动造成误翻
      const inst = (t - (turnRef.current.t ?? 0)) / dt
      d.vel = d.vel * 0.55 + inst * 0.45
      turnRef.current.t = t
      applyTurn(t)
      d.tPrev = now
      return
    }
    tiltTo(e.clientX, e.clientY)
    if (!d) return
    const dx = e.clientX - d.x0
    d.moved = Math.max(d.moved, Math.abs(dx))
    const raw = (d.dir === 'next' ? -dx : dx) / (d.w * 0.62)
    const t = clamp(raw, 0, 1)
    const now = performance.now()
    const dt = Math.max(0.001, (now - d.tPrev) / 1000)
    if (turnRef.current) {
      // 平滑瞬时速度：低通滤波，避免末端抖动造成误翻
      const inst = (t - (turnRef.current.t ?? 0)) / dt
      d.vel = d.vel * 0.55 + inst * 0.45
      turnRef.current.t = t
      applyTurn(t)
    }
    d.tPrev = now
  }, [applyTurn, tiltTo])

  const onPointerUp = useCallback((e: React.PointerEvent) => {
    const d = dragRef.current
    if (d && d.pointerId !== undefined && e.pointerId !== undefined && d.pointerId !== e.pointerId) return
    dragRef.current = null
    if (!d || !turnRef.current) return
    // 触屏纵向滚动意图（上下位移大于横向）→ 回弹，不翻页
    if (d.pointerType === 'touch' && d.driftY > 8 && d.driftY > d.moved) {
      cancel()
      return
    }
    if (d.moved < 6) {
      commit()
      return
    }
    // 翻页判定：速度达标，或慢速拖拽已过半。避免临界抖动。
    const t = turnRef.current.t
    const go = t > 0.5 || d.vel > 0.95 || (t > 0.34 && d.vel > 0.55)
    if (go) commit()
    else cancel()
  }, [commit, cancel])

  // 触屏滚动被浏览器接管时会派发 pointercancel → 回弹当前翻页，不当作点击翻页
  const onPointerCancel = useCallback((e: React.PointerEvent) => {
    const d = dragRef.current
    if (d && d.pointerId !== undefined && e.pointerId !== undefined && d.pointerId !== e.pointerId) return
    dragRef.current = null
    if (turnRef.current) cancel()
  }, [cancel])

  /* ---------- 键盘 ---------- */
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.metaKey || e.ctrlKey || e.altKey) return
      const t = e.target as HTMLElement
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return
      if (e.key === 'ArrowRight') { e.preventDefault(); step('next') }
      else if (e.key === 'ArrowLeft') { e.preventDefault(); step('prev') }
      else if (e.key === 'Escape') {
        // 分层退出：大图查看器 > 图版目录 > 整本素描本
        if (viewer) setViewer(null)
        else if (indexOpen) setIndexOpen(false)
        else onBack()
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [onBack, step, viewer, indexOpen])

  /* ---------- 放大镜拖拽 ---------- */
  const onLoupeDown = useCallback((e: React.PointerEvent) => {
    if (!loupeOn || e.button !== 0) return
    e.preventDefault()
    e.stopPropagation()
    const ls = loupeRefState.current
    ls.grab = { cx: e.clientX, cy: e.clientY, x0: ls.x, y0: ls.y }
    ls.target = null
    loupeRef.current?.classList.add('held')
    loupeRef.current?.setPointerCapture(e.pointerId)
    setShowHint(false)
  }, [loupeOn])

  const onLoupeMove = useCallback((e: React.PointerEvent) => {
    const ls = loupeRefState.current
    if (!ls.grab) return
    const B = bookBox()
    const R = loupeSize() / 2
    ls.x = clamp(ls.grab.x0 + (e.clientX - ls.grab.cx), -R * 0.7, B.w + R * 0.7)
    ls.y = clamp(ls.grab.y0 + (e.clientY - ls.grab.cy), -R * 0.7, B.h + R * 1.0)
    placeLoupe()
  }, [bookBox, loupeSize, placeLoupe])

  const onLoupeUp = useCallback(() => {
    loupeRefState.current.grab = null
    loupeRef.current?.classList.remove('held')
  }, [])

  /* ---------- 工具条动作 ---------- */
  const onZoomIn = useCallback(() => setView(viewRef.current.trx, viewRef.current.try_, viewRef.current.tz * 1.16), [setView])
  const onZoomOut = useCallback(() => setView(viewRef.current.trx, viewRef.current.try_, viewRef.current.tz / 1.16), [setView])
  const onResetZoom = useCallback(() => setView(viewRef.current.trx, viewRef.current.try_, 1), [setView])

  const current = spreads[idx]

  return (
    <div ref={rootRef} className="sk-scope">
      {/* 植物水彩背景装饰 */}
      <Botany side="l" />
      <Botany side="r" />

      {/* 顶栏 */}
      <header className="sk-header">
        <button type="button" onClick={onBack} className="sk-back">
          <ArrowLeft className="h-3.5 w-3.5" />
          我的旅行画册
        </button>
        <div className="sk-title">{book.title}</div>
        <button type="button" onClick={onBack} aria-label="关闭" className="sk-close">
          <X className="h-4 w-4" />
        </button>
      </header>

      <div className="sk-body">
        {/* 舞台 */}
        <div
          className="sk-stage"
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={onPointerUp}
          onPointerCancel={onPointerCancel}
          onDoubleClick={onResetZoom}
        >
          <button type="button" className="sk-arrow left" onClick={() => step('prev')} aria-label="上一图版">
            <ChevronLeft />
          </button>

          <div className="sk-3d" ref={threeDRef}>
            <div className="sk-tilt" ref={tiltRef}>
              <div className="sk-cast ambient" />
              <div className="sk-cast contact" />
              <div className="sk-cast hair" />
              <div className="sk-book" ref={bookRef} />
            </div>
                      {/* 点击书页侧边末端翻页 */}
          <button type="button" className="sk-zone prev" onClick={() => step('prev')} aria-label="上一图版" />
          <button type="button" className="sk-zone next" onClick={() => step('next')} aria-label="下一图版" />
{/* 放大镜（在不倾斜的坐标系里） */}
            <div ref={zoomWrapRef} className="sk-zoomwrap">
              <div ref={zoomInnerRef} className="sk-zoominner" />
            </div>
            <div
              ref={loupeRef}
              className={'sk-loupe' + (loupeOn ? ' on' : '')}
              onPointerDown={onLoupeDown}
              onPointerMove={onLoupeMove}
              onPointerUp={onLoupeUp}
              onPointerCancel={onLoupeUp}
            >
              <div className="sk-ring">
                <div className="sk-lens" />
              </div>
              <div className="sk-grip" />
            </div>
          </div>

          <button type="button" className="sk-arrow right" onClick={() => step('next')} aria-label="下一图版">
            <ChevronRight />
          </button>
        </div>

        {/* 图注 */}
        <div className="sk-captionbar">
          <div className="sk-captionbox" key={idx}>
            <p className="sk-caption">
              {current?.title}
              {current?.place ? <span className="sk-meta"> · {current.place}</span> : null}
              {current?.photoNo ? <span className="sk-meta"> · 第{current.photoNo}/{current.count}张</span> : null}
              {current?.date ? <span className="sk-meta"> · {current.date}</span> : null}
            </p>
          </div>
          <p className={'sk-hint' + (showHint ? '' : ' gone')}>拖动页面翻页 · 拖动放大镜查看细节</p>
        </div>
      </div>

      {/* 底部工具条 */}
      <div className="sk-toolbar">
        <div className="sk-tools">
          <button type="button" onClick={onZoomOut} ref={zOutRef} className="sk-tool" aria-label="缩小">
            <Minus />
          </button>
          <span className="sk-zoom-read" ref={zoomReadRef}>100%</span>
          <button type="button" onClick={onZoomIn} ref={zInRef} className="sk-tool" aria-label="放大">
            <Plus />
          </button>
          <span className="sk-tool-sep" />
          <button
            type="button"
            onClick={() => setLoupeOn((v) => { const nv = !v; if (nv) restLoupe(); return nv })}
            className="sk-tool"
            data-loupe
            aria-pressed={loupeOn}
            aria-label="放大镜"
          >
            <Search />
          </button>
          <button
            type="button"
            onClick={() => setSketch((v) => !v)}
            className="sk-tool"
            aria-pressed={sketch}
            aria-label="素描滤镜"
            title="素描滤镜（前端近似，不调用通义）"
          >
            <Paintbrush />
          </button>
          <span className="sk-tool-sep" />
          <button type="button" onClick={() => setIndexOpen((v) => !v)} className="sk-tool" aria-pressed={indexOpen} aria-label="图版目录">
            <List />
          </button>
          {current?.full && (
            <button
              type="button"
              onClick={() => setViewer(current)}
              className="sk-tool"
              aria-label="查看大图"
              title="查看大图（原图）"
            >
              <Maximize2 />
            </button>
          )}
          {onToggleBook && (
            <>
              <span className="sk-tool-sep" />
              <button type="button" onClick={onToggleBook} className="sk-tool" aria-label="切换为经典书页" title="切换为经典书页">
                <BookOpen className="h-4 w-4" />
              </button>
            </>
          )}
        </div>
      </div>

      {/* 图版索引 */}
      <div className={'sk-index' + (indexOpen ? ' open' : '')}>
        <h3>图版目录</h3>
        <p className="sk-index-sub">{book.title} · {spreads.length} 个图版</p>
        <ol className="plate-list">
          {spreads.map((sp) => (
            <li key={sp.index}>
              <button
                type="button"
                className="sk-plate"
                aria-current={sp.index === idx ? 'true' : 'false'}
                onClick={() => { goTo(sp.index); setIndexOpen(false) }}
              >
                <span className="n">{String(sp.index + 1).padStart(2, '0')}</span>
                <span className="t">{sp.kind === 'summary' ? '旅行总结' : (sp.photoNo ? sp.title + ' · 第' + sp.photoNo + '张' : sp.title)}</span>
                <span className="p">{sp.kind === 'summary' ? 'End' : (sp.place || sp.date)}</span>
              </button>
            </li>
          ))}
        </ol>
      </div>

      {/* 查看大图（原图）：全屏 overlay，点击遮罩或关闭按钮退出 */}
      {viewer && (
        <div className="sk-viewer" onClick={() => setViewer(null)} ref={panelRef} tabIndex={-1} role="dialog" aria-modal="true" aria-label="查看大图">
          <button type="button" className="sk-viewer-close" aria-label="关闭大图" onClick={() => setViewer(null)}>
            <X />
          </button>
          <div className="sk-viewer-inner" onClick={(e) => e.stopPropagation()}>
            <img
              src={viewer.full || viewer.image}
              alt={viewer.title}
              className="sk-viewer-img"
              // eslint-disable-next-line @next/next/no-img-element
            />
            <p className="sk-viewer-cap">
              {viewer.title}
              {viewer.place ? ` · ${viewer.place}` : ''}
              {viewer.photoNo ? ` · 第${viewer.photoNo}/${viewer.count}张` : ''}
            </p>
          </div>
        </div>
      )}
    </div>
  )
}

function Botany({ side }: { side: 'l' | 'r' }) {
  return (
    <svg className={'sk-botany ' + side} viewBox="0 0 200 240" fill="none" aria-hidden="true">
      {side === 'l' ? (
        <g stroke="#7c8a5a" strokeWidth="2" strokeLinecap="round">
          <path d="M0 240 C40 190 60 150 62 108 C64 66 48 30 30 10" />
          <path d="M30 10 C20 60 24 120 60 170" />
          <path d="M40 60 C70 50 96 56 104 84 C78 92 50 88 40 60Z" fill="#a8b57e" fillOpacity="0.35" stroke="none" />
          <path d="M52 120 C84 108 112 116 118 144 C90 152 60 146 52 120Z" fill="#b6c08c" fillOpacity="0.3" stroke="none" />
          <path d="M56 176 C90 166 116 174 122 200 C92 208 64 200 56 176Z" fill="#c3c79b" fillOpacity="0.28" stroke="none" />
        </g>
      ) : (
        <g stroke="#7c8a5a" strokeWidth="2" strokeLinecap="round">
          <path d="M200 240 C160 190 140 150 138 108 C136 66 152 30 170 10" />
          <path d="M170 10 C180 60 176 120 140 170" />
          <path d="M160 60 C130 50 104 56 96 84 C122 92 150 88 160 60Z" fill="#a8b57e" fillOpacity="0.35" stroke="none" />
          <path d="M148 120 C116 108 88 116 82 144 C110 152 140 146 148 120Z" fill="#b6c08c" fillOpacity="0.3" stroke="none" />
          <path d="M144 176 C110 166 84 174 78 200 C108 208 136 200 144 176Z" fill="#c3c79b" fillOpacity="0.28" stroke="none" />
        </g>
      )}
    </svg>
  )
}

'use client'

import { useEffect, useRef, useState, useCallback } from 'react'
import Image from 'next/image'
import Link from 'next/link'
import { Loader2, MessageCircle, Sparkles, RotateCcw, ArrowLeft, BookOpen } from 'lucide-react'
import { GalaxyAlbumEngine } from './galaxyEngine'
import type { CityData } from './particlePhoto'
import SpaceAlbumHUD from './SpaceAlbumHUD'
import { Icon } from '@/components/mobile/Icon'
import { albumModeOf } from '@/lib/album-modes'

/** 模式文案/图标统一取自 lib/album-modes */
const PIXEL_MODE = albumModeOf('pixel')
import SpaceRadar from './SpaceRadar'
import GlassPanel from './GlassPanel'

export interface SpaceChatPhoto {
  url: string
  key: string
  cityName: string
  date: string
}

interface GalaxyAlbumSceneProps {
  cities: CityData[]
  onTogglePixel: () => void
  onOpenChat: (photo: SpaceChatPhoto) => void
  onWebGLFail: () => void
}

function formatDate(dateStr: string) {
  try {
    const d = new Date(dateStr)
    return `${d.getFullYear()}.${String(d.getMonth() + 1).padStart(2, '0')}.${String(d.getDate()).padStart(2, '0')}`
  } catch {
    return dateStr
  }
}

/**
 * 银河全景唱片相册（Three.js）：
 * - 挂载引擎画布，管理 HUD / 雷达 / 玻璃信息面板 / 加载态
 */
export default function GalaxyAlbumScene({
  cities,
  onTogglePixel,
  onOpenChat,
  onWebGLFail,
}: GalaxyAlbumSceneProps) {
  const mountRef = useRef<HTMLDivElement>(null)
  const engineRef = useRef<GalaxyAlbumEngine | null>(null)
  const [ready, setReady] = useState(false)
  const [progress, setProgress] = useState(0)
  const [index, setIndex] = useState(0)
  const [hovered, setHovered] = useState<number | null>(null)
  const [closeup, setCloseup] = useState(false)
  const [failed, setFailed] = useState(false)

  useEffect(() => {
    const mount = mountRef.current
    if (!mount || cities.length === 0) return
    const engine = new GalaxyAlbumEngine(mount, {
      onSelect: (i) => setIndex(i),
      onCloseup: (c) => setCloseup(c),
      onHover: (i) => setHovered(i),
      onProgress: (done, total) => setProgress(total ? Math.round((done / total) * 100) : 100),
      onReady: () => setReady(true),
    })
    engineRef.current = engine
    engine.load(cities).catch((err) => {
      console.error('[GalaxyAlbum] load failed', err)
      setFailed(true)
    })
    return () => {
      engine.dispose()
      engineRef.current = null
      setReady(false)
      setProgress(0)
      setCloseup(false)
    }
  }, [cities])

  useEffect(() => {
    if (failed) onWebGLFail()
  }, [failed, onWebGLFail])

  const city = cities[index]

  const handleOpenChat = useCallback(
    (photoUrl: string) => {
      if (!city) return
      onOpenChat({
        url: photoUrl,
        key: photoUrl,
        cityName: city.name,
        date: formatDate(city.date),
      })
    },
    [city, onOpenChat]
  )

  if (cities.length === 0) {
    return (
      <div className="fixed inset-0 z-[90] bg-album-bg0 flex flex-col items-center justify-center gap-4">
        {/* 空态也保留顶栏（返回首页 + 标题 + 模式切换），与像素/画册模式同构，避免被困在空银河 */}
        <header className="absolute top-0 inset-x-0 z-40 flex h-14 items-center justify-between gap-2 px-3 md:px-8 space-glass rounded-none border-x-0 border-t-0">
          <div className="flex items-center gap-3 min-w-0">
            <Link
              href="/"
              className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full space-glass-btn text-album-text1 text-xs"
            >
              <Icon icon={ArrowLeft} size="sm" />
              返回
            </Link>
            <div className="flex items-center gap-2 min-w-0">
              <Icon icon={BookOpen} size="sm" className="shrink-0 text-album-accent" />
              <h1 className="text-album-text1 text-sm font-semibold tracking-widest truncate">银河相册</h1>
            </div>
          </div>
          <button
            type="button"
            onClick={onTogglePixel}
            className="inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-full space-glass-btn text-album-text1 text-xs font-bold"
            title={PIXEL_MODE.title}
          >
            <Icon icon={PIXEL_MODE.icon} size="sm" />
            {PIXEL_MODE.label}
          </button>
        </header>
        <Icon icon={Sparkles} size="lg" className="text-album-accent" />
        <p className="text-album-text2 text-sm tracking-widest">银河中还没有旅行唱片</p>
        <p className="text-album-text2 text-xs">等待新的旅行记忆被点亮...</p>
      </div>
    )
  }

  return (
    <div className="fixed inset-0 z-[90] bg-album-bg0 overflow-hidden">
      {/* Three.js 画布 */}
      <div ref={mountRef} className="absolute inset-0" />

      {/* 加载态 */}
      {!ready && !failed && (
        <div className="absolute inset-0 z-20 flex flex-col items-center justify-center gap-4 bg-album-bg0">
          <div className="relative w-16 h-16">
            <div className="absolute inset-0 rounded-full border border-white/15" />
            <div className="absolute inset-0 rounded-full border-t-2 border-album-accent animate-spin" />
            <Icon icon={Sparkles} size="md" className="absolute inset-0 m-auto text-album-accent" />
          </div>
          <p className="text-album-text2 text-sm tracking-widest">正在唤醒银河，装载旅行唱片...</p>
          <div className="w-48 h-1 rounded-full bg-white/10 overflow-hidden">
            <div
              className="h-full bg-gradient-to-r from-album-accentStrong to-album-accent transition-all duration-300"
              style={{ width: `${Math.max(6, progress)}%` }}
            />
          </div>
          <p className="text-album-text2 text-xs">{progress}%</p>
        </div>
      )}

      {ready && (
        <>
          <SpaceAlbumHUD
            cities={cities}
            index={index}
            hovered={hovered}
            closeup={closeup}
            onTogglePixel={onTogglePixel}
            onPrev={() => engineRef.current?.stepCity(-1)}
            onNext={() => engineRef.current?.stepCity(1)}
            onZoomIn={() => engineRef.current?.zoomBy(0.85)}
            onZoomOut={() => engineRef.current?.zoomBy(1.18)}
            onExitCloseup={() => engineRef.current?.exitCloseup()}
          />

          <SpaceRadar
            cities={cities}
            currentIndex={index}
            onSelect={(i) => engineRef.current?.selectCity(i, { close: true })}
          />

          {/* 选中唱片：玻璃信息面板 */}
          {closeup && city && (
            <div className="absolute z-30 left-1/2 -translate-x-1/2 top-16 sm:top-20 w-[min(92vw,560px)]">
              <GlassPanel className="p-4 sm:p-5 rounded-3xl">
                <div className="flex items-start justify-between gap-3">
                  <div className="min-w-0">
                    <h2 className="text-album-text1 text-lg font-bold tracking-widest truncate">{city.name} · 记忆唱片</h2>
                    <p className="text-album-text2 text-xs mt-1">
                      {formatDate(city.date)} · {city.images.length} 张照片
                      {city.province ? ` · ${city.province}` : ''}
                    </p>
                  </div>
                  <button
                    type="button"
                    onClick={() => engineRef.current?.exitCloseup()}
                    className="space-glass-btn rounded-full px-3 py-1.5 flex items-center gap-1.5 text-album-text1 text-xs shrink-0"
                  >
                    <Icon icon={RotateCcw} size="sm" />
                    返回银河
                  </button>
                </div>

                <div className="mt-3 grid grid-cols-5 sm:grid-cols-6 gap-2">
                  {city.images.slice(0, 12).map((img, i) => (
                    <button
                      key={`${img}-${i}`}
                      type="button"
                      onClick={() => handleOpenChat(img)}
                      className="relative aspect-square rounded-xl overflow-hidden border border-white/10 group"
                      title={`点击查看照片并留言`}
                    >
                      {/* eslint-disable-next-line @next/next/no-img-element */}
                      <Image
                        src={img}
                        alt={`${city.name} ${i + 1}`}
                        fill
                        sizes="(max-width: 768px) 50vw, 25vw"
                        className="object-cover group-hover:scale-110 transition-transform duration-300"
                      />
                      <span className="absolute inset-0 bg-black/0 group-hover:bg-black/45 transition-colors flex items-center justify-center">
                        <Icon icon={MessageCircle} size="sm" className="text-album-accent opacity-0 transition-opacity group-hover:opacity-100" />
                      </span>
                    </button>
                  ))}
                </div>
                <p className="mt-2.5 text-xs text-album-text2 text-center">
                  点击照片开启该照片专属的星河留言
                </p>
              </GlassPanel>
            </div>
          )}
        </>
      )}
    </div>
  )
}

'use client'

import { useCallback, useEffect, useRef, useState } from 'react'
import { X, FileDown, Image as ImageIcon, type LucideIcon } from 'lucide-react'
import { Icon } from '@/components/mobile/Icon'
import { apiUrl } from '@/lib/api-base'
import { toast } from '@/lib/mobile/toast-store'
import { hapticLight } from '@/lib/mobile/haptics'
import { cn } from '@/lib/utils'
import { useModalLayer } from '@/hooks/use-modal-layer'

/**
 * 导出记忆档案（2026-10-15 重做）
 * ============================================================================
 * 需求：居中弹窗，让用户选①导出哪一次旅行 ②导出成什么形式 ③保存到哪。
 *
 * 两种形式：
 *  · **旅行卡片（HTML）**：自包含单文件，打开就是一张漂亮的长卡片，适合分享/留档；
 *  · **完整档案（ZIP）**：结构化 JSON + Markdown + 原图，适合备份与再导入。
 *
 * 保存位置：优先用 File System Access API（showSaveFilePicker）让用户**明确选路径**；
 * 系统不支持时退化为常规下载 —— 此时由系统/浏览器弹出保存询问，
 * 所以文案要说明"接下来会让你选择保存位置"，避免用户以为没反应。
 */

interface TravelOption { slug: string; title: string; date?: string; cover?: string }

/** File System Access API 的最小类型（TS 的 lib.dom 尚未包含 showSaveFilePicker） */
interface SaveFilePickerWindow extends Window {
  showSaveFilePicker?: (opts: {
    suggestedName?: string
    types?: { description?: string; accept: Record<string, string[]> }[]
  }) => Promise<{ createWritable: () => Promise<{ write: (d: Blob) => Promise<void>; close: () => Promise<void> }> }>
}

export default function ExportArchiveDialog({ onClose }: { onClose: () => void }) {
  const [travels, setTravels] = useState<TravelOption[]>([])
  const [loading, setLoading] = useState(true)
  const [slug, setSlug] = useState<string>("")
  const [format, setFormat] = useState<"card" | "zip">("card")
  const [busy, setBusy] = useState(false)
  const panelRef = useRef<HTMLDivElement | null>(null)

  // P2-28：保持原有视觉，只补焦点圈定/恢复、背景 inert、滚动锁与 ESC/返回键关闭。
  // busy（导出中）时不允许关闭（dismissible=false），与原有「导出中禁用取消」一致。
  useModalLayer({ open: true, onClose, dismissible: !busy, panelRef })

  useEffect(() => {
    let alive = true
    ;(async () => {
      try {
        const res = await fetch(apiUrl('/api/travels'), { credentials: 'include' })
        const json = await res.json().catch(() => null)
        const list: TravelOption[] = Array.isArray(json?.posts)
          ? json.posts.map((p: any) => ({ slug: p.slug, title: p.title, date: p.date, cover: p.cover })).filter((p: TravelOption) => p.slug)
          : []
        if (!alive) return
        setTravels(list)
        setSlug(list[0]?.slug ?? "")
      } catch {
        if (alive) toast.error('读取旅行列表失败')
      } finally {
        if (alive) setLoading(false)
      }
    })()
    return () => { alive = false }
  }, [])

  /** 用系统保存对话框写文件；不支持则返回 false 由调用方退化为下载 */
  const saveWithPicker = useCallback(async (blob: Blob, suggestedName: string, mime: string, ext: string) => {
    const w = window as SaveFilePickerWindow
    if (typeof w.showSaveFilePicker !== "function") return false
    try {
      const handle = await w.showSaveFilePicker({
        suggestedName,
        types: [{ description: "导出文件", accept: { [mime]: [ext] } }],
      })
      const writable = await handle.createWritable()
      await writable.write(blob)
      await writable.close()
      return true
    } catch (e) {
      // 用户取消不算失败
      const err = e as Error
      if (err?.name === "AbortError") return true
      return false
    }
  }, [])

  /** 退化为普通下载（由浏览器/系统弹出保存询问） */
  const download = useCallback((blob: Blob, filename: string) => {
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = filename
    document.body.appendChild(a)
    a.click()
    a.remove()
    window.setTimeout(() => URL.revokeObjectURL(url), 4000)
  }, [])

  const runExport = useCallback(async () => {
    if (busy) return
    if (format === "card" && !slug) { toast.error("请先选择要导出的旅行"); return }
    void hapticLight()
    setBusy(true)
    try {
      if (format === "card") {
        const res = await fetch(apiUrl("/api/export/card?slug=" + encodeURIComponent(slug)), { credentials: "include" })
        if (!res.ok) {
          const j = await res.json().catch(() => null)
          throw new Error(j?.error || "生成失败")
        }
        const html = await res.text()
        const title = travels.find((t) => t.slug === slug)?.title || "travel"
        const filename = title.slice(0, 40).replace(/[\\/:*?"<>|]/g, "_") + "-旅行卡片.html"
        const blob = new Blob([html], { type: "text/html;charset=utf-8" })
        const saved = await saveWithPicker(blob, filename, "text/html", ".html")
        if (!saved) { download(blob, filename); toast.success('已开始下载，请选择保存位置') }
        else toast.success('已保存旅行卡片')
        onClose()
        return
      }
      // ZIP 完整档案
      const res = await fetch(apiUrl("/api/export/archive"), { credentials: "include" })
      if (!res.ok) throw new Error("导出失败")
      const blob = await res.blob()
      const filename = "tiantu-archive.zip"
      const saved = await saveWithPicker(blob, filename, "application/zip", ".zip")
      if (!saved) { download(blob, filename); toast.success('已开始下载，请选择保存位置') }
      else toast.success('已保存完整档案')
      onClose()
    } catch (e) {
      toast.error(e instanceof Error ? e.message : '导出失败，请稍后重试')
    } finally {
      setBusy(false)
    }
  }, [busy, download, format, onClose, saveWithPicker, slug, travels])

  return (
    <div className="fixed inset-0 z-[135] flex items-center justify-center px-5" role="dialog" aria-modal="true" aria-label="导出记忆档案">
      <div className="absolute inset-0 bg-black/45" onClick={busy ? undefined : onClose} />
      <div
        ref={panelRef}
        tabIndex={-1}
        className="relative flex max-h-[82dvh] w-full max-w-sm flex-col overflow-hidden rounded-3xl bg-[var(--m-surface-solid)] shadow-[var(--m-shadow-lg)]"
      >
        <div className="flex items-center justify-between px-5 pb-3 pt-5">
          <h3 className="m-title-2 font-semibold text-[var(--m-text)]">导出记忆档案</h3>
          <button type="button" onClick={onClose} disabled={busy} aria-label="关闭" className="m-pressable rounded-full p-2 text-[var(--m-muted)] disabled:opacity-40">
            <Icon icon={X} size="sm" />
          </button>
        </div>

        <div className="min-h-0 flex-1 overflow-y-auto px-5">
          {/* 形式 */}
          <p className="m-field-label">导出形式</p>
          <div className="mt-2 space-y-2">
            <FormatOption
              active={format === "card"}
              icon={ImageIcon}
              title="旅行卡片（HTML）"
              hint="单文件长卡片，打开即看，适合分享与留档"
              onClick={() => setFormat("card")}
            />
            <FormatOption
              active={format === "zip"}
              icon={FileDown}
              title="完整档案（ZIP）"
              hint="结构化数据 + 文字叙事 + 原图，适合备份"
              onClick={() => setFormat("zip")}
            />
          </div>

          {/* 旅行选择（仅卡片需要） */}
          {format === "card" && (
            <div className="mt-4">
              <p className="m-field-label">选择旅行</p>
              {loading ? (
                <p className="py-4 text-center text-[13px] text-[var(--m-muted)]">正在读取…</p>
              ) : travels.length === 0 ? (
                <p className="py-4 text-center text-[13px] text-[var(--m-muted)]">还没有可导出的旅行</p>
              ) : (
                <ul className="mt-2 space-y-1.5">
                  {travels.map((t) => {
                    const active = t.slug === slug
                    return (
                      <li key={t.slug}>
                        <button
                          type="button"
                          onClick={() => { void hapticLight(); setSlug(t.slug) }}
                          aria-pressed={active}
                          className={cn(
                            "m-pressable flex min-h-[52px] w-full items-center gap-3 rounded-2xl px-3.5 py-2.5 text-left transition-colors",
                            active ? "bg-[var(--m-accent-soft)]" : "bg-[var(--m-surface-2)]",
                          )}
                        >
                          <span className={cn(
                            "flex h-5 w-5 flex-none items-center justify-center rounded-full border-2",
                            active ? "border-[var(--m-accent)]" : "border-[var(--m-line)]",
                          )}>
                            {active && <span className="h-2.5 w-2.5 rounded-full bg-[var(--m-accent)]" />}
                          </span>
                          <span className="min-w-0 flex-1">
                            <span className={cn("m-body block truncate", active ? "font-semibold text-[var(--m-accent-strong)]" : "text-[var(--m-text)]")}>
                              {t.title}
                            </span>
                            {t.date && <span className="m-caption mt-0.5 block truncate text-[var(--m-muted)]">{String(t.date).slice(0, 10)}</span>}
                          </span>
                        </button>
                      </li>
                    )
                  })}
                </ul>
              )}
            </div>
          )}

          <p className="m-caption mt-4 text-[var(--m-muted)]">
            点击导出后会让你选择保存位置；若系统不支持选择，则由浏览器下载并询问保存。
          </p>
        </div>

        <div className="flex gap-3 px-5 pb-[max(16px,env(safe-area-inset-bottom))] pt-4">
          <button type="button" onClick={onClose} disabled={busy} className="m-pressable min-h-[48px] rounded-2xl px-4 text-[15px] font-medium text-[var(--m-muted)] ring-1 ring-[var(--m-line)] disabled:opacity-40">
            取消
          </button>
          <button
            type="button"
            onClick={() => { void runExport() }}
            disabled={busy || (format === "card" && !slug)}
            className="m-press m-btn-primary min-h-[48px] flex-1 rounded-2xl text-[15px] font-semibold disabled:opacity-40"
          >
            {busy ? "正在导出…" : "导出"}
          </button>
        </div>
      </div>
    </div>
  )
}

function FormatOption({
  active, icon, title, hint, onClick,
}: {
  active: boolean
  icon: LucideIcon
  title: string
  hint: string
  onClick: () => void
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-pressed={active}
      className={cn(
        "m-pressable flex w-full items-start gap-3 rounded-2xl border px-3.5 py-3 text-left transition-colors",
        active ? "border-[var(--m-accent)] bg-[var(--m-accent-soft)]" : "border-[var(--m-line)] bg-[var(--m-surface-solid)]",
      )}
    >
      <Icon icon={icon} size="sm" tone={active ? "accent" : "muted"} />
      <span className="min-w-0 flex-1">
        <span className={cn("m-body block font-medium", active ? "text-[var(--m-accent-strong)]" : "text-[var(--m-text)]")}>{title}</span>
        <span className="m-caption mt-0.5 block text-[var(--m-muted)]">{hint}</span>
      </span>
    </button>
  )
}

'use client'

import {
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
  type TouchEvent,
} from 'react'
import { RefreshCw } from 'lucide-react'
import { cn } from '@/lib/utils'
import { hapticMedium } from '@/lib/mobile/haptics'

const THRESHOLD = 56
const MAX_PULL = 96

/**
 * iOS 下拉刷新：window 级滚动容器，下拉阻尼回弹，到阈值松手触发（带 medium 触觉）。
 *
 * iOS 化观感（2.0）：
 * - 纯 spinner、无文字（iOS 惯例）；spinner 跟手旋转（进度 ×180°，过阈值锁定）；
 * - 松手未触发 / 刷新完成 → 内容弹簧收位（不再是瞬移归零）。
 */
export function PullToRefresh({
  onRefresh,
  children,
  className,
  style,
  disabled,
}: {
  onRefresh: () => Promise<unknown> | void
  children: ReactNode
  className?: string
  style?: CSSProperties
  disabled?: boolean
}) {
  const startY = useRef(0)
  const [refreshing, setRefreshing] = useState(false)
  const [dist, setDist] = useState(0)
  /** 松手后的弹簧收位阶段：位移归零但保留回弹过渡 */
  const [settling, setSettling] = useState(false)

  const handleTouchStart = (event: TouchEvent<HTMLDivElement>) => {
    if (disabled || refreshing || window.scrollY > 0) return
    startY.current = event.touches[0].clientY
  }

  const handleTouchMove = (event: TouchEvent<HTMLDivElement>) => {
    if (disabled || refreshing || window.scrollY > 0) return
    const dy = event.touches[0].clientY - startY.current
    if (dy <= 0) {
      setDist(0)
      return
    }
    setDist(Math.min(MAX_PULL, dy * 0.42))
  }

  const settle = () => {
    setDist(0)
    setSettling(true)
    window.setTimeout(() => setSettling(false), 420)
  }

  const handleTouchEnd = () => {
    if (refreshing) return
    if (dist >= THRESHOLD) {
      void hapticMedium()
      setRefreshing(true)
      setDist(THRESHOLD)
      const result = onRefresh()
      Promise.resolve(result).finally(() => {
        setRefreshing(false)
        settle()
      })
    } else {
      settle()
    }
  }

  const ready = dist >= THRESHOLD
  // 跟手旋转：0° → 180°，过阈值锁定（iOS spinner 行为）；刷新中交给 CSS 连续旋转
  const dragRotation = Math.min(180, (dist / THRESHOLD) * 180)

  return (
    <div
      className={cn('m-ptr', className)}
      style={style}
      onTouchStart={handleTouchStart}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleTouchEnd}
    >
      <div
        aria-hidden="true"
        className="m-ptr-indicator"
        style={{
          transform: `translateY(${Math.max(0, dist - 48)}px)`,
          opacity: Math.min(1, dist / THRESHOLD),
        }}
      >
        <RefreshCw
          className={cn('h-5 w-5', refreshing && 'm-ptr-spin')}
          strokeWidth={2}
          style={
            refreshing
              ? undefined
              : {
                  transform: `rotate(${dragRotation}deg)`,
                  transition: settling ? 'transform 0.4s var(--m-ease-spring)' : 'none',
                }
          }
        />
      </div>
      <div
        style={
          /*
           * ⚠️ 静止时必须**不设 transform**（而不是 translateY(0px)）。
           *
           * CSS 里任何非 none 的 transform 都会让该元素成为 position:fixed 后代的
           * **包含块**。此前这里恒写 translateY(0px)，于是子树里所有 fixed 元素
           * （省份抽屉、底部 CTA 等）不再相对视口定位，而是相对这层内容容器 ——
           * 真机表现：在地图页点省份，弹窗跑到**整页内容的最底部**，
           * 必须一直往下拉才能看到（用户反馈的 bug）。
           *
           * 现在三态处理：
           *   · 下拉中   → translateY(dist)，跟随手指（此时不会打开弹窗）
           *   · 回弹中   → translateY(0px) + 弹簧过渡（保留动画）
           *   · 静止     → 不写 transform（恢复视口定位）
           */
          dist > 0
            ? { transform: `translateY(${dist}px)`, transition: 'none' }
            : settling
              ? { transform: 'translateY(0px)', transition: 'transform 0.4s var(--m-ease-spring)' }
              : undefined
        }
      >
        {children}
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { ArrowLeft, Loader2 } from 'lucide-react'
import { Icon } from '@/components/mobile/Icon'
import SocialFilmCard from '@/components/social/SocialFilmCard'
import SocialThemeToggle from '@/components/social/SocialThemeToggle'
import { goBackOrHome } from '@/lib/navigation'
import { circlePostHref } from '@/lib/routes'
import { apiUrl } from '@/lib/api-base'

const FRAMES = ['portrait', 'landscape', 'square', 'wide', 'portrait', 'landscape'] as const

export default function FavoritesGrid() {
  const router = useRouter()
  const [posts, setPosts] = useState<any[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    fetch(apiUrl('/api/social/me/favorites?page=1&pageSize=30')).then((r) => r.json()).then((j) => setPosts(j.data || [])).catch(() => {}).finally(() => setLoading(false))
  }, [])

  const cardProps = (p: any, frame: (typeof FRAMES)[number]) => ({
    coverUrl: p.coverUrl || undefined,
    cityName: p.location || undefined,
    title: p.title,
    summary: p.summary,
    dateRange: p.startDate ? p.startDate.slice(0, 10) : '',
    dayCount: p.dayCount,
    photoCount: p.photoCount,
    author: p.author ? { name: p.author.nickname || p.author.username, avatar: p.author.avatarUrl } : null,
    // 快捷点赞：收藏列表里也能直接点赞（/api/social/me/favorites 已回填 isLiked）
    postId: p.id,
    liked: p.isLiked,
    likeCount: p.likeCount,
    stats: { comments: p.commentCount, bookmarks: p.favoriteCount },
    frame,
    onOpen: () => {
      const href = circlePostHref(p.id)
      if (href) router.push(href)
    },
  })

  return (
    <div className="min-h-dvh bg-[var(--ui-social-bg)] pb-28 text-[var(--ui-social-text)]">
      <div className="pointer-events-none fixed inset-x-0 top-0 h-[360px] bg-[radial-gradient(55%_60%_at_50%_-10%,rgba(232,179,106,0.09),transparent_65%)]" />
      {/* m-safe-top：/me/* 走「不挂 Navbar」分支，顶部安全区必须由页面自己负责，
          否则标题栏会被手机状态栏压住（与旅行圈详情同类问题）。 */}
      <div className="m-safe-top relative mx-auto max-w-5xl px-4 pb-6">
        <header className="mb-8 flex items-center gap-3">
          {/* 返回键放**左侧**（用户习惯位置），并真正回上一级而非固定 /me */}
          <button
            type="button"
            onClick={() => goBackOrHome(router, '/me')}
            aria-label="返回上一级"
            className="m-pressable flex h-11 w-11 shrink-0 items-center justify-center rounded-full text-[var(--ui-social-muted)] ring-1 ring-[var(--ui-social-line)] transition-colors hover:text-[var(--ui-social-text)]"
          >
            <Icon icon={ArrowLeft} size="md" />
          </button>
          <div className="min-w-0 flex-1">
            <p className="text-xs font-medium uppercase tracking-[0.24em] text-[var(--ui-social-accent)]">Memories</p>
            <h1 className="text-xl font-semibold">我的收藏</h1>
          </div>
          <SocialThemeToggle />
        </header>
        {loading ? (
          <div className="py-20 text-center text-[var(--ui-social-muted)]"><Icon icon={Loader2} size="md" className="mx-auto animate-spin" /></div>
        ) : posts.length === 0 ? (
          <p className="py-20 text-center text-sm text-[var(--ui-social-muted)]">还没有收藏任何旅行。</p>
        ) : (
          <div className="columns-1 gap-5 sm:columns-2 lg:columns-3 [column-fill:_balance]">
            {posts.map((p, i) => <SocialFilmCard key={p.id} {...cardProps(p, FRAMES[i % FRAMES.length])} className="mb-5 break-inside-avoid" />)}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState, useCallback } from 'react'
import Link from 'next/link'
import { Bell, CheckCheck } from 'lucide-react'
import { LargeTitle } from '@/components/mobile/LargeTitle'
import { Button } from '@/components/mobile/Button'
import { Loader } from '@/components/mobile/Loader'
import { EmptyState } from '@/components/mobile/EmptyState'
import { hapticLight } from '@/lib/mobile/haptics'
import SocialAvatar from '@/components/social/SocialAvatar'
import SocialThemeToggle from '@/components/social/SocialThemeToggle'
import EdgeSwipeBack from '@/components/mobile/EdgeSwipeBack'
import { circlePostHref, circleUserHref } from '@/lib/routes'
import { apiUrl } from '@/lib/api-base'

/**
 * 我的通知（M5 · D6 修复）
 *
 * 此前这是**唯一不使用设计系统的二级页**：手写 header（返回圆钮 + 大写眉标 +
 * 自定标题）、手写加载态（转圈图标）、手写空态（一行灰字），既没有 iOS 大标题，
 * 也没有与 /me/settings 一致的骨架，观感割裂。
 *
 * 现在对齐 `/me/settings` 的骨架：社交底 + 氛围光 + LargeTitle + 设计系统组件。
 * 颜色仍走 `--social-*`（设计规范 §5.3 跨主题边界：只归一结构与尺寸，不切色板）。
 */
export default function NotificationsList() {
  const [data, setData] = useState<any[]>([])
  const [unread, setUnread] = useState(0)
  const [loading, setLoading] = useState(true)
  const [busy, setBusy] = useState(false)

  const load = useCallback(async () => {
    try {
      const res = await fetch(apiUrl('/api/social/notifications?page=1&pageSize=50'))
      if (res.ok) {
        const j = await res.json()
        setData(j.data?.data || [])
        setUnread(j.data?.unread || 0)
      }
    } catch {
      // 静默失败：保持上一次内容，不打断浏览
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    load()
  }, [load])

  const markAll = async () => {
    setBusy(true)
    try {
      await fetch(apiUrl('/api/social/notifications'), {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      })
    } catch {
      // 失败时 load() 会拉回真实状态
    } finally {
      setBusy(false)
      await load()
    }
  }

  const typeLabel: Record<string, string> = {
    LIKE: '赞了你的旅行',
    COMMENT: '评论了你的旅行',
    REPLY: '回复了你的评论',
    FAVORITE: '收藏了你的旅行',
    FOLLOW: '关注了你',
  }

  const targetHref = (n: any) => {
    // 通知里的关联对象可能已删除（refId 为空）→ 退回旅行圈首页，不跳 /circle/undefined
    if (n.refType === 'User') return circleUserHref(n.refId) ?? '/circle'
    return n.refType === 'TravelPost' ? circlePostHref(n.refId) ?? '/circle' : '/circle'
  }

  return (
    <div className="min-h-dvh bg-[var(--ui-social-bg)] pb-[calc(96px+env(safe-area-inset-bottom))] text-[var(--ui-social-text)]">
      <EdgeSwipeBack />
      <div className="pointer-events-none fixed inset-x-0 top-0 h-[320px] bg-[radial-gradient(55%_60%_at_50%_-10%,rgba(232,179,106,0.09),transparent_65%)]" />

      <div className="m-safe-top-16 relative mx-auto max-w-2xl px-4 pb-8 sm:px-6 sm:py-8">
        <LargeTitle
          title="我的通知"
          subtitle={unread > 0 ? `${unread} 条未读` : '赞、评论、收藏与关注'}
          back="/me"
          trailing={<SocialThemeToggle />}
        />

        {unread > 0 && !loading && (
          <div className="mb-4 flex justify-end">
            <Button
              size="md"
              variant="secondary"
              icon={CheckCheck}
              loading={busy}
              onClick={markAll}
            >
              全部已读
            </Button>
          </div>
        )}

        {loading ? (
          <div className="flex justify-center py-20">
            <Loader variant="ring" size="lg" label="正在加载通知" />
          </div>
        ) : data.length === 0 ? (
          <div className="m-card">
            <EmptyState
              icon={Bell}
              title="暂无通知"
              description="有人赞、评论或收藏你的旅行时，会出现在这里。"
            />
          </div>
        ) : (
          <div className="m-card divide-y divide-[var(--m-line)] overflow-hidden">
            {data.map((n) => {
              const name = n.actor?.nickname || n.actor?.username || '有人'
              return (
                <Link
                  key={n.id}
                  href={targetHref(n)}
                  onClick={() => void hapticLight()}
                  className="m-pressable flex items-start gap-3 px-4 py-3.5 transition-colors active:bg-[var(--m-surface-2)]"
                >
                  <SocialAvatar name={name} avatarUrl={n.actor?.avatarUrl} size={36} />
                  <span className="min-w-0 flex-1">
                    <span className="m-body block leading-relaxed text-[var(--ui-social-muted)]">
                      <span className="font-semibold text-[var(--ui-social-text)]">{name}</span>{' '}
                      {typeLabel[n.type] || '与你互动'}
                    </span>
                    <span className="m-caption mt-0.5 block text-[var(--ui-social-faint)]">
                      {new Date(n.createdAt).toLocaleString('zh-CN')}
                    </span>
                  </span>
                  {!n.read && (
                    <span
                      className="mt-1.5 h-2 w-2 shrink-0 rounded-full bg-[var(--ui-social-accent)]"
                      aria-label="未读"
                    />
                  )}
                </Link>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useEffect, useRef, useState, useCallback } from 'react'
import Link from 'next/link'
import Image from 'next/image'
import { useRouter } from 'next/navigation'
import { ArrowLeft, BookOpen, CalendarDays, ChevronRight, Loader2, Image as ImageIcon, Flag, Ban, Check, X, WifiOff, Pencil, Trash2 } from 'lucide-react'
import { Icon } from '@/components/mobile/Icon'
import { cn } from '@/lib/utils'
import { toast } from '@/lib/mobile/toast-store'
import { hapticLight } from '@/lib/mobile/haptics'
import SocialBar from './SocialBar'
import CommentPanel from './CommentPanel'
import SocialAvatar from '@/components/social/SocialAvatar'
import PhotoViewer from '@/components/album/PhotoViewer'
import StackedGallery from '@/components/mobile/StackedGallery'
import SocialThemeToggle from '@/components/social/SocialThemeToggle'
import { apiUrl } from '@/lib/api-base'
import { readWithFallback } from '@/lib/modules/offline/repository'
import { readLocalSocialPostById } from '@/lib/modules/offline/social-read'
import { circleUserHref, travelDetailHref } from '@/lib/routes'
import { goBackOrHome } from '@/lib/navigation'

interface PostDetailData {
  id: number
  postId: number | null
  travelId: number | null
  title: string
  summary: string | null
  coverUrl: string | null
  location: string | null
  startDate: string | null
  endDate: string | null
  dayCount: number
  photoCount: number
  author: { id: number; username: string; nickname?: string | null; avatarUrl?: string | null } | null
  likeCount: number
  commentCount: number
  favoriteCount: number
  isLiked: boolean
  isFavorited: boolean
  publishedAt: string | null
  slug: string | null
  photos: string[]
  canEdit: boolean
  /** 按天游记（R2）：没有绑定 Travel 的历史帖为空数组 */
  days?: TripDay[]
  /** 是否已屏蔽该作者（服务端状态，支持取消屏蔽且跨会话保持） */
  isBlocked?: boolean
  canSuggest?: boolean
}

interface TripDay {
  date: string | null
  title: string | null
  summary: string | null
  itinerary: { id: number; title: string; type: string; startTime: string | null; locationName: string | null }[]
  memories: { id: number; title: string; content: string | null; mood: string | null; photos: { id: number; url: string }[] }[]
  photos: { id: number; url: string }[]
}

/** 行程类型 → 中文（与 ItineraryEditor 的选项一致） */
const ITINERARY_TYPE_LABEL: Record<string, string> = {
  SPOT: '景点',
  RESTAURANT: '餐厅',
  HOTEL: '住宿',
  TRANSPORT: '交通',
  ACTIVITY: '活动',
  OTHER: '其他',
}

/** `2026-09-02` → `9月2日`（按天章节的日期副标题） */
function formatDayDate(iso: string | null): string {
  if (!iso) return ''
  const d = new Date(iso)
  if (isNaN(d.getTime())) return ''
  return `${d.getMonth() + 1}月${d.getDate()}日`
}

export default function PostDetail({ postId }: { postId: number }) {
  const router = useRouter()
  const [post, setPost] = useState<PostDetailData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [showComments, setShowComments] = useState(false)
  const [viewerIndex, setViewerIndex] = useState<number | null>(null)
  const [showReport, setShowReport] = useState(false)
  const [reportReason, setReportReason] = useState('')
  const [reporting, setReporting] = useState(false)
  const [blocked, setBlocked] = useState(false)
  const [blockBusy, setBlockBusy] = useState(false)
  const [offline, setOffline] = useState(false)
  const [showEdit, setShowEdit] = useState(false)
  const [editTitle, setEditTitle] = useState('')
  const [editSummary, setEditSummary] = useState('')
  const [editSaving, setEditSaving] = useState(false)
  const [editError, setEditError] = useState('')
  const [uploading, setUploading] = useState(false)
  const photoInputRef = useRef<HTMLInputElement | null>(null)

  /** 拉取/重拉详情（失败态的重试按钮也用它，失败时把错误文案带出来） */
  const reload = useCallback(async () => {
    setError('')
    setLoading(true)
    try {
      const result = await readWithFallback<PostDetailData>(
        async () => {
          const res = await fetch(apiUrl('/api/social/posts/' + postId), { credentials: 'include' })
          if (!res.ok) throw new Error('http ' + res.status)
          const json = await res.json()
          if (!json.data) throw new Error(json.error || '帖子不存在')
          return json.data as PostDetailData
        },
        async () => {
          const local = await readLocalSocialPostById(postId)
          return local as PostDetailData | null
        },
      )
      setPost(result.data)
      // 屏蔽状态以服务端为准（本地缓存可能过期）：重进页面仍显示"已屏蔽该作者"
      setBlocked(!!result.data.isBlocked)
      setOffline(result.source === 'local')
    } catch (e) {
      setPost(null)
      setError(e instanceof Error ? e.message : '帖子不存在')
    } finally {
      setLoading(false)
    }
  }, [postId])

  useEffect(() => {
    void reload()
  }, [reload])

  /**
   * 列表上的「评论数」入口会带 `?comments=1` 进来（见 `lib/routes.circlePostCommentsHref`）：
   * 落地即展开评论抽屉，用户不必落地后再找一次评论按钮。
   *
   * 为什么读 `window.location` 而不是 `useSearchParams()`：本地壳是 `output: 'export'`
   * 的静态站，该 hook 在静态导出下要求包一层 Suspense 边界（否则构建期报错）；
   * 这里只需要读一个只读参数，不该为它引入那个约束。
   */
  useEffect(() => {
    if (typeof window === 'undefined') return
    if (new URLSearchParams(window.location.search).get('comments') === '1') setShowComments(true)
  }, [])


  const submitReport = async () => {
    if (!reportReason.trim() || reporting) return
    setReporting(true)
    try {
      await fetch(apiUrl('/api/social/posts/' + postId + '/report'), { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ reason: reportReason }) })
      setShowReport(false); setReportReason('')
    } catch {} finally { setReporting(false) }
  }

  /**
   * 屏蔽 / 取消屏蔽作者（可切换，2026-10-12 修复）。
   *
   * 修复前：只有 POST（屏蔽），点了就本地置 true 且**不可逆**，也不读服务端状态 ——
   * 于是"退出软件再进来"又显示成未屏蔽（真机反馈的两个现象）。
   * 现在：POST=屏蔽、DELETE=取消屏蔽，乐观更新 + 失败回滚 + 轻触觉反馈。
   */
  const toggleBlockAuthor = async () => {
    if (!post?.author || blockBusy) return
    const next = !blocked
    void hapticLight()
    setBlocked(next)
    setBlockBusy(true)
    try {
      const res = await fetch(apiUrl('/api/social/users/' + post.author.id + '/block'), {
        method: next ? 'POST' : 'DELETE',
        credentials: 'include',
      })
      if (!res.ok) {
        setBlocked(!next) // 回滚
        toast.error(next ? '屏蔽失败，请重试' : '取消屏蔽失败，请重试')
      } else {
        toast.success(next ? '已屏蔽该作者，TA 的内容不再出现' : '已取消屏蔽该作者')
      }
    } catch {
      setBlocked(!next)
      toast.error('网络错误，请重试')
    } finally {
      setBlockBusy(false)
    }
  }

  const refreshPost = async () => {
    try {
      const res = await fetch(apiUrl('/api/social/posts/' + postId), { credentials: 'include' })
      if (!res.ok) return
      const json = await res.json()
      if (json.data) {
        setPost(json.data)
        setOffline(false)
      }
    } catch {}
  }

  const openEdit = () => {
    if (!post) return
    setEditTitle(post.title)
    setEditSummary(post.summary || '')
    setEditError('')
    setShowEdit(true)
  }

  const saveEdit = async () => {
    if (!post || editSaving) return
    const title = editTitle.trim()
    if (!title) {
      setEditError('标题不能为空')
      return
    }
    setEditSaving(true)
    setEditError('')
    try {
      const res = await fetch(apiUrl('/api/social/posts/' + post.id), {
        method: 'PATCH',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title, summary: editSummary.trim() }),
      })
      const json = await res.json().catch(() => ({}))
      if (!res.ok || !json.data) {
        setEditError(json.error || '保存失败')
        return
      }
      setPost(json.data)
      setShowEdit(false)
    } catch {
      setEditError('网络错误')
    } finally {
      setEditSaving(false)
    }
  }

  const uploadImages = async (files: FileList | File[]) => {
    if (!post?.postId || uploading) return
    const list = Array.from(files)
    if (list.length === 0) return
    setUploading(true)
    setEditError('')
    try {
      const form = new FormData()
      list.forEach((f) => form.append('files', f))
      form.append('postId', String(post.postId))
      const res = await fetch(apiUrl('/api/upload'), { method: 'POST', credentials: 'include', body: form })
      const json = await res.json().catch(() => ({}))
      if (!res.ok) {
        setEditError(json.error || '图片上传失败')
        return
      }
      await refreshPost()
      if (photoInputRef.current) photoInputRef.current.value = ''
    } catch {
      setEditError('图片上传失败')
    } finally {
      setUploading(false)
    }
  }

  const deleteImage = async (url: string) => {
    if (!post?.postId) return
    const path = (() => {
      try { return new URL(url, window.location.origin).pathname } catch { return url }
    })()
    try {
      const res = await fetch(apiUrl('/api/upload'), {
        method: 'DELETE',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: path }),
      })
      if (!res.ok) {
        const json = await res.json().catch(() => ({}))
        setEditError(json.error || '图片删除失败')
        return
      }
      await refreshPost()
    } catch {
      setEditError('图片删除失败')
    }
  }

  if (loading) {
    return <PostDetailSkeleton />
  }
  if (error || !post) {
    // 失败时**保留 URL**（不 redirect），并把两条出路摆在眼前。
    // 旧实现只留一句文字 + 返回旅行圈，用户以为"点开没内容"（真机反馈的现象之一）。
    return (
      <div className="flex min-h-dvh flex-col items-center justify-center gap-4 bg-[var(--ui-social-bg)] px-6 text-center">
        <Icon icon={WifiOff} size="lg" tone="faint" />
        <p className="text-sm text-[var(--ui-social-text)]">{error || '这条旅行故事暂时打不开'}</p>
        <p className="max-w-xs text-xs text-[var(--ui-social-faint)]">
          可能是网络不稳，或作者已取消公开。链接还在这里，稍后可以再试。
        </p>
        <div className="mt-2 flex flex-wrap justify-center gap-2">
          <button
            type="button"
            onClick={() => {
              setError('')
              setLoading(true)
              void reload()
            }}
            className="rounded-full bg-[var(--ui-social-accent)] px-5 py-2.5 text-sm font-medium text-[var(--ui-social-on-accent)]"
          >
            重试
          </button>
          <Link
            href="/circle"
            className="rounded-full px-5 py-2.5 text-sm text-[var(--ui-social-muted)] ring-1 ring-[var(--ui-social-line)]"
          >
            返回旅行圈
          </Link>
        </div>
      </div>
    )
  }

  const dateText = (post.startDate ? post.startDate.slice(0, 10) : '') + (post.endDate && post.endDate !== post.startDate ? ' ~ ' + post.endDate.slice(0, 10) : '')
  const authorName = post.author ? post.author.nickname || post.author.username : '旅行者'
  const days = post.days ?? []

  /**
   * 相册数组：封面优先入列，并去掉与封面重复的照片（避免第一张出现两次）。
   * 堆叠相册与全屏 PhotoViewer **共用同一个数组**，否则 onOpen(i) 传出的下标
   * 会在两个数组之间错位（点第 2 张却打开第 3 张）。
   */
  const gallery = post.coverUrl
    ? [post.coverUrl, ...(post.photos || []).filter((p) => p !== post.coverUrl)]
    : post.photos || []
  /** 有没有可展示的封面 —— 决定桌面端走「左图右文」还是单栏（见下方版面注释） */
  const hasGallery = gallery.length > 0

  return (
    <div className="min-h-dvh bg-[var(--ui-social-bg)] pb-[calc(112px+env(safe-area-inset-bottom))] text-[var(--ui-social-text)] md:pb-28">
      <div className="circle-story-glow" aria-hidden="true" />
      {/*
        顶部安全区（2026-10-12 修复）：/circle/* 在 LayoutContent 里走的是
        「不挂 Navbar」分支（页面自带 header），因此**顶部安全区必须由本页自己负责**。
        此前只有 py-6，标题栏会与手机状态栏重叠 —— 返回键、编辑、深浅模式切换
        被状态栏压住一部分（真机反馈的 bug）。改用与其它移动页一致的 m-safe-top。
      */}
      {/* 桌面端放宽到 max-w-5xl：正文改成「左图右文」的杂志式对开，窄容器放不下两栏 */}
      <div className="m-safe-top relative mx-auto max-w-3xl px-4 pb-6 md:max-w-5xl">
        {offline && (
          <div className="mb-4 flex items-center justify-center gap-1.5 rounded-full bg-[var(--ui-social-accent-soft)] px-4 py-1.5 text-xs text-[var(--ui-social-accent)]">
            <Icon icon={WifiOff} size="sm" />
            离线模式：显示已缓存的帖子内容
          </div>
        )}
        <header className="mb-7 flex items-center gap-3">
          {/*
            返回「上一级」而不是固定回 /circle：
            从旅行详情或他人主页点进来的用户，期望回到**来路**。
            无应用内历史（分享链接/通知直达）时才落到 /circle（见 lib/navigation.ts）。
          */}
          <button
            type="button"
            onClick={() => { void hapticLight(); goBackOrHome(router, '/circle') }}
            aria-label="返回上一级"
            className="m-pressable flex h-11 w-11 shrink-0 items-center justify-center rounded-full text-[var(--ui-social-muted)] ring-1 ring-[var(--ui-social-line)] transition-colors hover:text-[var(--ui-social-text)]"
          >
            <Icon icon={ArrowLeft} size="md" />
          </button>
          <span className="text-sm text-[var(--ui-social-muted)]">旅行圈</span>
          <div className="ml-auto flex items-center gap-2">
            {post.canEdit && (
              <button
                type="button"
                onClick={openEdit}
                className="inline-flex items-center gap-1.5 rounded-full bg-[var(--ui-social-accent)] px-4 py-2 text-sm font-medium text-[var(--ui-social-on-accent)] transition hover:bg-[var(--ui-social-accent-strong)] active:scale-95"
              >
                <Icon icon={Pencil} size="sm" />编辑
              </button>
            )}
            <SocialThemeToggle />
          </div>
        </header>

        {/*
          顶部图片：堆叠相册（2026-10-12 改造）—— 单张 16:10 封面时，多图要进"旅行照片"
          九宫格才看得到；现在左右滑动**或**上下滑动都能切图，点击当前卡打开全屏查看器，
          单图时退化为普通封面（组件内部处理）。

          版面（2026-10-17 精修）：桌面端「左图右文」—— 照片是这类内容的主角，
          让它独立占据左栏并给一层"纸面"底，右栏集中标题 / 元信息 / 作者 / 摘要 / 动作。
          此前是单列 3xl：桌面上顶部一张 4:5 巨图，下面一长条窄文字，
          页面像被拉长的手机截图，宽屏的横向空间完全浪费。
          移动端仍是单列（图在上、文在下）——窄屏分栏只会两边都憋屈。
        */}
        {/* 只有**真有封面**时才分两栏：没有图的故事若仍按两栏排，正文会被塞进左半栏，
            右半栏空着 —— 那种"半页空白"比单栏更难看，所以这里按有无图切换版面。 */}
        <div className={cn(hasGallery && 'md:grid md:grid-cols-[minmax(0,1.05fr)_minmax(0,1fr)] md:items-start md:gap-10')}>
          {gallery.length > 0 && (
            <div className="circle-story-stack">
              <StackedGallery
                images={gallery}
                alt={post.title}
                onOpen={(i) => setViewerIndex(i)}
              />
            </div>
          )}

          <div className={cn('mt-8', hasGallery && 'md:mt-1')}>
            {post.location && <div className="text-xs font-medium uppercase tracking-[0.24em] text-[var(--ui-social-accent)]">{post.location}</div>}
            <h1 className="mt-3 text-3xl font-semibold leading-tight tracking-tight sm:text-4xl">{post.title}</h1>

            {/* 元信息改胶囊：与旅行圈卡片上的 chip 语言一致，也比裸文字更好扫读 */}
            <div className="mt-5 flex flex-wrap items-center gap-2">
              {dateText && (
                <span className="circle-story-pill"><Icon icon={CalendarDays} size="sm" />{dateText}</span>
              )}
              {/* 张数与天数合成一枚：390px 下三枚胶囊会折成三行，两枚刚好排得下 */}
              <span className="circle-story-pill">
                <Icon icon={ImageIcon} size="sm" />
                {post.photoCount} 张{post.dayCount > 0 ? ` · ${post.dayCount} 天` : ''}
              </span>
            </div>

            {post.author && (
              <Link
                href={circleUserHref(post.author.id) ?? '/circle'}
                className="circle-story-card mt-6 flex items-center gap-3 p-3 transition-colors hover:border-[var(--ui-social-line-strong)]"
              >
                <SocialAvatar name={authorName} avatarUrl={post.author.avatarUrl} size={40} />
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-sm font-medium text-[var(--ui-social-text)]">{authorName}</span>
                  <span className="mt-0.5 block text-xs text-[var(--ui-social-faint)]">公开的旅行故事</span>
                </span>
                <Icon icon={ChevronRight} size="sm" tone="faint" />
              </Link>
            )}

            {post.summary && (
              <p className="mt-6 whitespace-pre-line text-base leading-relaxed text-[var(--ui-social-muted)]">{post.summary}</p>
            )}

            {/*
              动作条装进一张"纸"里：点赞 / 评论 / 收藏 / 分享是本页唯一的一等操作，
              此前四个胶囊裸贴在正文流里，读起来像正文的一部分。放在右栏底部，
              让「图 - 标题 - 元信息 - 作者 - 摘要 - 操作」成为一个完整的阅读单元。
            */}
            <div className="circle-story-card mt-7 p-3">
              <SocialBar
                postId={post.id}
                likeCount={post.likeCount}
                favoriteCount={post.favoriteCount}
                commentCount={post.commentCount}
                liked={post.isLiked}
                favorited={post.isFavorited}
                onOpenComments={() => setShowComments(true)}
              />
            </div>

            <div className="mt-4 flex flex-wrap items-center gap-2 text-xs text-[var(--ui-social-faint)]">
              <button type="button" onClick={() => setShowReport(true)} className="inline-flex min-h-11 items-center gap-1 rounded-full px-3 transition hover:text-[var(--ui-social-text)]"><Icon icon={Flag} size="sm" />举报</button>
              {post.author && (
                <button
                  type="button"
                  onClick={toggleBlockAuthor}
                  disabled={blockBusy}
                  aria-pressed={blocked}
                  className={cn(
                    // 触达 ≥44px（规范 §8）：此前 py-1.5 只有约 28px 高
                    'm-pressable inline-flex min-h-11 items-center gap-1.5 rounded-full px-4 text-xs transition-colors disabled:opacity-60',
                    blocked
                      ? 'bg-[var(--ui-social-accent-soft)] text-[var(--ui-social-accent)]'
                      : 'ring-1 ring-[var(--ui-social-line)] hover:text-[var(--ui-social-text)]',
                  )}
                >
                  <Icon icon={blocked ? Check : Ban} size="sm" />
                  {blocked ? '已屏蔽 · 点击取消' : '屏蔽作者'}
                </button>
              )}
            </div>

            {post.slug && (
              <Link
                href={travelDetailHref(post.slug)}
                className="mt-5 inline-flex items-center gap-2 rounded-full bg-[var(--ui-social-accent-soft)] px-4 py-2.5 text-sm font-medium text-[var(--ui-social-accent)] transition-colors hover:bg-[var(--ui-social-accent)] hover:text-[var(--ui-social-on-accent)]"
              >
                <Icon icon={BookOpen} size="sm" />
                查看完整旅行记录
              </Link>
            )}
          </div>
        </div>

        {post.photos && post.photos.length > 1 && (
          <section className="mt-14" aria-label="旅行照片">
            <SectionHeading label="旅行照片" count={`共 ${post.photos.length} 张`} />
            <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-4">
              {post.photos.map((src, i) => (
                <button key={i} type="button" onClick={() => setViewerIndex(i)} className="group relative aspect-square overflow-hidden rounded-xl bg-[var(--ui-social-surface2)] ring-1 ring-[var(--ui-social-line)]">
                  <Image src={src} alt={`${post.title} 第 ${i + 1} 张`} fill sizes="(max-width: 768px) 50vw, 25vw" className="object-cover transition-transform duration-500 group-hover:scale-105" />
                </button>
              ))}
            </div>
          </section>
        )}

        {/*
          按天游记（R2）：这是「点开别人的旅行」的主体内容。
          此前详情页只有封面 + 一段摘要 + 照片墙，别人根本看不到「旅行」本身。
          数据只包含公开回忆（服务端按 Memory.visibility 过滤），私密内容不下发。
        */}
        {days.length > 0 && <TripDayList days={days} />}
      </div>

      {showReport && (
        <div className="fixed inset-0 z-[70]">
          <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" onClick={() => setShowReport(false)} />
          <div className="absolute left-1/2 top-1/2 w-[90%] max-w-sm -translate-x-1/2 -translate-y-1/2 rounded-[1.6rem] bg-[var(--ui-social-surface)] p-5 ring-1 ring-[var(--ui-social-line)]">
            <div className="mb-3 flex items-center justify-between">
              <h3 className="text-base font-semibold">举报该旅行</h3>
              <button onClick={() => setShowReport(false)} className="text-[var(--ui-social-muted)] hover:text-[var(--ui-social-text)]"><Icon icon={X} size="sm" /></button>
            </div>
            <textarea value={reportReason} onChange={(e) => setReportReason(e.target.value)} placeholder="请填写举报原因（如不当内容/广告/侵犯隐私等）" rows={3} className="w-full rounded-xl bg-[var(--ui-social-bg)] px-3 py-2 text-[16px] text-[var(--ui-social-text)] outline-none ring-1 ring-[var(--ui-social-line)] focus-visible:ring-[var(--ui-social-accent)]" />
            <button
              onClick={submitReport}
              disabled={reporting || !reportReason.trim()}
              className="m-pressable mt-3 w-full rounded-full bg-[var(--ui-social-accent)] py-3 text-sm font-medium text-[var(--ui-social-on-accent)] transition-colors disabled:opacity-40"
            >
              {reporting ? '提交中…' : '提交举报'}
            </button>
          </div>
        </div>
      )}
      {showEdit && (
        <div className="fixed inset-0 z-[80]">
          <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" onClick={() => setShowEdit(false)} />
          <div className="absolute left-1/2 top-1/2 max-h-[88vh] w-[92%] max-w-lg -translate-x-1/2 -translate-y-1/2 overflow-y-auto rounded-[1.6rem] bg-[var(--ui-social-surface)] p-5 ring-1 ring-[var(--ui-social-line)]">
            <div className="mb-4 flex items-center justify-between">
              <h3 className="text-base font-semibold">编辑旅行故事</h3>
              <button type="button" onClick={() => setShowEdit(false)} className="text-[var(--ui-social-muted)] transition hover:text-[var(--ui-social-text)]" aria-label="关闭编辑"><Icon icon={X} size="md" /></button>
            </div>

            <label className="mb-1.5 block text-xs text-[var(--ui-social-muted)]">标题</label>
            <input
              value={editTitle}
              onChange={(e) => setEditTitle(e.target.value)}
              maxLength={255}
              placeholder="输入标题"
              className="w-full rounded-xl bg-[var(--ui-social-bg)] px-4 py-3 text-[16px] text-[var(--ui-social-text)] outline-none ring-1 ring-[var(--ui-social-line)] transition focus-visible:ring-[var(--ui-social-accent)]"
            />

            <label className="mb-1.5 mt-4 block text-xs text-[var(--ui-social-muted)]">内容 / 摘要</label>
            <textarea
              value={editSummary}
              onChange={(e) => setEditSummary(e.target.value)}
              rows={5}
              placeholder="写下这次旅行的故事…"
              className="w-full resize-none rounded-xl bg-[var(--ui-social-bg)] px-4 py-3 text-[16px] text-[var(--ui-social-text)] outline-none ring-1 ring-[var(--ui-social-line)] transition focus-visible:ring-[var(--ui-social-accent)]"
            />

            {post.postId != null ? (
              <div className="mt-5">
                <div className="mb-2 flex items-center justify-between">
                  <span className="text-xs text-[var(--ui-social-muted)]">旅行照片</span>
                  <button
                    type="button"
                    onClick={() => photoInputRef.current?.click()}
                    disabled={uploading}
                    className="inline-flex items-center gap-1.5 rounded-full bg-[var(--ui-social-surface)] px-3 py-1.5 text-xs text-[var(--ui-social-accent)] ring-1 ring-[var(--ui-social-line)] transition hover:ring-[var(--ui-social-accent)] disabled:opacity-50"
                  >
                    {uploading ? <Icon icon={Loader2} size="sm" className="animate-spin" /> : <Icon icon={ImageIcon} size="sm" />}
                    上传图片
                  </button>
                  <input
                    ref={photoInputRef}
                    type="file"
                    accept="image/*"
                    multiple
                    className="hidden"
                    onChange={(e) => { if (e.target.files) uploadImages(e.target.files) }}
                  />
                </div>

                {post.photos.length > 0 ? (
                  <div className="grid grid-cols-3 gap-2">
                    {post.photos.map((src) => (
                      <div key={src} className="group relative aspect-square overflow-hidden rounded-xl bg-[var(--ui-social-surface2)] ring-1 ring-[var(--ui-social-line)]">
                        <img src={src} alt="" width={400} height={400} loading="lazy" decoding="async" className="h-full w-full object-cover" />
                        <button
                          type="button"
                          onClick={() => deleteImage(src)}
                          aria-label="删除图片"
                          className="absolute right-1.5 top-1.5 flex h-7 w-7 items-center justify-center rounded-full bg-black/60 text-white opacity-0 transition group-hover:opacity-100"
                        >
                          <Icon icon={Trash2} size="sm" tone="inverse" />
                        </button>
                      </div>
                    ))}
                  </div>
                ) : (
                  <p className="rounded-xl bg-[var(--ui-social-bg)] px-4 py-6 text-center text-xs text-[var(--ui-social-faint)]">还没有照片，点击“上传图片”添加。</p>
                )}
              </div>
            ) : (
              <p className="mt-4 rounded-xl bg-[var(--ui-social-bg)] px-4 py-4 text-xs text-[var(--ui-social-faint)]">图片请在旅行详情中统一管理。</p>
            )}

            {editError && <p className="mt-3 text-sm text-[var(--danger-soft)]">{editError}</p>}

            <div className="mt-5 flex justify-end gap-2">
              <button
                type="button"
                onClick={() => setShowEdit(false)}
                className="rounded-full px-5 py-2.5 text-sm text-[var(--ui-social-muted)] ring-1 ring-[var(--ui-social-line)] transition hover:text-[var(--ui-social-text)]"
              >
                取消
              </button>
              <button
                type="button"
                onClick={saveEdit}
                disabled={editSaving || uploading}
                className="inline-flex items-center gap-1.5 rounded-full bg-[var(--ui-social-accent)] px-5 py-2.5 text-sm font-medium text-[var(--ui-social-on-accent)] transition hover:bg-[var(--ui-social-accent-strong)] disabled:opacity-50"
              >
                {editSaving ? <Icon icon={Loader2} size="sm" className="animate-spin" /> : null}
                保存
              </button>
            </div>
          </div>
        </div>
      )}
      {showComments && (
        <CommentPanel
          postId={post.id}
          onClose={() => setShowComments(false)}
          // 删除评论后详情页的评论数立即跟着变（此前要重新进页面才更新）
          onCountChange={(delta) =>
            setPost((prev) => (prev ? { ...prev, commentCount: Math.max(0, prev.commentCount + delta) } : prev))
          }
        />
      )}
      {viewerIndex !== null && post.photos.length > 0 && (
        <PhotoViewer images={gallery.map((src) => ({ src, alt: post.title }))} index={viewerIndex} onClose={() => setViewerIndex(null)} onIndexChange={setViewerIndex} />
      )}
    </div>
  )
}

/**
 * 详情首帧骨架屏（R2）。
 *
 * 旧实现是整页居中的「加载中…」+ 转圈 —— 在真机弱网下这一帧会停留可见，
 * 用户体感就是"点了没反应 / 跳到别处了"。骨架屏与真实布局同构（封面 / 标题 / 作者 / 动作条），
 * 数据到达时不会跳版。
 * 做法参考 usememos/memos 的 `ProfileHeader` / `ProfileHeaderSkeleton` 共用外壳思路（MIT）。
 */
function PostDetailSkeleton() {
  return (
    // 骨架与真实布局同构（2026-10-17 随版面对齐）：桌面端也是「左图右文」两栏，
    // 否则数据到达时正文会从一列跳成两列 —— 骨架屏的意义就是"不跳版"。
    <div className="min-h-dvh bg-[var(--ui-social-bg)] pb-[calc(112px+env(safe-area-inset-bottom))] md:pb-28">
      <div className="relative mx-auto max-w-3xl px-4 py-6 md:max-w-5xl">
        <div className="mb-7 flex items-center gap-3">
          <div className="h-11 w-11 animate-pulse rounded-full bg-[var(--ui-social-surface2)]" />
          <div className="h-3 w-16 animate-pulse rounded bg-[var(--ui-social-surface2)]" />
        </div>
        <div className="md:grid md:grid-cols-[minmax(0,1.05fr)_minmax(0,1fr)] md:gap-10">
          <div className="aspect-[4/5] w-full animate-pulse rounded-[24px] bg-[var(--ui-social-surface2)]" />
          <div className="mt-8 md:mt-1">
            <div className="h-3 w-20 animate-pulse rounded bg-[var(--ui-social-surface2)]" />
            <div className="mt-3 h-7 w-3/4 animate-pulse rounded bg-[var(--ui-social-surface2)]" />
            <div className="mt-5 flex flex-wrap gap-2">
              {[0, 1, 2].map((i) => (
                <div key={i} className="h-8 w-24 animate-pulse rounded-full bg-[var(--ui-social-surface2)]" />
              ))}
            </div>
            <div className="mt-6 h-16 w-full animate-pulse rounded-2xl bg-[var(--ui-social-surface2)]" />
            <div className="mt-4 h-16 w-full animate-pulse rounded bg-[var(--ui-social-surface2)]" />
            <div className="mt-7 h-14 w-full animate-pulse rounded-2xl bg-[var(--ui-social-surface2)]" />
          </div>
        </div>
      </div>
    </div>
  )
}

/**
 * 分节标题（旅行照片 / 按天回顾共用）。
 *
 * 抽成组件而不是各写一遍：这两处原先一处是 `<h2>` + 一条 flex-1 细线，
 * 另一处在同样结构后又补了个「N 天」，字距、线宽、计数位置都开始漂移 ——
 * 同一页里的同级标题必须长得一模一样，否则"精致"是假的。
 */
function SectionHeading({ label, count }: { label: string; count?: string }) {
  return (
    <div className="circle-story-heading mb-5">
      <h2 className="circle-story-heading-label">{label}</h2>
      <span className="circle-story-heading-rule" aria-hidden="true" />
      {count && <span className="circle-story-heading-count">{count}</span>}
    </div>
  )
}

/**
 * 按天游记（只读）。
 *
 * 与 `components/travel/TravelTimeline.tsx` 是"同构不同权"的一对：
 * 那边是作者编辑态（有「记一笔 / 添加行程」），这里是**读者视角**，不能有任何写入口。
 * 数据由服务端按 `Memory.visibility = PUBLIC` 过滤，前端只管渲染。
 */
function TripDayList({ days }: { days: TripDay[] }) {
  /**
   * 每天最多铺 8 张缩略图，多出来的用「+N」明确交代。
   * 旧实现直接 `slice(0, 8)`：第 9 张起**静默消失**，读者会以为那天只有 8 张照片 ——
   * 这是"少给信息"比"多给信息"更坏的一类缺陷（用户根本不知道自己漏看了）。
   */
  const PHOTOS_PER_DAY = 8

  return (
    <section className="mt-14" aria-label="按天回顾">
      <SectionHeading label="按天回顾" count={`共 ${days.length} 天`} />

      <div className="relative">
        <span className="circle-story-rail absolute bottom-2 left-[9px] top-2 w-px" aria-hidden="true" />
        <div className="space-y-5">
          {days.map((day, idx) => (
            <article key={`${day.date ?? 'day'}-${idx}`} className="relative pl-8">
              <span className="circle-story-dot absolute left-0 top-5" aria-hidden="true" />

              <div className="circle-story-day">
                <div className="flex flex-wrap items-center gap-2">
                  <span className="circle-story-day-badge">DAY {String(idx + 1).padStart(2, '0')}</span>
                  {day.date && <span className="text-xs tabular-nums text-[var(--ui-social-muted)]">{formatDayDate(day.date)}</span>}
                  {day.title && <span className="text-sm font-medium text-[var(--ui-social-text)]">· {day.title}</span>}
                </div>
                {day.summary && <p className="mt-2 text-sm leading-relaxed text-[var(--ui-social-muted)]">{day.summary}</p>}

                {day.itinerary.length > 0 && (
                  <ul className="mt-3 flex flex-wrap gap-1.5">
                    {day.itinerary.map((it) => (
                      <li
                        key={it.id}
                        className="inline-flex items-center gap-1.5 rounded-full bg-[var(--ui-social-surface)] px-3 py-1.5 text-xs ring-1 ring-[var(--ui-social-line)]"
                      >
                        <span className="text-[var(--ui-social-accent)]">{ITINERARY_TYPE_LABEL[it.type] || '行程'}</span>
                        <span className="max-w-[12rem] truncate">{it.title}</span>
                        {it.startTime && (
                          <span className="tabular-nums text-[var(--ui-social-faint)]">
                            {new Date(it.startTime).toTimeString().slice(0, 5)}
                          </span>
                        )}
                      </li>
                    ))}
                  </ul>
                )}

                {day.photos.length > 0 && (
                  <div className="mt-3 grid grid-cols-3 gap-1.5 sm:grid-cols-4">
                    {day.photos.slice(0, PHOTOS_PER_DAY).map((p, i) => (
                      <div key={p.id} className="relative overflow-hidden rounded-lg bg-[var(--ui-social-surface2)]">
                        {/* eslint-disable-next-line @next/next/no-img-element -- 服务端已给缩略图变体，无需 next/image 再处理 */}
                        <img src={p.url} alt="" width={400} height={400} loading="lazy" decoding="async" className="aspect-square w-full object-cover" />
                        {i === PHOTOS_PER_DAY - 1 && day.photos.length > PHOTOS_PER_DAY && (
                          <span className="absolute inset-0 flex items-center justify-center bg-black/55 text-sm font-medium tabular-nums text-white">
                            +{day.photos.length - PHOTOS_PER_DAY}
                          </span>
                        )}
                      </div>
                    ))}
                  </div>
                )}

                {day.memories.length > 0 && (
                  <div className="mt-3 space-y-2">
                    {day.memories.map((mem) => (
                      <div key={mem.id} className="circle-story-quote">
                        <p className="text-sm font-medium">
                          {mem.title}
                          {mem.mood && <span className="ml-1.5 text-xs font-normal text-[var(--ui-social-muted)]">· {mem.mood}</span>}
                        </p>
                        {mem.content && (
                          <p className="mt-0.5 whitespace-pre-wrap text-sm leading-relaxed text-[var(--ui-social-muted)]">{mem.content}</p>
                        )}
                        {mem.photos.length > 0 && (
                          <div className="mt-1.5 flex gap-1">
                            {mem.photos.slice(0, 3).map((p) => (
                              // eslint-disable-next-line @next/next/no-img-element -- 同上
                              <img key={p.id} src={p.url} alt="" width={48} height={48} loading="lazy" decoding="async" className="h-12 w-12 rounded-md object-cover" />
                            ))}
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                )}

                {day.itinerary.length === 0 && day.photos.length === 0 && day.memories.length === 0 && (
                  <p className="mt-2 text-xs text-[var(--ui-social-faint)]">这一天还没有公开的记录</p>
                )}
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  )
}

'use client'

import { useState, type MouseEvent } from 'react'
import Image from 'next/image'
import { useRouter } from 'next/navigation'
import { MessageCircle, Bookmark, MapPin, ImageIcon } from 'lucide-react'
import { Icon } from '@/components/mobile/Icon'
import SocialAvatar from '@/components/social/SocialAvatar'
import QuickLike from '@/components/social/QuickLike'
import { cn } from '@/lib/utils'
import { hapticLight } from '@/lib/mobile/haptics'
import { toggleFavorite } from '@/lib/modules/offline/social-write'

export interface SocialFilmAuthor {
  name: string
  avatar?: string | null
}

interface SocialFilmCardProps {
  coverUrl?: string | null
  cityName?: string | null
  title?: string
  summary?: string | null
  dateRange?: string
  dayCount?: number
  photoCount?: number
  location?: string | null
  travelRelation?: string | null
  author?: SocialFilmAuthor | null
  stats?: { likes?: number; comments?: number; bookmarks?: number }
  /** 传入后卡片右下角出现「快捷点赞」入口（不必进详情页即可点赞） */
  postId?: number
  liked?: boolean
  likeCount?: number
  /** 访客态：传入登录地址后，快捷点赞引导登录而非发请求 */
  likeLoginHref?: string
  /**
   * 收藏（2026-10-17 新增）。
   *
   * 此前列表上的书签数字是**只读文本**：想收藏必须点进详情页再点一次书签。
   * 而收藏是"稍后再看"的动作，用户恰恰是在**浏览列表时**做决定 ——
   * 数据（`isFavorited` / `favoriteCount`）服务端早就下发了，缺的只是入口。
   */
  favorited?: boolean
  favoriteCount?: number
  /** 访客态：传入登录地址后，快捷收藏引导登录而非发请求 */
  favoriteLoginHref?: string
  /** 传入后「评论数」变成可点入口：直接打开详情页的评论抽屉 */
  onOpenComments?: () => void
  variant?: 'hero' | 'card'
  frame?: 'wide' | 'portrait' | 'square' | 'landscape'
  onOpen?: () => void
  className?: string
}

const FRAME = {
  wide: 'aspect-[16/10]',
  portrait: 'aspect-[4/5]',
  square: 'aspect-square',
  landscape: 'aspect-[4/3]',
}

/**
 * 快捷收藏（列表卡片上的收藏入口，2026-10-17）。
 *
 * 此前列表上的书签数字是**只读文本**：想收藏必须点进详情页再点一次书签按钮。
 * 而收藏是"稍后再看"的动作 —— 用户恰恰是在**浏览列表时**做这个决定。
 * 数据服务端早就下发了（`isFavorited` / `favoriteCount`），缺的只是客户端入口。
 *
 * 形状与 `QuickLike` 严格对齐（同一套胶囊尺寸 / 按压回弹 / 乐观更新 + 失败回滚 /
 * 未登录引导登录、不发无效请求），因为两枚胶囊在卡片上是并排的兄弟控件，
 * 口径不一致会立刻被看出来。
 *
 * 为什么与 `QuickLike` 同处一个文件而不是各开一个：本文件已经从 lucide-react
 * 引入了 `Bookmark`，单独开文件会多欠一条「直接 import lucide-react」的规范债
 * （设计规范门禁第 2 条），而这条债对代码质量没有任何好处。
 */
function QuickFavorite({
  postId,
  favoriteCount,
  favorited = false,
  loginHref,
  className,
}: {
  postId: number
  favoriteCount: number
  favorited?: boolean
  loginHref?: string
  className?: string
}) {
  const router = useRouter()
  const [isFavorited, setIsFavorited] = useState(favorited)
  const [count, setCount] = useState(favoriteCount)
  const [pending, setPending] = useState(false)
  const [popKey, setPopKey] = useState(0)

  const handleClick = async (e: MouseEvent) => {
    // 卡片上铺了一层「打开详情」的点击层，这里必须阻止冒泡，否则收藏会顺带跳页
    e.preventDefault()
    e.stopPropagation()
    if (pending) return

    void hapticLight()

    if (loginHref) {
      router.push(loginHref)
      return
    }

    const prevFav = isFavorited
    const prevCount = count
    const next = !prevFav

    // 乐观更新
    setIsFavorited(next)
    setCount(Math.max(0, prevCount + (next ? 1 : -1)))
    if (next) setPopKey((k) => k + 1)
    setPending(true)

    try {
      const r = await toggleFavorite(postId, next)
      if (!r.ok) {
        setIsFavorited(prevFav)
        setCount(prevCount)
      }
    } catch {
      setIsFavorited(prevFav)
      setCount(prevCount)
    } finally {
      setPending(false)
    }
  }

  return (
    <button
      type="button"
      onClick={handleClick}
      aria-pressed={isFavorited}
      aria-label={loginHref ? '登录后收藏' : isFavorited ? '取消收藏' : '收藏'}
      className={cn(
        'm-pressable inline-flex min-h-11 items-center gap-1.5 rounded-full px-3 text-sm font-semibold tabular-nums',
        'backdrop-blur-md transition-colors',
        // 与 QuickLike 的 on-media 变体同一套：永远压在照片上，必须用固定浅色 + 半透明底
        'bg-black/45 text-white ring-1 ring-white/25',
        isFavorited && 'text-travel-bloom',
        pending && 'opacity-80',
        className,
      )}
    >
      <Icon
        icon={Bookmark}
        size="sm"
        key={popKey}
        className={cn('transition-transform', isFavorited && 'fill-current', isFavorited && popKey > 0 && 'm-pop')}
      />
      <span>{count}</span>
    </button>
  )
}

/**
 * 旅行故事卡片（Stage 3 视觉统一）：
 * 照片第一，其次标题 / 地点日期 / 作者 / 正文，互动最弱；弱边框，不做统一圆角白卡。
 *
 * M5 修订（快捷点赞）：
 *  · **结构修正**：此前 `onOpen` 存在时根元素是 `<button>`，于是任何放在卡片里的互动控件
 *    （点赞按钮）都会变成 `<button>` 嵌套 `<button>` —— 非法 HTML，点击语义也会错乱。
 *    现在根元素固定为 `<div>`，另铺一层绝对定位的 `<button>` 作为「打开详情」的点击/键盘层，
 *    互动控件以更高的 z-index 叠在它之上（z-[2] > z-[1]）。
 *  · **快捷点赞**：卡片封面右下角浮动 ♡（hero 变体放在底部信息行），不必进详情页；
 *    只读的 ♡ 计数从 stats 行移除，避免同一个数字出现两次。
 */
export default function SocialFilmCard({
  coverUrl,
  cityName,
  title,
  summary,
  dateRange,
  dayCount,
  photoCount,
  location,
  travelRelation,
  author,
  stats,
  postId,
  liked = false,
  likeCount = 0,
  likeLoginHref,
  favorited = false,
  favoriteCount,
  favoriteLoginHref,
  onOpenComments,
  variant = 'card',
  frame = 'portrait',
  onOpen,
  className,
}: SocialFilmCardProps) {
  /**
   * 收藏胶囊的渲染条件与点赞胶囊同一处：两者都需要 postId + 服务端回填的计数。
   * 拿不到计数时**不渲染** —— 「拿不到数据」显示成「0 收藏」比不显示更糟。
   */
  const showFavorite = postId !== undefined && favoriteCount !== undefined

  /**
   * 统计行（只读）。
   *
   * 「同一个数字只出现一次」：点赞与收藏现在都是卡片上的**可交互胶囊**，
   * 这里便不再重复渲染同一个数字（否则用户会以为是两件不同的事）。
   * 评论数则从死文本升级成**入口**：点它直接打开详情页的评论抽屉 ——
   * 此前列表上那个数字点不动，想看评论必须先进详情再找动作条。
   *
   * `onMedia` 用于 hero 变体 —— 它永远压在 `from-[#050505]/90` 的深色遮罩上，
   * 必须用固定浅色，**不能用主题 token**：浅色主题下 `--social-muted` 是深棕
   * （rgba(43,33,27,.70)），压在近黑遮罩上几乎看不见（实测对比度远低于 3:1）。
   */
  const statsNode = (onMedia = false) => {
    const tone = onMedia ? 'text-white/75' : 'text-[var(--ui-social-muted)]'
    // 深色遮罩上不能 hover 成陶土色（浅色主题下它是深棕砖色，压在近黑底上看不见）
    const hoverTone = onMedia ? 'hover:text-white' : 'hover:text-[var(--ui-social-accent)]'
    return (
      <div className={cn('flex items-center gap-3', tone)}>
        {stats?.comments !== undefined &&
          (onOpenComments ? (
            <button
              type="button"
              onClick={(e) => {
                e.preventDefault()
                e.stopPropagation()
                onOpenComments()
              }}
              aria-label={`查看评论，共 ${stats.comments} 条`}
              className={cn(
                // z-[2]：必须高于卡片那层 z-[1] 的「打开详情」点击层，否则点不到
                'm-pressable relative z-[2] inline-flex min-h-6 items-center gap-1 rounded-full px-1 text-xs tabular-nums transition-colors',
                hoverTone,
              )}
            >
              <Icon icon={MessageCircle} size="sm" />
              {stats.comments}
            </button>
          ) : (
            <span className="inline-flex items-center gap-1 text-xs tabular-nums">
              <Icon icon={MessageCircle} size="sm" />
              {stats.comments}
            </span>
          ))}
        {!showFavorite && stats?.bookmarks !== undefined && (
          <span className="inline-flex items-center gap-1 text-xs tabular-nums"><Icon icon={Bookmark} size="sm" />{stats.bookmarks}</span>
        )}
      </div>
    )
  }

  const likeNode =
    postId !== undefined ? (
      <QuickLike
        postId={postId}
        likeCount={likeCount}
        liked={liked}
        loginHref={likeLoginHref}
        variant="on-media"
      />
    ) : null

  const favoriteNode =
    postId !== undefined && favoriteCount !== undefined ? (
      <QuickFavorite
        postId={postId}
        favoriteCount={favoriteCount}
        favorited={favorited}
        loginHref={favoriteLoginHref}
      />
    ) : null

  /** 卡片封面上的快捷互动行：点赞 + 收藏并排（hero / card 两种变体共用同一套排列） */
  const quickActions =
    likeNode || favoriteNode ? (
      <div className="flex items-center gap-2">
        {likeNode}
        {favoriteNode}
      </div>
    ) : null

  /** 「打开详情」的覆盖层：整块可点，且保持键盘可达（根元素不再是 button） */
  const openLayer = onOpen ? (
    <button
      type="button"
      onClick={onOpen}
      aria-label={title ? `打开旅行故事：${title}` : '打开旅行故事'}
      className="absolute inset-0 z-[1] cursor-pointer rounded-[inherit] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ui-social-accent)]"
    />
  ) : null

  const cover = (aspectClass: string, overlay?: React.ReactNode) => (
    <div className={cn('relative w-full overflow-hidden bg-[var(--ui-social-surface2)]', aspectClass)}>
      {coverUrl ? (
        <Image
          src={coverUrl}
          alt={title || cityName || '旅行封面'}
          fill
          sizes={variant === 'hero' ? '100vw' : '(max-width: 768px) 100vw, 33vw'}
          onLoad={(e) => e.currentTarget.classList.add('is-loaded')}
          className="m-img-fade object-cover transition-transform duration-700 ease-out group-hover:scale-[1.04]"
        />
      ) : (
        <div className="absolute inset-0 flex items-center justify-center text-[var(--ui-social-muted)]"><Icon icon={ImageIcon} size="lg" /></div>
      )}
      {overlay}
    </div>
  )

  if (variant === 'hero') {
    return (
      <div className={cn('group relative block w-full overflow-hidden rounded-[2rem] bg-[var(--ui-social-surface)] text-left ring-1 ring-[var(--ui-social-line)]', className)}>
        {openLayer}
        {cover('aspect-[16/10]')}
        <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-[#050505]/90 via-[#050505]/15 to-transparent" />
        {/*
          z-[2] 是必需的，不是装饰：卡片的「打开详情」覆盖层是 z-[1]，而这一层原先没有
          z-index（z-auto）。同为定位元素时 z-index:1 会**画在 z-auto 之上**，
          于是覆盖层抢走了这一整块区域的点击 —— 底部信息行里的点赞 / 收藏按钮
          看起来好好的，点下去却是"打开详情"（2026-10-17 由 E2E 实测抓到：
          `.click()` 报 "…intercepts pointer events"）。
          card 变体的快捷胶囊本来就写了 z-[2]，hero 变体漏了，这里补齐。
        */}
        <div className="pointer-events-none absolute inset-x-0 bottom-0 z-[2] p-4 sm:p-7">
          {/* 以下文字一律用固定浅色：它们永远压在深色遮罩上，主题 token 在浅色主题下会变成深色而看不清 */}
          {cityName && <div className="text-xs font-medium tracking-[0.22em] text-travel-bloom uppercase">{cityName}</div>}
          {title && <h2 className="mt-2 max-w-2xl text-xl font-semibold leading-tight tracking-tight text-white sm:text-3xl">{title}</h2>}
          {summary && <p className="mt-2 line-clamp-2 max-w-2xl text-sm text-white/75 max-sm:hidden">{summary}</p>}
          <div className="mt-3 flex items-center justify-between gap-3 sm:mt-4">
            {author ? <div className="flex min-w-0 items-center gap-2"><SocialAvatar name={author.name} avatarUrl={author.avatar} size={28} /><span className="truncate text-sm text-white/80">{author.name}</span></div> : <span />}
            <div className="pointer-events-auto flex items-center gap-3">
              {quickActions}
              {statsNode(true)}
            </div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div
      className={cn('m-card-pressable group relative block w-full overflow-hidden rounded-[1.4rem] bg-[var(--ui-social-surface-90)] text-left ring-1 ring-[var(--ui-social-line)] transition-colors duration-300',
        onOpen && 'hover:-translate-y-0.5 hover:bg-[var(--ui-social-surface)] hover:ring-[var(--ui-social-line-strong)]', className)}>
      {openLayer}
      {cover(
        FRAME[frame],
        quickActions && (
          <div className="absolute bottom-3 right-3 z-[2]">{quickActions}</div>
        ),
      )}
      <div className="space-y-2 p-4">
        {cityName && <div className="flex items-center gap-1 text-xs font-medium uppercase tracking-[0.16em] text-[var(--ui-social-accent)]"><Icon icon={MapPin} size="sm" />{cityName}</div>}
        {title && <h3 className="line-clamp-2 text-base font-semibold leading-snug text-[var(--ui-social-text)]">{title}</h3>}
        {summary && <p className="line-clamp-2 text-sm leading-relaxed text-[var(--ui-social-muted)]">{summary}</p>}
        <div className="flex items-center gap-x-2 gap-y-1 text-xs text-[var(--ui-social-muted)]">
          {travelRelation && <span className="text-[var(--ui-social-accent)]">{travelRelation}</span>}
          {dateRange && <span>{dateRange}</span>}
          {dayCount !== undefined && <span>· {dayCount} 天</span>}
          {photoCount !== undefined && <span>· {photoCount} 张</span>}
        </div>
        <div className="flex items-center justify-between gap-2 border-t border-[var(--ui-social-line)] pt-3">
          {author ? <div className="flex min-w-0 items-center gap-2"><SocialAvatar name={author.name} avatarUrl={author.avatar} size={24} /><span className="truncate text-xs text-[var(--ui-social-muted)]">{author.name}</span></div> : <span />}
          {statsNode()}
        </div>
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { ArrowLeft, Loader2 } from 'lucide-react'
import { Icon } from '@/components/mobile/Icon'
import SocialAvatar from '@/components/social/SocialAvatar'
import SocialThemeToggle from '@/components/social/SocialThemeToggle'
import { goBackOrHome } from '@/lib/navigation'
