export default function UserList({ endpoint, title }: { endpoint: string; title: string }) {
  const router = useRouter()
  const [users, setUsers] = useState<any[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    fetch(endpoint).then((r) => r.json()).then((j) => setUsers(j.data || [])).catch(() => {}).finally(() => setLoading(false))
  }, [endpoint])

  return (
    <div className="min-h-dvh bg-[var(--ui-social-bg)] pb-28 text-[var(--ui-social-text)]">
      {/* m-safe-top：同「我的收藏」，避免标题栏与状态栏重叠 */}
      <div className="m-safe-top relative mx-auto max-w-2xl px-4 pb-6">
        <header className="mb-8 flex items-center gap-3">
          <button
            type="button"
            onClick={() => goBackOrHome(router, '/me')}
            aria-label="返回上一级"
            className="m-pressable flex h-11 w-11 shrink-0 items-center justify-center rounded-full text-[var(--ui-social-muted)] ring-1 ring-[var(--ui-social-line)] transition-colors hover:text-[var(--ui-social-text)]"
          >
            <Icon icon={ArrowLeft} size="md" />
          </button>
          <div className="min-w-0 flex-1">
            <p className="text-xs font-medium uppercase tracking-[0.24em] text-[var(--ui-social-accent)]">People</p>
            <h1 className="text-xl font-semibold">{title}</h1>
          </div>
          <SocialThemeToggle />
        </header>
        {loading ? (
          <div className="py-20 text-center text-[var(--ui-social-faint)]"><Icon icon={Loader2} size="md" className="mx-auto animate-spin" /></div>
        ) : users.length === 0 ? (
          <p className="py-20 text-center text-sm text-[var(--ui-social-faint)]">暂无数据。</p>
        ) : (
          <div className="space-y-1">
            {users.map((u) => {
              const name = u.nickname || u.username
              return (
                <Link key={u.id} href={circleUserHref(u.id) ?? '/circle'} className="flex items-center gap-3 border-b border-[var(--ui-social-line)] px-2 py-3.5 transition hover:bg-[var(--ui-social-surface-50)]">
                  <SocialAvatar name={name} avatarUrl={u.avatarUrl} size={40} />
                  <span className="min-w-0 flex-1 truncate text-sm font-medium">{name}</span>
                  <span className="text-xs text-[var(--ui-social-faint)]">@{u.username}</span>
                </Link>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { ArrowLeft, Loader2, UserPlus, UserMinus, Ban } from 'lucide-react'
import { Icon } from '@/components/mobile/Icon'
import SocialAvatar from '@/components/social/SocialAvatar'
import SocialFilmCard from '@/components/social/SocialFilmCard'
import { cn } from '@/lib/utils'
import SocialThemeToggle from '@/components/social/SocialThemeToggle'
import { apiUrl } from '@/lib/api-base'
import { circlePostCommentsHref, circlePostHref } from '@/lib/routes'
import { goBackOrHome } from '@/lib/navigation'

interface Profile {
  id: number
  username: string
  nickname: string | null
  avatarUrl: string | null
  accountId: string | null
  createdAt: string | null
  stats: { postCount: number; followerCount: number; followingCount: number }
  isFollowing: boolean
  isBlocked: boolean
  posts: any[]
}

const FRAMES = ['portrait', 'landscape', 'square', 'wide', 'portrait', 'landscape'] as const

function displayName(p: Profile): string {
  return p.nickname || p.username
}

function Stat({ label, value }: { label: string; value: number }) {
  return (
    <div>
      <div className="text-xl font-semibold text-[var(--ui-social-text)] tabular-nums">{value}</div>
      <div className="mt-1 text-xs uppercase tracking-[0.16em] text-[var(--ui-social-faint)]">{label}</div>
    </div>
  )
}

export default function UserProfile({ userId }: { userId: number }) {
  const router = useRouter()
  const [profile, setProfile] = useState<Profile | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)

  useEffect(() => {
    fetch(apiUrl('/api/social/users/' + userId), { credentials: 'include' })
      .then((r) => r.json())
      .then((json) => { if (json.data) setProfile(json.data); else setError(json.error || '用户不存在') })
      .catch(() => setError('网络错误'))
      .finally(() => setLoading(false))
  }, [userId])

  const follow = async () => {
    if (!profile || busy) return
    const next = !profile.isFollowing
    const snapshot = profile
    setBusy(true)
    setProfile({ ...profile, isFollowing: next, stats: { ...profile.stats, followerCount: profile.stats.followerCount + (next ? 1 : -1) } })
    try {
      const res = await fetch(apiUrl('/api/social/users/' + userId + '/follow'), { method: next ? 'POST' : 'DELETE', credentials: 'include' })
      if (!res.ok) throw new Error()
    } catch { setProfile(snapshot) } finally { setBusy(false) }
  }

  const toggleBlock = async () => {
    if (!profile || busy) return
    const next = !profile.isBlocked
    const snapshot = profile
    setBusy(true)
    setProfile({ ...profile, isBlocked: next })
    try {
      const res = await fetch(apiUrl('/api/social/users/' + userId + '/block'), { method: next ? 'POST' : 'DELETE', credentials: 'include' })
      if (!res.ok) throw new Error()
    } catch { setProfile(snapshot) } finally { setBusy(false) }
  }

  if (loading) return <div className="flex min-h-dvh items-center justify-center bg-[var(--ui-social-bg)] text-[var(--ui-social-faint)]"><Icon icon={Loader2} size="lg" className="animate-spin" /></div>
  if (error || !profile) return <div className="flex min-h-dvh flex-col items-center justify-center gap-3 bg-[var(--ui-social-bg)] text-[var(--ui-social-faint)]">{error || '用户不存在'}<Link href="/circle" className="text-[var(--ui-social-accent)]">返回旅行圈</Link></div>

  const cardProps = (p: any, frame: (typeof FRAMES)[number]) => ({
    coverUrl: p.coverUrl || undefined,
    cityName: p.location || undefined,
    title: p.title,
    summary: p.summary,
    dateRange: p.startDate ? p.startDate.slice(0, 10) : '',
    dayCount: p.dayCount,
    photoCount: p.photoCount,
    location: p.location || undefined,
    author: { name: displayName(profile), avatar: profile.avatarUrl },
    // 快捷点赞：在别人的主页浏览其旅行时也能直接点赞（/circle/user/* 需登录才能进）
    postId: p.id,
    liked: p.isLiked,
    likeCount: p.likeCount,
    // 收藏与评论入口：与旅行圈列表口径一致（`/api/social/users/[id]` 走 attachViewerState，
    // 已回填 isFavorited / favoriteCount；评论数点击直接展开评论抽屉）
    favorited: p.isFavorited,
    favoriteCount: p.favoriteCount,
    onOpenComments: () => {
      const href = circlePostCommentsHref(p.id)
      if (href) router.push(href)
    },
    stats: { comments: p.commentCount, bookmarks: p.favoriteCount },
    frame,
    onOpen: () => {
      const href = circlePostHref(p.id)
      if (href) router.push(href)
    },
  })

  return (
    <div className="min-h-dvh bg-[var(--ui-social-bg)] pb-24 text-[var(--ui-social-text)]">
      <div className="pointer-events-none fixed inset-x-0 top-0 h-[360px] bg-[radial-gradient(55%_60%_at_50%_-10%,rgba(232,179,106,0.09),transparent_65%)]" />
      <div className="relative mx-auto max-w-5xl px-4 py-6">
        <header className="mb-8 flex items-center gap-3">
          <div className="ml-auto"><SocialThemeToggle /></div>
          {/* 图标按钮：补可访问名称 + 44px 触达（pro-rules 两条硬要求） */}
          <button
            type="button"
            onClick={() => goBackOrHome(router)}
            aria-label="返回"
            className="m-pressable flex h-11 w-11 items-center justify-center rounded-full text-[var(--ui-social-muted)] ring-1 ring-[var(--ui-social-line)] hover:text-[var(--ui-social-text)]"
          >
            <Icon icon={ArrowLeft} size="md" />
          </button>
          <span className="text-sm text-[var(--ui-social-muted)]">旅行者主页</span>
        </header>

        <section className="flex flex-col gap-8 sm:flex-row sm:items-center">
          <SocialAvatar name={displayName(profile)} avatarUrl={profile.avatarUrl} size={96} className="text-3xl" />
          <div className="min-w-0 flex-1">
            <h1 className="text-2xl font-semibold tracking-tight text-[var(--ui-social-text)]">{displayName(profile)}</h1>
            <p className="mt-1 text-sm text-[var(--ui-social-muted)]">@{profile.username}</p>
            {profile.accountId && <span className="mt-2 inline-block rounded-full bg-[var(--ui-social-accent-soft)] px-3 py-1 text-xs text-[var(--ui-social-accent)]">ID {profile.accountId}</span>}
            <div className="mt-6 flex gap-10">
              <Stat label="Trips" value={profile.stats.postCount} />
              <Stat label="Followers" value={profile.stats.followerCount} />
              <Stat label="Following" value={profile.stats.followingCount} />
            </div>
            <div className="mt-6 flex gap-2">
              <button type="button" onClick={follow} disabled={busy}
                className={cn('inline-flex items-center gap-1.5 rounded-full px-6 py-2.5 text-sm font-medium transition active:scale-95 disabled:opacity-50',
                  profile.isFollowing ? 'bg-[var(--ui-social-surface)] text-[var(--ui-social-muted)] ring-1 ring-[var(--ui-social-line)]' : 'bg-[var(--ui-social-accent)] text-[var(--ui-social-on-accent)]')}>
                {profile.isFollowing ? <Icon icon={UserMinus} size="sm" /> : <Icon icon={UserPlus} size="sm" />}
                {profile.isFollowing ? '取消关注' : '关注'}
              </button>
              <button type="button" onClick={toggleBlock} disabled={busy}
                className="inline-flex items-center gap-1.5 rounded-full bg-[var(--ui-social-surface)] px-6 py-2.5 text-sm text-[var(--ui-social-muted)] ring-1 ring-[var(--ui-social-line)] transition hover:text-[var(--ui-social-text)] disabled:opacity-50">
                <Icon icon={Ban} size="sm" />{profile.isBlocked ? '取消屏蔽' : '屏蔽'}
              </button>
            </div>
          </div>
        </section>

        <div className="mt-12 flex items-center gap-3">
          <h2 className="text-sm font-medium uppercase tracking-[0.2em] text-[var(--ui-social-accent)]">Travel Stories</h2>
          <div className="h-px flex-1 bg-[var(--ui-social-line)]" />
        </div>

        {profile.posts.length > 0 ? (
          <div className="mt-6 columns-1 gap-5 sm:columns-2 lg:columns-3 [column-fill:_balance]">
            {profile.posts.map((p, i) => <SocialFilmCard key={p.id} {...cardProps(p, FRAMES[i % FRAMES.length])} className="mb-5 break-inside-avoid" />)}
          </div>
        ) : (
          <p className="py-16 text-center text-sm text-[var(--ui-social-faint)]">还没有公开的旅行故事。</p>
        )}
      </div>
    </div>
  )
}

'use client'

import { useEffect, useRef, useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { cn } from '@/lib/utils'
import {
  Images, Sparkles, MapPin, Camera, UserPlus, Settings2, LogOut, ChevronRight,
  ChevronLeft, CalendarDays, Plus,
} from '@/lib/mobile/icon-system'
import { Icon } from '@/components/mobile/Icon'
import { Button } from '@/components/mobile/Button'
import { BottomSheet } from '@/components/mobile/BottomSheet'
import { ActionSheet } from '@/components/mobile/ActionSheet'
import { Field, FieldTextarea, FieldSelect } from '@/components/mobile/Field'
import { Pill } from '@/components/mobile/Pills'
import { toast } from '@/lib/mobile/toast-store'
import { hapticLight } from '@/lib/mobile/haptics'
import { apiUrl } from '@/lib/api-base'
import { SPACE_TYPES, spaceThemeOf, spaceTypeIconOf, spaceTypeLabelOf, spaceRoleLabelOf } from '@/lib/mobile/space-system'
import { travelTypeIconOf, travelTypeLabelOf } from '@/lib/mobile/icon-system'
import { SpaceAvatarStack } from './SpaceAvatarStack'
import { SpaceActivityFeed } from './SpaceActivityFeed'
import { SpaceInvitePanel } from './SpaceInvitePanel'
import { SpaceMemberList } from './SpaceMemberList'
import type { SpaceOverview } from '@/lib/modules/space/space-overview.types'

export type SpaceDetailData = SpaceOverview

function fmtDate(iso?: string | null): string {
  if (!iso) return ''
  const d = new Date(iso)
  if (isNaN(d.getTime())) return ''
  return `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()}`
}

function SectionHeader({ title, action }: { title: string; action?: React.ReactNode }) {
  return (
    <div className="flex items-center justify-between gap-3 px-1">
      <h2 className="text-[13px] font-semibold tracking-[0.08em] text-[var(--ui-social-muted)]">{title}</h2>
      {action}
    </div>
  )
}

/**
 * 空间详情 —— 协作主场。
 *
 * 五段内容 + 一个成员区，全部按「能不能一起改」组织：
 *   ① 一起记录的旅行  ② 一起经营的相册  ③ 正在规划下一趟  ④ 最近的共同回忆  ⑤ 空间动态
 *
 * 权限：OWNER 看得到邀请与设置；MEMBER 只能编辑内容；VIEWER 全页只读
 * （服务端仍会各自校验，前端显隐只是体验）。
 */
export default function SpaceDetail({
  data,
  onChanged,
}: {
  data: SpaceDetailData
  /** 数据变更后的刷新回调：客户端壳重新取数（服务端渲染场景不传也不影响） */
  onChanged?: () => void
}) {
  const router = useRouter()
  const { space, stats } = data
  const [inviteOpen, setInviteOpen] = useState(false)
  const [settingsOpen, setSettingsOpen] = useState(false)
  const [leaveOpen, setLeaveOpen] = useState(false)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')

  const isOwner = space.myRole === 'OWNER'
  const canEdit = space.myRole === 'OWNER' || space.myRole === 'MEMBER'

  // 空间设置（改名 / 改类型 / 改简介）
  const [editName, setEditName] = useState(space.name)
  const [editDesc, setEditDesc] = useState(space.description || '')
  const [editType, setEditType] = useState(space.spaceType)

  const saveSettings = async () => {
    setBusy(true)
    setError('')
    try {
      const res = await fetch(apiUrl(`/api/spaces/${space.id}`), {
        method: 'PATCH',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: editName, description: editDesc, spaceType: editType }),
      })
      const j = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(j.error || '保存失败')
      setSettingsOpen(false)
      // 客户端壳下 router.refresh() 无效（页面是客户端取数），走回调重新拉一次
      if (onChanged) onChanged()
      else router.refresh()
    } catch (e: any) {
      setError(e.message || '保存失败')
    } finally {
      setBusy(false)
    }
  }

  const leave = async () => {
    try {
      const res = await fetch(apiUrl(`/api/spaces/${space.id}/leave`), {
        method: 'POST',
        credentials: 'include',
      })
      if (!res.ok) throw new Error('退出失败')
      toast.info('已退出空间')
      router.push('/space')
    } catch (e: any) {
      toast.error(e.message || '退出失败')
    }
  }

  const statItems: Array<[string, number, typeof Images]> = [
    ['旅行', stats.travelCount, MapPin],
    ['相册', stats.albumCount, Images],
    ['回忆', stats.memoryCount, Sparkles],
    ['照片', stats.mediaCount, Camera],
  ]

  // ── 滚动折叠栏（iOS Large Title 心智，配色走空间 token）────────────
  // hero 滚出视口顶部时浮出：返回 + 空间名 + 设置；IO 哨兵，零 scroll 监听。
  const [barCollapsed, setBarCollapsed] = useState(false)
  const heroSentinelRef = useRef<HTMLDivElement>(null)
  useEffect(() => {
    const el = heroSentinelRef.current
    if (!el || typeof IntersectionObserver === 'undefined') return
    const io = new IntersectionObserver(
      ([entry]) => setBarCollapsed(!entry.isIntersecting),
      { rootMargin: '-1px 0px 0px 0px' },
    )
    io.observe(el)
    return () => io.disconnect()
  }, [])

  return (
    <div className="pb-24">
      {/* 哨兵：与 hero 同位置滚出视口顶部 → 折叠 */}
      <div ref={heroSentinelRef} aria-hidden="true" className="h-px w-full" />
      <div className={cn('m-space-collapser', barCollapsed && 'is-collapsed')} aria-hidden={!barCollapsed}>
        <Link
          href="/space"
          aria-label="返回空间列表"
          className="m-pressable flex h-10 w-10 items-center justify-center justify-self-center rounded-full text-[var(--ui-space-accent-text)]"
        >
          <Icon icon={ChevronLeft} size="md" />
        </Link>
        <span className="m-space-collapser-title truncate">{space.name}</span>
        {isOwner ? (
          <button
            type="button"
            onClick={() => { setError(''); setSettingsOpen(true) }}
            aria-label="空间设置"
            className="m-pressable flex h-10 w-10 items-center justify-center justify-self-center rounded-full text-[var(--ui-space-accent-text)]"
          >
            <Icon icon={Settings2} size="md" />
          </button>
        ) : (
          <span aria-hidden="true" />
        )}
      </div>

      {/* ── 头图：空间主题渐变的唯一大面积用武之地（≤ 屏 35%） ── */}
      <div className="space-hero m-safe-top-16 relative px-5 pb-5">
        <div className="flex items-start justify-between">
          <Link
            href="/space"
            className="flex h-11 w-11 items-center justify-center rounded-full bg-[var(--ui-social-surface)]/60 text-[var(--ui-space-accent-text)] backdrop-blur"
            aria-label="返回空间列表"
          >
            <Icon icon={ChevronLeft} size="md" />
          </Link>
          {isOwner && (
            <button
              type="button"
              onClick={() => { setError(''); setSettingsOpen(true) }}
              className="flex h-11 w-11 items-center justify-center rounded-full bg-[var(--ui-social-surface)]/60 text-[var(--ui-space-accent-text)] backdrop-blur"
              aria-label="空间设置"
            >
              <Icon icon={Settings2} size="md" />
            </button>
          )}
        </div>

        <div className="mt-6">
          <span className="inline-flex items-center gap-1.5 rounded-full bg-[var(--ui-social-surface)]/70 px-3 py-1 text-[11px] font-semibold text-[var(--ui-space-accent-text)] backdrop-blur">
            <Icon icon={spaceTypeIconOf(space.spaceType)} size="sm" />
            {spaceTypeLabelOf(space.spaceType)}
            <span className="opacity-70">· 我是{spaceRoleLabelOf(space.myRole)}</span>
          </span>
          <h1 className="mt-2.5 text-[24px] font-bold leading-8 text-[var(--ui-space-accent-text)]">
            {space.name}
          </h1>
          {space.description && (
            <p className="mt-1.5 max-w-md text-[13px] leading-5 text-[var(--ui-space-accent-text)] opacity-85">
              {space.description}
            </p>
          )}

          <div className="mt-4 flex items-center gap-3">
            <SpaceAvatarStack members={space.members || []} max={5} size="md" />
            <span className="text-[13px] text-[var(--ui-space-accent-text)] opacity-85">
              {space.memberCount} 位成员
            </span>
            {isOwner && (
              <Button
                size="sm"
                variant="secondary"
                icon={UserPlus}
                className="ml-auto"
                onClick={() => setInviteOpen(true)}
              >
                邀请
              </Button>
            )}
          </div>
        </div>
      </div>

      <div className="m-gutter pt-4">
        {/* ── 统计四格 ── */}
        <div className="grid grid-cols-4 gap-1.5">
          {statItems.map(([label, value, icon]) => (
            <div
              key={label}
              className="rounded-[var(--m-radius-control)] bg-[var(--ui-social-surface)] py-3 text-center ring-1 ring-[var(--ui-social-line)]"
            >
              <Icon icon={icon} size="sm" className="mx-auto text-[var(--ui-space-accent-strong)]" />
              <div className="mt-1 text-[18px] font-semibold leading-5 tabular-nums text-[var(--ui-social-text)]">
                {value}
              </div>
              <div className="text-[11px] text-[var(--ui-social-faint)]">{label}</div>
            </div>
          ))}
        </div>

        {/* ── ① 一起记录的旅行 ── */}
        <section className="mt-7">
          <SectionHeader
            title="一起记录的旅行"
            action={
              <Link href="/travel" className="inline-flex items-center gap-0.5 text-[13px] text-[var(--ui-space-accent-strong)]">
                全部<Icon icon={ChevronRight} size="sm" />
              </Link>
            }
          />
          {data.travels.length === 0 ? (
            <div className="mt-3 rounded-[var(--m-radius-card)] bg-[var(--ui-social-surface-50)] px-4 py-6 text-center ring-1 ring-[var(--ui-social-line)]">
              <p className="text-[13px] text-[var(--ui-social-muted)]">这个空间还没有旅行记录</p>
              {canEdit && (
                <Link href="/travel/new" className="mt-2 inline-flex items-center gap-1 text-[13px] font-medium text-[var(--ui-space-accent-strong)]">
                  <Icon icon={Plus} size="sm" />
                  记录一次旅行
                </Link>
              )}
            </div>
          ) : (
            <div className="mt-3 space-y-2">
              {data.travels.map((t) => (
                <Link
                  key={t.id}
                  href={`/travel/${t.slug}`}
                  className="m-card-pressable flex items-center gap-3 rounded-[var(--m-radius-card)] bg-[var(--ui-social-surface)] p-3.5 ring-1 ring-[var(--ui-social-line)]"
                >
                  <span className="flex h-10 w-10 flex-none items-center justify-center rounded-[14px] bg-[var(--ui-space-accent-soft)] text-[var(--ui-space-accent-strong)]">
                    <Icon icon={travelTypeIconOf(t.travelType)} size="md" />
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-[15px] font-medium text-[var(--ui-social-text)]">{t.title}</span>
                    <span className="mt-0.5 flex items-center gap-1.5 text-[11px] text-[var(--ui-social-faint)]">
                      {t.startDate && (
                        <>
                          <Icon icon={CalendarDays} size="sm" />
                          {fmtDate(t.startDate)}
                        </>
                      )}
                      <span>{travelTypeLabelOf(t.travelType)}</span>
                      {t.visibility === 'PRIVATE' && <span>· 仅自己可见</span>}
                    </span>
                  </span>
                  <Icon icon={ChevronRight} size="sm" tone="faint" />
                </Link>
              ))}
            </div>
          )}
        </section>

        {/* ── ② 一起经营的相册 ── */}
        <section className="mt-7">
          <SectionHeader
            title="一起经营的相册"
            action={
              <Link href="/album" className="inline-flex items-center gap-0.5 text-[13px] text-[var(--ui-space-accent-strong)]">
                全部<Icon icon={ChevronRight} size="sm" />
              </Link>
            }
          />
          {data.albums.length === 0 ? (
            <div className="mt-3 rounded-[var(--m-radius-card)] bg-[var(--ui-social-surface-50)] px-4 py-6 text-center ring-1 ring-[var(--ui-social-line)]">
              <p className="text-[13px] text-[var(--ui-social-muted)]">还没有共享相册</p>
              <p className="mt-1 text-[11px] text-[var(--ui-social-faint)]">
                照片会随「旅程回忆」一起进到这个空间
              </p>
            </div>
          ) : (
            <div className="mt-3 grid grid-cols-3 gap-2">
              {data.albums.map((a) => (
                <Link
                  key={a.id}
                  href="/album"
                  className="m-pressable overflow-hidden rounded-[var(--m-radius-control)] bg-[var(--ui-social-surface)] ring-1 ring-[var(--ui-social-line)]"
                >
                  <span className="block aspect-square w-full bg-[var(--ui-space-accent-soft)]">
                    {a.coverUrl ? (
                      // eslint-disable-next-line @next/next/no-img-element
                      <img
                        src={a.coverUrl}
                        alt={a.title}
                        loading="lazy"
                        className="m-img-fade h-full w-full object-cover"
                        onLoad={(e) => e.currentTarget.classList.add('is-loaded')}
                      />
                    ) : (
                      <span className="flex h-full w-full items-center justify-center text-[var(--ui-space-accent-strong)] opacity-60">
                        <Icon icon={Images} size="md" />
                      </span>
                    )}
                  </span>
                  <span className="block truncate px-2 py-1.5 text-[11px] text-[var(--ui-social-text)]">
                    {a.title}
                  </span>
                </Link>
              ))}
            </div>
          )}
        </section>

        {/* ── ③ 正在规划下一趟 ── */}
        {data.upcoming.length > 0 && (
          <section className="mt-7">
            <SectionHeader title="正在规划" />
            <div className="mt-3 space-y-2">
              {data.upcoming.map((t) => (
                <Link
                  key={t.id}
                  href={`/travel/${t.slug}`}
                  className="m-card-pressable flex items-center gap-3 rounded-[var(--m-radius-card)] bg-[var(--ui-space-accent-soft)] p-3.5"
                >
                  <Icon icon={MapPin} size="md" className="text-[var(--ui-space-accent-strong)]" />
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-[15px] font-medium text-[var(--ui-space-accent-text)]">
                      {t.title}
                    </span>
                    <span className="text-[11px] text-[var(--ui-space-accent-text)] opacity-80">
                      {t.startDate ? `${fmtDate(t.startDate)} 出发` : '还没定日期'}
                    </span>
                  </span>
                  <Pill tone="neutral" size="sm">计划中</Pill>
                </Link>
              ))}
            </div>
          </section>
        )}

        {/* ── ④ 最近的共同回忆 ── */}
        {data.memories.length > 0 && (
          <section className="mt-7">
            <SectionHeader title="最近的共同回忆" />
            <div className="mt-3 space-y-1.5">
              {data.memories.map((m) => (
                <div
                  key={m.id}
                  className="rounded-[var(--m-radius-control)] bg-[var(--ui-social-surface)] px-3.5 py-3 ring-1 ring-[var(--ui-social-line)]"
                >
                  <p className="line-clamp-2 text-[13px] leading-5 text-[var(--ui-social-text)]">
                    {m.content || '（无文字）'}
                  </p>
                  <p className="mt-1 text-[11px] text-[var(--ui-social-faint)]">
                    {m.createdBy ? `${m.createdBy} · ` : ''}
                    {fmtDate(m.happenedAt)}
                  </p>
                </div>
              ))}
            </div>
          </section>
        )}

        {/* ── ⑤ 空间动态（读 AuditLog，零改库） ── */}
        <section className="mt-7">
          <SectionHeader title="空间动态" />
          {data.activity.length === 0 ? (
            <p className="mt-3 rounded-[var(--m-radius-card)] bg-[var(--ui-social-surface-50)] px-4 py-6 text-center text-[13px] text-[var(--ui-social-muted)] ring-1 ring-[var(--ui-social-line)]">
              还没有动态。有人创建内容或调整成员后，这里会留下痕迹。
            </p>
          ) : (
            <div className="mt-1 rounded-[var(--m-radius-card)] bg-[var(--ui-social-surface)] px-3.5 py-1 ring-1 ring-[var(--ui-social-line)]">
              <SpaceActivityFeed items={data.activity} />
            </div>
          )}
        </section>

        {/* ── 成员与邀请 ── */}
        <section className="mt-7">
          <SectionHeader
            title={`成员（${space.memberCount}）`}
            action={
              isOwner ? (
                <button
                  type="button"
                  onClick={() => setInviteOpen(true)}
                  className="inline-flex items-center gap-0.5 text-[13px] text-[var(--ui-space-accent-strong)]"
                >
                  管理<Icon icon={ChevronRight} size="sm" />
                </button>
              ) : undefined
            }
          />
          <div className="mt-3">
            <SpaceMemberList
              spaceId={space.id}
              myRole={space.myRole}
              members={data.members}
              onChanged={() => (onChanged ? onChanged() : router.refresh())}
            />
          </div>
        </section>

        {space.myRole !== 'OWNER' && (
          <button
            type="button"
            onClick={() => {
              void hapticLight()
              setLeaveOpen(true)
            }}
            className="m-pressable mt-6 flex w-full items-center justify-center gap-1.5 rounded-full py-3 text-[13px] text-[var(--ui-social-faint)] transition-colors hover:text-[var(--danger-soft)]"
          >
            <Icon icon={LogOut} size="sm" />
            退出空间
          </button>
        )}

        {/* 退出确认：iOS ActionSheet（破坏性项红色），替代 window.confirm 的浏览器弹窗 */}
        <ActionSheet
          open={leaveOpen}
          onClose={() => setLeaveOpen(false)}
          title={`退出「${space.name}」后将无法查看空间内的共享内容`}
          options={[
            {
              label: '退出空间',
              destructive: true,
              onClick: () => void leave(),
            },
          ]}
        />

        {error && !settingsOpen && (
          <p className="mt-3 text-center text-[13px] text-[var(--danger-soft)]">{error}</p>
        )}
