          )}

          {error && <p className="text-[13px] text-[var(--danger-soft)]">{error}</p>}

          <Button block size="lg" loading={busy} onClick={() => void saveSettings()}>
            保存
          </Button>
        </div>
      </BottomSheet>
    </div>
  )
}

﻿'use client'

import { useCallback, useEffect, useState } from 'react'
import { Copy, Check, Gift, Ban, Clock, Link2 } from '@/lib/mobile/icon-system'
import { Icon } from '@/components/mobile/Icon'
import { Button } from '@/components/mobile/Button'
import { Loader } from '@/components/mobile/Loader'
import { apiUrl } from '@/lib/api-base'
import { SPACE_ROLE_LABELS, spaceRoleLabelOf } from '@/lib/mobile/space-system'

interface Invite {
  id: number
  role: string
  code?: string
  expiresAt: string
  createdBy: string
  usedAt: string | null
  status: 'PENDING' | 'USED' | 'EXPIRED'
}

function daysLeft(iso: string): number {
  return Math.max(0, Math.ceil((new Date(iso).getTime() - Date.now()) / 86400000))
}

/**
 * 邀请面板（仅 OWNER）。
 *
 * 信息结构取自 `app/admin/spaces/page.tsx`（那一版已经比移动端弹窗完整）：
 * 角色 + 有效期选择、生成后展示码与链接、下方邀请记录带 PENDING/USED/EXPIRED 三态。
 * 视觉重做为移动端 token；并把 admin 版里缺失的「复制邀请链接」保留下来
 * （分享链接比让用户手抄 8 位码更符合移动端习惯）。
 */
export function SpaceInvitePanel({ spaceId }: { spaceId: number }) {
  const [invites, setInvites] = useState<Invite[]>([])
  const [loading, setLoading] = useState(true)
  const [generating, setGenerating] = useState(false)
  const [error, setError] = useState('')
  const [role, setRole] = useState('MEMBER')
  const [days, setDays] = useState(7)
  const [generated, setGenerated] = useState('')
  const [copied, setCopied] = useState<'code' | 'link' | null>(null)

  const load = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch(apiUrl(`/api/spaces/${spaceId}/invites`), { credentials: 'include' })
      const j = await res.json().catch(() => ({}))
      if (res.ok) setInvites(j.invites || [])
    } catch {
      // 静默：邀请记录加载失败不应该挡住整个空间页
    } finally {
      setLoading(false)
    }
  }, [spaceId])

  useEffect(() => {
    void load()
  }, [load])

  const generate = async () => {
    setGenerating(true)
    setError('')
    try {
      const res = await fetch(apiUrl(`/api/spaces/${spaceId}/invites`), {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ role, expiresInDays: days }),
      })
      const j = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(j.error || '生成失败')
      setGenerated(j.code || '')
      await load()
    } catch (e: any) {
      setError(e.message || '生成失败')
    } finally {
      setGenerating(false)
    }
  }

  const revoke = async (inviteId: number) => {
    try {
      await fetch(apiUrl(`/api/spaces/${spaceId}/invites/${inviteId}`), {
        method: 'DELETE',
        credentials: 'include',
      })
      await load()
    } catch {
      setError('撤销失败')
    }
  }

  const copy = async (text: string, kind: 'code' | 'link') => {
    try {
      await navigator.clipboard.writeText(text)
      setCopied(kind)
      window.setTimeout(() => setCopied(null), 1600)
    } catch {
      setError('复制失败，请手动选择文本')
    }
  }

  const inviteLink = (code: string) =>
    typeof window === 'undefined' ? '' : `${window.location.origin}/space?join=${code}`

  const pending = invites.filter((i) => i.status === 'PENDING')

  return (
    <div className="space-y-3">
      {/* 生成：角色 + 有效期 */}
      <div className="flex flex-wrap items-center gap-2">
        <select
          value={role}
          onChange={(e) => setRole(e.target.value)}
          aria-label="邀请角色"
          className="h-11 flex-1 rounded-[var(--m-radius-control)] bg-[var(--ui-social-surface)] px-3 text-[13px] text-[var(--ui-social-text)] outline-none ring-1 ring-[var(--ui-social-line)] focus-visible:ring-[var(--ui-space-accent)]"
        >
          <option value="MEMBER">{SPACE_ROLE_LABELS.MEMBER}（可一起编辑）</option>
          <option value="VIEWER">{SPACE_ROLE_LABELS.VIEWER}（只能查看）</option>
        </select>
        <select
          value={days}
          onChange={(e) => setDays(parseInt(e.target.value, 10))}
          aria-label="有效期"
          className="h-11 rounded-[var(--m-radius-control)] bg-[var(--ui-social-surface)] px-3 text-[13px] text-[var(--ui-social-text)] outline-none ring-1 ring-[var(--ui-social-line)] focus-visible:ring-[var(--ui-space-accent)]"
        >
          <option value={1}>1 天</option>
          <option value={3}>3 天</option>
          <option value={7}>7 天</option>
          <option value={30}>30 天</option>
        </select>
        <Button icon={Gift} loading={generating} onClick={() => void generate()}>
          生成邀请码
        </Button>
      </div>

      {/* 生成结果：码 + 链接 */}
      {generated && (
        <div className="rounded-[var(--m-radius-control)] bg-[var(--ui-space-accent-soft)] p-3.5">
          <p className="text-[13px] text-[var(--ui-space-accent-text)]">
            把下面的邀请码或链接发给对方（{role === 'VIEWER' ? '只能查看' : '可一起编辑'}，
            {days} 天内有效）
          </p>
          <p className="mt-2 select-all text-center font-mono text-[18px] font-bold tracking-[0.28em] text-[var(--ui-space-accent-strong)]">
            {generated}
          </p>
          <div className="mt-3 flex gap-2">
            <Button
              variant="secondary"
              size="sm"
              block
              icon={copied === 'code' ? Check : Copy}
              onClick={() => void copy(generated, 'code')}
            >
              复制邀请码
            </Button>
            <Button
              variant="secondary"
              size="sm"
              block
              icon={copied === 'link' ? Check : Link2}
              onClick={() => void copy(inviteLink(generated), 'link')}
            >
              复制链接
            </Button>
          </div>
        </div>
      )}

      {/* 邀请记录 */}
      <div>
        <p className="mb-2 text-[13px] font-semibold tracking-[0.08em] text-[var(--ui-social-muted)]">
          邀请记录
          {pending.length > 0 && (
            <span className="ml-1.5 tabular-nums text-[var(--ui-social-faint)]">{pending.length} 个待使用</span>
          )}
        </p>
        {loading ? (
          <div className="flex justify-center py-4">
            <Loader variant="ring" />
          </div>
        ) : invites.length === 0 ? (
          <p className="py-3 text-center text-[13px] text-[var(--ui-social-faint)]">还没有邀请记录</p>
        ) : (
          <div className="space-y-1.5">
            {invites.map((inv) => (
              <div
                key={inv.id}
                className="flex items-center justify-between gap-2 rounded-[var(--m-radius-control)] bg-[var(--ui-social-surface-60)] px-3 py-2.5"
              >
                <div className="min-w-0">
                  <p className="text-[13px] text-[var(--ui-social-text)]">
                    {spaceRoleLabelOf(inv.role)}
                    <span className="ml-2 text-[11px] text-[var(--ui-social-faint)]">
                      {inv.status === 'PENDING' && (
                        <span className="inline-flex items-center gap-1">
                          <Icon icon={Clock} size="sm" />
                          {daysLeft(inv.expiresAt)} 天后过期
                        </span>
                      )}
                      {inv.status === 'USED' && '已使用'}
                      {inv.status === 'EXPIRED' && '已过期'}
                    </span>
                  </p>
                  {inv.code && inv.status === 'PENDING' && (
                    <p className="mt-0.5 select-all font-mono text-[13px] tracking-[0.2em] text-[var(--ui-space-accent-strong)]">
                      {inv.code}
                    </p>
                  )}
                </div>
                {inv.status === 'PENDING' && (
                  <button
                    type="button"
                    aria-label="撤销邀请"
                    onClick={() => void revoke(inv.id)}
                    className="flex h-9 w-9 flex-none items-center justify-center rounded-full text-[var(--ui-social-faint)] transition hover:text-[var(--danger-soft)]"
                  >
                    <Icon icon={Ban} size="sm" />
                  </button>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {error && <p className="text-[13px] text-[var(--danger-soft)]">{error}</p>}
    </div>
  )
}

export default SpaceInvitePanel

'use client'

import { useCallback, useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import { Plus, KeyRound, Sparkles } from '@/lib/mobile/icon-system'
import { LargeTitle } from '@/components/mobile/LargeTitle'
import { Button } from '@/components/mobile/Button'
import { BottomSheet } from '@/components/mobile/BottomSheet'
import { EmptyState } from '@/components/mobile/EmptyState'
import { Field, FieldTextarea } from '@/components/mobile/Field'
import { LoaderBlock } from '@/components/mobile/Loader'
import { toast } from '@/lib/mobile/toast-store'
import { apiUrl } from '@/lib/api-base'
import { spaceDetailHref } from '@/lib/routes'
import { SPACE_TYPE_NAME_HINTS, SPACE_ROLE_LABELS } from '@/lib/mobile/space-system'
import { SpaceCard, SpaceSectionHeader, type SpaceCardData } from './SpaceCard'
import { SpaceThemeScope } from './SpaceThemeScope'
import { SpaceTypePicker } from './SpaceTypePicker'

/**
 * 我的空间（列表 / 切换器 / 创建 / 加入）。
 *
 * 架构决定（方案 §9-1 采用「B」）：**不引入全局「当前空间」**。
 * 本页只做「进入某个空间的视角聚合」，`/travel`、`/album` 仍保持「我的全部」语义 ——
 * 否则「我的旅行」的含义会随进入哪个空间而漂移，回归风险远大于收益。
 *
 * 主题作用域：页面本身保持中性（品牌色），**每张卡片自带自己的 data-space**。
 * 这是「五套主题不像五个 App」的关键 —— 列表里同时出现五种配色仍然是一个 App，
 * 因为中性层、间距、圆角、字号完全一致，只有卡片内部的 7 个空间令牌不同。
 */
export default function SpaceListClient({ initialSpaces }: { initialSpaces?: SpaceCardData[] }) {
  const router = useRouter()
  const [spaces, setSpaces] = useState<SpaceCardData[]>(initialSpaces || [])
  const [loading, setLoading] = useState(!initialSpaces)
  const [error, setError] = useState('')

  // 创建
  const [createOpen, setCreateOpen] = useState(false)
  const [name, setName] = useState('')
  const [description, setDescription] = useState('')
  const [spaceType, setSpaceType] = useState('COUPLE')
  const [submitting, setSubmitting] = useState(false)

  // 加入
  const [joinOpen, setJoinOpen] = useState(false)
  const [joinCode, setJoinCode] = useState('')
  const [joining, setJoining] = useState(false)

  const load = useCallback(async () => {
    setLoading(true)
    setError('')
    try {
      const res = await fetch(apiUrl('/api/spaces'), { credentials: 'include' })
      const j = await res.json()
      if (res.ok) setSpaces(j.spaces || [])
      else setError(j.error || '加载空间失败')
    } catch {
      setError('网络错误，请重试')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    if (!initialSpaces) void load()
  }, [initialSpaces, load])

  // 邀请链接直达：/space?join=CODE（邀请面板复制的就是这个地址）
  useEffect(() => {
    const code = new URLSearchParams(window.location.search).get('join')
    if (code) {
      setJoinCode(code.toUpperCase())
      setJoinOpen(true)
    }
  }, [])

  const showToast = (text: string) => {
    toast.success(text)
  }

  const create = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!name.trim()) return
    setSubmitting(true)
    setError('')
    try {
      // slug 不再由前端生成：中文名派生不出 ASCII slug 时由服务端回退随机值
      const res = await fetch(apiUrl('/api/spaces'), {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: name.trim(), description: description.trim() || undefined, spaceType }),
      })
      const j = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(j.error || '创建失败')
      setName('')
      setDescription('')
      setCreateOpen(false)
      showToast('空间已创建，去邀请伙伴一起记录吧')
      await load()
      if (j.slug) router.push(spaceDetailHref(j.slug))
    } catch (err: any) {
      setError(err.message || '创建失败')
    } finally {
      setSubmitting(false)
    }
  }

  const join = async (e: React.FormEvent) => {
    e.preventDefault()
    const code = joinCode.trim()
    if (!code) return
    setJoining(true)
    setError('')
    try {
      const res = await fetch(apiUrl('/api/spaces/join'), {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code }),
      })
      const j = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(j.error || '加入失败')
      setJoinCode('')
      setJoinOpen(false)
      showToast(`已加入「${j.spaceName || '空间'}」`)
      await load()
    } catch (err: any) {
      setError(err.message || '加入失败')
    } finally {
      setJoining(false)
    }
  }

  // 分组：有别人的空间 = 共享；只有自己的 = 个人（真库里 34 个空间全是自动创建的单人 SOLO，
  // 不分组会让用户看到一屏同名卡片）
  const shared = spaces.filter((s) => (s.memberCount ?? 0) > 1)
  const personal = spaces.filter((s) => (s.memberCount ?? 0) <= 1)

  return (
    <div className="m-gutter pb-24 pt-2">
      <LargeTitle title="我的空间" back="/me" subtitle="一起记录，各自上色" />

      {/* 主操作区：一屏只有一个实心 CTA（创建），加入走次级按钮 */}
      <div className="mt-4 flex items-center gap-2">
        <Button icon={Plus} block onClick={() => { setError(''); setCreateOpen(true) }}>
          创建空间
        </Button>
        <Button
          variant="secondary"
          icon={KeyRound}
          onClick={() => { setError(''); setJoinOpen(true) }}
          aria-label="输入邀请码加入空间"
        >
          邀请码加入
        </Button>
      </div>

      {error && !createOpen && !joinOpen && (
        <p className="mt-3 text-center text-[13px] text-[var(--danger-soft)]">{error}</p>
      )}

      {loading ? (
        <LoaderBlock label="正在加载空间…" />
      ) : spaces.length === 0 ? (
        <EmptyState
          className="mt-10"
          icon={Sparkles}
          title="还没有空间"
          description="创建一个空间，把旅行、相册和回忆放进去，邀请 TA 一起经营。"
          action={
            <Button icon={Plus} onClick={() => setCreateOpen(true)}>
              创建第一个空间
            </Button>
          }
        />
      ) : (
        <>
          {shared.length > 0 && (
            <section className="mt-6">
              <SpaceSectionHeader title="共享空间" count={shared.length} />
              <div className="mt-3 space-y-3">
                {shared.map((s) => (
                  <SpaceThemeScope key={s.id} type={s.spaceType}>
                    <SpaceCard space={s} />
                  </SpaceThemeScope>
                ))}
              </div>
            </section>
          )}

          {personal.length > 0 && (
            <section className="mt-6">
              <SpaceSectionHeader title="只有我" count={personal.length} />
              <div className="mt-3 space-y-3">
                {personal.map((s) => (
                  <SpaceThemeScope key={s.id} type={s.spaceType}>
                    <SpaceCard space={{ ...s, isDefault: !s.description || s.description.includes('自动创建') }} />
                  </SpaceThemeScope>
                ))}
              </div>
            </section>
          )}
        </>
      )}

      {/* ── 创建空间 ── */}
      <BottomSheet open={createOpen} onClose={() => setCreateOpen(false)} title="创建空间">
        <form onSubmit={create} className="space-y-4">
          <div>
            <p className="mb-2 text-[13px] font-medium text-[var(--m-text)]">这是什么空间？</p>
            <SpaceTypePicker
              value={spaceType}
              onChange={setSpaceType}
              disabled={submitting}
            />
            <p className="mt-2 text-[13px] text-[var(--m-muted)]">
              选好类型后，这个空间会用它自己的配色 —— 五种都清新淡雅，明暗两套都做了对比度校核。
            </p>
          </div>

          <Field
            label="空间名称"
            name="space-name"
            required
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder={SPACE_TYPE_NAME_HINTS[spaceType] || '给这个空间起个名字'}
            maxLength={200}
          />

          <FieldTextarea
            label="简介"
            name="space-desc"
            hint="可选，一句话说明这个空间用来记录什么"
            rows={2}
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="例如：2026 年全家的出行记录"
            maxLength={500}
          />

          {error && <p className="text-[13px] text-[var(--danger-soft)]">{error}</p>}

          <Button type="submit" block size="lg" loading={submitting} disabled={!name.trim()}>
            创建空间
          </Button>
        </form>
      </BottomSheet>

      {/* ── 邀请码加入 ── */}
      <BottomSheet open={joinOpen} onClose={() => setJoinOpen(false)} title="输入邀请码加入">
        <form onSubmit={join} className="space-y-4">
          <Field
            label="邀请码"
            name="join-code"
            required
            value={joinCode}
            onChange={(e) => setJoinCode(e.target.value.toUpperCase())}
            placeholder="形如 7XK2-M9PQ"
            className="text-center"
            hint={`${SPACE_ROLE_LABELS.MEMBER}可一起编辑旅行与相册`}
          />
          {error && <p className="text-[13px] text-[var(--danger-soft)]">{error}</p>}
          <Button type="submit" block size="lg" loading={joining} disabled={!joinCode.trim()}>
            加入空间
          </Button>
        </form>
      </BottomSheet>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { UserMinus, ShieldCheck } from '@/lib/mobile/icon-system'
import { Icon } from '@/components/mobile/Icon'
import { apiUrl } from '@/lib/api-base'
import { SPACE_ROLE_HINTS, SPACE_ROLE_LABELS, spaceRoleLabelOf } from '@/lib/mobile/space-system'
import { SpaceAvatar, type SpaceMemberPreview } from './SpaceAvatarStack'

export interface SpaceMemberRow extends SpaceMemberPreview {
  id: number
  status: string
  joinedAt: string
}

const ROLE_ORDER = ['OWNER', 'MEMBER', 'VIEWER'] as const

function joinedText(iso: string): string {
  const d = new Date(iso)
  if (isNaN(d.getTime())) return ''
  return `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()} 加入`
}

/**
 * 成员列表 + 角色调整 + 移除。
 *
 * 信息结构借鉴 supabase/supabase `apps/studio/components/interfaces/Organization/
 * TeamSettings/`（Apache-2.0）：成员行 = 头像 + 名字 + 角色 + 行内操作。
 * 视觉全部重做为本项目的移动端 token（项目规范禁用裸 hex 与冷色）。
 *
 * 权限：只有 OWNER 能调整角色 / 移除成员；「最后一个主人」由服务端兜底拒否
 * （`spaceService.updateMemberRole`），前端只做显隐，不做安全假设。
 */
export function SpaceMemberList({
  spaceId,
  myRole,
  members,
  onChanged,
}: {
  spaceId: number
  myRole: string
  members: SpaceMemberRow[]
  onChanged: () => void
}) {
  const [busy, setBusy] = useState<string | null>(null)
  const [error, setError] = useState('')
  const isOwner = myRole === 'OWNER'

  const changeRole = async (username: string, role: string) => {
    setBusy(username)
    setError('')
    try {
      const res = await fetch(apiUrl(`/api/spaces/${spaceId}/members`), {
        method: 'PATCH',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, role }),
      })
      const j = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(j.error || '调整失败')
      onChanged()
    } catch (e: any) {
      setError(e.message || '调整失败')
    } finally {
      setBusy(null)
    }
  }

  const remove = async (username: string) => {
    if (!window.confirm(`确定把「${username}」移出空间吗？TA 将立即失去空间内所有内容的访问权。`)) return
    setBusy(username)
    setError('')
    try {
      const res = await fetch(apiUrl(`/api/spaces/${spaceId}/members`), {
        method: 'DELETE',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username }),
      })
      const j = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(j.error || '移除失败')
      onChanged()
    } catch (e: any) {
      setError(e.message || '移除失败')
    } finally {
      setBusy(null)
    }
  }

  if (members.length === 0) {
    return <p className="py-4 text-center text-[13px] text-[var(--ui-social-faint)]">还没有成员</p>
  }

  return (
    <div className="space-y-1.5">
      {members.map((m) => {
        const canManage = isOwner && m.role !== 'OWNER'
        return (
          <div
            key={m.id}
            className="rounded-[var(--m-radius-control)] bg-[var(--ui-social-surface-60)] px-3 py-2.5"
          >
            <div className="flex items-center gap-2.5">
              <SpaceAvatar member={m} size="md" />
              <div className="min-w-0 flex-1">
                <p className="truncate text-[15px] font-medium text-[var(--ui-social-text)]">
                  {m.nickname || m.username}
                </p>
                <p className="truncate text-[11px] text-[var(--ui-social-faint)]">
                  {m.nickname ? `${m.username} · ` : ''}
                  {joinedText(m.joinedAt)}
                </p>
              </div>

              {canManage ? (
                <select
                  value={m.role}
                  disabled={busy === m.username}
                  onChange={(e) => void changeRole(m.username, e.target.value)}
                  aria-label={`调整 ${m.username} 的角色`}
                  className="h-9 rounded-[10px] bg-[var(--ui-social-surface)] px-2 text-[13px] text-[var(--ui-social-text)] outline-none ring-1 ring-[var(--ui-social-line)] focus-visible:ring-[var(--ui-space-accent)] disabled:opacity-50"
                >
                  {ROLE_ORDER.map((r) => (
                    <option key={r} value={r}>
                      {SPACE_ROLE_LABELS[r]}
                    </option>
                  ))}
                </select>
              ) : (
                <span className="flex-none rounded-full bg-[var(--ui-social-surface2)] px-2.5 py-1 text-[11px] font-semibold text-[var(--ui-social-muted)]">
                  {spaceRoleLabelOf(m.role)}
                </span>
              )}

              {canManage && (
                <button
                  type="button"
                  aria-label={`移除 ${m.username}`}
                  disabled={busy === m.username}
                  onClick={() => void remove(m.username)}
                  className="flex h-9 w-9 flex-none items-center justify-center rounded-full text-[var(--ui-social-faint)] transition hover:text-[var(--danger-soft)] disabled:opacity-50"
                >
                  <Icon icon={UserMinus} size="sm" />
                </button>
              )}
            </div>
          </div>
        )
      })}

      {isOwner && (
        <div className="rounded-[var(--m-radius-control)] bg-[var(--ui-social-surface-50)] px-3 py-2.5">
          <p className="flex items-center gap-1.5 text-[11px] font-semibold text-[var(--ui-social-muted)]">
            <Icon icon={ShieldCheck} size="sm" className="shrink-0" />
            角色区别
          </p>
          <dl className="mt-1.5 space-y-1">
            {ROLE_ORDER.map((r) => (
              <div key={r} className="flex gap-2 text-[11px] leading-4">
                <dt className="w-8 flex-none font-medium text-[var(--ui-social-muted)]">
                  {SPACE_ROLE_LABELS[r]}
                </dt>
                <dd className="text-[var(--ui-social-faint)]">{SPACE_ROLE_HINTS[r]}</dd>
              </div>
            ))}
          </dl>
          <p className="mt-1.5 text-[11px] leading-4 text-[var(--ui-social-faint)]">
            空间至少保留一位主人，最后一位主人不能被降级或移除。
          </p>
        </div>
      )}

      {error && <p className="pt-1 text-[13px] text-[var(--danger-soft)]">{error}</p>}
    </div>
  )
}

export default SpaceMemberList

'use client'

import { useEffect, useState } from 'react'
import { Plus, Loader2, X, Check } from 'lucide-react'
import { Icon } from '@/components/mobile/Icon'
import { apiUrl } from '@/lib/api-base'

interface CandidatePhoto {
  id: number
  url: string
  width: number | null
  height: number | null
  primaryMemoryId: number | null
}

/**
 * v3.1 M2-A2：给回忆关联照片（从用户相册媒体中选择，支持多选；一张照片可关联多个回忆）。
 */
export default function MemoryPhotoPicker({
  memoryId,
  onDone,
}: {
  memoryId: number
  onDone?: () => void
}) {
  const [open, setOpen] = useState(false)
  const [photos, setPhotos] = useState<CandidatePhoto[]>([])
  const [loading, setLoading] = useState(false)
  const [selected, setSelected] = useState<Set<number>>(new Set())
  const [saving, setSaving] = useState(false)
  const [message, setMessage] = useState<{ type: 'ok' | 'err'; text: string } | null>(null)

  const load = async () => {
    setLoading(true)
    try {
      const res = await fetch(apiUrl('/api/memories/media-candidates?limit=50'), { credentials: 'include' })
      const j = await res.json()
      setPhotos(j.media || [])
    } catch {
      setMessage({ type: 'err', text: '照片加载失败' })
    } finally {
      setLoading(false)
    }
  }

  const openPicker = () => {
    setOpen(true)
    setSelected(new Set())
    setMessage(null)
    load()
  }

  const toggle = (id: number) => {
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const save = async () => {
    if (selected.size === 0) return
    setSaving(true)
    setMessage(null)
    try {
      const res = await fetch(apiUrl(`/api/memories/${memoryId}/media`), {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mediaIds: Array.from(selected) }),
      })
      const j = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(j.error || '关联失败')
      setMessage({ type: 'ok', text: `已关联 ${selected.size} 张照片` })
      setTimeout(() => {
        setOpen(false)
        onDone?.()
      }, 900)
    } catch (e: any) {
      setMessage({ type: 'err', text: e.message || '关联失败' })
    } finally {
      setSaving(false)
    }
  }

  return (
    <>
      <button
        type="button"
        onClick={openPicker}
        className="mt-1.5 inline-flex items-center gap-1 rounded-full bg-travel-bloom/30 px-2.5 py-1 text-xs text-travel-ink/80 transition hover:bg-travel-bloom/50"
      >
        <Icon icon={Plus} size="sm" />
        关联照片
      </button>

      {open && (
        <div className="fixed inset-0 z-[90] flex items-center justify-center bg-black/60 p-4" onClick={() => setOpen(false)}>
          <div className="flex max-h-[80vh] w-full max-w-md flex-col rounded-2xl bg-white p-4 shadow-xl" onClick={(e) => e.stopPropagation()}>
            <div className="mb-3 flex items-center justify-between">
              <h3 className="font-semibold text-travel-ink">选择照片关联到回忆</h3>
              <button type="button" onClick={() => setOpen(false)} className="rounded-full p-1 text-travel-ink/50 hover:bg-travel-sakura/40" aria-label="关闭">
                <Icon icon={X} size="sm" />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto">
              {loading ? (
                <div className="flex justify-center py-10 text-travel-ink/50"><Icon icon={Loader2} size="md" className="animate-spin" /></div>
              ) : photos.length === 0 ? (
                <p className="py-10 text-center text-sm text-travel-ink/50">还没有可关联的照片，先去相册上传吧</p>
              ) : (
                <div className="grid grid-cols-4 gap-1.5">
                  {photos.map((p) => (
                    <button
                      key={p.id}
                      type="button"
                      onClick={() => toggle(p.id)}
                      className={`relative aspect-square overflow-hidden rounded-lg transition ${selected.has(p.id) ? 'ring-2 ring-travel-bloom' : 'ring-1 ring-travel-line'}`}
                    >
                      {/* eslint-disable-next-line @next/next/no-img-element */}
                      <img src={p.url} alt="" width={400} height={400} className="h-full w-full object-cover" loading="lazy" decoding="async" />
                      {selected.has(p.id) && (
                        <span className="absolute inset-0 flex items-center justify-center bg-travel-bloom/40">
                          <Icon icon={Check} size="md" tone="inverse" />
                        </span>
                      )}
                    </button>
                  ))}
                </div>
              )}
            </div>

            {message && <p className={`mt-2 text-center text-xs ${message.type === 'ok' ? 'text-emerald-600' : 'text-red-500'}`}>{message.text}</p>}

            <div className="mt-3 flex items-center justify-between">
              <span className="text-xs text-travel-ink/50">已选 {selected.size} 张</span>
              <button
                type="button"
                onClick={save}
                disabled={saving || selected.size === 0}
                className="rounded-full bg-travel-bloom px-4 py-2 text-sm font-medium text-white transition hover:bg-[#DDA5B2] disabled:opacity-50"
              >
                {saving ? '关联中...' : '关联照片'}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

'use client'

import { useState } from 'react'
import { Loader2, Plus, Trash2 } from 'lucide-react'
import { BottomSheet } from '@/components/mobile/BottomSheet'
import { Button } from '@/components/mobile/Button'
import { Field, FieldTextarea } from '@/components/mobile/Field'
import { TimeField } from '@/components/mobile/TimePicker'
import { Icon } from '@/components/mobile/Icon'
import { ITINERARY_TYPES, itineraryIconOf, itineraryLabelOf } from '@/lib/mobile/icon-system'
import { apiUrl } from '@/lib/api-base'
import { toast } from '@/lib/mobile/toast-store'
import { formatTime, dayFullLabel } from './format'
import type { TimelineDay, TimelineItineraryItem } from './types'

/**
 * 「添加 / 编辑行程」抽屉。
 *
 * 对齐参考产品的两件事：
 *  1. **先明确加到哪一天**（顶部「添加到 DAY 03 · 10.01 周四」，可就地切换）——
 *     参考产品抽屉顶部就是这个选择器；否则用户在"全部天"视图里加东西会不知道落哪。
 *  2. **类型先选**（景点/餐厅/住宿/交通/活动/其他 六宫格），而不是先敲标题。
 *
 * 同时补上此前缺失的**编辑与删除**（前台原先只有 POST，加错了删不掉也改不了）。
 */
export default function AddItinerarySheet({
  open,
  travelId,
  days,
  defaultDayId,
  editing,
  onClose,
  onDone,
}: {
  open: boolean
  travelId: number
  days: TimelineDay[]
  defaultDayId?: number | null
  /** 传入即为编辑模式（此时不再允许换天：换天等于换归属，超出本次范围） */
  editing?: { dayId: number; item: TimelineItineraryItem } | null
  onClose: () => void
  onDone: () => void
}) {
  const [dayId, setDayId] = useState<number | null>(editing?.dayId ?? defaultDayId ?? days[0]?.id ?? null)
  const [title, setTitle] = useState(editing?.item.title ?? '')
  const [type, setType] = useState(editing?.item.type ?? 'SPOT')
  const [startTime, setStartTime] = useState(formatTime(editing?.item.startTime) || '')
  const [endTime, setEndTime] = useState(formatTime(editing?.item.endTime) || '')
  const [notes, setNotes] = useState(editing?.item.notes ?? '')
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')

  const isEdit = Boolean(editing)
  const dayIndex = days.findIndex((d) => d.id === dayId)

  const submit = async () => {
    if (!title.trim()) {
      setError('写个名字吧，比如「喀纳斯湖」')
      return
    }
    if (dayId == null) {
      setError('请选择加到哪一天')
      return
    }
    setSaving(true)
    setError('')
    try {
      const payload = {
        title: title.trim(),
        type,
        startTime: startTime ? `${startTime}:00` : null,
        endTime: endTime ? `${endTime}:00` : null,
        notes: notes.trim() || null,
      }
      const res = await fetch(
        isEdit
          ? apiUrl(`/api/travels/${travelId}/itinerary/${editing!.item.id}`)
          : apiUrl(`/api/travels/${travelId}/itinerary`),
        {
          method: isEdit ? 'PATCH' : 'POST',
          credentials: 'include',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(isEdit ? payload : { ...payload, dayId }),
        },
      )
      const j = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(j.error || '保存失败')
      toast.success(isEdit ? '已保存' : '已添加')
      onDone()
      onClose()
    } catch (e) {
      setError(e instanceof Error ? e.message : '保存失败')
    } finally {
      setSaving(false)
    }
  }

  const remove = async () => {
    if (!isEdit) return
    setSaving(true)
    setError('')
    try {
      const res = await fetch(apiUrl(`/api/travels/${travelId}/itinerary/${editing!.item.id}`), {
        method: 'DELETE',
        credentials: 'include',
      })
      const j = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(j.error || '删除失败')
      toast.success('已删除')
      onDone()
      onClose()
    } catch (e) {
      setError(e instanceof Error ? e.message : '删除失败')
    } finally {
      setSaving(false)
    }
  }

  return (
    <BottomSheet open={open} onClose={onClose} title={isEdit ? '编辑行程' : '添加行程'}>
      <div className="space-y-4">
        {/* 加到哪天（编辑时锁定） */}
        {!isEdit && days.length > 1 && (
          <div>
            <p className="m-field-label">添加到</p>
            <div className="-mx-1 mt-1.5 flex gap-2 overflow-x-auto px-1 pb-1">
              {days.map((d, i) => {
                const active = d.id === dayId
                return (
                  <button
                    key={d.id}
                    type="button"
                    aria-pressed={active}
                    onClick={() => setDayId(d.id)}
                    className={
                      'm-chip shrink-0 ' + (active ? 'm-chip-active' : '')
                    }
                  >
                    {dayFullLabel(d.date, i)}
                  </button>
                )
              })}
            </div>
          </div>
        )}
        {isEdit && dayIndex >= 0 && (
          <p className="m-caption text-[var(--m-muted)]">{dayFullLabel(days[dayIndex].date, dayIndex)}</p>
        )}

        <Field
          label="去哪 / 做了什么"
          placeholder="例如 喀纳斯湖"
          value={title}
          maxLength={120}
          onChange={(e) => setTitle(e.target.value)}
        />

        {/* 类型先选：六宫格，图标 + 名称（对齐参考产品的"添加"入口分组） */}
        <div>
          <p className="m-field-label">类型</p>
          <div className="mt-2 grid grid-cols-3 gap-2">
            {ITINERARY_TYPES.map((t) => {
              const active = type === t
              return (
                <button
                  key={t}
                  type="button"
                  aria-pressed={active}
                  onClick={() => setType(t)}
                  className={
                    'flex min-h-[60px] flex-col items-center justify-center gap-1 rounded-2xl border transition active:scale-[0.98] ' +
                    (active
                      ? 'border-[var(--m-accent)] bg-[var(--m-accent-soft)] text-[var(--m-accent-strong)]'
                      : 'border-[var(--m-line)] text-[var(--m-text)]')
                  }
                >
                  <Icon icon={itineraryIconOf(t)} size="md" />
                  <span className="text-[12px] font-medium">{itineraryLabelOf(t)}</span>
                </button>
              )
            })}
          </div>
        </div>

        {/*
          时间改用自绘滚轮（TimeField）。
          原生 type="time" 在 Android 上会拉起系统**圆盘钟表**，与全站设计语言割裂，
          且各 ROM 造型不一致（真机反馈「这个圆形钟表挺丑的」）。
        */}
        <div className="flex gap-3">
          <TimeField
            className="flex-1"
            label="开始"
            value={startTime}
            onChange={setStartTime}
          />
          <TimeField
            className="flex-1"
            label="结束"
            value={endTime}
            onChange={setEndTime}
          />
        </div>

        <FieldTextarea
          label="备注"
          rows={2}
          placeholder="门票、路线、感受……（可选）"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
        />

        {error && (
          <p role="alert" className="text-[13px] text-[var(--m-danger)]">
            {error}
          </p>
        )}

        <Button block size="lg" loading={saving} icon={isEdit ? undefined : Plus} onClick={submit}>
          {isEdit ? '保存' : '添加行程'}
        </Button>

        {isEdit && (
          <Button block variant="danger" icon={Trash2} disabled={saving} onClick={remove}>
            删除这条行程
          </Button>
        )}
      </div>
    </BottomSheet>
  )
}

'use client'

import type { InputHTMLAttributes, TextareaHTMLAttributes, ReactNode } from 'react'
import { cn } from '@/lib/utils'

const inputBase =
  'w-full rounded-xl border border-semantic-line bg-semantic-surface px-4 py-2.5 text-sm text-semantic-text placeholder-semantic-faint shadow-sm transition-all focus-visible:border-transparent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-semantic-accentSoft/50'

interface InputFieldProps {
  label?: string
  hint?: string
  required?: boolean
}

/** 统一输入框（支持 label / hint / required，满足无障碍：label 与控件关联） */
export function Input({
  label,
  hint,
  required,
  id,
  className,
  ...props
}: InputHTMLAttributes<HTMLInputElement> & InputFieldProps) {
  const inputId = id || props.name
  return (
    <div className={className}>
      {label && (
        <label htmlFor={inputId} className="mb-1.5 block text-sm font-medium text-semantic-text">
          {label}
          {required && <span className="ml-0.5 text-travel-danger">*</span>}
        </label>
      )}
      <input id={inputId} className={cn(inputBase)} {...props} />
      {hint && <p className="mt-1 text-xs text-semantic-faint">{hint}</p>}
    </div>
  )
}

/** 统一文本域 */
export function Textarea({
  label,
  hint,
  required,
  id,
  className,
  ...props
}: TextareaHTMLAttributes<HTMLTextAreaElement> & InputFieldProps) {
  const inputId = id || props.name
  return (
    <div className={className}>
      {label && (
        <label htmlFor={inputId} className="mb-1.5 block text-sm font-medium text-semantic-text">
          {label}
          {required && <span className="ml-0.5 text-travel-danger">*</span>}
        </label>
      )}
      <textarea id={inputId} className={cn(inputBase, 'resize-none py-3')} {...props} />
      {hint && <p className="mt-1 text-xs text-semantic-faint">{hint}</p>}
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback, useRef } from 'react'

interface UseFullScreenScrollOptions {
  totalPages: number
  /** 切换锁定期（ms），防止滚动过快 */
  lockDuration?: number
  targetRef?: React.RefObject<HTMLElement | null>
}

export function useFullScreenScroll({
  totalPages,
  lockDuration = 700,
  targetRef,
}: UseFullScreenScrollOptions) {
  const [currentPage, setCurrentPage] = useState(0)
  const lockRef = useRef(false)
  const startYRef = useRef(0)
  const currentPageRef = useRef(0)
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    currentPageRef.current = currentPage
  }, [currentPage])

  const goToPage = useCallback(
    (page: number) => {
      if (lockRef.current) return
      const target = Math.max(0, Math.min(totalPages - 1, page))
      if (target === currentPageRef.current) return

      lockRef.current = true
      setCurrentPage(target)

      if (timerRef.current) clearTimeout(timerRef.current)
      timerRef.current = setTimeout(() => {
        lockRef.current = false
      }, lockDuration)
    },
    [totalPages, lockDuration],
  )

  const next = useCallback(() => goToPage(currentPageRef.current + 1), [goToPage])
  const prev = useCallback(() => goToPage(currentPageRef.current - 1), [goToPage])

  useEffect(() => {
    const target = targetRef?.current
    if (!target) return

    const wheelHandler = (e: WheelEvent) => {
      e.preventDefault()
      if (lockRef.current) return

      const delta = Math.abs(e.deltaY)
      if (delta < 5) return

      if (e.deltaY > 0) {
        next()
      } else {
        prev()
      }
    }

    const touchStartHandler = (e: TouchEvent) => {
      startYRef.current = e.touches[0].clientY
    }

    const touchEndHandler = (e: TouchEvent) => {
      if (lockRef.current) return
      const endY = e.changedTouches[0].clientY
      const diff = startYRef.current - endY
      if (Math.abs(diff) > 30) {
        if (diff > 0) next()
        else prev()
      }
    }

    const keyDownHandler = (e: KeyboardEvent) => {
      if (lockRef.current) return
      if (e.key === 'ArrowDown' || e.key === 'PageDown') {
        e.preventDefault()
        next()
      } else if (e.key === 'ArrowUp' || e.key === 'PageUp') {
        e.preventDefault()
        prev()
      } else if (e.key === 'Home') {
        e.preventDefault()
        goToPage(0)
      } else if (e.key === 'End') {
        e.preventDefault()
        goToPage(totalPages - 1)
      }
    }

    target.addEventListener('wheel', wheelHandler, { passive: false })
    target.addEventListener('touchstart', touchStartHandler, { passive: true })
    target.addEventListener('touchend', touchEndHandler, { passive: true })
    window.addEventListener('keydown', keyDownHandler)

    return () => {
      target.removeEventListener('wheel', wheelHandler)
      target.removeEventListener('touchstart', touchStartHandler)
      target.removeEventListener('touchend', touchEndHandler)
      window.removeEventListener('keydown', keyDownHandler)
      if (timerRef.current) clearTimeout(timerRef.current)
    }
  }, [targetRef?.current, next, prev, goToPage, totalPages])

  // 清理定时器（组件卸载时）
  useEffect(() => () => {
    if (timerRef.current) clearTimeout(timerRef.current)
  }, [])

  return {
    currentPage,
    goToPage,
    next,
    prev,
  }
}

import { NextResponse } from 'next/server'

export interface ApiResponse<T = unknown> {
  success: boolean
  data?: T
  error?: string
  /** 稳定的错误码（前端据此分支，不用匹配中文文案）；成功响应不带 */
  code?: string
  /** 请求追踪 ID（与服务端日志一致，便于用户报错时定位） */
  requestId?: string
  message?: string
}

export function ok<T>(data?: T, message?: string): NextResponse {
  return NextResponse.json({
    success: true,
    data,
    message,
  } as ApiResponse<T>)
}

export function fail(error: string, status: number = 400, code?: string): NextResponse {
  return NextResponse.json({
    success: false,
    error,
    ...(code ? { code } : {}),
  } as ApiResponse, { status })
}

export function notFound(message: string = '资源不存在'): NextResponse {
  return fail(message, 404, 'NOT_FOUND')
}

export function unauthorized(message: string = '未授权'): NextResponse {
  return fail(message, 401, 'UNAUTHORIZED')
}

export function forbidden(message: string = '权限不足'): NextResponse {
  return fail(message, 403, 'FORBIDDEN')
}

export function serverError(message: string = '服务器内部错误'): NextResponse {
  return fail(message, 500, 'INTERNAL_ERROR')
}

/**
 * 业务异常（P1-17）：路由里 throw，由 withAuth/errorResponse 统一转成
 * `{ success:false, error, code, requestId }`。
 * code 用大写下划线常量（如 VALIDATION_ERROR / NOT_FOUND），前端按 code 分支。
 */
export class ApiError extends Error {
  readonly code: string
  readonly status: number

  constructor(code: string, message: string, status: number = 400) {
    super(message)
    this.name = 'ApiError'
    this.code = code
    this.status = status
  }
}

/**
 * 统一错误响应（P1-17）：
 * - ApiError → 原样使用其 message/code/status（message 是面向前端的中文提示）；
 * - 其它异常 → 500 + 通用文案（**不把 error.message 泄漏给客户端**，原文只进服务端日志）；
 * - requestId 始终回传，便于把用户截图和服务端日志对上。
 */
export function errorResponse(err: unknown, requestId?: string): NextResponse {
  let status = 500
  let message = '服务器内部错误'
  let code = 'INTERNAL_ERROR'

  if (err instanceof ApiError) {
    status = err.status
    message = err.message
    code = err.code
  } else {
    // 非预期异常：记录完整栈（服务端），对外只给通用文案
    console.error(`[api] 未处理异常${requestId ? ` requestId=${requestId}` : ''}:`, err)
  }

  const body: ApiResponse = { success: false, error: message, code }
  if (requestId) body.requestId = requestId
  return NextResponse.json(body, { status })
}

export interface PaginationParams {
  page?: number
  pageSize?: number
}

export interface PaginatedResponse<T> {
  success: boolean
  data: T[]
  total: number
  page: number
  pageSize: number
  hasMore: boolean
}

export function paginatedResponse<T>(
  data: T[],
  total: number,
  page: number,
  pageSize: number
): NextResponse {
  return NextResponse.json({
    success: true,
    data,
    total,
    page,
    pageSize,
    hasMore: page * pageSize < total,
  } as PaginatedResponse<T>)
}

export function getPaginationFromSearchParams(
  searchParams: URLSearchParams,
  defaultPageSize: number = 20
): { page: number; pageSize: number } {
  const page = Math.max(1, parseInt(searchParams.get('page') || '1'))
  const pageSize = Math.min(100, Math.max(1, parseInt(searchParams.get('pageSize') || String(defaultPageSize))))
  return { page, pageSize }
}

/** 旧版宽松合并工具：保留以兼容存量路由（新路由请用 zod parseBody） */
export function parseBody<T extends Record<string, any>>(body: any, defaults?: Partial<T>): T {
  const result = { ...(defaults || {}) } as T
  if (!body || typeof body !== 'object') return result
  for (const key of Object.keys(body)) {
    if (body[key] !== undefined) {
      ;(result as any)[key] = body[key]
    }
  }
  return result
}

/**
 * API 路由统一封装（P1-17）。
 *
 * 目标：把「鉴权 + 401/503 + 请求 ID + 异常转统一错误格式」收口到一处，
 * 让写路由只需要关心业务；body 校验统一走 zod（parseBody）。
 *
 * 用法：
 *   export const POST = withAuth(async (request, { userId, username, requestId }) => {
 *     const body = await parseBody(request, CreateSchema)
 *     ...
 *     return ok(...) / NextResponse.json(...)
 *   })
 *
 * 兼容性：成功响应完全不变；失败统一为 { success:false, error, code, requestId }，
 * 旧客户端读 error 字段仍然工作（只是多了 code/requestId）。
 */
import { NextRequest, NextResponse } from 'next/server'
import type { ZodType, output } from 'zod'
import { requireAuth, type AuthResult } from '../auth-middleware'
import { ApiError, errorResponse } from '../api-response'

/** 透传给业务处理器的认证上下文 */
export interface ApiContext {
  auth: AuthResult
  requestId: string
  /** 当前用户 id（登录会话必有；兼容极老 token 可能为 undefined） */
  userId?: number
  username?: string
}

export interface WithAuthOptions {
  /** 处理器内部未转成 ApiError 的异常，默认按 500 处理；需要「业务错误 → 400」时可覆盖 */
  errorStatus?: number
  /** 覆盖默认的兜底错误文案（仅在非 ApiError 时使用） */
  errorMessage?: string
}

/**
 * 路由第二参数（{ params }）在 SDK 侧被 Next 的类型生成器严格校验；
 * 这里用 any 接住，避免不同动态段形状导致 .next/types 校验失败。
 * 动态路由内部自行收窄：`const { id } = await (routeContext as { params: Promise<{ id: string }> }).params`。
 */
type RouteContext = any

/**
 * 请求 ID：优先沿用上游（Nginx/网关）注入的 X-Request-Id，保证跨层可关联；
 * 没有则生成一个 UUID（crypto.randomUUID 在 Node 与 Edge 都可用）。
 */
export function getRequestId(request: Request): string {
  const incoming = request.headers.get('x-request-id')
  if (incoming && /^[\w.:-]{8,128}$/.test(incoming)) return incoming
  try {
    return crypto.randomUUID()
  } catch {
    return `req-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`
  }
}

/**
 * 认证包装器：
 * - 未登录 → 401 { code: 'UNAUTHORIZED' }
 * - 数据库不可用导致无法校验会话 → 503（fail-closed，绝不是 200 放行）
 * - 处理器抛错 → errorResponse（ApiError 用其 code/status，其它 500 且隐藏细节）
 * - 响应头带 X-Request-Id
 */
export function withAuth(
  handler: (request: NextRequest, ctx: ApiContext, routeContext: RouteContext) => Promise<NextResponse> | NextResponse,
  options: WithAuthOptions = {},
): (request: NextRequest, routeContext?: RouteContext) => Promise<NextResponse> {
  return async (request: NextRequest, routeContext?: RouteContext): Promise<NextResponse> => {
    const requestId = getRequestId(request)
    const auth = await requireAuth(request)
    if (!auth.authenticated) {
      const res = auth.databaseUnavailable
        ? errorResponse(new ApiError('AUTH_UNAVAILABLE', '服务暂时不可用，请稍后重试', 503), requestId)
        : errorResponse(new ApiError('UNAUTHORIZED', '未授权', 401), requestId)
      res.headers.set('X-Request-Id', requestId)
      return res
    }

    try {
      const response = await handler(
        request,
        {
          auth,
          requestId,
          userId: auth.payload?.userId,
          username: auth.username,
        },
        routeContext,
      )
      response.headers.set('X-Request-Id', requestId)
      return response
    } catch (error) {
      let mapped: unknown = error
      if (!(error instanceof ApiError) && options.errorStatus) {
        mapped = new ApiError(
          error instanceof ApiError ? error.code : 'BAD_REQUEST',
          options.errorMessage || (error as Error)?.message || '请求处理失败',
          options.errorStatus,
        )
      }
      const response = errorResponse(mapped, requestId)
      response.headers.set('X-Request-Id', requestId)
      return response
    }
  }
}

/**
 * 解析并校验 JSON 请求体（zod）。
 * 失败统一抛 ApiError('VALIDATION_ERROR', 第一条中文提示, 400)；
 * 非 JSON 请求体抛 ApiError('INVALID_JSON')，不再出现「读 body 抛错 → 500」。
 */
export async function parseBody<S extends ZodType>(request: Request, schema: S): Promise<output<S>> {
  let raw: unknown
  try {
    raw = await request.json()
  } catch {
    throw new ApiError('INVALID_JSON', '请求体不是合法的 JSON', 400)
  }
  const parsed = schema.safeParse(raw)
  if (!parsed.success) {
    const first = parsed.error.issues[0]
    throw new ApiError('VALIDATION_ERROR', first?.message || '请求参数不合法', 400)
  }
  return parsed.data as output<S>
}

/**
 * P1-17 收尾 B：写路由共用的 zod 片段与路由壳。
 *
 * 为什么放在 lib/api/schemas 下：本轮只授权改动目标写路由与本目录；
 * `lib/api/handler.ts` 的 withAuth/parseBody 保持不动，这里复用它们并补齐：
 * ① 路径 id 校验（z.coerce.number().int().positive）
 * ② guard（lib/modules/travel/api-guard）旧格式响应 → 统一 ApiError
 * ③ 未使用 withAuth 的 guard 类路由的异常兜底（errorResponse + requestId）
 * ④ 可空 JSON body（如 PATCH notifications 允许无 body）
 *
 * 约束：失败信息只回传"看起来是业务提示"的短中文，其余用兜底文案 —— 不把
 * Prisma/SQL/堆栈等内部细节透给客户端（评审 P1-17 规则⑤）。
 */
import { NextRequest, NextResponse } from 'next/server'
import type { ZodType, output } from 'zod'
import { z } from 'zod'
import { ApiError, errorResponse } from '@/lib/api-response'
import { getRequestId } from '@/lib/api/handler'

/** 数字主键（路径参数 / body 内的 id）：字符串或数字 → 正整数 */
export const IdSchema = z.coerce
  .number({ message: 'ID 必须为数字' })
  .int('ID 必须为整数')
  .positive('ID 必须为正整数')

/** 解析路径 id；失败抛 400（消息只说明"哪个 ID 无效"，不含内部细节） */
export function parseIdParam(value: unknown, label = 'ID'): number {
  const parsed = IdSchema.safeParse(value)
  if (!parsed.success) throw new ApiError('INVALID_ID', `无效的${label}`, 400)
  return parsed.data
}

/** 日期/时间字符串：允许空串（调用方按旧语义当 null）与 null */
export const NullableDateStringSchema = z
  .string({ message: '日期格式不正确' })
  .max(40, '日期格式不正确')
  .refine((v) => v === '' || !Number.isNaN(new Date(v).getTime()), '日期格式不正确')
  .nullable()

/** 可空正整数 id：null 表示清空关联 */
export const NullableIdSchema = z.union([IdSchema, z.null()])

/** 业务错误 → ApiError。只回传"短中文业务提示"，其余用兜底文案，避免泄露内部信息。 */
const BUSINESS_HINT_RE =
  /(不存在|无权|未授权|不能|不可|不允许|失败|已存在|已被|已过期|需|请|无效|不合法|不足|至少|最多|超过|过长|格式|重复|占用|不在|为空)/
const UNSAFE_RE = /(prisma|sql|invalid\s+`|select\s|insert\s|update\s|delete\s+from|stack|at\s+\S+\s+\()/i

export function toApiError(
  error: unknown,
  fallback = '操作失败',
  status = 400,
  code = 'BAD_REQUEST',
): ApiError {
  if (error instanceof ApiError) return error
  const raw = error instanceof Error ? error.message : ''
  const safe = raw.length > 0 && raw.length <= 120 && !UNSAFE_RE.test(raw) && BUSINESS_HINT_RE.test(raw)
  return new ApiError(code, safe ? raw : fallback, status)
}

/**
 * guard 返回的旧格式响应（`{ error }`）→ 统一 ApiError。
 * 保留原状态码与文案，只是把响应形态统一为 `{ success:false, error, code, requestId }`。
 */
export async function asApiErrorFromResponse(response: NextResponse): Promise<ApiError> {
  const status = response.status
  const code =
    status === 401 ? 'UNAUTHORIZED'
      : status === 403 ? 'FORBIDDEN'
        : status === 404 ? 'NOT_FOUND'
          : status === 429 ? 'RATE_LIMITED'
            : 'BAD_REQUEST'
  let message =
    status === 401 ? '未授权'
      : status === 403 ? '权限不足'
        : status === 404 ? '资源不存在'
          : '请求参数不合法'
  try {
    const body = (await response.clone().json()) as { error?: unknown }
    if (typeof body?.error === 'string' && body.error) message = body.error
  } catch {
    // 非 JSON 响应：沿用兜底文案
  }
  return new ApiError(code, message, status)
}

type RouteContext = any
type RouteHandler = (request: NextRequest, routeContext?: RouteContext) => Promise<NextResponse>

/**
 * 未使用 withAuth 的路由壳（guard 类路由用）：统一 requestId + 异常转统一错误格式。
 * 刻意**不做鉴权**——鉴权仍在 guard / requireAuth 内，避免同一请求重复做两次会话校验。
 */
export function withRouteErrors(handler: RouteHandler): RouteHandler {
  return async (request, routeContext) => {
    const requestId = getRequestId(request)
    try {
      const response = await handler(request, routeContext)
      response.headers.set('X-Request-Id', requestId)
      return response
    } catch (error) {
      const response = errorResponse(error, requestId)
      response.headers.set('X-Request-Id', requestId)
      return response
    }
  }
}

/** 可选 JSON body：无 body → undefined；非法 JSON → 400；校验失败 → 400（第一条中文提示） */
export async function parseOptionalBody<S extends ZodType>(
  request: Request,
  schema: S,
): Promise<output<S> | undefined> {
  let text: string
  try {
    text = await request.text()
  } catch {
    text = ''
  }
  if (!text.trim()) return undefined
  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch {
    throw new ApiError('INVALID_JSON', '请求体不是合法的 JSON', 400)
  }
  const parsed = schema.safeParse(raw)
  if (!parsed.success) {
    const first = parsed.error.issues[0]
    throw new ApiError('VALIDATION_ERROR', first?.message || '请求参数不合法', 400)
  }
  return parsed.data as output<S>
}

import { prisma } from './db'
import { hashPassword, verifyPassword, signSession, verifySession, getSessionPayload } from './auth-utils'
import { getCachedSiteSettings, invalidateSiteSettingsCache } from './cache'

export { hashPassword, verifyPassword, signSession, verifySession, getSessionPayload }

const DEFAULT_USERNAME = 'admin'

export interface SiteSettings {
  username: string
  passwordHash: string
  email: string | null
  emailVerified: boolean
  requirePasswordChange: boolean
  anniversaryStart: string | null
}

function mapSetting(setting: any): SiteSettings {
  return {
    username: setting.username,
    passwordHash: setting.passwordHash,
    email: setting.email,
    emailVerified: setting.emailVerified,
    requirePasswordChange: (setting as any).requirePasswordChange ?? false,
    anniversaryStart: (setting as any).anniversaryStart ?? null,
  }
}

/** 未配置任何凭据时的安全空设置：passwordHash 为空，登录将提示"系统尚未配置访问密码"。 */
function emptySettings(): SiteSettings {
  return {
    username: process.env.ADMIN_USERNAME || DEFAULT_USERNAME,
    passwordHash: '',
    email: null,
    emailVerified: false,
    requirePasswordChange: false,
    anniversaryStart: null,
  }
}

/**
 * 单管理员迁移：从旧 SiteSetting 回填到 User 表（幂等）。
 * 仅在 User 表为空且 SiteSetting 存在时执行，用于平滑升级。
 *
 * 这是**引导性**写入（库里一个用户都没有），不是「改某个用户」，因此不存在写错人的风险。
 */
async function migrateSiteSettingToUser(): Promise<void> {
  try {
    const [userCount, legacy] = await Promise.all([
      prisma.user.count(),
      prisma.siteSetting.findFirst({ orderBy: { id: 'asc' } }),
    ])
    if (userCount > 0 || !legacy) return

    await prisma.user.create({
      data: {
        username: legacy.username,
        passwordHash: legacy.passwordHash,
        email: legacy.email,
        emailVerified: legacy.emailVerified,
        requirePasswordChange: (legacy as any).requirePasswordChange ?? false,
        anniversaryStart: (legacy as any).anniversaryStart ?? null,
      },
    })
  } catch (error) {
    console.error('[migrateSiteSettingToUser] Failed:', error)
  }
}

/**
 * 读取站点设置（**只读兼容路径**，B11）。
 *
 * 为什么这里仍保留「首个用户（id 升序）」：
 *  · 登录页 / 初始化引导 / 未登录时的 needsSetup 判断没有 username 上下文，只需要「站点是否已配置」；
 *  · 历史数据是单管理员模型，首用户即站点主人。
 *
 * **写路径绝对不要走这里** —— 写完会隐式落到别的用户头上（评审 S-2/A-1 的账号接管链）。
 * 写凭据必须用 updateCredentials（按显式 username 定位）。
 */
async function fetchSiteSettingsFromDB(): Promise<SiteSettings> {
  try {
    await migrateSiteSettingToUser()

    // 只读兼容：首用户 = 站点级配置的归属者
    const user = await prisma.user.findFirst({ orderBy: { id: 'asc' } })
    if (user) {
      return mapSetting(user)
    }
  } catch {
    const envPasswordHash = process.env.ADMIN_PASSWORD_HASH
    if (envPasswordHash) {
      return {
        username: process.env.ADMIN_USERNAME || DEFAULT_USERNAME,
        passwordHash: envPasswordHash,
        email: null,
        emailVerified: false,
        requirePasswordChange: false,
        anniversaryStart: null,
      }
    }
    return emptySettings()
  }

  await initializeDefaultAdmin()

  try {
    // 只读兼容：同上（初始化后重新读首用户）
    const user = await prisma.user.findFirst({ orderBy: { id: 'asc' } })
    if (user) {
      return mapSetting(user)
    }
  } catch {}

  const envPasswordHash = process.env.ADMIN_PASSWORD_HASH
  if (envPasswordHash) {
    return {
      username: process.env.ADMIN_USERNAME || DEFAULT_USERNAME,
      passwordHash: envPasswordHash,
      email: null,
      emailVerified: false,
      requirePasswordChange: false,
      anniversaryStart: null,
    }
  }

  return emptySettings()
}

export async function getSiteSettings(): Promise<SiteSettings> {
  return getCachedSiteSettings(fetchSiteSettingsFromDB)
}

async function initializeDefaultAdmin(): Promise<void> {
  // 安全策略：仅当显式配置了 ADMIN_PASSWORD_HASH 时才创建初始账号，
  // 绝不使用硬编码的默认密码。未配置时由 /admin/setup 引导完成初始化。
  const envPasswordHash = process.env.ADMIN_PASSWORD_HASH
  if (!envPasswordHash) return

  try {
    const count = await prisma.user.count()
    if (count === 0) {
      await prisma.user.create({
        data: {
          username: process.env.ADMIN_USERNAME || DEFAULT_USERNAME,
          passwordHash: envPasswordHash,
          requirePasswordChange: false,
        },
      })
    }
  } catch (error) {
    console.error('[initializeDefaultAdmin] Failed:', error)
  }
}

/**
 * 引导初始化（B11）：**只在「一个用户都没有」时**按 env 创建初始管理员，已有用户时什么都不做。
 * 因此它不会隐式改写任何既有用户的凭据（旧语义的 7 处首用户写路径已全部移除）。
 */
export async function initializeCredentialsFromEnv(): Promise<void> {
  try {
    await migrateSiteSettingToUser()
    const count = await prisma.user.count()
    if (count === 0) {
      await initializeDefaultAdmin()
    }
  } catch (error) {
    console.error('[initializeCredentialsFromEnv] Failed:', error)
  }
}

/**
 * 写入账号凭据（B11：**按显式 username 定位**，不再 findFirst(id asc)）。
 *
 * 旧实现每次写都先取「id 最小的用户」，于是任何一次漏传目标都会改掉站长的账号/密码
 * （评审 S-2：注册即可接管站长）。现在：
 *  · 目标用户存在 → 按 id 更新，只影响这一个人；
 *  · 不存在 → 创建（仅初始化/引导路径会走到：/api/admin/setup、env 初始化）；
 *  · 绝不隐式改动其它用户。
 */
export async function updateCredentials(
  username: string,
  passwordHash: string,
  email?: string | null,
  clearRequireChange: boolean = false,
): Promise<void> {
  try {
    await migrateSiteSettingToUser()
    const user = await prisma.user.findUnique({ where: { username }, select: { id: true } })
    if (user) {
      const updateData: any = { passwordHash, updatedAt: new Date() }
      if (clearRequireChange) {
        updateData.requirePasswordChange = false
      }
      if (email !== undefined) {
        updateData.email = email
        if (!email) {
          updateData.emailVerified = false
        }
      }
      await prisma.user.update({ where: { id: user.id }, data: updateData })
    } else {
      await prisma.user.create({
        data: {
          username,
          passwordHash,
          email: email || null,
          emailVerified: email ? true : false,
          requirePasswordChange: false,
        },
      })
    }
    invalidateSiteSettingsCache()
  } catch (error) {
    console.error('[updateCredentials] Failed:', error)
  }
}

interface CacheEntry<T> {
  value: T
  expireAt: number
  tags: Set<string>
}

class MemoryCache {
  private cache: Map<string, CacheEntry<any>> = new Map()
  private tagIndex: Map<string, Set<string>> = new Map()
  private maxSize: number
  private defaultTTL: number
  private hits = 0
  private misses = 0

  constructor(maxSize: number = 1000, defaultTTL: number = 60000) {
    this.maxSize = maxSize
    this.defaultTTL = defaultTTL
  }

  get<T>(key: string): T | null {
    const entry = this.cache.get(key)
    if (!entry) {
      this.misses++
      return null
    }
    if (Date.now() > entry.expireAt) {
      this.delete(key)
      this.misses++
      return null
    }
    this.hits++
    return entry.value as T
  }

  set<T>(key: string, value: T, ttl: number = this.defaultTTL, tags: string[] = []): void {
    if (this.cache.size >= this.maxSize) {
      this.evict()
    }

    const expireAt = Date.now() + ttl
    this.cache.set(key, { value, expireAt, tags: new Set(tags) })

    for (const tag of tags) {
      if (!this.tagIndex.has(tag)) {
        this.tagIndex.set(tag, new Set())
      }
      this.tagIndex.get(tag)!.add(key)
    }
  }

  getOrSet<T>(key: string, fetcher: () => Promise<T>, ttl?: number, tags?: string[]): Promise<T> {
    const cached = this.get<T>(key)
    if (cached !== null) {
      return Promise.resolve(cached)
    }
    return fetcher().then((value) => {
      this.set(key, value, ttl, tags)
      return value
    })
  }

  delete(key: string): void {
    const entry = this.cache.get(key)
    if (entry) {
      entry.tags.forEach(tag => {
        const keys = this.tagIndex.get(tag)
        if (keys) {
          keys.delete(key)
          if (keys.size === 0) {
            this.tagIndex.delete(tag)
          }
        }
      })
      this.cache.delete(key)
    }
  }

  deleteByTag(tag: string): void {
    const keys = this.tagIndex.get(tag)
    if (keys) {
      keys.forEach(key => {
        this.cache.delete(key)
      })
      this.tagIndex.delete(tag)
    }
  }

  clear(): void {
    this.cache.clear()
    this.tagIndex.clear()
    this.hits = 0
    this.misses = 0
  }

  clearByPrefix(prefix: string): void {
    const keysToDelete: string[] = []
    this.cache.forEach((_, key) => {
      if (key.startsWith(prefix)) {
        keysToDelete.push(key)
      }
    })
    keysToDelete.forEach(key => {
      this.delete(key)
    })
  }

  getStats(): { size: number; hits: number; misses: number; hitRate: number } {
    const total = this.hits + this.misses
    return {
      size: this.cache.size,
      hits: this.hits,
      misses: this.misses,
      hitRate: total > 0 ? (this.hits / total) * 100 : 0,
    }
  }

  private evict(): void {
    let oldestKey: string | null = null
    let oldestExpire = Infinity

    this.cache.forEach((entry, key) => {
      if (entry.expireAt < oldestExpire) {
        oldestExpire = entry.expireAt
        oldestKey = key
      }
    })

    if (oldestKey) {
      this.delete(oldestKey)
    } else {
      const firstKey = this.cache.keys().next().value
      if (firstKey) {
        this.delete(firstKey as string)
      }
    }
  }
}

export const appCache = new MemoryCache(2000, 60000)

const SITE_SETTINGS_CACHE_KEY = 'site:settings'
const SITE_SETTINGS_CACHE_TTL = 30000

export async function getCachedSiteSettings<T>(fetcher: () => Promise<T>): Promise<T> {
  return appCache.getOrSet(
    SITE_SETTINGS_CACHE_KEY,
    fetcher,
    SITE_SETTINGS_CACHE_TTL,
    ['settings']
  )
}

export function invalidateSiteSettingsCache(): void {
  appCache.deleteByTag('settings')
}

export function invalidatePostCacheByType(type: string): void {
  appCache.deleteByTag(`posts:${type}`)
}

export function invalidateAllPostCache(): void {
  const tagIndex = appCache['tagIndex'] as Map<string, Set<string>>
  tagIndex.forEach((_, tag) => {
    if (tag.startsWith('posts:')) {
      appCache.deleteByTag(tag)
    }
  })
}

export function getCacheStats(): { size: number; hits: number; misses: number; hitRate: number } {
  return appCache.getStats()
}

