import { PrismaClient } from '@prisma/client'
import { PrismaMariaDB } from './prisma-adapter'

const globalForPrisma = globalThis as unknown as {
  prisma: PrismaClient | undefined
  prismaAdapter: PrismaMariaDB | undefined
}

const adapter =
  globalForPrisma.prismaAdapter ??
  new PrismaMariaDB({
    connectionString: process.env.DATABASE_URL!,
  })

export const prisma =
  globalForPrisma.prisma ??
  new PrismaClient({
    adapter: adapter as any,
    log: process.env.NODE_ENV === 'development' ? ['error', 'warn'] : ['error'],
  })

if (process.env.NODE_ENV !== 'production') {
  globalForPrisma.prisma = prisma
  globalForPrisma.prismaAdapter = adapter
}

/**
 * 优雅停机（P2-35）：断开 Prisma 客户端 + 关闭底层连接池。
 *
 * 由进程入口调用（instrumentation.ts 的 SIGTERM/SIGINT 处理），
 * 历史实现把信号处理写在 PrismaMariaDB 构造函数里并直接 process.exit(0)，
 * 导致任何引用 lib/db 的脚本都被动接管进程生命周期。现在职责分离：
 * 适配器只提供 close()，何时关、关完是否退出由入口决定。
 */
export async function shutdownPrisma(): Promise<void> {
  try {
    await prisma.$disconnect()
  } catch (error) {
    console.error('[db] prisma.$disconnect 失败:', (error as Error)?.message || error)
  }
  try {
    await adapter.close()
  } catch (error) {
    console.error('[db] 关闭数据库连接池失败:', (error as Error)?.message || error)
  }
}

// 极简 JPEG EXIF 解析器（无第三方依赖，2C2G 友好）
// 提取相机品牌/型号/光圈/快门/ISO/焦距/拍摄时间等常用字段

export interface ExifData {
  make?: string
  model?: string
  fNumber?: number
  exposureTime?: string
  iso?: number
  focalLength?: number
  dateTaken?: string
  width?: number
  height?: number
  /** EXIF Orientation（1-8）：前端据此旋转显示，避免"手机拍的照片躺着" */
  orientation?: number
}

/**
 * 对外可返回的 EXIF 白名单（P0-4 / S-5）。
 *
 * 为什么必须白名单而不是黑名单：GPS（0x8825 GPS IFD）、设备序列号（0xA431 BodySerialNumber）、
 * 镜头序列号等字段一旦随 /meta 下发，等于公开"这张照片在哪拍的、用什么机器拍的"。
 * 黑名单永远漏字段（新 EXIF 标签每年都在加），所以只保留排版/显示必需的安全字段。
 */
export interface PublicExifData {
  width?: number
  height?: number
  orientation?: number
  dateTaken?: string
}

/** ExifData → 对外安全子集；没有任何可返回字段时返回 null（前端按"无 EXIF"处理） */
export function toPublicExif(exif: ExifData | null | undefined): PublicExifData | null {
  if (!exif) return null
  const out: PublicExifData = {}
  if (typeof exif.width === 'number' && exif.width > 0) out.width = exif.width
  if (typeof exif.height === 'number' && exif.height > 0) out.height = exif.height
  if (typeof exif.orientation === 'number' && exif.orientation >= 1 && exif.orientation <= 8) {
    out.orientation = exif.orientation
  }
  if (typeof exif.dateTaken === 'string' && exif.dateTaken) out.dateTaken = exif.dateTaken
  return Object.keys(out).length > 0 ? out : null
}

/**
 * 只读图片像素尺寸（不做 EXIF 解析）。
 *
 * 用途：画册排版需要宽高比来决定单页 / 跨页出血。存量旅行文章的图片存在
 * `PostImage.data` BLOB 里（不是文件），没有 Media 行也没有变体链，
 * 而 `parseExif()` 对无 EXIF 段的 JPEG 也会返回尺寸——代价是要走完整个段循环。
 * 本函数只扫到 SOF 标记即返回，明显更省。
 *
 * 支持 JPEG / WebP；其他格式返回 null（调用方回退"未知尺寸"的安全缺省）。
 */
export function readImageDimensions(buffer: Buffer): { width: number; height: number } | null {
  if (!buffer || buffer.length < 12) return null
  if (buffer[0] === 0xff && buffer[1] === 0xd8) return readJpegDimensions(buffer)
  // WebP: RIFF....WEBP → VP8X / VP8 / VP8L
  if (buffer.toString('ascii', 0, 4) === 'RIFF' && buffer.toString('ascii', 8, 12) === 'WEBP') {
    return readWebpDimensions(buffer)
  }
  return null
}



const EXIF_TAG_NAMES: Record<number, string> = {
  0x829a: 'exposureTime',
  0x829d: 'fNumber',
  0x8827: 'iso',
  0x920a: 'focalLength',
  0x9003: 'dateTaken',
  0x0132: 'dateTaken',
}

interface IfdEntry {
  tag: number
  type: number
  count: number
  valueOffset: number
}

function readAscii(data: Buffer, offset: number, count: number): string {
  const end = Math.min(offset + count, data.length)
  return data.toString('ascii', offset, end).replace(/\0+$/g, '').trim()
}

function parseIfd(
  data: Buffer,
  ifdOffset: number,
  byteOrder: 'II' | 'MM',
  tagMap: Record<number, string>
): Record<string, unknown> {
  const little = byteOrder === 'II'
  const result: Record<string, unknown> = {}

  const numEntries = little
    ? data.readUInt16LE(ifdOffset)
    : data.readUInt16BE(ifdOffset)

  for (let i = 0; i < numEntries; i++) {
    const entryOffset = ifdOffset + 2 + i * 12
    if (entryOffset + 12 > data.length) break

    const tag = little
      ? data.readUInt16LE(entryOffset)
      : data.readUInt16BE(entryOffset)
    const type = little
      ? data.readUInt16LE(entryOffset + 2)
      : data.readUInt16BE(entryOffset + 2)
    const count = little
      ? data.readUInt32LE(entryOffset + 4)
      : data.readUInt32BE(entryOffset + 4)

    const fieldName = tagMap[tag]
    if (!fieldName) continue

    const valueOffset = entryOffset + 8
    const byteSize = (() => {
      switch (type) {
        case 1: case 2: case 6: case 7: return 1
        case 3: return 2
        case 4: case 9: return 4
        case 5: case 10: return 8
        default: return 1
      }
    })()

    const dataOffset =
      byteSize * count <= 4
        ? valueOffset
        : little
          ? data.readUInt32LE(valueOffset)
          : data.readUInt32BE(valueOffset)

    if (dataOffset + byteSize * count > data.length) continue

    if (type === 2) {
      result[fieldName] = readAscii(data, dataOffset, count)
    } else if (type === 5 || type === 10) {
      // 有理数（分子/分母）
      const num = little
        ? data.readUInt32LE(dataOffset)
        : data.readUInt32BE(dataOffset)
      const den = little
        ? data.readUInt32LE(dataOffset + 4)
        : data.readUInt32BE(dataOffset + 4)
      result[fieldName] = den !== 0 ? num / den : 0
    } else if (type === 3) {
      result[fieldName] = little
        ? data.readUInt16LE(dataOffset)
        : data.readUInt16BE(dataOffset)
    } else if (type === 4 || type === 9) {
      result[fieldName] = little
        ? data.readUInt32LE(dataOffset)
        : data.readUInt32BE(dataOffset)
    } else if (type === 1) {
      result[fieldName] = data[dataOffset]
    }
  }

  return result
}

function formatExposureTime(value: number): string {
  if (!value || value <= 0) return ''
  if (value >= 1) return `${Math.round(value)}s`
  return `1/${Math.round(1 / value)}s`
}

function formatDateTaken(value: string): string {
  // EXIF 日期格式: "2024:05:01 12:30:00"
  if (!value) return ''
  const m = value.match(/^(\d{4}):(\d{2}):(\d{2})[ ](\d{2}):(\d{2}):(\d{2})/)
  if (m) {
    return `${m[1]}-${m[2]}-${m[3]} ${m[4]}:${m[5]}:${m[6]}`
  }
  return value
}

/** 从 JPEG 二进制解析 EXIF；非 JPEG 或无 EXIF 返回 null */
export function parseExif(buffer: Buffer): ExifData | null {  if (!buffer || buffer.length < 4) return null
  // JPEG SOI 检查
  if (!(buffer[0] === 0xff && buffer[1] === 0xd8)) {
    // WebP: RIFF....WEBP
    if (
      buffer.toString('ascii', 0, 4) === 'RIFF' &&
      buffer.toString('ascii', 8, 12) === 'WEBP'
    ) {
      return parseWebpExif(buffer)
    }
    return null
  }

  let offset = 2
  const width = readJpegDimensions(buffer)
  let exifOffset = -1

  // 遍历 JPEG 段，查找 APP1 (0xFFE1) 且包含 "Exif\0\0"
  while (offset + 4 <= buffer.length) {
    if (buffer[offset] !== 0xff) {
      offset++
      continue
    }
    const marker = buffer[offset + 1]
    if (marker === 0xd8 || marker === 0xd9 || (marker >= 0xd0 && marker <= 0xd7)) {
      offset += 2
      continue
    }
    const segLen = buffer.readUInt16BE(offset + 2)
    if (segLen < 2) break
    if (marker === 0xe1 && segLen >= 10) {
      const app1Start = offset + 4
      if (buffer.toString('ascii', app1Start, app1Start + 6) === 'Exif\x00\x00') {
        exifOffset = app1Start + 6
        break
      }
    }
    offset += 2 + segLen
  }

  if (exifOffset < 0 || exifOffset + 8 > buffer.length) {
    return width ? { width: width.width, height: width.height } : null
  }

  const byteOrder = buffer.toString('ascii', exifOffset, exifOffset + 2)
  if (byteOrder !== 'II' && byteOrder !== 'MM') {
    return width ? { width: width.width, height: width.height } : null
  }
  const little = byteOrder === 'II'

  const ifd0Offset =
    exifOffset +
    (little ? buffer.readUInt32LE(exifOffset + 4) : buffer.readUInt32BE(exifOffset + 4))

  const ifd0 = parseIfd(buffer, ifd0Offset, byteOrder, {
    0x010f: 'make',
    0x0110: 'model',
    0x0112: 'orientation',
  })

  const exifIfdPointer = little
    ? buffer.readUInt32LE(ifd0Offset + 8)
    : buffer.readUInt32BE(ifd0Offset + 8)
  const exifIfd = exifIfdPointer
    ? parseIfd(buffer, exifOffset + exifIfdPointer, byteOrder, EXIF_TAG_NAMES)
    : {}

  const result: ExifData = {
    ...(width || {}),
    make: (ifd0.make as string) || undefined,
    model: (ifd0.model as string) || undefined,
  }
  if (ifd0.orientation !== undefined) result.orientation = Number(ifd0.orientation) || undefined

  if (exifIfd.fNumber !== undefined) result.fNumber = Number(exifIfd.fNumber) || undefined
  if (exifIfd.exposureTime !== undefined) {
    const t = formatExposureTime(Number(exifIfd.exposureTime))
    if (t) result.exposureTime = t
  }
  if (exifIfd.iso !== undefined) result.iso = Number(exifIfd.iso) || undefined
  if (exifIfd.focalLength !== undefined) result.focalLength = Number(exifIfd.focalLength) || undefined
  if (exifIfd.dateTaken !== undefined) {
    const d = formatDateTaken(String(exifIfd.dateTaken))
    if (d) result.dateTaken = d
  }

  return result
}

function parseWebpExif(buffer: Buffer): ExifData | null {
  // WebP EXIF 存放于 'EXIF' chunk（可能带 "Exif\0\0" 前缀）
  let offset = 12
  while (offset + 8 <= buffer.length) {
    const chunkId = buffer.toString('ascii', offset, offset + 4)
    const chunkSize = buffer.readUInt32LE(offset + 4)
    const dataStart = offset + 8
    if (chunkId === 'EXIF' && dataStart + chunkSize <= buffer.length) {
      let exifOffset = dataStart
      if (buffer.toString('ascii', dataStart, dataStart + 6) === 'Exif\x00\x00') {
        exifOffset = dataStart + 6
      }
      const byteOrder = buffer.toString('ascii', exifOffset, exifOffset + 2)
      if (byteOrder === 'II' || byteOrder === 'MM') {
        const little = byteOrder === 'II'
        const ifd0Offset =
          exifOffset +
          (little ? buffer.readUInt32LE(exifOffset + 4) : buffer.readUInt32BE(exifOffset + 4))
        const ifd0 = parseIfd(buffer, ifd0Offset, byteOrder, {
          0x010f: 'make',
          0x0110: 'model',
          0x0112: 'orientation',
        })
        const exifIfdPointer = little
          ? buffer.readUInt32LE(ifd0Offset + 8)
          : buffer.readUInt32BE(ifd0Offset + 8)
        const exifIfd = exifIfdPointer
          ? parseIfd(buffer, exifOffset + exifIfdPointer, byteOrder, EXIF_TAG_NAMES)
          : {}
        const result: ExifData = {
          make: (ifd0.make as string) || undefined,
          model: (ifd0.model as string) || undefined,
        }
        if (ifd0.orientation !== undefined) result.orientation = Number(ifd0.orientation) || undefined
        if (exifIfd.fNumber !== undefined) result.fNumber = Number(exifIfd.fNumber) || undefined
        if (exifIfd.exposureTime !== undefined) {
          const t = formatExposureTime(Number(exifIfd.exposureTime))
          if (t) result.exposureTime = t
        }
        if (exifIfd.iso !== undefined) result.iso = Number(exifIfd.iso) || undefined
        if (exifIfd.focalLength !== undefined) result.focalLength = Number(exifIfd.focalLength) || undefined
        if (exifIfd.dateTaken !== undefined) {
          const d = formatDateTaken(String(exifIfd.dateTaken))
          if (d) result.dateTaken = d
        }
        return result
      }
    }
    offset = dataStart + chunkSize + (chunkSize % 2)
  }
  return null
}

/** WebP 尺寸：优先 VP8X（含 canvas 宽高），否则 VP8 / VP8L 帧头 */
function readWebpDimensions(buffer: Buffer): { width: number; height: number } | null {
  if (buffer.length < 30) return null
  const fourcc = buffer.toString('ascii', 12, 16)
  if (fourcc === 'VP8X') {
    // 24 位小端（值 = 实际宽高 - 1），偏移 24 / 27
    const w = 1 + (buffer[24] | (buffer[25] << 8) | (buffer[26] << 16))
    const h = 1 + (buffer[27] | (buffer[28] << 8) | (buffer[29] << 16))
    if (w > 0 && h > 0) return { width: w, height: h }
    return null
  }
  if (fourcc === 'VP8 ') {
    // 关键帧头：偏移 26..29 为 14 位宽高（低 14 位）
    const w = (buffer[26] | (buffer[27] << 8)) & 0x3fff
    const h = (buffer[28] | (buffer[29] << 8)) & 0x3fff
    if (w > 0 && h > 0) return { width: w, height: h }
    return null
  }
  if (fourcc === 'VP8L') {
    // 无损：1 字节签名 0x2f + 14 位宽、14 位高，从偏移 21 开始
    const b = buffer.readUInt32LE(21)
    const w = (b & 0x3fff) + 1
    const h = ((b >> 14) & 0x3fff) + 1
    if (w > 0 && h > 0) return { width: w, height: h }
  }
  return null
}

function readJpegDimensions(buffer: Buffer): { width: number; height: number } | null {  let offset = 2
  while (offset + 4 <= buffer.length) {
    if (buffer[offset] !== 0xff) {
      offset++
      continue
    }
    const marker = buffer[offset + 1]
    if (marker === 0xd8 || marker === 0xd9 || (marker >= 0xd0 && marker <= 0xd7)) {
      offset += 2
      continue
    }
    const segLen = buffer.readUInt16BE(offset + 2)
    if (segLen < 2) break
    // SOF0-SOF15（排除 DHT C4 / DAC CC / RST / SOI / EOI）
    if (
      marker >= 0xc0 &&
      marker <= 0xcf &&
      marker !== 0xc4 &&
      marker !== 0xc8 &&
      marker !== 0xcc
    ) {
      const height = buffer.readUInt16BE(offset + 5)
      const width = buffer.readUInt16BE(offset + 7)
      return { width, height }
    }
    offset += 2 + segLen
  }
  return null
}

import { unified } from 'unified'
import remarkParse from 'remark-parse'
import remarkGfm from 'remark-gfm'
import remarkMath from 'remark-math'
import rehypeKatex from 'rehype-katex'
import remarkRehype from 'remark-rehype'
import rehypeSlug from 'rehype-slug'
import rehypeHighlight from 'rehype-highlight'
import rehypeStringify from 'rehype-stringify'
import rehypeSanitize, { defaultSchema } from 'rehype-sanitize'
import type { Schema } from 'hast-util-sanitize'
import rehypeRaw from 'rehype-raw'
import matter from 'gray-matter'

export interface TocItem {
  level: number
  text: string
  id: string
}

export interface RenderedContent {
  html: string
  toc: TocItem[]
  headings: TocItem[]
  wordCount: number
  readMinutes: number
}

export interface MarkdownRenderer {
  render(content: string, options?: { extractToc?: boolean }): Promise<RenderedContent>
  extractToc(html: string): TocItem[]
  extractFrontMatter(content: string): { data: Record<string, any>; content: string }
}

/**
 * Markdown 输出安全边界（XSS 防护）：
 * - 基于 rehype-sanitize 默认白名单，剥离 <script>、事件属性、javascript: 协议、
 *   <object>/<embed>/<iframe> 等危险内容
 * - 额外放行：语法高亮 className、TOC id、GFM 任务列表、KaTeX MathML
 */
const sanitizeSchema: Schema = {
  ...defaultSchema,
  tagNames: [
    ...(defaultSchema.tagNames || []),
    // KaTeX MathML 所需标签
    'math', 'semantics', 'mrow', 'mfrac', 'mi', 'mo', 'mn', 'msup', 'msub',
    'msubsup', 'msqrt', 'mroot', 'mtext', 'merror', 'mpadded', 'mphantom',
    'mspace', 'mtable', 'mtr', 'mtd', 'mover', 'munder', 'munderover',
    'menclose', 'mstyle', 'annotation',
  ],
  attributes: {
    ...(defaultSchema.attributes || {}),
    '*': [
      ...((defaultSchema.attributes as any)?.['*'] || []),
      'className',
      'data-marker',
    ],
    // 语法高亮 / Mermaid 代码块的语言类名
    code: [
      ...((defaultSchema.attributes as any)?.code || []),
      ['className', /^language-[a-zA-Z0-9_-]+$/],
    ],
    // GFM 任务列表
    input: [
      ['type', 'checkbox'],
      'checked',
      'disabled',
    ],
    // 链接：仅允许 http(s)/mailto（默认协议白名单已限制 javascript: 等）
    a: [
      ...((defaultSchema.attributes as any)?.a || []),
      'target',
      'rel',
    ],
    img: [
      ...((defaultSchema.attributes as any)?.img || []),
      'loading',
      'referrerPolicy',
    ],
    math: ['xmlns', 'display'],
    annotation: ['encoding'],
  },
}

function slugify(text: string): string {
  return text
    .toLowerCase()
    .trim()
    .replace(/[\s]+/g, '-')
    .replace(/[^\w\u4e00-\u9fa5-]/g, '')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
}

export class UnifiedMarkdownRenderer implements MarkdownRenderer {
  async render(content: string, options?: { extractToc?: boolean }): Promise<RenderedContent> {
    const { data, content: body } = this.extractFrontMatter(content)

    const file = await unified()
      .use(remarkParse)
      .use(remarkGfm)
      .use(remarkMath)
      .use(remarkRehype, { allowDangerousHtml: true })
      .use(rehypeRaw)
      .use(rehypeKatex)
      .use(rehypeSlug)
      .use(rehypeHighlight)
      .use(rehypeSanitize, sanitizeSchema)
      .use(rehypeStringify, { allowDangerousHtml: true })
      .process(body)

    const html = String(file)
    const toc = options?.extractToc ? this.extractTocFromMarkdown(body) : this.extractToc(html)
    const wordCount = this.countWords(body)
    const readMinutes = Math.ceil(wordCount / 200)

    return {
      html,
      toc,
      headings: toc,
      wordCount,
      readMinutes: Math.max(1, readMinutes),
    }
  }

  extractToc(html: string): TocItem[] {
    const headingRegex = /<h([23])(?:\s+id="([^"]*)")?[^>]*>(.*?)<\/h\1>/g
    const toc: TocItem[] = []
    let match

    while ((match = headingRegex.exec(html)) !== null) {
      const level = parseInt(match[1], 10)
      const rawId = match[2]
      const rawText = match[3]
      const text = this.stripHtmlTags(rawText).trim()
      const id = rawId || slugify(text)
      toc.push({ level, text, id })
    }

    return toc
  }

  private extractTocFromMarkdown(content: string): TocItem[] {
    const lines = content.split('\n')
    const toc: TocItem[] = []
    const inCodeBlock = { value: false }

    for (const line of lines) {
      if (line.trim().startsWith('```')) {
        inCodeBlock.value = !inCodeBlock.value
        continue
      }
      if (inCodeBlock.value) continue

      const headingMatch = line.match(/^(#{2,3})\s+(.+)$/)
      if (headingMatch) {
        const level = headingMatch[1].length
        const text = headingMatch[2].trim()
        const id = slugify(text)
        toc.push({ level, text, id })
      }
    }

    return toc
  }

  extractFrontMatter(content: string): { data: Record<string, any>; content: string } {
    try {
      const result = matter(content)
      return {
        data: result.data as Record<string, any>,
        content: result.content,
      }
    } catch {
      return { data: {}, content }
    }
  }

  private stripHtmlTags(text: string): string {
    return text.replace(/<[^>]*>/g, '')
  }

  private countWords(content: string): number {
    const stripped = content
      .replace(/```[\s\S]*?```/g, '')
      .replace(/`[^`]*`/g, '')
      .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
      .replace(/\[[^\]]*\]\([^)]*\)/g, '')
      .replace(/^#+\s*/gm, '')
      .replace(/[*_~`>-]/g, '')
      .replace(/\s+/g, ' ')
      .trim()

    const chineseChars = (stripped.match(/[\u4e00-\u9fa5]/g) || []).length
    const englishWords = stripped
      .replace(/[\u4e00-\u9fa5]/g, ' ')
      .split(/\s+/)
      .filter((w) => w.length > 0)
      .length

    return chineseChars + englishWords
  }
}

export const unifiedMarkdownRenderer = new UnifiedMarkdownRenderer()

/**
 * 媒体上传安全校验：
 * - 不信任客户端 MIME，使用 Magic Number 检测真实类型
 * - 仅允许 JPEG / PNG / WebP（默认禁止 SVG，防止存储型 XSS）
 * - 使用 sharp 重新编码，剥离 EXIF/GPS 等危险或隐私元数据
 * - 限制文件大小、尺寸与单次数量
 */
import sharp, { type Sharp } from 'sharp'

export const MAX_IMAGE_SIZE = 10 * 1024 * 1024 // 10MB
export const MAX_IMAGE_DIMENSION = 8000 // 宽或高最大 8000px
export const MAX_IMAGE_COUNT = 20 // 单次请求最多文件数

export const MAX_VIDEO_SIZE = 500 * 1024 * 1024 // 500MB
export const MAX_VIDEO_COUNT = 5

export type DetectedImageType = 'jpeg' | 'png' | 'webp' | 'gif' | null

const EXT_TO_MIME: Record<string, string> = {
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg',
  png: 'image/png',
  webp: 'image/webp',
}

/** 通过 Magic Number 检测图片真实类型 */
export function detectImageType(buffer: Buffer): DetectedImageType {
  if (!buffer || buffer.length < 12) return null

  // JPEG: FF D8 FF
  if (buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) return 'jpeg'

  // PNG: 89 50 4E 47 0D 0A 1A 0A
  if (
    buffer[0] === 0x89 && buffer[1] === 0x50 && buffer[2] === 0x4e &&
    buffer[3] === 0x47 && buffer[4] === 0x0d && buffer[5] === 0x0a &&
    buffer[6] === 0x1a && buffer[7] === 0x0a
  ) return 'png'

  // WebP: RIFF .... WEBP
  if (
    buffer.toString('ascii', 0, 4) === 'RIFF' &&
    buffer.toString('ascii', 8, 12) === 'WEBP'
  ) return 'webp'

  // GIF: 47 49 46 38 (GIF8)
  if (
    buffer[0] === 0x47 && buffer[1] === 0x49 &&
    buffer[2] === 0x46 && buffer[3] === 0x38
  ) return 'gif'

  return null
}

function detectVideoType(buffer: Buffer): string | null {
  if (!buffer || buffer.length < 12) return null
  // MP4 / MOV: ftyp box at offset 4
  if (buffer.toString('ascii', 4, 8) === 'ftyp') return 'video/mp4'
  // WebM / Matroska: EBML header 1A 45 DF A3
  if (buffer[0] === 0x1a && buffer[1] === 0x45 && buffer[2] === 0xdf && buffer[3] === 0xa3) return 'video/webm'
  // OGG: OggS
  if (buffer.toString('ascii', 0, 4) === 'OggS') return 'video/ogg'
  return null
}

export interface ValidatedImage {
  buffer: Buffer
  mimeType: string
  width: number
  height: number
}

/**
 * 校验并安全化图片：
 * 1. Magic Number 校验（拒绝伪造/误报类型）
 * 2. 尺寸与大小限制
 * 3. sharp 解码并重新编码（剥离 EXIF/GPS 元数据，杜绝 polyglot）
 */
export async function validateAndSanitizeImage(
  input: Buffer,
  declaredMimeType?: string,
): Promise<ValidatedImage> {
  if (!input || input.length === 0) {
    throw new Error('文件为空')
  }
  if (input.length > MAX_IMAGE_SIZE) {
    throw new Error(`文件大小超过限制（最大 ${Math.round(MAX_IMAGE_SIZE / 1024 / 1024)}MB）`)
  }

  const detected = detectImageType(input)
  if (!detected) {
    throw new Error('不支持或无法识别的图片格式（仅支持 JPEG/PNG/WebP）')
  }
  if (detected === 'gif' || detected === 'svg' as any) {
    throw new Error('不支持该图片格式（仅支持 JPEG/PNG/WebP）')
  }

  // 若声明了 MIME，校验与 Magic Number 一致；不一致时拒绝（不信任客户端）
  const actualMime = EXT_TO_MIME[detected]
  if (declaredMimeType && declaredMimeType !== actualMime) {
    throw new Error('文件类型声明与实际内容不符')
  }

  let image: Sharp
  try {
    image = sharp(input, { failOn: 'error' })
    const metadata = await image.metadata()
    if (!metadata.width || !metadata.height) {
      throw new Error('无法解析图片尺寸')
    }
    if (
      metadata.width > MAX_IMAGE_DIMENSION ||
      metadata.height > MAX_IMAGE_DIMENSION
    ) {
      throw new Error(`图片尺寸超过限制（最大 ${MAX_IMAGE_DIMENSION}px）`)
    }

    // 重新编码：默认剥离全部元数据（EXIF/GPS）
    let output: Buffer
    let mimeType: string
    switch (detected) {
      case 'jpeg':
        output = await image.jpeg({ quality: 88, mozjpeg: true }).toBuffer()
        mimeType = 'image/jpeg'
        break
      case 'png':
        output = await image.png({ compressionLevel: 8 }).toBuffer()
        mimeType = 'image/png'
        break
      case 'webp':
        output = await image.webp({ quality: 88 }).toBuffer()
        mimeType = 'image/webp'
        break
      default:
        throw new Error('不支持或无法识别的图片格式（仅支持 JPEG/PNG/WebP）')
    }

    const outMeta = await sharp(output).metadata()
    return {
      buffer: output,
      mimeType,
      width: outMeta.width || metadata.width,
      height: outMeta.height || metadata.height,
    }
  } catch (err: any) {
    if (err?.message?.includes('无法解析图片尺寸') || err?.message?.startsWith('图片尺寸')) {
      throw err
    }
    throw new Error('图片解码失败或文件已损坏')
  }
}

/** 校验视频文件（Magic Number + 大小限制），返回真实 MIME */
export function validateVideoBuffer(input: Buffer, declaredMimeType?: string): string {
  if (!input || input.length === 0) {
    throw new Error('文件为空')
  }
  if (input.length > MAX_VIDEO_SIZE) {
    throw new Error(`视频文件过大（最大 ${Math.round(MAX_VIDEO_SIZE / 1024 / 1024)}MB）`)
  }

  const detected = detectVideoType(input)
  if (!detected) {
    throw new Error('无法识别的视频格式（仅支持 MP4/WebM）')
  }
  if (declaredMimeType && declaredMimeType !== detected) {
    throw new Error('文件类型声明与实际内容不符')
  }
  return detected
}

/**
 * 轻量内存 Rate Limiter（固定窗口计数）。
 * 适用于小型单体：单实例内存即可，无需 Redis。
 * 多个限制维度可用不同 prefix 组合（IP / 用户名 / 邮箱 / 全局）。
 */

export interface RateLimitOptions {
  /** 限制键前缀，如 "login:ip"、"login:user" */
  prefix: string
  /** 限制键（IP / 用户名 / 邮箱等） */
  key: string
  /** 窗口内允许的最大次数 */
  limit: number
  /** 窗口长度（毫秒） */
  windowMs: number
}

export interface RateLimitResult {
  ok: boolean
  /** 当前窗口已用次数 */
  used: number
  /** 剩余可放行次数 */
  remaining: number
  /** 需要等待的秒数（被限流时） */
  retryAfterSeconds: number
}

interface WindowEntry {
  count: number
  resetAt: number
}

const windows = new Map<string, WindowEntry>()

function bucketKey(prefix: string, key: string): string {
  return `${prefix}:${key}`
}

/** 清理过期窗口，防止内存膨胀 */
function sweep(): void {
  const now = Date.now()
  if (windows.size > 5000) {
    windows.forEach((v, k) => {
      if (v.resetAt < now) windows.delete(k)
    })
  }
}

export function rateLimit(options: RateLimitOptions): RateLimitResult {
  const now = Date.now()
  const key = bucketKey(options.prefix, options.key)
  sweep()

  let entry = windows.get(key)
  if (!entry || entry.resetAt < now) {
    entry = { count: 0, resetAt: now + options.windowMs }
    windows.set(key, entry)
  }

  const used = entry.count
  const remaining = Math.max(0, options.limit - used)
  const retryAfterSeconds = Math.max(1, Math.ceil((entry.resetAt - now) / 1000))

  if (used >= options.limit) {
    return { ok: false, used, remaining: 0, retryAfterSeconds }
  }

  entry.count += 1
  return { ok: true, used: used + 1, remaining: Math.max(0, options.limit - used - 1), retryAfterSeconds }
}

/**
 * 登录失败锁定：连续失败达到阈值后，对 (IP, 用户名) 组合锁定一段时间。
 * 锁定期间直接拒绝，并返回剩余等待时间（指数退避的简单实现）。
 */
export interface LoginLockOptions {
  /** 连续失败多少次后锁定 */
  maxFailures: number
  /** 首次锁定毫秒数 */
  baseLockMs: number
  /** 最大锁定毫秒数 */
  maxLockMs: number
}

const failures = new Map<string, { count: number; lockedUntil: number; lockMs: number }>()

export function checkLoginLock(lockKey: string, options: LoginLockOptions): { locked: boolean; retryAfterSeconds: number } {
  const now = Date.now()
  const entry = failures.get(lockKey)
  if (!entry || entry.lockedUntil <= now) {
    return { locked: false, retryAfterSeconds: 0 }
  }
  return { locked: true, retryAfterSeconds: Math.ceil((entry.lockedUntil - now) / 1000) }
}

export function recordLoginFailure(lockKey: string, options: LoginLockOptions): { locked: boolean; retryAfterSeconds: number } {
  const now = Date.now()
  const prev = failures.get(lockKey)
  const count = (prev ? prev.count : 0) + 1
  const lockMs = Math.min(options.baseLockMs * Math.pow(2, count - 1), options.maxLockMs)

  const entry = {
    count,
    lockedUntil: now + lockMs,
    lockMs,
  }
  failures.set(lockKey, entry)
  return { locked: true, retryAfterSeconds: Math.ceil(lockMs / 1000) }
}

export function clearLoginFailures(lockKey: string): void {
  failures.delete(lockKey)
}

// ============================================================
// 多副本准备（B）：共享限流抽象
//
// 上面两个函数是**进程内**固定窗口实现，默认行为保持不变（未配置 REDIS_URL 时
// 所有调用点继续走它们）。下面这层接口 + MemoryRateLimiter 提供统一的异步形态，
// 由 rate-limit-factory.ts 在配置 REDIS_URL 时切换成 Redis 实现（跨副本共享）。
// ============================================================

export interface LoginLockState {
  locked: boolean
  retryAfterSeconds: number
}

/** 限流器接口：内存实现与 Redis 实现共同遵守；调用方使用 rateLimitShared 即可 */
export interface RateLimiter {
  consume(options: RateLimitOptions): Promise<RateLimitResult>
  checkLock(lockKey: string, options: LoginLockOptions): Promise<LoginLockState>
  recordFailure(lockKey: string, options: LoginLockOptions): Promise<LoginLockState>
  clearFailures(lockKey: string): Promise<void>
}

/** 内存实现：直接复用上面的同步函数，保证「未配置 Redis 时行为与改造前完全一致」 */
export class MemoryRateLimiter implements RateLimiter {
  async consume(options: RateLimitOptions): Promise<RateLimitResult> {
    return rateLimit(options)
  }

  async checkLock(lockKey: string, options: LoginLockOptions): Promise<LoginLockState> {
    return checkLoginLock(lockKey, options)
  }

  async recordFailure(lockKey: string, options: LoginLockOptions): Promise<LoginLockState> {
    return recordLoginFailure(lockKey, options)
  }

  async clearFailures(lockKey: string): Promise<void> {
    clearLoginFailures(lockKey)
  }
}

export const memoryRateLimiter = new MemoryRateLimiter()

/**
 * Redis 客户端（多副本准备 · B）。
 *
 * 定位：**可选**共享状态后端。未配置 REDIS_URL 时所有调用方都走纯内存实现，
 * 行为与改造前完全一致；配置后限流与缓存跨副本共享。
 *
 * 三条硬约束（评审 /api/health 与多副本清单的落地要求）：
 *  1) 连接必须快失败：connectTimeout=500ms + ping 探活，失败立即降级内存而不是把请求挂住；
 *  2) 降级只打**一次**告警日志（avoid 每请求刷屏），并在 60s 冷却期内不再重试连接；
 *  3) 绝不因 Redis 不可用而让业务失败：调用方拿到 null 后自行回退内存。
 */

/** 连接/命令超时（评审要求 500ms） */
export const REDIS_TIMEOUT_MS = 500

/** 连接失败后的冷却期：这段时间内直接按「不可用」处理，避免每个请求都尝试重连 */
const RECONNECT_COOLDOWN_MS = 60_000

/**
 * 对外暴露的最小命令集合：只保留缓存/限流真正用到的命令。
 * 这样单测可以用一个 Map 实现 fake client，不需要跑真的 Redis。
 */
export interface RedisClient {
  get(key: string): Promise<string | null>
  setPx(key: string, value: string, ttlMs: number): Promise<void>
  del(keys: string[]): Promise<number>
  sadd(key: string, members: string[]): Promise<number>
  smembers(key: string): Promise<string[]>
  expireSeconds(key: string, seconds: number): Promise<number>
  incr(key: string): Promise<number>
  pexpire(key: string, ms: number): Promise<number>
  pttl(key: string): Promise<number>
  /** 用 SCAN 按前缀收集 key（生产禁用 KEYS） */
  scanPrefix(prefix: string): Promise<string[]>
  ping(): Promise<void>
}

/** ioredis 实例的最小形状（v5/v6 都兼容；用结构类型避免被版本类型细节绊住） */
interface IoredisLike {
  connect(): Promise<void>
  ping(): Promise<string>
  get(key: string): Promise<string | null>
  set(key: string, value: string, mode: 'PX', ttlMs: number): Promise<unknown>
  del(...keys: string[]): Promise<number>
  sadd(key: string, ...members: string[]): Promise<number>
  smembers(key: string): Promise<string[]>
  expire(key: string, seconds: number): Promise<number>
  incr(key: string): Promise<number>
  pexpire(key: string, ms: number): Promise<number>
  pttl(key: string): Promise<number>
  scan(cursor: string, ...args: (string | number)[]): Promise<[string, string[]]>
  on(event: 'error', listener: (error: Error) => void): unknown
  quit(): Promise<unknown>
  disconnect(): void
}

class IoredisAdapter implements RedisClient {
  constructor(private readonly redis: IoredisLike) {}

  async get(key: string): Promise<string | null> {
    return this.redis.get(key)
  }

  async setPx(key: string, value: string, ttlMs: number): Promise<void> {
    await this.redis.set(key, value, 'PX', Math.max(1, ttlMs))
  }

  async del(keys: string[]): Promise<number> {
    if (keys.length === 0) return 0
    return this.redis.del(...keys)
  }

  async sadd(key: string, members: string[]): Promise<number> {
    if (members.length === 0) return 0
    return this.redis.sadd(key, ...members)
  }

  async smembers(key: string): Promise<string[]> {
    return this.redis.smembers(key)
  }

  async expireSeconds(key: string, seconds: number): Promise<number> {
    return this.redis.expire(key, Math.max(1, Math.ceil(seconds)))
  }

  async incr(key: string): Promise<number> {
    return this.redis.incr(key)
  }

  async pexpire(key: string, ms: number): Promise<number> {
    return this.redis.pexpire(key, Math.max(1, Math.ceil(ms)))
  }

  async pttl(key: string): Promise<number> {
    return this.redis.pttl(key)
  }

  async scanPrefix(prefix: string): Promise<string[]> {
    const found: string[] = []
    let cursor = '0'
    // 上限保护：前缀扫描最多 20 轮（COUNT 500），避免异常数据把请求拖死
    for (let round = 0; round < 20; round++) {
      const [next, keys] = await this.redis.scan(cursor, 'MATCH', prefix + '*', 'COUNT', 500)
      found.push(...keys)
      cursor = next
      if (cursor === '0') break
    }
    return found
  }

  async ping(): Promise<void> {
    await this.redis.ping()
  }
}

let client: RedisClient | null = null
let lastFailureAt = 0
let degradedLogged = false
/** 测试注入点：返回 null 表示「Redis 不可用」，返回 fake 表示「可用」 */
let testProvider: (() => Promise<RedisClient | null>) | null = null

/** 配置了 REDIS_URL 才启用共享后端 */
export function redisUrl(): string | null {
  const url = (process.env.REDIS_URL || '').trim()
  return url || null
}

export function redisConfigured(): boolean {
  return redisUrl() !== null
}

/** 降级告警只打一次（一次故障 = 一条日志，不刷屏） */
export function logRedisDegradedOnce(context: string, error?: unknown): void {
  if (degradedLogged) return
  degradedLogged = true
  const detail = error instanceof Error ? error.message : error ? String(error) : ''
  console.warn('[redis] 共享后端不可用，已降级为进程内存实现（Redis 恢复后需重启或等冷却期重连）:', context, detail)
}

/** 给 Promise 加超时（Redis 卡住时不能把请求挂死） */
export function withTimeout<T>(promise: Promise<T>, ms: number = REDIS_TIMEOUT_MS): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('redis timeout ' + ms + 'ms')), ms)
    promise.then(
      (value) => {
        clearTimeout(timer)
        resolve(value)
      },
      (error) => {
        clearTimeout(timer)
        reject(error)
      },
    )
  })
}

async function connectIoredis(url: string): Promise<RedisClient> {
  const mod: any = await import('ioredis')
  const RedisCtor = mod?.default ?? mod?.Redis ?? mod
  const redis: IoredisLike = new RedisCtor(url, {
    lazyConnect: true,
    connectTimeout: REDIS_TIMEOUT_MS,
    // 单command 最多重试 1 次：健康检查/限流不能被重试拖长
    maxRetriesPerRequest: 1,
    enableOfflineQueue: false,
    retryStrategy: (times: number) => (times > 3 ? null : Math.min(times * 200, 1000)),
  })
  redis.on('error', (error) => logRedisDegradedOnce('连接异常', error))
  await withTimeout(redis.connect())
  await withTimeout(redis.ping())
  return new IoredisAdapter(redis)
}

/**
 * 取共享 Redis 客户端；未配置 / 连接失败 / 冷却期内一律返回 null（调用方回退内存）。
 * 连接被缓存：成功的连接在进程生命周期内复用。
 */
export async function getRedisClient(): Promise<RedisClient | null> {
  if (testProvider) return testProvider()
  const url = redisUrl()
  if (!url) return null
  if (client) return client
  if (Date.now() - lastFailureAt < RECONNECT_COOLDOWN_MS) return null
  try {
    client = await connectIoredis(url)
    return client
  } catch (error) {
    lastFailureAt = Date.now()
    logRedisDegradedOnce('连接失败', error)
    return null
  }
}

/** 测试用：注入 provider（null 恢复真实连接） */
export function __setRedisClientProviderForTest(provider: (() => Promise<RedisClient | null>) | null): void {
  testProvider = provider
  client = null
  lastFailureAt = 0
  degradedLogged = false
}

/** 测试用：重置模块状态 */
export function __resetRedisForTest(): void {
  try {
    client = null
    lastFailureAt = 0
    degradedLogged = false
    testProvider = null
  } catch {
    // ignore
  }
}

/**
 * 存储抽象：本地文件系统（默认）或 S3 兼容对象存储（MinIO / Cloudflare R2 / 阿里云 OSS）。
 * 配置 STORAGE_ENDPOINT + STORAGE_ACCESS_KEY + STORAGE_SECRET_KEY + STORAGE_BUCKET 后自动启用对象存储。
 */
import fs from 'fs'
import { randomUUID } from 'crypto'
import path from 'path'
import {
  S3Client,
  PutObjectCommand,
  DeleteObjectCommand,
  GetObjectCommand,
} from '@aws-sdk/client-s3'

export interface StoredFile {
  key: string
  url: string
  size: number
  contentType: string
}

export interface StorageService {
  upload(file: Buffer, key: string, contentType: string): Promise<StoredFile>
  delete(key: string): Promise<void>
  getUrl(key: string): Promise<string>
}

export class LocalStorageService implements StorageService {
  private uploadDir: string

  constructor(uploadDir?: string) {
    this.uploadDir = uploadDir || process.env.UPLOAD_DIR || 'public/uploads'
  }

  async upload(file: Buffer, key: string, contentType: string): Promise<StoredFile> {
    const filePath = path.join(this.uploadDir, key)
    await fs.promises.mkdir(path.dirname(filePath), { recursive: true })
    await fs.promises.writeFile(filePath, file)
    return {
      key,
      url: `/uploads/${key}`,
      size: file.length,
      contentType,
    }
  }

  async delete(key: string): Promise<void> {
    const filePath = path.join(this.uploadDir, key)
    await fs.promises.unlink(filePath).catch(() => {})
  }

  async getUrl(key: string): Promise<string> {
    return `/uploads/${key}`
  }
}

export const localStorageService = new LocalStorageService()

/** S3 兼容对象存储（MinIO / R2 / OSS） */
export class S3StorageService implements StorageService {
  private client: S3Client
  private bucket: string
  private publicBaseUrl: string

  constructor() {
    const endpoint = process.env.STORAGE_ENDPOINT
    const accessKey = process.env.STORAGE_ACCESS_KEY
    const secretKey = process.env.STORAGE_SECRET_KEY
    const bucket = process.env.STORAGE_BUCKET

    if (!endpoint || !accessKey || !secretKey || !bucket) {
      throw new Error('[S3StorageService] 缺少 STORAGE_* 环境变量配置')
    }

    this.bucket = bucket
    this.publicBaseUrl = (process.env.STORAGE_PUBLIC_BASE_URL || endpoint).replace(/\/+$/, '')

    this.client = new S3Client({
      endpoint,
      region: process.env.STORAGE_REGION || 'auto',
      credentials: { accessKeyId: accessKey, secretAccessKey: secretKey },
      forcePathStyle: true,
    })
  }

  async upload(file: Buffer, key: string, contentType: string): Promise<StoredFile> {
    await this.client.send(
      new PutObjectCommand({
        Bucket: this.bucket,
        Key: key,
        Body: file,
        ContentType: contentType,
      })
    )
    return {
      key,
      url: `${this.publicBaseUrl}/${key}`,
      size: file.length,
      contentType,
    }
  }

  async delete(key: string): Promise<void> {
    await this.client.send(
      new DeleteObjectCommand({ Bucket: this.bucket, Key: key })
    )
  }

  async getUrl(key: string): Promise<string> {
    return `${this.publicBaseUrl}/${key}`
  }

  /** 生成安全随机对象键 */
  static makeKey(prefix: string, ext: string): string {
    const rand = randomUUID().slice(0, 8)
    const ts = Date.now()
    return `${prefix}/${ts}-${rand}.${ext}`
  }
}

let storageServiceInstance: StorageService | null = null

/** 返回全局存储服务：配置了 STORAGE_* 时使用对象存储，否则使用本地文件系统 */
export function getStorageService(): StorageService {
  if (storageServiceInstance) return storageServiceInstance

  if (process.env.STORAGE_ENDPOINT && process.env.STORAGE_BUCKET) {
    storageServiceInstance = new S3StorageService()
  } else {
    storageServiceInstance = localStorageService
  }
  return storageServiceInstance
}

/**
 * Album：纪念相册（基于独立 Media 模型 + 对象/本地存储）
 */
import { prisma } from '../../db'
import { scopedWhere } from '../../visibility'
import { myActiveSpaceIds, spaceScopedWhere } from '../access/space-scope'
import { randomUUID } from 'crypto'
import { getStorageService } from '../../infrastructure/storage'
import { absoluteMediaUrl } from '../../media-url'
import { generateMediaVariants } from '../../infrastructure/media-variants'
import { recordSyncTombstone } from '../../api/sync-tombstone'
import {
  validateAndSanitizeImage,
  MAX_IMAGE_COUNT,
} from '../../infrastructure/media-validation'

export interface AlbumItem {
  id: number
  title: string
  description: string | null
  coverUrl: string | null
  mediaCount: number
  date: string | null
  createdAt: string
  updatedAt: string
  visibility: string
  spaceId: number | null
  userId: number | null
  coverMediaId: number | null
  locationId: number | null
  /** v3.1 M1-A1：关联旅行（一个相册 = 一次旅行/一座城市） */
  travelId: number | null
  /** 多元场景：关联旅行的类型/同行者（相册按类型分组 + 按同行者筛选） */
  travelType: string | null
  companions: unknown
}

export interface AlbumMediaItem {
  id: number
  url: string
  mimeType: string
  size: number
  width: number | null
  height: number | null
  createdAt: string
  /** 三级缩略（Stage C2）：列表/详情/原图按需取用 */
  thumbnailUrl?: string | null
  previewUrl?: string | null
}

function variantUrl(media: any, variant: string): string | null {
  const v = media?.variants?.find((x: any) => x.variant === variant)
  return v?.storageKey ? mediaPublicUrl(v.storageKey) : null
}

export interface UploadFile {
  name: string
  buffer: Buffer
  mimeType: string
}

const EXT_BY_MIME: Record<string, string> = {
  'image/jpeg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp',
}

/** 根据存储配置计算媒体的公开访问 URL */
export function mediaPublicUrl(storageKey: string): string {
  if (process.env.STORAGE_ENDPOINT && process.env.STORAGE_BUCKET) {
    const base = (process.env.STORAGE_PUBLIC_BASE_URL || process.env.STORAGE_ENDPOINT).replace(/\/+$/, '')
    return absoluteMediaUrl(`${base}/${storageKey}`) ?? `${base}/${storageKey}`
  }
  return absoluteMediaUrl(`/uploads/${storageKey}`) ?? `/uploads/${storageKey}`
}

function mapAlbum(a: any): AlbumItem {
  return {
    id: a.id,
    title: a.title,
    description: a.description,
    coverUrl: a.coverMedia
      ? (variantUrl(a.coverMedia, 'THUMBNAIL') ?? mediaPublicUrl(a.coverMedia.storageKey))
      : null,
    mediaCount: a._count?.items ?? 0,
    date: a.date ? (a.date instanceof Date ? a.date.toISOString() : String(a.date)) : null,
    createdAt: a.createdAt instanceof Date ? a.createdAt.toISOString() : String(a.createdAt),
    updatedAt: a.updatedAt instanceof Date ? a.updatedAt.toISOString() : String(a.updatedAt),
    visibility: a.visibility ?? 'SPACE',
    spaceId: a.spaceId ?? null,
    userId: a.userId ?? null,
    coverMediaId: a.coverMediaId ?? null,
    locationId: a.locationId ?? null,
    travelId: a.travelId ?? null,
    travelType: a.travel?.travelType ?? null,
    companions: a.travel?.companions ?? null,
  }
}

/**
 * 某空间下的相册（空间详情页用）。
 * 需调用方自行保证空间成员身份（路由层用 `requireSpaceRole`），
 * 这里只做「空间内的相册」这一个维度的过滤。
 */
export async function listAlbumsForSpace(spaceId: number, limit = 60): Promise<AlbumItem[]> {
  const rows = await prisma.album.findMany({
    where: { spaceId },
    orderBy: { createdAt: 'desc' },
    take: Math.min(Math.max(limit, 1), 200),
    include: {
      coverMedia: { include: { variants: true } },
      _count: { select: { items: true } },
      travel: { select: { travelType: true, companions: true } },
    },
  })
  return rows.map(mapAlbum)
}

/**
 * 相册可见性 where 片段。
 *
 * **P0 修复**：原先 `listAlbums` / `getAlbum` 直接用 `scopedWhere(userId)`，
 * 只认「我名下的 ∪ 公开的」，**不含 `spaceId ∈ 我的活跃空间`** —— 而写入侧
 * `canManageAlbum` 又明确允许空间 OWNER/MEMBER 管理。于是出现
 * 「同空间成员的相册在列表里看不到、直接开链接又能看、还能改」的读写口径不一致。
 * 这和第三轮已经修掉的 `listTravels` 是同一个 bug，相册漏修了。
 *
 * 现在与 `travel.service.listTravels` 共用 `lib/modules/access/space-scope`。
 */
async function albumVisibilityWhere(
  userId?: number | null,
  username?: string | null,
): Promise<Record<string, unknown>> {
  const spaceIds = await myActiveSpaceIds(userId, username)
  // 空间内的相册仍需尊重自身可见性：PRIVATE 的相册即使同空间也不对成员开放。
  return spaceScopedWhere(userId, 'userId', spaceIds, ['SPACE', 'PUBLIC'])
}

export async function listAlbums(
  userId?: number | null,
  username?: string | null,
): Promise<AlbumItem[]> {
  const rows = await prisma.album.findMany({
    where: (await albumVisibilityWhere(userId, username)) as any,
    orderBy: { createdAt: 'desc' },
    include: {
      coverMedia: { include: { variants: true } },
      _count: { select: { items: true } },
      // 多元场景：附带关联旅行的类型/同行者，供相册按类型分组 + 按同行者筛选
      travel: { select: { travelType: true, companions: true } },
    },
  })
  return rows.map(mapAlbum)
}

export async function getAlbum(
  albumId: number,
  userId?: number | null,
  username?: string | null,
): Promise<(AlbumItem & { media: AlbumMediaItem[] }) | null> {
  const album = await prisma.album.findFirst({
    where: { ...(await albumVisibilityWhere(userId, username)), id: albumId } as any,
    include: {
      coverMedia: { include: { variants: true } },
      _count: { select: { items: true } },
      items: {
        orderBy: { sortOrder: 'asc' },
        include: { media: { include: { variants: true } } },
      },
    },
  })
  if (!album) return null
  return {
    ...mapAlbum(album),
    media: album.items
      .map((it: any) => it.media)
      .filter(Boolean)
      .map((m: any) => ({
        id: m.id,
        url: mediaPublicUrl(m.storageKey),
        mimeType: m.mimeType,
        size: m.size,
        width: m.width,
        height: m.height,
        createdAt: m.createdAt instanceof Date ? m.createdAt.toISOString() : String(m.createdAt),
        thumbnailUrl: variantUrl(m, 'THUMBNAIL'),
        previewUrl: variantUrl(m, 'PREVIEW'),
      })),
  }
}

export interface CreateAlbumInput {
  title: string
  description?: string
  date?: string
  userId?: number | null
  isPublic?: boolean
  /** v3.1 M1-A1：关联旅行 */
  travelId?: number | null
}

export async function createAlbum(input: CreateAlbumInput): Promise<{ id: number }> {
  const row = await prisma.album.create({
    data: {
      title: input.title,
      description: input.description || null,
      date: input.date ? new Date(input.date) : null,
      userId: input.userId ?? null,
      isPublic: input.isPublic ?? false,
      travelId: input.travelId ?? null,
    },
  })
  return { id: row.id }
}

export async function updateAlbum(id: number, input: Partial<CreateAlbumInput>): Promise<void> {
  const data: any = {}
  if (input.title !== undefined) data.title = input.title
  if (input.description !== undefined) data.description = input.description || null
  if (input.date !== undefined) data.date = input.date ? new Date(input.date) : null
  if (input.isPublic !== undefined) data.isPublic = input.isPublic
  if (input.travelId !== undefined) data.travelId = input.travelId || null
  await prisma.album.update({ where: { id }, data })
}

/**
 * 删除前引用检查：同一 Media 可挂多个相册（AlbumMedia @@unique([albumId, mediaId])），
 * 也可能被回忆引用（MemoryMedia）。仍被引用的媒体只解除当前关联，不删 Media 记录与存储文件，
 * 避免删 A 相册打碎 B 相册/回忆里的同一张图。
 */
async function mediaReferencedElsewhere(mediaIds: number[], excludeAlbumId?: number): Promise<Set<number>> {
  const refs = new Set<number>()
  if (mediaIds.length === 0) return refs
  const [otherAlbumLinks, memoryLinks] = await Promise.all([
    prisma.albumMedia.findMany({
      where: {
        mediaId: { in: mediaIds },
        ...(excludeAlbumId ? { albumId: { not: excludeAlbumId } } : {}),
      },
      select: { mediaId: true },
    }),
    prisma.memoryMedia.findMany({ where: { mediaId: { in: mediaIds } }, select: { mediaId: true } }),
  ])
  for (const l of otherAlbumLinks) refs.add(l.mediaId)
  for (const l of memoryLinks) refs.add(l.mediaId)
  return refs
}

export async function deleteAlbum(id: number, actorUserId?: number | null): Promise<void> {
  // 先收集媒体，删除相册后一并清理 Media 记录与存储文件（避免孤儿数据）；
  // 仍被其他相册/回忆引用的媒体只随级联解除本相册关联，不删记录与文件。
  const albumRow = await prisma.album
    .findUnique({ where: { id }, select: { userId: true } })
    .catch(() => null)
  const links = await prisma.albumMedia.findMany({
    where: { albumId: id },
    select: { mediaId: true, media: { select: { storageKey: true } } },
  })
  const mediaIds = links.map((l) => l.mediaId)
  const referenced = await mediaReferencedElsewhere(mediaIds, id)
  const deletableIds = mediaIds.filter((mid) => !referenced.has(mid))
  const storageKeys = links
    .filter((l) => !referenced.has(l.mediaId))
    .map((l) => l.media?.storageKey)
    .filter(Boolean) as string[]

  if (deletableIds.length > 0) {
    await prisma.media.deleteMany({ where: { id: { in: deletableIds } } }).catch(() => {})
  }
  await prisma.album.delete({ where: { id } })

  const storage = getStorageService()
  for (const key of storageKeys) {
    storage.delete(key).catch(() => {})
  }
  // B4：删除墓碑（best-effort）—— 行已删除，墓碑失败不影响主流程
  await recordSyncTombstone('Album', id, actorUserId ?? albumRow?.userId ?? null)
}

/** 上传图片到相册：校验 + 重新编码 → 存储 → Media + AlbumMedia 记录 */
export async function addMediaToAlbum(albumId: number, files: UploadFile[], userId?: number | null): Promise<AlbumMediaItem[]> {
  if (!files || files.length === 0) throw new Error('未上传任何文件')
  if (files.length > MAX_IMAGE_COUNT) throw new Error(`单次最多上传 ${MAX_IMAGE_COUNT} 张图片`)

  const album = await prisma.album.findUnique({ where: { id: albumId } })
  if (!album) throw new Error('相册不存在')

  const storage = getStorageService()
  const created: AlbumMediaItem[] = []

  for (const file of files) {
    const safe = await validateAndSanitizeImage(file.buffer, file.mimeType)
    const ext = EXT_BY_MIME[safe.mimeType] || 'jpg'
    const key = `albums/${albumId}/${Date.now()}-${randomUUID().slice(0, 8)}.${ext}`
    const stored = await storage.upload(safe.buffer, key, safe.mimeType)

    const media = await prisma.media.create({
      data: {
        type: 'IMAGE',
        storageKey: key,
        mimeType: safe.mimeType,
        size: stored.size,
        width: safe.width,
        height: safe.height,
        visibility: 'SPACE',
        userId: userId ?? null,
      },
    })
    // 生成并持久化媒体变体（缩略图/预览/模糊占位）
    try {
      const variants = await generateMediaVariants(safe.buffer)
      for (const v of variants) {
        const variantKey = key.replace(/\.[a-z0-9]+$/i, '-' + v.variant.toLowerCase() + '.jpg')
        await storage.upload(v.buffer, variantKey, v.mimeType)
        await prisma.mediaVariant.create({
          data: {
            mediaId: media.id,
            variant: v.variant as any,
            storageKey: variantKey,
            width: v.width,
            height: v.height,
            size: v.size,
            mimeType: v.mimeType,
          },
        })
      }
    } catch (error) {
      console.error('[Album] 生成媒体变体失败:', error)
    }

    const maxOrder = await prisma.albumMedia.aggregate({
      where: { albumId },
      _max: { sortOrder: true },
    })
    await prisma.albumMedia.create({
      data: {
        albumId,
        mediaId: media.id,
        sortOrder: (maxOrder._max.sortOrder ?? -1) + 1,
      },
    })

    // 未设置封面时使用第一张
    if (!album.coverMediaId) {
      await prisma.album.update({ where: { id: albumId }, data: { coverMediaId: media.id } })
    }

    created.push({
      id: media.id,
      url: mediaPublicUrl(key),
      mimeType: safe.mimeType,
      size: stored.size,
      width: safe.width,
      height: safe.height,
      createdAt: media.createdAt instanceof Date ? media.createdAt.toISOString() : String(media.createdAt),
    })
  }

  return created
}

/** 从相册移除媒体（删除关联、Media 记录与存储文件） */
export async function removeMediaFromAlbum(albumId: number, mediaId: number): Promise<void> {
  const link = await prisma.albumMedia.findUnique({
    where: { albumId_mediaId: { albumId, mediaId } },
  })
  if (!link) throw new Error('媒体不在该相册中')

  await prisma.albumMedia.delete({ where: { id: link.id } })

  // 若被删除的是封面，重新挑选
  const album = await prisma.album.findUnique({ where: { id: albumId } })
  if (album?.coverMediaId === mediaId) {
    const first = await prisma.albumMedia.findFirst({
      where: { albumId },
      orderBy: { sortOrder: 'asc' },
      select: { mediaId: true },
    })
    await prisma.album.update({
      where: { id: albumId },
      data: { coverMediaId: first?.mediaId ?? null },
    })
  }

  const media = await prisma.media.findUnique({ where: { id: mediaId } })
  if (media) {
    // 仍被其他相册或回忆引用时保留媒体与文件，只解除本相册关联
    const referenced = await mediaReferencedElsewhere([mediaId], albumId)
    if (referenced.has(mediaId)) return
    await prisma.media.delete({ where: { id: mediaId } }).catch(() => {})
    if (media.storageKey) {
      getStorageService().delete(media.storageKey).catch(() => {})
    }
  }
}

// ============================================================
// 3.6 子资源所有权校验：判断用户是否可管理该相册。
// 规则：直接归属（userId）或所属空间（spaceId）的活跃 OWNER/MEMBER。
// ============================================================
export async function canManageAlbum(albumId: number, userId: number | null | undefined): Promise<boolean> {
  if (!userId) return false
  const album = await prisma.album.findUnique({
    where: { id: albumId },
    select: { userId: true, spaceId: true },
  })
  if (!album) return false
  if (album.userId === userId) return true
  if (album.spaceId) {
    const member = await prisma.spaceMember.findFirst({
      where: { spaceId: album.spaceId, userId, status: 'ACTIVE', role: { in: ['OWNER', 'MEMBER'] } },
      select: { id: true },
    })
    if (member) return true
  }
  return false
}

/**
 * Travel Book（旅行画册 2.0 Phase 2）：把一次旅行编排成一本「旅行摄影杂志」。
 * 数据来源（自动聚合，无需手动创建）：
 *  - Travel 模型：Travel(封面) → TravelDay(章节) → Memory(回忆) → Media(照片)。有 Travel 数据时优先。
 *  - Post 旅行文章：按城市/日期自动生成画册（覆盖绝大多数存量内容，Travel 为 0 时也能出册）。
 * 复用原图/缩略图/预览三级变体，列表/封面用 THUMBNAIL、画册页用 PREVIEW。
 * 不改 schema、不绕过权限层（scopedWhere 归属/公开过滤）。
 */
import { prisma } from '../../db'
import { scopedWhere } from '../../visibility'
import { skipDbOnBuild } from '../../db-guard'
import { getPostService } from '../../container'
import { findCityByName } from '../../../data/cities'
import { resolveLocalUrlVariants, resolveLocalImageDimensions } from '../../infrastructure/media-variants'
import { absoluteMediaUrl } from '../../media-url'

export interface TravelBookChapterPhoto {
  id: number
  thumbnailUrl: string | null
  previewUrl: string | null
  blurUrl: string | null
  /** 原始图 URL（用于放大镜/查看大图按需加载，避免默认传输原图） */
  fullUrl: string | null
  width: number | null
  height: number | null
}

export interface TravelBookChapter {
  id: number
  index: number
  date: string | null
  title: string | null
  summary: string | null
  itinerary: { id: number; title: string; startTime: string | null; endTime: string | null; type: string; notes: string | null; locationName: string | null }[]
  memories: { id: number; title: string; content: string | null; mood: string | null; happenedAt: string | null; photos: TravelBookChapterPhoto[] }[]
  photos: TravelBookChapterPhoto[]
}

export interface TravelBookData {
  /** 稳定唯一键：Travel 画册 `travel:{id}`，Post 城市画册 `city:{城市名}`（React key / 伪随机种子用） */
  bookKey: string
  travelId: number
  slug: string
  title: string
  description: string | null
  location: string | null
  startDate: string | null
  endDate: string | null
  travelType: string | null
  companions: unknown
  coverThumb: string | null
  coverPreview: string | null
  coverBlur: string | null
  dayCount: number
  photoCount: number
  chapters: TravelBookChapter[]
}

function iso(v: Date | string | null | undefined): string | null {
  if (!v) return null
  const d = v instanceof Date ? v : new Date(v)
  return isNaN(d.getTime()) ? null : d.toISOString()
}

function storageBase(): string | null {
  if (process.env.STORAGE_ENDPOINT && process.env.STORAGE_BUCKET) {
    return (process.env.STORAGE_PUBLIC_BASE_URL || process.env.STORAGE_ENDPOINT).replace(/\/+$/, '')
  }
  return null
}

function mediaUrl(storageKey: string): string {
  const base = storageBase()
  return base ? (absoluteMediaUrl(`${base}/${storageKey}`) ?? `${base}/${storageKey}`) : (absoluteMediaUrl(`/uploads/${storageKey}`) ?? `/uploads/${storageKey}`)
}

function variantOf(media: any, variant: string): string | null {
  const v = media?.variants?.find((x: any) => x.variant === variant)
  return v?.storageKey ? mediaUrl(v.storageKey) : null
}

function toPhoto(m: any): TravelBookChapterPhoto {
  return {
    id: m.id,
    thumbnailUrl: variantOf(m, 'THUMBNAIL') ?? mediaUrl(m.storageKey),
    previewUrl: variantOf(m, 'PREVIEW') ?? mediaUrl(m.storageKey),
    // 无 BLUR 变体时返回 null（消费方回退缩略图占位），避免拿原图冒充模糊层多拉大图
    blurUrl: variantOf(m, 'BLUR'),
    fullUrl: mediaUrl(m.storageKey),
    width: m.width ?? null,
    height: m.height ?? null,
  }
}

async function listTravelModelBooks(userId?: number | null, travelId?: number): Promise<TravelBookData[]> {
  if (skipDbOnBuild()) return []

  // 只给「已归档」的旅行成册：confirmedAt 为空 = 进行中的草稿，
  // 用户在首页明确点「完成并归档」之后才进画册（真机需求）
  const where = { ...(scopedWhere(userId, 'ownerId') as any), confirmedAt: { not: null } }
  const travels = await prisma.travel.findMany({
    where: travelId === undefined ? where : { AND: [where, { id: travelId }] },
    orderBy: { startDate: 'desc' },
    include: {
      coverMedia: { include: { variants: true } },
      days: {
        orderBy: { sortOrder: 'asc' },
        include: {
          itineraryItems: {
            orderBy: { sortOrder: 'asc' },
            include: { location: { select: { name: true } } },
          },
          memories: {
            orderBy: { happenedAt: 'asc' },
            include: {
              media: { include: { variants: true } },
              mediaLinks: { include: { media: { include: { variants: true } } } },
            },
          },
        },
      },
    },
  })

  return travels.map((travel: any) => {
    let photoCount = 0
    const chapters: TravelBookChapter[] = (travel.days || []).map((d: any, idx: number) => {
      const memories = (d.memories || []).map((mem: any) => {
        const primary = (mem.media || []).map(toPhoto)
        const linked = (mem.mediaLinks || []).map((l: any) => toPhoto(l.media))
        const seen = new Set<number>()
        const photos = [...primary, ...linked].filter((p) => (seen.has(p.id) ? false : (seen.add(p.id), true)))
        return {
          id: mem.id,
          title: mem.title,
          content: mem.content ?? null,
          mood: mem.mood ?? null,
          happenedAt: iso(mem.happenedAt),
          photos,
        }
      })
      const seen = new Set<number>()
      const photos = memories.flatMap((mem: any) => mem.photos).filter((p: any) => (seen.has(p.id) ? false : (seen.add(p.id), true)))
      // 照片数按「章内去重后」累计，与翻页实际页数一致
      photoCount += photos.length
      return {
        id: d.id,
        index: idx + 1,
        date: iso(d.date),
        title: d.title,
        summary: d.summary,
        itinerary: (d.itineraryItems || []).map((it: any) => ({
          id: it.id,
          title: it.title,
          startTime: iso(it.startTime),
          endTime: iso(it.endTime),
          type: it.type,
          notes: it.notes,
          locationName: it.location?.name ?? null,
        })),
        memories,
        photos,
      }
    })

    return {
      bookKey: `travel:${travel.id}`,
      travelId: travel.id,
      slug: travel.slug,
      title: travel.title,
      description: travel.description ?? null,
      location: travel.location ?? null,
      startDate: iso(travel.startDate),
      endDate: iso(travel.endDate),
      travelType: travel.travelType ?? null,
      companions: travel.companions ?? null,
      coverThumb: travel.coverMedia ? (variantOf(travel.coverMedia, 'THUMBNAIL') ?? mediaUrl(travel.coverMedia.storageKey)) : absoluteMediaUrl(travel.cover ?? null),
      coverPreview: travel.coverMedia ? (variantOf(travel.coverMedia, 'PREVIEW') ?? mediaUrl(travel.coverMedia.storageKey)) : absoluteMediaUrl(travel.cover ?? null),
      coverBlur: travel.coverMedia ? variantOf(travel.coverMedia, 'BLUR') : null,
      dayCount: (travel.days || []).length,
      photoCount,
      chapters,
    }
  })
}

/**
 * 从存量旅行文章（Post）按城市自动生成画册：无需手动创建 Travel 记录。
 * 每个城市 = 一本画册；按日期聚合为章节；照片 = 文章封面+图片。
 *
 * @param onlyCity 只生成指定城市（规范化后的城市名）的画册——单本深链查询用，
 *                 避免为一个城市把全部文章都聚合一遍。
 */
async function listPostCityBooks(userId?: number | null, onlyCity?: string): Promise<TravelBookData[]> {
  if (skipDbOnBuild()) return []
  const postService = getPostService()
  const posts = await postService.getPostsHybrid('travel', userId)
  if (!posts || posts.length === 0) return []

  // 按城市匹配最近一次 Travel，取其旅行类型/同行者作为该城市画册的徽章数据。
  // Post 本身无 travelType/companions，这里用「城市名=地点」做稳定关联（取最新一条 Travel）。
  const travelByLocation = new Map<string, { travelType: string | null; companions: unknown }>()
  try {
    const travels = await prisma.travel.findMany({
      // 同上：草稿不参与画册的城市徽章
      where: { ...(scopedWhere(userId, 'ownerId') as any), confirmedAt: { not: null } },
      select: { location: true, travelType: true, companions: true, startDate: true },
      orderBy: { startDate: 'desc' },
    })
    for (const t of travels) {
      if (!t.location) continue
      const key = findCityByName(t.location)?.name ?? t.location
      const existing = travelByLocation.get(key)
      if (!existing) {
        travelByLocation.set(key, { travelType: t.travelType ?? null, companions: (t.companions as unknown) ?? null })
      }
    }
  } catch {
    // 查询失败不阻断画册生成，仅缺徽章
  }

  interface Chap {
    date: string | null
    title: string
    summary: string | null
    photos: TravelBookChapterPhoto[]
  }
  interface CityBox {
    name: string
    location: string
    travelType: string | null
    companions: unknown
    days: Map<string, Chap>
    photos: TravelBookChapterPhoto[]
  }
  const cityMap = new Map<string, CityBox>()
  const urlPhoto = new Map<string, Promise<TravelBookChapterPhoto>>()
  let photoSeq = 1
  const toUrlPhoto = (url: string): Promise<TravelBookChapterPhoto> => {
    let existing = urlPhoto.get(url)
    if (!existing) {
      existing = (async () => {
        const abs = (u: string | null | undefined) => absoluteMediaUrl(u)
        // 变体 URL 与像素尺寸都要：前者决定带宽，后者决定画册版式（单页 / 跨页出血）。
        // 两者都进缓存，重复 URL（封面 == images[0]）不会重复读盘。
        const [v, dim] = await Promise.all([
          resolveLocalUrlVariants(url),
          resolveLocalImageDimensions(url),
        ])
        return {
          id: photoSeq++,
          thumbnailUrl: abs(v?.thumbnailUrl ?? url),
          previewUrl: abs(v?.previewUrl ?? url),
          blurUrl: abs(v?.blurUrl),
          fullUrl: abs(url),
          width: dim?.width ?? null,
          height: dim?.height ?? null,
        }
      })()
      urlPhoto.set(url, existing)
    }
    return existing
  }

  for (const post of posts) {
    if (!post.location) continue
    const city = findCityByName(post.location)
    const name = city?.name ?? post.location
    // 单本查询：先按城市过滤，避免为打开一本册子把所有文章的图片变体都算一遍
    if (onlyCity !== undefined && name !== onlyCity) continue
    const raw = [...(post.cover ? [post.cover] : []), ...((post.images as string[]) || [])]
    if (raw.length === 0) continue
    const imgs = await Promise.all(raw.filter((u) => !(!u)).map(toUrlPhoto))

    let box = cityMap.get(name)
    if (!box) {
      const meta = travelByLocation.get(name)
      box = { name, location: post.location, travelType: meta?.travelType ?? null, companions: meta?.companions ?? null, days: new Map(), photos: [] }
      cityMap.set(name, box)
    }
    const date = post.date ?? ''
    let chap = box.days.get(date)
    if (!chap) {
      chap = { date: post.date ?? null, title: post.title, summary: post.description ?? null, photos: [] }
      box.days.set(date, chap)
    }
    const seenChap = new Set<number>(chap.photos.map((p) => p.id))
    for (const p of imgs) {
      if (seenChap.has(p.id)) continue
      seenChap.add(p.id)
      chap.photos.push(p)
    }
    const seenBox = new Set<number>(box.photos.map((p) => p.id))
    for (const p of imgs) {
      if (seenBox.has(p.id)) continue
      seenBox.add(p.id)
      box.photos.push(p)
    }
  }

  const books: TravelBookData[] = []
  let chapterSeq = 1
  for (const box of Array.from(cityMap.values())) {
    // 章节按日期升序（DAY 01 = 旅行第一天），与 /api/album 的聚合口径一致
    const days = Array.from(box.days.values()).sort((a, b) =>
      String(a.date || '').localeCompare(String(b.date || ''))
    )
    const chapters: TravelBookChapter[] = days.map((d) => ({
      id: chapterSeq++,
      index: 0, // 下方按序重排
      date: d.date,
      title: d.title,
      summary: d.summary,
      itinerary: [],
      memories: d.photos.length
        ? [{ id: d.photos[0].id, title: d.title, content: d.summary, mood: null, happenedAt: d.date, photos: d.photos }]
        : [],
      photos: d.photos,
    }))
    chapters.forEach((c, i) => (c.index = i + 1))
    books.push({
      bookKey: `city:${box.name}`,
      travelId: 0,
      slug: '',
      title: box.name,
      description: box.photos.length ? `${box.photos.length} 张照片 · ${chapters.length} 天` : null,
      location: box.location,
      startDate: days[0]?.date ?? null,
      endDate: null,
      travelType: box.travelType,
      companions: box.companions,
      coverThumb: box.photos[0]?.thumbnailUrl ?? null,
      coverPreview: box.photos[0]?.previewUrl ?? null,
      coverBlur: box.photos[0]?.blurUrl ?? null,
      dayCount: days.length,
      photoCount: box.photos.length,
      chapters,
    })
  }

  // 按最新日期排序（取每个城市最晚章节日期）
  books.sort((a, b) => new Date(b.startDate || 0).getTime() - new Date(a.startDate || 0).getTime())
  return books
}

/**
 * 旅行画册数据：合并「Travel 模型画册」+「旅行文章(Post)城市画册」。
 * Travel 优先：城市已有 **有内容**（photoCount>0）的 Travel 画册时，不再输出该城市的
 * Post 城市画册（避免同地两本内容重叠）。空壳 Travel（0 章 0 图）不覆盖城市册，
 * 否则存量文章照片会被一本空画册挡住。
 */
export async function listTravelBooks(userId?: number | null): Promise<TravelBookData[]> {
  const [travelBooks, cityBooks] = await Promise.all([
    listTravelModelBooks(userId),
    listPostCityBooks(userId),
  ])
  return mergeTravelAndCityBooks(travelBooks, cityBooks)
}

/** 「同城已有有内容的 Travel 画册」判定所需的城市 → 最大照片数 映射 */
function cityCoverageOf(travelBooks: TravelBookData[]): Map<string, number> {
  const travelCityPhotos = new Map<string, number>()
  for (const b of travelBooks) {
    const loc = b.location || ''
    if (!loc) continue
    const key = findCityByName(loc)?.name ?? loc
    travelCityPhotos.set(key, Math.max(travelCityPhotos.get(key) ?? 0, b.photoCount))
  }
  return travelCityPhotos
}

/**
 * 跨源合并 + 去重（Travel 覆盖同城 Post 城市册）。
 * 抽成纯函数：列表接口与单本接口必须用同一份判定，否则会出现
 * 「书架上没有这本，深链却能打开」或反之的口径漂移。
 */
function mergeTravelAndCityBooks(
  travelBooks: TravelBookData[],
  cityBooks: TravelBookData[],
): TravelBookData[] {
  if (travelBooks.length === 0) return cityBooks
  if (cityBooks.length === 0) return travelBooks

  const travelCityPhotos = cityCoverageOf(travelBooks)
  const isCityCovered = (b: TravelBookData): boolean => {
    if ((travelCityPhotos.get(b.title) ?? 0) > 0) return true
    const loc = b.location || ''
    if (!loc) return false
    return (travelCityPhotos.get(findCityByName(loc)?.name ?? loc) ?? 0) > 0
  }
  return [...travelBooks, ...cityBooks.filter((b) => !isCityCovered(b))]
}

/** 该城市是否已被「有内容的 Travel 画册」覆盖（单本查询用，只查 count 不拉明细） */
async function isCityBookCovered(cityName: string, userId?: number | null): Promise<boolean> {
  if (skipDbOnBuild()) return false
  if (!cityName) return false
  // 与 cityCoverageOf 同口径：只看「该城市是否有照片数 > 0 的 Travel」，不拉章节/照片明细
  const rows = await prisma.travel
    .findMany({
      // 草稿不算"有照片的城市"（与成册口径一致）
      where: { ...(scopedWhere(userId, 'ownerId') as any), confirmedAt: { not: null } },
      select: { location: true, _count: { select: { memories: true } } },
    })
    .catch(() => null)
  // 查询失败时不阻断（与 listPostCityBooks 里 try/catch 的策略一致）
  if (!rows) return false
  for (const row of rows as { location: string | null; _count: { memories: number } }[]) {
    const loc = row.location
    if (!loc) continue
    if ((findCityByName(loc)?.name ?? loc) !== cityName) continue
    if ((row._count?.memories ?? 0) > 0) return true
  }
  return false
}

/** 列表摘要：不含章节/照片明细（封面 + 统计），供画册墙渲染；打开某本再拉全书。 */
export async function listTravelBookSummaries(userId?: number | null) {
  const books = await listTravelBooks(userId)
  return books.map(({ chapters, ...rest }) => ({
    ...rest,
    dayCount: rest.dayCount || chapters.length,
  }))
}

/**
 * 按 bookKey 取单本完整画册（travel:{id} / city:{城市名}）。
 *
 * 【Album 2.0 P0】不再「取全库再 find」——那会让单本查询随画册数量/照片总数线性变慢
 * （旧实现是 listTravelBooks() 全量聚合后再 Array.find）。
 * 现在按 bookKey 直接命中：travel 册只拉那一本；城市册只拉该城市的文章。
 * 去重口径仍复用 mergeTravelAndCityBooks / isCityBookCovered，避免与列表接口漂移。
 */
export async function getTravelBookByKey(key: string, userId?: number | null): Promise<TravelBookData | null> {
  if (!key) return null

  if (key.startsWith('travel:')) {
    const id = Number(key.slice('travel:'.length))
    if (!Number.isFinite(id)) return null
    const books = await listTravelModelBooks(userId, id)
    return books[0] ?? null
  }

  if (key.startsWith('city:')) {
    const cityName = key.slice('city:'.length)
    if (!cityName) return null
    // 同城已有「有内容的 Travel 画册」时，这本城市册在列表里就是不存在的 → 深链也应 404
    if (await isCityBookCovered(cityName, userId)) return null
    const books = await listPostCityBooks(userId, cityName)
    return books.find((b) => b.bookKey === key) ?? null
  }

  return null
}

/**
 * Anniversary：纪念日管理（第一次见面/第一次旅行/生日等）
 */
import { prisma } from '../../db'
import { scopedWhere } from '../../visibility'
import { skipDbOnBuild } from '../../db-guard'

export interface AnniversaryRecord {
  id: number
  title: string
  date: string
  recurring: boolean
  description: string | null
  coverMediaId: number | null
  createdAt: string
  updatedAt: string
}

export interface AnniversaryInput {
  title: string
  date: Date
  recurring?: boolean
  description?: string
}

function map(r: any): AnniversaryRecord {
  return {
    id: r.id,
    title: r.title,
    date: r.date instanceof Date ? r.date.toISOString() : String(r.date),
    recurring: r.recurring,
    description: r.description,
    coverMediaId: r.coverMediaId,
    createdAt: r.createdAt instanceof Date ? r.createdAt.toISOString() : String(r.createdAt),
    updatedAt: r.updatedAt instanceof Date ? r.updatedAt.toISOString() : String(r.updatedAt),
  }
}

export async function listAnniversaries(userId?: number | null): Promise<AnniversaryRecord[]> {
  if (skipDbOnBuild()) return []
  const rows = await prisma.anniversary.findMany({
    where: scopedWhere(userId) as any,
    orderBy: { date: 'asc' },
  })
  return rows.map(map)
}

export async function createAnniversary(input: AnniversaryInput & { userId?: number | null; isPublic?: boolean }): Promise<{ id: number }> {
  const row = await prisma.anniversary.create({
    data: {
      title: input.title,
      date: input.date,
      recurring: input.recurring ?? true,
      description: input.description || null,
      userId: input.userId ?? null,
      isPublic: input.isPublic ?? false,
    },
  })
  return { id: row.id }
}

export async function updateAnniversary(id: number, input: Partial<AnniversaryInput>): Promise<void> {
  const data: any = {}
  if (input.title !== undefined) data.title = input.title
  if (input.date !== undefined) data.date = input.date
  if (input.recurring !== undefined) data.recurring = input.recurring
  if (input.description !== undefined) data.description = input.description || null
  if ((input as any).isPublic !== undefined) data.isPublic = (input as any).isPublic
  await prisma.anniversary.update({ where: { id }, data })
}

export async function deleteAnniversary(id: number): Promise<void> {
  await prisma.anniversary.delete({ where: { id } })
}

/** 计算下次纪念日的剩余天数 */
export function daysUntilNext(date: Date, recurring: boolean): number {
  const now = new Date()
  const target = new Date(date)

  if (!recurring) {
    return Math.max(0, Math.ceil((target.getTime() - now.getTime()) / 86400000))
  }

  // 周年纪念：计算下一次同月同日
  const next = new Date(now.getFullYear(), target.getMonth(), target.getDate())
  if (next.getTime() < now.setHours(0, 0, 0, 0)) {
    next.setFullYear(next.getFullYear() + 1)
  }
  return Math.ceil((next.getTime() - new Date(now).setHours(0, 0, 0, 0)) / 86400000)
}

/**
 * AuditLog：记录关键操作（登录/退出/增删改/权限变更/上传等）。
 * 对情侣共同编辑场景具有审计价值。
 */
import { prisma } from '../../db'
import { hashIp } from '../../services/auth-service'

export type AuditAction =
  | 'LOGIN'
  | 'LOGOUT'
  | 'CREATE'
  | 'UPDATE'
  | 'DELETE'
  | 'UPLOAD_MEDIA'
  | 'DELETE_MEDIA'
  | 'INVITE_MEMBER'
  | 'UPDATE_PERMISSIONS'
  | 'CHANGE_PASSWORD'
  | 'SETTINGS_UPDATE'

export interface AuditLogInput {
  username: string
  action: AuditAction
  resourceType?: string
  resourceId?: string
  metadata?: Record<string, unknown> | null
  ip?: string | null
  spaceId?: number | null
}

export async function writeAuditLog(input: AuditLogInput): Promise<void> {
  try {
    await prisma.auditLog.create({
      data: {
        username: input.username,
        action: input.action as any,
        resourceType: input.resourceType || null,
        resourceId: input.resourceId || null,
        metadata: input.metadata ? JSON.stringify(input.metadata) : null,
        ipHash: hashIp(input.ip),
        spaceId: input.spaceId || null,
      },
    })
  } catch (error) {
    // 审计日志写入失败不应影响主流程
    console.error('[AuditLog] write failed:', (error as Error)?.message)
  }
}

export async function listAuditLogs(options: { limit?: number; username?: string; action?: string } = {}): Promise<
  Array<{
    id: number
    username: string
    action: string
    resourceType: string | null
    resourceId: string | null
    metadata: Record<string, unknown> | null
    createdAt: string
  }>
> {
  const { limit = 100, username, action } = options
  const where: any = {}
  if (username) where.username = username
  if (action) where.action = action
  const rows = await prisma.auditLog.findMany({
    where,
    orderBy: { createdAt: 'desc' },
    take: limit,
  })
  return rows.map((r) => ({
    id: r.id,
    username: r.username,
    action: r.action,
    resourceType: r.resourceType,
    resourceId: r.resourceId,
    metadata: r.metadata ? safeParse(r.metadata) : null,
    createdAt: r.createdAt.toISOString(),
  }))
}

function safeParse(text: string): Record<string, unknown> | null {
  try {
    const parsed = JSON.parse(text)
    return parsed && typeof parsed === 'object' ? parsed : null
  } catch {
    return null
  }
}

/**
 * v3.1 M2-E1：记忆档案导出。
 * 生成 ZIP：data.json（结构化元数据）+ travels.md / memories.md / moments.md（Markdown 叙事）
 *          + photos/（原图，按 storageKey 从本地/对象存储读取）。
 * 设计目标：导出包可再导入（data.json 含相对路径映射）。
 */
import archiver from 'archiver'
import { prisma } from '../../db'
import { scopedWhere } from '../../visibility'
import { memoryService } from '../memory/memory.service'

export interface ExportResult {
  /** 内存 ZIP buffer */
  buffer: Buffer
  filename: string
  stats: { travels: number; memories: number; moments: number; photos: number }
}

const md = (s: string | null | undefined) => (s ? String(s) : '')

/** 读取媒体文件字节（本地存储 or 对象存储） */
async function readMediaBytes(storageKey: string): Promise<Buffer | null> {
  try {
    if (process.env.STORAGE_ENDPOINT && process.env.STORAGE_BUCKET) {
      const { S3Client, GetObjectCommand } = await import('@aws-sdk/client-s3')
      const client = new S3Client({
        endpoint: process.env.STORAGE_ENDPOINT,
        region: process.env.STORAGE_REGION || 'auto',
        credentials: {
          accessKeyId: process.env.STORAGE_ACCESS_KEY || '',
          secretAccessKey: process.env.STORAGE_SECRET_KEY || '',
        },
        forcePathStyle: true,
      })
      const res = await client.send(new GetObjectCommand({ Bucket: process.env.STORAGE_BUCKET, Key: storageKey }))
      const chunks: Uint8Array[] = []
      const stream = res.Body as any
      for await (const chunk of stream) chunks.push(chunk as Uint8Array)
      return Buffer.concat(chunks)
    }
    const fs = await import('fs')
    const path = await import('path')
    const filePath = path.join(process.env.UPLOAD_DIR || 'public/uploads', storageKey)
    return await fs.promises.readFile(filePath)
  } catch {
    return null
  }
}

/** 导出当前用户的全部记忆档案 */
export async function exportMemoryArchive(username: string): Promise<ExportResult> {
  const userId = (await prisma.user.findUnique({ where: { username }, select: { id: true } }))?.id

  // 1) 旅行（含天数）
  const travels = await prisma.travel.findMany({
    where: scopedWhere(userId, 'ownerId') as any,
    orderBy: { startDate: 'asc' },
    include: { days: { orderBy: { sortOrder: 'asc' } } },
  })

  // 2) 回忆（含照片）——查用户创建或所属空间的回忆
  const userSpaces = userId
    ? (await prisma.spaceMember.findMany({
        where: { userId, status: 'ACTIVE' },
        select: { spaceId: true },
      })).map((s) => s.spaceId)
    : []
  const memories = await prisma.memory.findMany({
    where: {
      OR: [
        ...(userSpaces.length ? [{ spaceId: { in: userSpaces } }] : []),
        ...(userId ? [{ createdById: userId }] : []),
      ],
    } as any,
    include: {
      media: { include: { variants: { where: { variant: 'THUMBNAIL' } } } },
      mediaLinks: { include: { media: true } },
    },
  })

  // 3) 碎碎念
  const moments = await prisma.moment.findMany({
    where: scopedWhere(userId) as any,
    orderBy: { createdAt: 'asc' },
  })

  // 4) 相册
  const albums = await prisma.album.findMany({
    where: scopedWhere(userId) as any,
    orderBy: { createdAt: 'asc' },
  })

  const photoCache = new Map<string, Buffer>()
  const photoKeys = new Set<string>()
  const allMedia = memories.flatMap((m: any) => [
    ...(m.media || []),
    ...(m.mediaLinks || []).map((l: any) => l.media).filter(Boolean),
  ])
  for (const media of allMedia) {
    if (media?.storageKey && !photoKeys.has(media.storageKey)) {
      photoKeys.add(media.storageKey)
      const bytes = await readMediaBytes(media.storageKey)
      if (bytes) photoCache.set(media.storageKey, bytes)
    }
  }

  // === 生成 Markdown ===
  const travelsMd: string[] = ['# 旅行档案\n']
  for (const t of travels) {
    travelsMd.push(`## ${t.title}（${t.startDate ? new Date(t.startDate).toISOString().slice(0, 10) : '未定日期'}）`)
    travelsMd.push(`- 地点：${md(t.location)}`)
    travelsMd.push(`- 状态：${t.status}`)
    travelsMd.push(`- 描述：${md(t.description)}`)
    if (t.days?.length) {
      travelsMd.push(`\n### 天数（${t.days.length}）`)
      for (const d of t.days) {
        travelsMd.push(`- DAY: ${d.title || ''} ${d.date ? new Date(d.date).toISOString().slice(0, 10) : ''} — ${md(d.summary)}`)
      }
    }
    travelsMd.push('')
  }

  const memoriesMd: string[] = ['# 回忆档案\n']
  for (const m of memories) {
    const photos = [
      ...(m.media || []).map((x: any) => x.storageKey),
      ...(m.mediaLinks || []).map((l: any) => l.media?.storageKey).filter(Boolean),
    ]
    memoriesMd.push(`## ${m.title}`)
    memoriesMd.push(`- 时间：${m.happenedAt ? new Date(m.happenedAt).toISOString() : ''}`)
    memoriesMd.push(`- 心情：${md(m.mood)}`)
    memoriesMd.push(`- 内容：${md(m.content)}`)
    if (photos.length) memoriesMd.push(`- 照片：${photos.map((p: string) => `photos/${p.replace(/\//g, '_')}`).join(', ')}`)
    memoriesMd.push('')
  }

  const momentsMd: string[] = ['# 碎碎念档案\n']
  for (const m of moments) {
    momentsMd.push(`- ${m.createdAt ? new Date(m.createdAt).toISOString() : ''}：${m.content}`)
  }

  // === 结构化 JSON（含相对路径映射，可再导入） ===
  const dataJson = {
    exportedAt: new Date().toISOString(),
    app: '甜途',
    version: '3.1-M2',
    travels: travels.map((t: any) => ({
      id: t.id,
      title: t.title,
      location: t.location,
      startDate: t.startDate,
      status: t.status,
      days: (t.days || []).map((d: any) => ({ title: d.title, date: d.date, summary: d.summary })),
    })),
    memories: memories.map((m: any) => ({
      id: m.id,
      title: m.title,
      content: m.content,
      mood: m.mood,
      happenedAt: m.happenedAt,
      photos: [
        ...(m.media || []).map((x: any) => `photos/${x.storageKey.replace(/\//g, '_')}`),
        ...(m.mediaLinks || []).map((l: any) => l.media ? `photos/${l.media.storageKey.replace(/\//g, '_')}` : null).filter(Boolean),
      ],
    })),
    moments: moments.map((m: any) => ({ id: m.id, content: m.content, createdAt: m.createdAt })),
    albums: albums.map((a: any) => ({ id: a.id, title: a.title, date: a.date })),
  }

  // === 打 ZIP ===
  const archive = archiver('zip', { zlib: { level: 9 } })
  const chunks: Buffer[] = []
  const stream = new Promise<Buffer>((resolve, reject) => {
    archive.on('data', (c) => chunks.push(c))
    archive.on('end', () => resolve(Buffer.concat(chunks)))
    archive.on('error', reject)
  })

  archive.append(travelsMd.join('\n'), { name: 'travels.md' })
  archive.append(memoriesMd.join('\n'), { name: 'memories.md' })
  archive.append(momentsMd.join('\n'), { name: 'moments.md' })
  archive.append(JSON.stringify(dataJson, null, 2), { name: 'data.json' })

  for (const [storageKey, bytes] of Array.from(photoCache.entries())) {
    archive.append(bytes, { name: `photos/${storageKey.replace(/\//g, '_')}` })
  }
  await archive.finalize()
  const buffer = await stream

  return {
    buffer,
    filename: `tiantu-archive-${username}-${new Date().toISOString().slice(0, 10)}.zip`,
    stats: { travels: travels.length, memories: memories.length, moments: moments.length, photos: photoCache.size },
  }
}

