/**
 * Memory 数据访问（Repository）—— 回忆是 甜途 的核心实体（§31）
 */
import { prisma } from '../../db'

export type MemoryVisibility = 'PRIVATE' | 'SPACE' | 'PUBLIC'

export interface MemoryRecord {
  id: number
  spaceId: number
  travelId: number | null
  travelDayId: number | null
  title: string
  content: string | null
  happenedAt: string | null
  locationId: number | null
  mood: string | null
  visibility: MemoryVisibility
  createdBy: string
  createdAt: string
  updatedAt: string
}

export interface CreateMemoryInput {
  spaceId: number
  travelId?: number | null
  travelDayId?: number | null
  title: string
  content?: string | null
  happenedAt?: Date | string | null
  locationId?: number | null
  mood?: string | null
  visibility?: MemoryVisibility
  createdBy: string
}

export type UpdateMemoryPatch = Partial<Omit<CreateMemoryInput, 'spaceId' | 'createdBy'>>

function serialize(m: any): MemoryRecord {
  return {
    id: m.id,
    spaceId: m.spaceId,
    travelId: m.travelId,
    travelDayId: m.travelDayId,
    title: m.title,
    content: m.content,
    happenedAt: m.happenedAt ? new Date(m.happenedAt).toISOString() : null,
    locationId: m.locationId,
    mood: m.mood,
    visibility: m.visibility,
    createdBy: m.createdBy,
    createdAt: m.createdAt.toISOString(),
    updatedAt: m.updatedAt.toISOString(),
  }
}

export class PrismaMemoryRepository {
  async create(input: CreateMemoryInput): Promise<number> {
    const m = await prisma.memory.create({
      data: {
        spaceId: input.spaceId,
        travelId: input.travelId ?? null,
        travelDayId: input.travelDayId ?? null,
        title: input.title,
        content: input.content ?? null,
        happenedAt: input.happenedAt ? new Date(input.happenedAt) : null,
        locationId: input.locationId ?? null,
        mood: input.mood ?? null,
        visibility: (input.visibility ?? 'SPACE') as any,
        createdBy: input.createdBy,
      },
    })
    return m.id
  }

  async findById(id: number): Promise<MemoryRecord | null> {
    const m = await prisma.memory.findUnique({ where: { id } })
    return m ? serialize(m) : null
  }

  async listForSpace(spaceId: number, travelId?: number | null): Promise<MemoryRecord[]> {
    const rows = await prisma.memory.findMany({
      where: { spaceId, ...(travelId ? { travelId } : {}) },
      orderBy: [{ happenedAt: 'desc' }, { id: 'desc' }],
    })
    return rows.map(serialize)
  }

  async update(id: number, patch: UpdateMemoryPatch): Promise<MemoryRecord | null> {
    const data: any = {}
    if (patch.title !== undefined) data.title = patch.title
    if (patch.content !== undefined) data.content = patch.content ?? null
    if (patch.happenedAt !== undefined) data.happenedAt = patch.happenedAt ? new Date(patch.happenedAt) : null
    if (patch.travelId !== undefined) data.travelId = patch.travelId ?? null
    if (patch.travelDayId !== undefined) data.travelDayId = patch.travelDayId ?? null
    if (patch.locationId !== undefined) data.locationId = patch.locationId ?? null
    if (patch.mood !== undefined) data.mood = patch.mood ?? null
    if (patch.visibility !== undefined) data.visibility = patch.visibility as any
    if (Object.keys(data).length === 0) return this.findById(id)
    const m = await prisma.memory.update({ where: { id }, data })
    return serialize(m)
  }

  async remove(id: number): Promise<void> {
    await prisma.memory.delete({ where: { id } })
  }
}

export const prismaMemoryRepository = new PrismaMemoryRepository()

/**
 * 下载拉取分发器（Stage 3.4b）：把服务器列表接口映射为本地表记录快照。
 * 首期覆盖「离线读」的列表级实体（MOMENT / TRAVEL / ALBUM）；
 * MEMORY / MEDIA / TRAVEL_DAY / ALBUM_MEDIA 需要 spaceId 作用域接口或详情扇出，留待后续子阶段。
 *
 * B4：新增 `pullChanges()` 优先走增量端点 GET /api/sync/changes（带游标、含墓碑）；
 * 端点不存在（404）或请求失败时返回 null，调用方回退到原有全量拉取（兼容老服务端）。
 */
import { apiUrl } from '@/lib/api-base'
import { getMeta, META_KEYS } from './meta'
import type { EntityType } from './types'

/**
 * 增量拉取游标（P2-29）。
 *
 * 客户端先带出去，服务端支持后即自动生效；**服务端未支持时行为不变**（多余 query 参数被忽略）。
 * 时间用毫秒时间戳字符串，避免服务端/客户端时区与格式歧义。
 */
async function sinceParam(): Promise<string> {
  const raw = await getMeta(META_KEYS.lastSyncAt)
  const since = raw ? Number(raw) : 0
  return Number.isFinite(since) && since > 0 ? 'updatedSince=' + Math.floor(since) : ''
}

/** B4 增量游标：优先 syncCursor，其次兼容旧的 lastSyncAt（首次升级时游标为空 → 全量） */
async function cursorParam(): Promise<string> {
  const raw = (await getMeta(META_KEYS.syncCursor)) ?? (await getMeta(META_KEYS.lastSyncAt))
  const since = raw ? Number(raw) : 0
  return Number.isFinite(since) && since > 0 ? 'updatedSince=' + Math.floor(since) : ''
}

function withQuery(url: string, ...parts: string[]): string {
  const qs = parts.filter(Boolean).join('&')
  if (!qs) return url
  return url + (url.includes('?') ? '&' : '?') + qs
}

/** 一条待落地的远端记录（已映射为本地表列名 → 值） */
export interface PullEntity {
  /** 本地表名（travel / album / moment / memory） */
  table: string
  /** 本地 id（= String(remoteId)） */
  id: string
  remoteId: number
  /** LWW 时间戳（毫秒） */
  updatedAt: number
  /** 本地表列名 → 值 的快照 */
  data: Record<string, unknown>
}

/** B4：服务端墓碑（删除传播） */
export interface PullTombstone {
  entityType: 'Travel' | 'Moment' | 'Album' | 'Memory'
  entityId: number
}

/** B4：增量拉取结果；serverTime = 下一轮游标（服务端时刻，避免客户端时钟偏差） */
export interface PullChanges {
  serverTime: number
  entities: PullEntity[]
  tombstones: PullTombstone[]
}

export interface PullDispatcher {
  /** 拉取某实体类型的远端记录列表 */
  pull(entityType: EntityType): Promise<PullEntity[]>
  /** B4：增量拉取；服务端不支持（404/失败）返回 null，调用方回退全量 */
  pullChanges?(): Promise<PullChanges | null>
}

function toMs(v: string | number | null | undefined): number {
  if (v == null || v === '') return 0
  const t = new Date(v).getTime()
  return isNaN(t) ? 0 : t
}

function mapMomentRow(m: any): PullEntity {
  return {
    table: 'moment',
    id: String(m.id),
    remoteId: Number(m.id),
    updatedAt: toMs(m.updatedAt) || toMs(m.createdAt) || Date.now(),
    data: {
      content: m.content,
      tags: Array.isArray(m.tags) ? JSON.stringify(m.tags) : null,
      userId: m.userId ?? null,
      isPublic: m.isPublic ? 1 : 0,
    },
  }
}

function mapTravelRow(t: any): PullEntity {
  return {
    table: 'travel',
    id: String(t.id),
    remoteId: Number(t.id),
    updatedAt: toMs(t.updatedAt) || Date.now(),
    data: {
      title: t.title,
      slug: t.slug,
      description: t.description ?? null,
      location: t.location ?? null,
      cover: t.cover ?? null,
      startDate: t.startDate ? new Date(t.startDate).getTime() : null,
      endDate: t.endDate ? new Date(t.endDate).getTime() : null,
      status: t.status ?? 'PLANNED',
      visibility: t.visibility ?? 'SPACE',
      isPublic: t.isPublic ? 1 : 0,
      spaceId: t.spaceId ?? null,
      ownerId: t.ownerId ?? null,
    },
  }
}

function mapAlbumRow(a: any): PullEntity {
  return {
    table: 'album',
    id: String(a.id),
    remoteId: Number(a.id),
    updatedAt: toMs(a.updatedAt) || toMs(a.createdAt) || Date.now(),
    data: {
      title: a.title,
      description: a.description ?? null,
      coverMediaId: a.coverMediaId ?? null,
      date: a.date ? new Date(a.date).getTime() : null,
      locationId: a.locationId ?? null,
      travelId: a.travelId ?? null,
      visibility: a.visibility ?? 'SPACE',
      isPublic: a.isPublic ? 1 : 0,
      spaceId: a.spaceId ?? null,
      userId: a.userId ?? null,
    },
  }
}

/** B4：本地 memory 表用 TEXT 存 travelId/travelDayId（可能是本地 UUID），服务端数字 id 转字符串即可 */
function mapMemoryRow(m: any): PullEntity {
  return {
    table: 'memory',
    id: String(m.id),
    remoteId: Number(m.id),
    updatedAt: toMs(m.updatedAt) || toMs(m.createdAt) || Date.now(),
    data: {
      spaceId: m.spaceId ?? null,
      travelId: m.travelId != null ? String(m.travelId) : null,
      travelDayId: m.travelDayId != null ? String(m.travelDayId) : null,
      title: m.title ?? '',
      content: m.content ?? null,
      happenedAt: m.happenedAt ? new Date(m.happenedAt).getTime() : null,
      mood: m.mood ?? null,
      visibility: m.visibility ?? 'SPACE',
      createdById: m.createdById ?? null,
    },
  }
}

function isTombstoneEntityType(v: unknown): v is PullTombstone['entityType'] {
  return v === 'Travel' || v === 'Moment' || v === 'Album' || v === 'Memory'
}

export class HttpPullDispatcher implements PullDispatcher {
  async pull(entityType: EntityType): Promise<PullEntity[]> {
    try {
      switch (entityType) {
        case 'MOMENT': return await this.pullMoments()
        case 'TRAVEL': return await this.pullTravels()
        case 'ALBUM': return await this.pullAlbums()
        case 'SOCIAL_POST': return await this.pullSocialPosts()
        default: return []
      }
    } catch {
      return []
    }
  }

  /**
   * B4 增量拉取：GET /api/sync/changes?updatedSince=<游标>
   * 返回 null 表示「服务端不支持/请求失败」——调用方回退全量拉取，不推进游标。
   */
  async pullChanges(): Promise<PullChanges | null> {
    let res: Response
    try {
      res = await fetch(apiUrl(withQuery('/api/sync/changes', await cursorParam())), { credentials: 'include' })
    } catch {
      return null
    }
    // 404 = 老服务端没有该端点；其余非 2xx 也回退（可能是未登录/网关错误）
    if (!res.ok) return null
    let json: any
    try {
      json = await res.json()
    } catch {
      return null
    }
    if (!json || typeof json !== 'object') return null

    const entities: PullEntity[] = [
      ...(Array.isArray(json.travels) ? json.travels.map(mapTravelRow) : []),
      ...(Array.isArray(json.moments) ? json.moments.map(mapMomentRow) : []),
      ...(Array.isArray(json.albums) ? json.albums.map(mapAlbumRow) : []),
      ...(Array.isArray(json.memories) ? json.memories.map(mapMemoryRow) : []),
    ]
    const tombstones: PullTombstone[] = (Array.isArray(json.tombstones) ? json.tombstones : [])
      .filter((t: any) => isTombstoneEntityType(t?.entityType) && Number.isFinite(Number(t?.entityId)))
      .map((t: any) => ({ entityType: t.entityType, entityId: Number(t.entityId) }))

    return {
      serverTime: toMs(json.serverTime) || Date.now(),
      entities,
      tombstones,
    }
  }

  private async pullMoments(): Promise<PullEntity[]> {
    const res = await fetch(apiUrl(withQuery('/api/admin/moments?page=1&pageSize=200', await sinceParam())), { credentials: 'include' })
    if (!res.ok) return []
    const json = await res.json()
    const rows = json?.data?.data ?? []
    return rows.map(mapMomentRow)
  }

  private async pullTravels(): Promise<PullEntity[]> {
    const res = await fetch(apiUrl(withQuery('/api/admin/travels', await sinceParam())), { credentials: 'include' })
    if (!res.ok) return []
    const json = await res.json()
    const rows = json?.travels ?? []
    return rows.map(mapTravelRow)
  }

  private async pullAlbums(): Promise<PullEntity[]> {
    const res = await fetch(apiUrl(withQuery('/api/admin/albums', await sinceParam())), { credentials: 'include' })
    if (!res.ok) return []
    const json = await res.json()
    const rows = json?.albums ?? []
    return rows.map(mapAlbumRow)
  }

  /** 旅行圈 Feed 缓存（D2 社交离线读）：拉推荐 Feed 前若干条进本地 social_post */
  private async pullSocialPosts(): Promise<PullEntity[]> {
    const res = await fetch(apiUrl(withQuery('/api/social/posts?tab=recommended&page=1&pageSize=50', await sinceParam())), { credentials: 'include' })
    if (!res.ok) return []
    const json = await res.json()
    const rows = json?.data ?? []
    return rows.map((p: any): PullEntity => ({
      table: 'social_post',
      id: String(p.id),
      remoteId: Number(p.id),
      updatedAt: toMs(p.publishedAt) || Date.now(),
      data: {
        title: p.title ?? '',
        summary: p.summary ?? null,
        coverUrl: p.coverUrl ?? null,
        location: p.location ?? null,
        startDate: p.startDate ? new Date(p.startDate).getTime() : null,
        endDate: p.endDate ? new Date(p.endDate).getTime() : null,
        dayCount: p.dayCount ?? 0,
        photoCount: p.photoCount ?? 0,
        authorId: p.author?.id ?? null,
        authorName: p.author?.username ?? null,
        authorNickname: p.author?.nickname ?? null,
        authorAvatar: p.author?.avatarUrl ?? null,
        likeCount: p.likeCount ?? 0,
        commentCount: p.commentCount ?? 0,
        favoriteCount: p.favoriteCount ?? 0,
        isLiked: p.isLiked ? 1 : 0,
        isFavorited: p.isFavorited ? 1 : 0,
        publishedAt: p.publishedAt ? new Date(p.publishedAt).getTime() : null,
      },
    }))
  }
}

/**
 * v3.1 M3-B2：社交治理处理闭环。
 * 后台处理举报：驳回（DISMISSED）/ 下架帖子（帖子隐藏 + 通知作者）/ 隐藏评论 / 封禁用户（拉黑作者 + 通知）。
 * 统一入口：handleReport(action, reportId)，由 /api/admin/social/reports 路由调用（canManageSocial 能力）。
 */
import { prisma } from '@/lib/db'
import { logger } from '@/lib/infrastructure/logger'

export type ReportAction = 'DISMISS' | 'TAKEDOWN_POST' | 'HIDE_COMMENT' | 'BAN_USER'

/** 系统通知（治理结果告知被举报者；actorId=null 表示系统） */
async function systemNotify(recipientId: number, refType: string, refId: number, message: string): Promise<void> {
  if (!recipientId) return
  await prisma.notification.create({
    data: { userId: recipientId, actorId: null, type: 'SYSTEM', refType, refId },
  }).catch(() => {})
  // message 由前端按 refType/refId 展示；留空即通用文案
  void message
}

/** 处理举报：标记状态 + 执行动作 + 通知被举报者（幂等：已处理不可重复动作） */
export async function handleReport(action: ReportAction, reportId: number): Promise<{ ok: boolean; message: string }> {
  const report = await prisma.report.findUnique({
    where: { id: reportId },
    include: {
      post: { select: { id: true, authorId: true, title: true } },
    },
  })
  if (!report) throw new Error('举报不存在')
  if (report.status !== 'PENDING') {
    throw new Error('该举报已处理')
  }

  switch (action) {
    case 'DISMISS': {
      await prisma.report.update({ where: { id: reportId }, data: { status: 'DISMISSED' } })
      return { ok: true, message: '已驳回举报' }
    }

    case 'TAKEDOWN_POST': {
      // 帖子下架：TravelPost 隐藏（visibility→PRIVATE 使 Feed 不再展示）
      await prisma.$transaction([
        prisma.travelPost.update({ where: { id: report.postId }, data: { visibility: 'PRIVATE' } }),
        prisma.report.update({ where: { id: reportId }, data: { status: 'ACTIONED' } }),
      ])
      if (report.post.authorId) {
        await systemNotify(report.post.authorId, 'TravelPost', report.postId, '你的旅行圈内容因违规被下架')
      }
      logger.info('moderation', 'report_takedown', { reportId, postId: report.postId, action })
      return { ok: true, message: '已下架该帖子' }
    }

    case 'HIDE_COMMENT': {
      // 隐藏帖子下全部评论（评论区治理：评论状态置 HIDDEN，前端不展示）
      const hidden = await prisma.comment.updateMany({
        where: { postId: report.postId, status: 'VISIBLE' },
        data: { status: 'HIDDEN' },
      })
      await prisma.report.update({ where: { id: reportId }, data: { status: 'ACTIONED' } })
      if (report.post.authorId) {
        await systemNotify(report.post.authorId, 'TravelPost', report.postId, `你的帖子下 ${hidden.count} 条评论因违规被隐藏`)
      }
      return { ok: true, message: `已隐藏 ${hidden.count} 条评论` }
    }

    case 'BAN_USER': {
      // 封禁：屏蔽作者（blockerId=作者 无意义，改为 admin 屏蔽语义：建立 UserBlock 由作者屏蔽举报者无意义；
      // 更合理做法：将帖子下架 + 作者后续发布受限（这里先做下架 + 通知，完整封禁策略在 B3 反垃圾统一处理）
      await prisma.$transaction([
        prisma.travelPost.update({ where: { id: report.postId }, data: { visibility: 'PRIVATE' } }),
        prisma.report.update({ where: { id: reportId }, data: { status: 'ACTIONED' } }),
      ])
      if (report.post.authorId) {
        await systemNotify(report.post.authorId, 'TravelPost', report.postId, '你的内容因严重违规已被下架，请遵守社区规范')
      }
      return { ok: true, message: '已下架帖子并警告作者' }
    }

    default:
      throw new Error('未知处理动作')
  }
}

/** 后台：按状态列出举报（含帖子/作者信息，供处理界面） */
export async function listReportsForAdmin(status?: string, page = 1, pageSize = 20) {
  const where: any = {}
  if (status && ['PENDING', 'REVIEWED', 'DISMISSED', 'ACTIONED'].includes(status)) where.status = status
  const [total, rows] = await Promise.all([
    prisma.report.count({ where }),
    prisma.report.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      skip: (page - 1) * pageSize,
      take: pageSize,
      include: {
        reporter: { select: { id: true, username: true } },
        post: {
          select: {
            id: true, title: true, visibility: true, publishedAt: true,
            author: { select: { id: true, username: true } },
          },
        },
      },
    }),
  ])
  return { data: rows, total, page, pageSize, hasMore: page * pageSize < total }
}

import { prisma } from '../../db'
import { getUserCapabilities, type UserCapabilities } from '../space/permissions'
import { invalidateCurrentUserCache } from '../../current-user'
import { absoluteMediaUrl, storageKeyToUrl } from '../../media-url'
import {
  diffInDays,
  getTravelArchiveStats,
  loadMyTravels,
  travelPhotoUrls,
  type TravelStatSource,
} from '../travel/travel-stats'

/**
 * 个人旅行档案统一数据源（R1 重构 / R3 统一口径）。
 *
 * ⚠️ 统计口径（travelCount / placeCount / photoCount）**不再在这里计算**，
 * 而是走 `lib/modules/travel/travel-stats.ts` —— 那是 `/api/me` 与 `/api/dashboard`
 * 共用的唯一事实源。原因：两处曾经各写一份、读不同的表（Travel vs Post），
 * 于是"我的"显示 0、看板显示 4（真机反馈"统计都是 0"的根因之一）。
 */

function iso(v: Date | null | undefined): string | null {
  if (!v) return null
  const d = v instanceof Date ? v : new Date(v)
  return isNaN(d.getTime()) ? null : d.toISOString()
}

export interface TravelProfileSummary {
  travelCount: number
  /** 城市去重口径（拍板结论）：`Travel.location` 去重数 */
  placeCount: number
  photoCount: number
  /** 可按天数据算出的总天数；无天数据时为 null（前端隐藏） */
  travelDays: number | null
  momentCount: number
  favoriteCount: number
  likeCount: number
  provinceCount: number
  /** 统计来自哪张表（Travel 为主、旧文章兜底）——便于排查"数字不对" */
  source: TravelStatSource
}

export interface RecentTravelSummary {
  id: number
  title: string
  slug: string
  location: string | null
  date: string | null
  coverUrl: string | null
  photoCount: number
}

/** 下一趟未出发的旅行（「我的」页与空间页共用） */
export interface UpcomingTravelSummary {
  id: number
  title: string
  slug: string
  location: string | null
  startDate: string | null
  /** 距离出发还有几天（今天出发为 0） */
  daysUntilStart: number
  coverUrl: string | null
}

/** 同行者聚合：「和 X 去过 N 次」 */
export interface CompanionStat {
  name: string
  relation: string | null
  count: number
}

export interface MeProfile {
  id: number
  username: string
  nickname: string | null
  bio: string | null
  avatarUrl: string | null
  /** 档案头图（用户上传的风景图） */
  coverUrl: string | null
  /** 头图焦点 0-1；渲染为 object-position。null = 居中 */
  coverFocusX: number | null
  coverFocusY: number | null
  accountId: string | null
  createdAt: string | null
  summary: TravelProfileSummary
  recentTravel: RecentTravelSummary | null
  upcomingTravel: UpcomingTravelSummary | null
  /** 同行者聚合（从 Travel.companions 汇总，按姓名去重计数，最多 8 人） */
  companionStats: CompanionStat[]
  capabilities: UserCapabilities
  /** 新用户偏好问卷答案（未做过为 null） */
  preferences: unknown
  /** 问卷完成或跳过的时刻；null 表示还没做过 → 客户端弹问卷 */
  preferencesCompletedAt: string | null
}

/** 一天中的零点（本地时区），用于「距离出发还有几天」 */
function startOfToday(): Date {
  const now = new Date()
  return new Date(now.getFullYear(), now.getMonth(), now.getDate())
}

// diffInDays 从 travel-stats 复用（原先本文件也有一份，两处实现重复）
export { diffInDays }

/** 单条 media → 缩略图优先、回退原图（与 travel.service 的 thumbOf 同口径） */
function thumbOf(m: any): string | null {
  const variants = Array.isArray(m?.variants) ? m.variants : []
  // 用 find 而不是 [0]：variants 数组的顺序不保证（曾因此拿到原图而非缩略图）
  const thumb = variants.find((v: any) => v.variant === 'THUMBNAIL') ?? variants[0]
  return storageKeyToUrl(thumb?.storageKey ?? m?.storageKey ?? null)
}

export async function getMyProfile(userId: number): Promise<MeProfile | null> {
  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: {
      id: true,
      username: true,
      nickname: true,
      bio: true,
      avatarUrl: true,
      coverUrl: true,
      coverFocusX: true,
      coverFocusY: true,
      accountId: true,
      // 新用户偏好问卷：客户端据此决定是否弹（见 lib/modules/user/preferences.ts）
      preferences: true,
      preferencesCompletedAt: true,
      createdAt: true,
    },
  })
  if (!user) return null

  const travels = await loadMyTravels(userId)

  // 统计走唯一事实源（与 /api/dashboard 同源；无 Travel 时用旧文章兜底）
  const stats = await getTravelArchiveStats(userId)

  const [momentCount, favoriteCount, likeAgg] = await Promise.all([
    prisma.moment.count({ where: { userId } }),
    prisma.postFavorite.count({ where: { userId } }),
    prisma.travelPost.aggregate({
      where: { authorId: userId, visibility: 'PUBLIC' },
      _sum: { likeCount: true },
    }),
  ])
  const likeCount = likeAgg._sum.likeCount ?? 0

  const capabilities = await getUserCapabilities(userId)

  const today = startOfToday()
  // 已结束的旅行（有结束日且早于今天）不进「最近的一次旅行」——
  // 否则用户改完旧旅行日期，首页/档案最显眼的位置会显示一段过去的行程。
  const finished = (t: { startDate: Date | null; endDate: Date | null }) => {
    const end = t.endDate ?? t.startDate
    return !!end && diffInDays(today, end) < 0
  }
  const byStartDesc = [...travels].sort((a, b) => {
    const av = a.startDate ? a.startDate.getTime() : 0
    const bv = b.startDate ? b.startDate.getTime() : 0
    return bv - av || b.id - a.id
  })
  const latest = byStartDesc.find((t) => !finished(t)) ?? byStartDesc[0] ?? null

  const recentTravel: RecentTravelSummary | null = latest
    ? {
        id: latest.id,
        title: latest.title,
        slug: latest.slug,
        location: latest.location,
        date: iso(latest.startDate),
        coverUrl: thumbOf(latest.coverMedia) ?? absoluteMediaUrl(latest.cover ?? null),
        photoCount: travelPhotoUrls(latest).length,
      }
    : null

  // 下一趟：开始日 >= 今天，取最近的一本
  const upcoming = byStartDesc
    .filter((t) => t.startDate && diffInDays(today, t.startDate) >= 0)
    .sort((a, b) => (a.startDate!.getTime() - b.startDate!.getTime()))
  const upcomingTravel: UpcomingTravelSummary | null = upcoming[0]
    ? {
        id: upcoming[0].id,
        title: upcoming[0].title,
        slug: upcoming[0].slug,
        location: upcoming[0].location,
        startDate: iso(upcoming[0].startDate),
        daysUntilStart: diffInDays(today, upcoming[0].startDate!),
        coverUrl: thumbOf(upcoming[0].coverMedia) ?? absoluteMediaUrl(upcoming[0].cover ?? null),
      }
    : null

  // 同行者聚合：从 Travel.companions 汇总（自己名下的旅行）
  const byName = new Map<string, CompanionStat>()
  for (const t of travels) {
    const companions = t.companions
    if (!Array.isArray(companions)) continue
    for (const c of companions as Array<{ name?: unknown; relation?: unknown }>) {
      const name = String(c?.name || '').trim()
      if (!name) continue
      const relation = String(c?.relation || '').trim() || null
      const cur = byName.get(name)
      if (cur) {
        cur.count += 1
        if (!cur.relation && relation) cur.relation = relation
      } else {
        byName.set(name, { name, relation, count: 1 })
      }
    }
  }
  const companionStats = Array.from(byName.values()).sort((a, b) => b.count - a.count).slice(0, 8)

  return {
    id: user.id,
    username: user.username,
    nickname: user.nickname,
    bio: user.bio,
    avatarUrl: absoluteMediaUrl(user.avatarUrl),
    coverUrl: absoluteMediaUrl(user.coverUrl),
    coverFocusX: user.coverFocusX ?? null,
    coverFocusY: user.coverFocusY ?? null,
    accountId: user.accountId,
    createdAt: iso(user.createdAt),
    summary: {
      travelCount: stats.travelCount,
      placeCount: stats.placeCount,
      photoCount: stats.photoCount,
      travelDays: stats.travelDays,
      momentCount,
      favoriteCount,
      likeCount,
      provinceCount: stats.provinceCount,
      source: stats.source,
    },
    recentTravel,
    upcomingTravel,
    companionStats,
    capabilities,
    preferences: user.preferences ?? null,
    preferencesCompletedAt: iso(user.preferencesCompletedAt),
  }
}

function normalizeNickname(nickname: unknown): string | null {
  if (nickname == null) return null
  const value = String(nickname).trim()
  if (!value) return null
  return value.slice(0, 24)
}

function normalizeBio(bio: unknown): string | null {
  if (bio == null) return null
  const value = String(bio).trim()
  if (!value) return null
  return value.slice(0, 120)
}

export async function updateMyProfile(
  userId: number,
  input: { nickname?: unknown; bio?: unknown },
): Promise<{ nickname: string | null; bio: string | null }> {
  const data: { nickname?: string | null; bio?: string | null } = {}

  if (Object.prototype.hasOwnProperty.call(input, 'nickname')) {
    const next = normalizeNickname(input.nickname)
    if (next && !/^[\u4e00-\u9fa5A-Za-z0-9_\-\s]{1,24}$/.test(next)) {
      throw new Error('昵称仅支持 1-24 位中文/字母/数字/空格/下划线/短横线')
    }
    data.nickname = next
  }

  if (Object.prototype.hasOwnProperty.call(input, 'bio')) {
    const bio = normalizeBio(input.bio)
    if (bio && bio.length > 120) {
      throw new Error('个性签名最多 120 字')
    }
    data.bio = bio
  }

  const user = await prisma.user.findUnique({ where: { id: userId }, select: { id: true } })
  if (!user) throw new Error('用户不存在')

  const updated = await prisma.user.update({ where: { id: userId }, data })
  invalidateCurrentUserCache(userId)
  return { nickname: updated.nickname, bio: updated.bio }
}

export async function updateMyAvatar(userId: number, avatarUrl: string) {
  const user = await prisma.user.findUnique({ where: { id: userId }, select: { id: true } })
  if (!user) throw new Error('用户不存在')
  const updated = await prisma.user.update({ where: { id: userId }, data: { avatarUrl } })
  invalidateCurrentUserCache(userId)
  return { avatarUrl: absoluteMediaUrl(updated.avatarUrl) }
}

/** 保存档案头图与焦点（焦点为 0-1 的归一化坐标，null 表示居中） */
export async function updateMyCover(
  userId: number,
  coverUrl: string,
  focus?: { x: number | null; y: number | null },
) {
  const user = await prisma.user.findUnique({ where: { id: userId }, select: { id: true } })
  if (!user) throw new Error('用户不存在')
  const updated = await prisma.user.update({
    where: { id: userId },
    data: {
      coverUrl,
      coverFocusX: focus?.x ?? null,
      coverFocusY: focus?.y ?? null,
    },
  })
  invalidateCurrentUserCache(userId)
  return {
    coverUrl: absoluteMediaUrl(updated.coverUrl),
    coverFocusX: updated.coverFocusX ?? null,
    coverFocusY: updated.coverFocusY ?? null,
  }
}

/** 只更新焦点（不重传图片）—— 用户重选「画面重点在哪」时调用 */
export async function updateMyCoverFocus(
