/**
 * Social 业务服务（Stage 2.3）：
 * Feed（推荐/最新/热门/关注）、帖子详情、点赞/收藏、评论/回复、评论点赞、
 * 关注/粉丝、屏蔽、通知、举报、我的收藏。
 * 所有互动走唯一约束 + 事务维护反规范化计数，幂等。
 */
import { prisma } from '../../db'
import { checkContent } from '../content/policy'
import { appCache } from '../../cache'
import { absoluteMediaUrl } from '../../media-url'

export type SocialFeedTab = 'recommended' | 'latest' | 'hot' | 'following'
export type NotificationTypeName = 'LIKE' | 'COMMENT' | 'REPLY' | 'FAVORITE' | 'FOLLOW'

const POST_INCLUDE: any = {
  author: { select: { id: true, username: true, nickname: true, avatarUrl: true, accountId: true } },
  travel: {
    include: {
      coverMedia: true,
      _count: { select: { days: true, memories: true } },
    },
  },
  post: {
    select: { id: true, slug: true, cover: true, images: true, location: true, date: true },
  },
}

function iso(v: Date | string | null | undefined): string | null {
  if (!v) return null
  const d = v instanceof Date ? v : new Date(v)
  return isNaN(d.getTime()) ? null : d.toISOString()
}

function mediaUrl(storageKey: string): string {
  if (process.env.STORAGE_ENDPOINT && process.env.STORAGE_BUCKET) {
    const base = (process.env.STORAGE_PUBLIC_BASE_URL || process.env.STORAGE_ENDPOINT).replace(/\/+$/, '')
    return absoluteMediaUrl(base + '/' + storageKey) ?? (base + '/' + storageKey)
  }
  return absoluteMediaUrl('/uploads/' + storageKey) ?? ('/uploads/' + storageKey)
}

function travelCoverUrl(travel: any): string | null {
  if (travel?.coverMedia?.storageKey) return mediaUrl(travel.coverMedia.storageKey)
  if (travel?.cover) return String(travel.cover)
  return null
}

function serializeAuthor(author: any) {
  if (!author) return null
  return {
    id: author.id,
    username: author.username,
    nickname: author.nickname ?? null,
    avatarUrl: absoluteMediaUrl(author.avatarUrl),
    accountId: author.accountId ?? null,
  }
}

function postImages(post: any): string[] {
  let raw: string[] = []
  if (!post) return raw
  if (Array.isArray(post.images)) raw = post.images.filter((v: any) => typeof v === 'string')
  else if (typeof post.images === 'string') {
    try {
      const parsed = JSON.parse(post.images)
      if (Array.isArray(parsed)) raw = parsed.filter((v: any) => typeof v === 'string')
    } catch {}
  }
  return raw.map((u) => absoluteMediaUrl(u) ?? u)
}

function serializePost(row: any, likedIds: Set<number>, favoriteIds: Set<number>) {
  const travel = row.travel ?? null
  const post = row.post ?? null
  const photos = post ? postImages(post) : []
  const coverUrl = absoluteMediaUrl(post ? (post.cover || photos[0] || null) : travelCoverUrl(travel))
  return {
    id: row.id,
    travelId: row.travelId ?? null,
    title: row.title,
    summary: row.summary,
    coverUrl,
    location: travel?.location ?? post?.location ?? null,
    startDate: iso(travel?.startDate ?? post?.date),
    endDate: iso(travel?.endDate ?? post?.date),
    dayCount: travel?._count?.days ?? (post ? 1 : 0),
    photoCount: travel?._count?.memories ?? photos.length,
    travelType: travel?.travelType ?? null,
    author: serializeAuthor(row.author),
    likeCount: row.likeCount,
    commentCount: row.commentCount,
    favoriteCount: row.favoriteCount,
    publishedAt: iso(row.publishedAt),
    isLiked: likedIds.has(row.id),
    isFavorited: favoriteIds.has(row.id),
  }
}

async function attachViewerState(rows: any[], userId: number | null | undefined) {
  const ids = rows.map((r) => r.id)
  let likedIds = new Set<number>()
  let favoriteIds = new Set<number>()
  if (userId && ids.length) {
    const [likes, favs] = await Promise.all([
      prisma.postLike.findMany({ where: { userId, postId: { in: ids } }, select: { postId: true } }),
      prisma.postFavorite.findMany({ where: { userId, postId: { in: ids } }, select: { postId: true } }),
    ])
    likedIds = new Set(likes.map((l) => l.postId))
    favoriteIds = new Set(favs.map((f) => f.postId))
  }
  return rows.map((r) => serializePost(r, likedIds, favoriteIds))
}

function heatScore(p: any): number {
  const publishedAt = new Date(p.publishedAt).getTime()
  const ageHours = Math.max(0, (Date.now() - publishedAt) / 3600000)
  const freshness = 1 / (1 + ageHours / 72)
  return (p.likeCount * 1 + p.commentCount * 3 + p.favoriteCount * 4 + 1) * freshness
}

async function blockedAuthorIds(userId: number): Promise<number[]> {
  const rows = await prisma.userBlock.findMany({ where: { blockerId: userId }, select: { blockedId: true } })
  return rows.map((r) => r.blockedId)
}

export interface SocialFeedResult {
  data: any[]
  total: number
  page: number
  pageSize: number
  hasMore: boolean
}

/** 旅行圈「同行关系」筛选（Travel.travelType 枚举；与前端 TYPE_FILTERS 一致） */
export const SOCIAL_FEED_TRAVEL_TYPES = ['ALONE', 'COUPLE', 'FAMILY', 'FRIENDS', 'BFF', 'GROUP', 'OTHER'] as const

export async function listSocialFeed(params: {
  tab?: SocialFeedTab
  userId?: number | null
  page?: number
  pageSize?: number
  travelType?: string | null
}): Promise<SocialFeedResult> {
  const tab = params.tab ?? 'recommended'
  const page = Math.max(1, params.page ?? 1)
  const pageSize = Math.min(100, Math.max(1, params.pageSize ?? 20))
  const userId = params.userId ?? null
  const travelType =
    params.travelType && (SOCIAL_FEED_TRAVEL_TYPES as readonly string[]).includes(params.travelType)
      ? params.travelType
      : null

  const baseWhere: any = { visibility: 'PUBLIC' }
  // 类型筛选：travelType 挂在关联的 Travel 上（legacy 帖没有 travel，不匹配任何类型）
  if (travelType) baseWhere.travel = { travelType }
  if (userId) {
    const blocked = await blockedAuthorIds(userId)
    if (blocked.length) baseWhere.authorId = { notIn: blocked }
  }

  if (tab === 'following') {
    if (!userId) return { data: [], total: 0, page, pageSize, hasMore: false }
    const follows = await prisma.userFollow.findMany({ where: { followerId: userId }, select: { followingId: true } })
    const ids = follows.map((f) => f.followingId)
    if (!ids.length) return { data: [], total: 0, page, pageSize, hasMore: false }
    const where = { ...baseWhere, authorId: { in: ids } }
    const total = await prisma.travelPost.count({ where })
    const rows = await prisma.travelPost.findMany({ where, include: POST_INCLUDE, orderBy: [{ publishedAt: 'desc' }, { id: 'desc' }], skip: (page - 1) * pageSize, take: pageSize })
    const data = await attachViewerState(rows, userId)
    return { data, total, page, pageSize, hasMore: page * pageSize < total }
  }

  if (tab === 'latest' || tab === 'hot') {
    const orderBy: any = tab === 'latest'
      ? [{ publishedAt: 'desc' }, { id: 'desc' }]
      : [{ likeCount: 'desc' }, { commentCount: 'desc' }, { favoriteCount: 'desc' }, { id: 'desc' }]
    const total = await prisma.travelPost.count({ where: baseWhere })
    const rows = await prisma.travelPost.findMany({ where: baseWhere, include: POST_INCLUDE, orderBy, skip: (page - 1) * pageSize, take: pageSize })
    const data = await attachViewerState(rows, userId)
    return { data, total, page, pageSize, hasMore: page * pageSize < total }
  }

  // recommended：近 90 天候选按热度分排序（第一版简单算法）
  // 阶段 A · A3：候选 + 评分结果内存缓存 60s，避免每个请求都重算 500 条热度排序
  // 缓存 key 必须带上类型筛选——同一用户在不同筛选下不能共享同一份候选集
  const since = new Date(Date.now() - 90 * 24 * 3600 * 1000)
  const feedCacheKey = `social:feed:recommended:u${userId ?? 'anon'}:t${travelType ?? 'all'}`
  const cachedScored = await appCache.get<Array<{ p: any; score: number }>>(feedCacheKey)
  let scored: Array<{ p: any; score: number }>
  if (cachedScored) {
    scored = cachedScored
  } else {
    const candidates = await prisma.travelPost.findMany({
      where: { ...baseWhere, publishedAt: { gte: since } },
      include: POST_INCLUDE,
      orderBy: { publishedAt: 'desc' },
      take: 500,
    })
    scored = candidates
      .map((p) => ({ p, score: heatScore(p) }))
      .sort((a, b) => b.score - a.score)
    await appCache.set(feedCacheKey, scored, 60_000)
  }
  const total = scored.length
  const slice = scored.slice((page - 1) * pageSize, page * pageSize).map((s) => s.p)
  const data = await attachViewerState(slice, userId)
  return { data, total, page, pageSize, hasMore: page * pageSize < total }
}

/**
 * 回忆照片的 include 形状（只在两处复用：公开帖照片收集、详情按天数据）。
 *
 * ⚠️ 这里**不能**在两层嵌套的 relation 上再加 `where`
 * （`mediaLinks: { include: { media: { where: ... } } }`）——
 * Prisma 会抛 `Unknown argument 'where'`，而调用方如果 catch 成空数组，
 * 表现就是"详情页看不到任何按天内容"，日志里却什么都没有。
 * 类型过滤（`type: 'IMAGE'`）改在 JS 侧做，反正一个回忆的照片数量很小。
 */
const memoryPhotosInclude: any = {
  media: { orderBy: { id: 'asc' } },
  mediaLinks: { include: { media: true } },
}

/** 只保留图片类型（原先把 `type: 'IMAGE'` 写在 where 里，见上面的说明） */
function imagesOf(rows: any[] | undefined): any[] {
  return (rows || []).filter((m: any) => m && m.type === 'IMAGE' && m.storageKey)
}

/**
 * 收集某本旅行下的**公开**照片（封面 + 公开回忆的主图与关联图，去重）。
 *
 * `Memory.visibility` 由创建流程决定（**私密回忆不该出现在公开帖里**），
 * 这里显式只取 `PUBLIC` —— 不依赖"旅行公开所以里面全公开"的隐含假设。
 */
async function collectTravelPhotos(travelId: number): Promise<string[]> {
  const urls: string[] = []
  try {
    const travel = await prisma.travel.findUnique({
      where: { id: travelId },
      select: { coverMedia: true, cover: true },
    })
    if (travel?.coverMedia?.storageKey) urls.push(mediaUrl(travel.coverMedia.storageKey))
    else if (travel?.cover) urls.push(String(travel.cover))

    const memories = await prisma.memory.findMany({
      where: { travelId, visibility: 'PUBLIC' },
      orderBy: [{ happenedAt: 'asc' }, { id: 'asc' }],
      include: memoryPhotosInclude,
    })
    for (const m of memories) {
      const keys = [
        ...imagesOf((m as any).media).map((x: any) => x.storageKey),
        ...imagesOf(((m as any).mediaLinks || []).map((l: any) => l?.media)).map((x: any) => x.storageKey),
      ]
      for (const key of keys) {
        if (!key) continue
        const u = mediaUrl(key)
        if (!urls.includes(u)) urls.push(u)
      }
    }
  } catch {
    // 照片收集失败不影响帖子详情返回
  }
  return urls
}

/**
 * 详情页的**按天**游记数据（R2）。
 *
 * 为什么需要：`/circle/<id>` 原先只有封面 + 一段摘要 + 照片墙，别人点进来
 * **看不到「旅行」本身** —— 没有每天的行程与回忆，这正是"点开别人的旅行却看不到内容"的实质。
 *
 * 与 `travel.service.getTravelTimeline` 口径一致（天 → 行程 → 回忆 → 照片），
 * 但这里是**发布态**，照片只取公开回忆（`Memory.visibility = PUBLIC`）与旅行封面，
 * 私密回忆一律不下发 —— 不依赖"旅行公开所以里面全公开"这种隐含假设。
 */
export interface PublicTripDay {
  date: string | null
  title: string | null
  summary: string | null
  itinerary: { id: number; title: string; type: string; startTime: string | null; locationName: string | null }[]
  memories: { id: number; title: string; content: string | null; mood: string | null; photos: { id: number; url: string }[] }[]
  photos: { id: number; url: string }[]
}

export async function getPublicTripDays(travelId: number): Promise<PublicTripDay[]> {
  const days = await prisma.travelDay.findMany({
    where: { travelId },
    orderBy: { sortOrder: 'asc' },
    include: {
      itineraryItems: {
        orderBy: { sortOrder: 'asc' },
        include: { location: { select: { name: true } } },
      },
      memories: {
        where: { visibility: 'PUBLIC' },
        orderBy: [{ happenedAt: 'asc' }, { id: 'asc' }],
        include: memoryPhotosInclude,
      },
    } as any,
  })

  return days.map((d: any) => {
    const memories = (d.memories || []).map((mem: any) => {
      const primary = imagesOf(mem.media).map((m: any) => ({ id: m.id, url: mediaUrl(m.storageKey) }))
      const linked = imagesOf((mem.mediaLinks || []).map((l: any) => l?.media)).map((m: any) => ({
        id: m.id,
        url: mediaUrl(m.storageKey),
      }))
      const seen = new Set<number>()
      const photos = [...primary, ...linked].filter((p: any) => (seen.has(p.id) ? false : (seen.add(p.id), true)))
      return {
        id: mem.id,
        title: mem.title,
        content: mem.content ?? null,
        mood: mem.mood ?? null,
        photos,
      }
    })
    // 当天的照片 = 当天公开回忆的照片去重（与时间线口径一致）
    const seen = new Set<number>()
    const photos = memories
      .flatMap((m: any) => m.photos)
      .filter((p: any) => (seen.has(p.id) ? false : (seen.add(p.id), true)))

    return {
      date: iso(d.date),
      title: d.title ?? null,
      summary: d.summary ?? null,
      itinerary: (d.itineraryItems || []).map((it: any) => ({
        id: it.id,
        title: it.title,
        type: it.type,
        startTime: iso(it.startTime),
        locationName: it.location?.name ?? null,
      })),
      memories,
      photos,
    }
  })
}

export async function getSocialPost(id: number, userId?: number | null) {
  const row: any = await prisma.travelPost.findUnique({ where: { id }, include: POST_INCLUDE })
  if (!row) return null
  if (row.visibility !== 'PUBLIC' && row.authorId !== userId) return null
  const [post] = await attachViewerState([row], userId)

  // 按天游记：只有绑定 Travel 的帖子才有（历史 Post 来源没有天数据）。
  // 查询失败时降级为空数组（详情页其余部分照常可读），但**必须留日志** ——
  // 先前这里静默 catch，把一个 `Unknown argument 'where'` 变成了"页面没内容、日志也干净"，
  // 排查花了好几轮。降级可以，静默不可以。
  const days = row.travelId
    ? await getPublicTripDays(row.travelId).catch((e) => {
        console.error('[social] 按天游记加载失败（详情页将只显示封面与摘要）:', (e as Error)?.message || e)
        return []
      })
    : []

  /**
   * 当前用户是否已屏蔽该作者（2026-10-12 新增）。
   *
   * 为什么必须由服务端给：详情页此前把「已屏蔽」只放在本地 useState(false) 里，
   * 既读不到历史状态（重进页面又变回"屏蔽作者"），也无法做取消屏蔽。
   * 真机反馈："点一下屏蔽、再点一下取消，退出软件后又变回屏蔽作者"。
   */
  const isBlocked =
    userId != null && row.authorId != null && userId !== row.authorId
      ? !!(await prisma.userBlock.findUnique({
          where: { blockerId_blockedId: { blockerId: userId, blockedId: row.authorId } },
          select: { blockerId: true },
        }))
      : false

  return {
    ...post,
    postId: row.postId ?? null,
    canEdit: row.authorId != null && userId != null && row.authorId === userId,
    slug: row.travel?.slug ?? row.post?.slug ?? null,
    photos: row.post ? postImages(row.post) : row.travelId ? await collectTravelPhotos(row.travelId) : [],
    days,
    /** 是否已屏蔽该作者（供详情页渲染可切换的屏蔽/取消屏蔽） */
    isBlocked,
    /** 是否可给建议（R4 用）：公开帖登录后可评论；空间帖需成员 —— 这里先给出登录态判断 */
    canSuggest: !!userId,
  }
}

/** 编辑公开旅行帖（仅作者本人）：同步更新 TravelPost 与底层 Post/Travel 的标题与摘要。 */
export async function updateSocialPost(
  id: number,
  userId: number,
  input: { title?: string; summary?: string },
) {
  const row: any = await prisma.travelPost.findUnique({ where: { id } })
  if (!row) return null
  if (row.authorId !== userId) return null

  const title = input.title !== undefined ? String(input.title).trim().slice(0, 255) : undefined
  const summary = input.summary !== undefined
    ? String(input.summary).trim()
    : undefined

  if (title !== undefined && !title) throw new Error('标题不能为空')

  const data: { title?: string; summary?: string | null } = {}
  if (title !== undefined) data.title = title
  if (summary !== undefined) data.summary = summary || null
  if (Object.keys(data).length === 0) return getSocialPost(id, userId)

  /**
   * P1-15：TravelPost / Post / Travel 三表写必须同事务。
   *
   * 老实现是三次独立 update、后两次各套 `.catch(() => {})`：任一步失败就留下
   * 「feed 标题已改、详情页还是旧标题」的长期不一致，且日志里毫无痕迹 ——
   * 这正是用户能看到的不一致，所以这里选择**全成功或全失败**（不再吞错）。
   */
  await prisma.$transaction(async (tx) => {
    await tx.travelPost.update({ where: { id }, data })

    // 同步底层数据源，保证后续 feed / 详情刷新后仍一致。
    if (row.postId) {
      const postData: { title?: string; summary?: string | null } = {}
      if (title !== undefined) postData.title = title
      if (summary !== undefined) postData.summary = summary || null
      await tx.post.update({ where: { id: row.postId }, data: postData })
    }
    if (row.travelId) {
      const travelData: { title?: string; description?: string | null } = {}
      if (title !== undefined) travelData.title = title
      if (summary !== undefined) travelData.description = summary || null
      await tx.travel.update({ where: { id: row.travelId }, data: travelData })
    }
  })

  return getSocialPost(id, userId)
}

async function notify(recipientId: number | null, actorId: number, type: NotificationTypeName, refType: string, refId: number) {
  if (!recipientId || recipientId === actorId) return
  // 通知是旁路：失败不能让点赞/评论失败，但也不能静默（P1-15）
  try {
    await prisma.notification.create({ data: { userId: recipientId, actorId, type, refType, refId } })
  } catch (err) {
    console.error('[social.notify] 通知写入失败', { recipientId, actorId, type, refType, refId, err })
  }
}

/**
 * 设置点赞状态（**幂等**）。
 *
 * 为什么必须是"确保状态"而不是"切换"：客户端离线队列会重放写操作
 * （网络失败 → 入队 → 恢复后回放，失败还会退避重试多次）。若 POST/DELETE 都走
 * 同一个 toggle，一次重放就会把用户刚点的赞**撤销掉**：
 *   · 在线点击 → 乐观入队 → 请求超时但服务端其实成功 → 回放再次 toggle → 变回未赞；
 *   · 失败重试同理，偶数次执行等于没执行。
 * 现在 POST = 确保已赞、DELETE = 确保未赞，重复执行结果恒定，可安全重放。
 */
export async function setPostLike(postId: number, userId: number, liked: boolean) {
  const post = await prisma.travelPost.findUnique({ where: { id: postId }, select: { id: true, authorId: true } })
  if (!post) throw new Error('帖子不存在')
  const result = await prisma.$transaction(async (tx) => {
    const existing = await tx.postLike.findUnique({ where: { postId_userId: { postId, userId } } })
    if (liked && !existing) {
      await tx.postLike.create({ data: { postId, userId } })
      const p = await tx.travelPost.update({ where: { id: postId }, data: { likeCount: { increment: 1 } } })
      return { liked: true, likeCount: p.likeCount, changed: true }
    }
    if (!liked && existing) {
      await tx.postLike.delete({ where: { id: existing.id } })
      const p = await tx.travelPost.update({ where: { id: postId }, data: { likeCount: { decrement: 1 } } })
      return { liked: false, likeCount: Math.max(0, p.likeCount), changed: true }
    }
    // 已是目标状态：不改计数，也不重复发通知（重放安全）
    const p = await tx.travelPost.findUnique({ where: { id: postId }, select: { likeCount: true } })
    return { liked, likeCount: p?.likeCount ?? 0, changed: false }
  })
  if (result.liked && result.changed) await notify(post.authorId, userId, 'LIKE', 'TravelPost', postId)
  return { liked: result.liked, likeCount: result.likeCount }
}

/** 兼容旧调用方（切换语义）；新代码请用 setPostLike 明确目标状态。 */
export async function togglePostLike(postId: number, userId: number) {
  const existing = await prisma.postLike.findUnique({ where: { postId_userId: { postId, userId } }, select: { id: true } })
  return setPostLike(postId, userId, !existing)
}

/** 设置收藏状态（幂等）——语义与理由同 setPostLike，保证队列重放不会翻转状态。 */
export async function setPostFavorite(postId: number, userId: number, favorited: boolean) {
  const post = await prisma.travelPost.findUnique({ where: { id: postId }, select: { id: true, authorId: true } })
  if (!post) throw new Error('帖子不存在')
  const result = await prisma.$transaction(async (tx) => {
    const existing = await tx.postFavorite.findUnique({ where: { postId_userId: { postId, userId } } })
    if (favorited && !existing) {
      await tx.postFavorite.create({ data: { postId, userId } })
      const p = await tx.travelPost.update({ where: { id: postId }, data: { favoriteCount: { increment: 1 } } })
      return { favorited: true, favoriteCount: p.favoriteCount, changed: true }
    }
    if (!favorited && existing) {
      await tx.postFavorite.delete({ where: { id: existing.id } })
      const p = await tx.travelPost.update({ where: { id: postId }, data: { favoriteCount: { decrement: 1 } } })
      return { favorited: false, favoriteCount: Math.max(0, p.favoriteCount), changed: true }
    }
    const p = await tx.travelPost.findUnique({ where: { id: postId }, select: { favoriteCount: true } })
    return { favorited, favoriteCount: p?.favoriteCount ?? 0, changed: false }
  })
  if (result.favorited && result.changed) await notify(post.authorId, userId, 'FAVORITE', 'TravelPost', postId)
  return { favorited: result.favorited, favoriteCount: result.favoriteCount }
}

/** 兼容旧调用方（切换语义）；新代码请用 setPostFavorite 明确目标状态。 */
export async function togglePostFavorite(postId: number, userId: number) {
  const existing = await prisma.postFavorite.findUnique({ where: { postId_userId: { postId, userId } }, select: { id: true } })
  return setPostFavorite(postId, userId, !existing)
}

function serializeComment(row: any, likedIds: Set<number>, viewerId?: number | null) {
  return {
    id: row.id,
    postId: row.postId,
    userId: row.userId,
    parentId: row.parentId,
    content: row.content,
    status: row.status,
    createdAt: iso(row.createdAt),
    updatedAt: iso(row.updatedAt),
    author: serializeAuthor(row.user),
    likeCount: row._count?.likes ?? 0,
    isLiked: likedIds.has(row.id),
    /**
     * 是否本人所写（2026-10-15）。
     * 由服务端判定而不是客户端比对 userId —— 客户端要拿"我的 id"就得再发一次请求，
     * 而且容易和真实登录态不一致。这里直接给结论，客户端据此决定要不要显示删除入口。
     */
    isMine: viewerId != null && row.userId === viewerId,
  }
}

export async function listPostComments(postId: number, userId?: number | null) {
  const post = await prisma.travelPost.findUnique({ where: { id: postId }, select: { id: true } })
  if (!post) throw new Error('帖子不存在')
  const rows = await prisma.comment.findMany({
    where: { postId, status: 'VISIBLE' },
    orderBy: { createdAt: 'asc' },
    include: { user: { select: { id: true, username: true, nickname: true, avatarUrl: true, accountId: true } }, _count: { select: { likes: true } } },
  })
  const ids = rows.map((r) => r.id)
  let likedIds = new Set<number>()
  if (userId && ids.length) {
    const likes = await prisma.commentLike.findMany({ where: { userId, commentId: { in: ids } }, select: { commentId: true } })
    likedIds = new Set(likes.map((l) => l.commentId))
  }
  const comments = rows.map((r) => serializeComment(r, likedIds, userId))
  const top = comments.filter((c) => !c.parentId)
  const byParent = new Map<number, any[]>()
  for (const c of comments) {
    if (c.parentId) {
      const list = byParent.get(c.parentId) || []
      list.push(c)
      byParent.set(c.parentId, list)
    }
  }
  return top.map((c) => ({ ...c, replies: byParent.get(c.id) || [] }))
}

export async function createPostComment(input: { postId: number; userId: number; content: string; parentId?: number | null }) {
  const content = (input.content || '').trim()
  // v3.1 M3-B3：统一内容策略（长度/敏感词/外链限制）
  const check = checkContent(content, { maxLength: 1000, maxLinks: 0 })
  if (!check.ok) throw new Error(check.reason || '评论内容不合法')
  const post = await prisma.travelPost.findUnique({ where: { id: input.postId }, select: { id: true, authorId: true } })
  if (!post) throw new Error('帖子不存在')

  let parentAuthorId: number | null = null
  if (input.parentId) {
    const parent = await prisma.comment.findUnique({ where: { id: input.parentId }, select: { id: true, postId: true, userId: true, status: true } })
    if (!parent || parent.postId !== input.postId || parent.status !== 'VISIBLE') throw new Error('回复的评论不存在')
    parentAuthorId = parent.userId
  }

  const id = await prisma.$transaction(async (tx) => {
    const c = await tx.comment.create({ data: { postId: input.postId, userId: input.userId, parentId: input.parentId ?? null, content, status: 'VISIBLE' } })
    await tx.travelPost.update({ where: { id: input.postId }, data: { commentCount: { increment: 1 } } })
    return c.id
  })

  if (input.parentId && parentAuthorId) await notify(parentAuthorId, input.userId, 'REPLY', 'Comment', id)
  else await notify(post.authorId, input.userId, 'COMMENT', 'TravelPost', input.postId)

  const created = await prisma.comment.findUnique({ where: { id }, include: { user: { select: { id: true, username: true, nickname: true, avatarUrl: true, accountId: true } }, _count: { select: { likes: true } } } })
  // 传 input.userId：刚发出去这条当然是本人所写，客户端要立刻显示删除入口
  return serializeComment(created, new Set(), input.userId)
}

export async function deletePostComment(commentId: number, userId: number) {
  const c = await prisma.comment.findUnique({ where: { id: commentId }, select: { id: true, userId: true, postId: true, status: true } })
  if (!c) throw new Error('评论不存在')
  if (c.userId !== userId) throw new Error('无权删除该评论')
  if (c.status !== 'DELETED') {
    await prisma.$transaction(async (tx) => {
      await tx.comment.update({ where: { id: commentId }, data: { status: 'DELETED' } })
      await tx.travelPost.update({ where: { id: c.postId }, data: { commentCount: { decrement: 1 } } })
    })
  }
  return { deleted: true }
}

/**
 * 评论点赞（幂等）：POST = 确保已赞，DELETE = 确保未赞。
 *
 * 为什么不做成 toggle：帖子收藏那边已经踩过同一个坑（见 `app/api/social/posts/[id]/favorite`
 * 的注释）—— 「切换」语义在下一次重放/重试时会把用户的赞**撤销**。而评论点赞天然会重试
 * （乐观更新失败回滚后用户再点、弱网重发），因此服务端只接受「设成目标状态」。
 *
 * 返回最新的 `likeCount`：客户端乐观更新后拿到服务端真值，不必再拉一次整个评论列表。
 */
export async function setCommentLike(commentId: number, userId: number, liked: boolean) {
  const c = await prisma.comment.findUnique({ where: { id: commentId }, select: { id: true } })
  if (!c) throw new Error('评论不存在')
  if (liked) {
    await prisma.commentLike.upsert({
      where: { commentId_userId: { commentId, userId } },
      update: {},
      create: { commentId, userId },
    })
  } else {
    await prisma.commentLike.deleteMany({ where: { commentId, userId } })
  }
  const likeCount = await prisma.commentLike.count({ where: { commentId } })
  return { liked, likeCount }
}

export async function followUser(actorId: number, targetId: number) {
  if (actorId === targetId) throw new Error('不能关注自己')
  const target = await prisma.user.findUnique({ where: { id: targetId }, select: { id: true } })
  if (!target) throw new Error('用户不存在')
  await prisma.userFollow.upsert({
    where: { followerId_followingId: { followerId: actorId, followingId: targetId } },
    update: {},
    create: { followerId: actorId, followingId: targetId },
  })
  await notify(targetId, actorId, 'FOLLOW', 'User', targetId)
  return { following: true }
}

export async function unfollowUser(actorId: number, targetId: number) {
  await prisma.userFollow.deleteMany({ where: { followerId: actorId, followingId: targetId } })
  return { following: false }
}

export async function blockUser(actorId: number, targetId: number) {
  if (actorId === targetId) throw new Error('不能屏蔽自己')
  const target = await prisma.user.findUnique({ where: { id: targetId }, select: { id: true } })
  if (!target) throw new Error('用户不存在')
  await prisma.userBlock.upsert({
    where: { blockerId_blockedId: { blockerId: actorId, blockedId: targetId } },
    update: {},
    create: { blockerId: actorId, blockedId: targetId },
  })
  return { blocked: true }
}

export async function unblockUser(actorId: number, targetId: number) {
  await prisma.userBlock.deleteMany({ where: { blockerId: actorId, blockedId: targetId } })
  return { blocked: false }
}

export async function getUserProfile(targetId: number, viewerId?: number | null) {
  // 阶段 A · A3：帖子/粉丝/关注三个 count 合并进 user 查询的 _count（过滤计数），
  // 从 3 次 count 降为 0 次额外查询（isFollowing/isBlocked 仍按需单独查）。
  const user = await prisma.user.findUnique({
    where: { id: targetId },
    select: {
      id: true, username: true, nickname: true, avatarUrl: true, accountId: true, createdAt: true,
      _count: {
        select: {
          travelPosts: { where: { visibility: 'PUBLIC' } },
          followers: true,
          following: true,
        },
      },
    },
  })
  if (!user) return null
  const [isFollowing, isBlocked] = await Promise.all([
    viewerId ? prisma.userFollow.findUnique({ where: { followerId_followingId: { followerId: viewerId, followingId: targetId } } }) : Promise.resolve(null),
    viewerId ? prisma.userBlock.findUnique({ where: { blockerId_blockedId: { blockerId: viewerId, blockedId: targetId } } }) : Promise.resolve(null),
  ])
  const postCount = user._count.travelPosts
  const followerCount = user._count.followers
  const followingCount = user._count.following
  const recent = await prisma.travelPost.findMany({ where: { authorId: targetId, visibility: 'PUBLIC' }, orderBy: { publishedAt: 'desc' }, take: 12, include: POST_INCLUDE })
  const posts = await attachViewerState(recent, viewerId)
  return {
    id: user.id,
    username: user.username,
    nickname: user.nickname,
    avatarUrl: user.avatarUrl,
    accountId: user.accountId,
    createdAt: iso(user.createdAt),
    stats: { postCount, followerCount, followingCount },
    isFollowing: !!isFollowing,
    isBlocked: !!isBlocked,
    posts,
  }
}

export async function listFollowers(userId: number) {
  const rows = await prisma.userFollow.findMany({ where: { followingId: userId }, orderBy: { createdAt: 'desc' }, include: { follower: { select: { id: true, username: true, nickname: true, avatarUrl: true, accountId: true } } } })
  return rows.map((r) => ({ ...serializeAuthor(r.follower) }))
}

export async function listFollowing(userId: number) {
  const rows = await prisma.userFollow.findMany({ where: { followerId: userId }, orderBy: { createdAt: 'desc' }, include: { following: { select: { id: true, username: true, nickname: true, avatarUrl: true, accountId: true } } } })
  return rows.map((r) => ({ ...serializeAuthor(r.following) }))
}

export async function listNotifications(userId: number, page?: number, pageSize?: number) {
  const p = Math.max(1, page ?? 1)
  const ps = Math.min(100, Math.max(1, pageSize ?? 20))
  const where = { userId }
  const total = await prisma.notification.count({ where })
  const rows = await prisma.notification.findMany({
    where,
    orderBy: { createdAt: 'desc' },
    skip: (p - 1) * ps,
    take: ps,
    include: { actor: { select: { id: true, username: true, nickname: true, avatarUrl: true, accountId: true } } },
  })
  const data = rows.map((r) => ({ id: r.id, type: r.type, refType: r.refType, refId: r.refId, read: r.read, createdAt: iso(r.createdAt), actor: serializeAuthor(r.actor) }))
  const unread = await prisma.notification.count({ where: { userId, read: false } })
  return { data, total, unread, page: p, pageSize: ps, hasMore: p * ps < total }
}

export async function markNotificationsRead(userId: number, ids?: number[]) {
  if (ids && ids.length) {
    await prisma.notification.updateMany({ where: { userId, id: { in: ids } }, data: { read: true } })
  } else {
    await prisma.notification.updateMany({ where: { userId, read: false }, data: { read: true } })
  }
  return { ok: true }
}

export async function reportPost(postId: number, reporterId: number, reason: string) {
  const r = (reason || '').trim()
  if (!r) throw new Error('请填写举报原因')
  const post = await prisma.travelPost.findUnique({ where: { id: postId }, select: { id: true } })
  if (!post) throw new Error('帖子不存在')
  await prisma.report.upsert({
    where: { postId_reporterId: { postId, reporterId } },
    update: { reason: r, status: 'PENDING' },
    create: { postId, reporterId, reason: r },
  })
  return { reported: true }
}

export async function listMyFavorites(userId: number, page?: number, pageSize?: number) {
  const p = Math.max(1, page ?? 1)
  const ps = Math.min(100, Math.max(1, pageSize ?? 20))
  const total = await prisma.postFavorite.count({ where: { userId } })
  const favs = await prisma.postFavorite.findMany({
    where: { userId },
    orderBy: { createdAt: 'desc' },
    skip: (p - 1) * ps,
    take: ps,
    include: { post: { include: POST_INCLUDE } },
  })
  const data = await attachViewerState(favs.map((f) => f.post), userId)
  return { data, total, page: p, pageSize: ps, hasMore: p * ps < total }
}

/**
 * TravelPost：公开旅行帖子（Stage 2.1/2.2 发布/同步服务）
 * - Travel 与 TravelPost 解耦：用户公开的是 TravelPost，不是整个 Space。
 * - 以 Travel.visibility === 'PUBLIC'（或旧 isPublic=true）为「公开」判定。
 * - syncTravelPost 幂等：公开则 upsert，非公开则删除。
 */
import { prisma } from '../../db'
import type { Prisma } from '@prisma/client'
import { isPublishedToCircle } from './social-permissions'
import { storageKeyToUrl, absoluteMediaUrl } from '../../media-url'

/**
 * 事务客户端（P1-15）：travel.service 的 create/update/delete 会把
 * `prisma.$transaction` 的 tx 透传进来，使「Travel 行 + TravelPost 投影」同事务。
 * 所有导出函数保持向后兼容：不传 tx 时行为与拆分前完全一致（走全局 prisma）。
 */
type TxClient = Prisma.TransactionClient

function toIso(v: Date | null | undefined): string | null {
  if (!v) return null
  const d = v instanceof Date ? v : new Date(v)
  return isNaN(d.getTime()) ? null : d.toISOString()
}

/** 解析 TravelPost 的作者 ID：优先 Travel.ownerId，其次 Space 的 OWNER 成员，最后首个用户 */
async function resolveAuthorId(
  spaceId: number | null,
  ownerId: number | null,
  db: TxClient | typeof prisma = prisma,
): Promise<number | null> {
  if (ownerId) return ownerId
  if (spaceId) {
    const owner = await db.spaceMember.findFirst({
      where: { spaceId, role: 'OWNER', status: 'ACTIVE' },
      select: { userId: true },
    })
    if (owner?.userId) return owner.userId
  }
  const first = await db.user.findFirst({ orderBy: { id: 'asc' }, select: { id: true } })
  return first?.id ?? null
}

export interface TravelPostSyncResult {
  id: number
  published: boolean
}

/** 幂等同步：根据当前 Travel 可见性决定创建/更新/删除 TravelPost（可传入事务客户端） */
export async function syncTravelPost(travelId: number, tx?: TxClient): Promise<TravelPostSyncResult | null> {
  const db = tx ?? prisma
  const travel = await db.travel.findUnique({
    where: { id: travelId },
    select: {
      id: true,
      spaceId: true,
      ownerId: true,
      visibility: true,
      isPublic: true,
      title: true,
      description: true,
      coverMediaId: true,
    },
  })
  if (!travel) return null

  if (!isPublishedToCircle(travel)) {
    // 取消公开：失败必须让事务回滚（老实现 .catch(() => {}) 会留下"帖子还在但旅行已私密"的不一致）
    await db.travelPost.deleteMany({ where: { travelId } })
    return null
  }

  const authorId = await resolveAuthorId(travel.spaceId, travel.ownerId, db)
  const summary = travel.description ?? null
  const coverMediaId = travel.coverMediaId ?? null

  const existing = await db.travelPost.findUnique({ where: { travelId } })
  if (existing) {
    await db.travelPost.update({
      where: { travelId },
      data: {
        title: travel.title,
        summary,
        coverMediaId,
        visibility: 'PUBLIC',
        ...(authorId ? { authorId } : {}),
      },
    })
    return { id: existing.id, published: true }
  }

  if (!authorId) return null
  const created = await db.travelPost.create({
    data: {
      travelId,
      authorId,
      visibility: 'PUBLIC',
      title: travel.title,
      summary,
      coverMediaId,
    },
  })
  return { id: created.id, published: true }
}

/** 公开到旅行圈 */
export async function publishTravelPost(travelId: number, tx?: TxClient): Promise<TravelPostSyncResult | null> {
  return syncTravelPost(travelId, tx)
}

/** 取消公开（移除旅行圈）；失败向上抛，由调用方决定是否阻断（P1-15 去静默） */
export async function unpublishTravelPost(travelId: number, tx?: TxClient): Promise<void> {
  const db = tx ?? prisma
  await db.travelPost.deleteMany({ where: { travelId } })
}

/** 按 Travel ID 取公开帖子 */
export async function getTravelPostByTravelId(travelId: number) {
  return prisma.travelPost.findUnique({
    where: { travelId },
    include: {
      author: { select: { id: true, username: true } },
      travel: {
        include: {
          coverMedia: true,
          _count: { select: { memories: true } },
        },
      },
    },
  })
}

/** 将帖子行映射为对外安全的摘要结构（供下一阶段 Feed API 复用） */
export function serializeTravelPost(row: any) {
  return {
    id: row.id,
    travelId: row.travelId,
    author: row.author
      ? { id: row.author.id, username: row.author.username }
      : null,
    title: row.title,
    summary: row.summary,
    coverUrl: row.travel?.coverMedia?.storageKey
      ? storageKeyToUrl(row.travel.coverMedia.storageKey)
      : absoluteMediaUrl(row.travel?.cover ?? null),
    publishedAt: toIso(row.publishedAt),
    likeCount: row.likeCount,
    commentCount: row.commentCount,
    favoriteCount: row.favoriteCount,
  }
}

/** 将公开的旧 Post（文章）同步到旅行圈；非 travel / 未发布 / 未公开则移除 */
export async function syncPublicPostToCircle(postId: number): Promise<TravelPostSyncResult | null> {
  const post = await prisma.post.findUnique({
    where: { id: postId },
    select: {
      id: true,
      userId: true,
      type: true,
      title: true,
      summary: true,
      location: true,
      date: true,
      published: true,
      isPublic: true,
    },
  })
  if (!post) return null

  if (post.type !== 'travel' || !post.published || !post.isPublic) {
    // 历史上这里静默吞错：清理失败没有日志，帖子会一直挂在旅行圈里
    try {
      await prisma.travelPost.deleteMany({ where: { postId } })
    } catch (err) {
      console.error('[travel-post.syncPublicPostToCircle] TravelPost 清理失败', { postId, err })
    }
    return null
  }

  const authorId = post.userId ?? (await resolveAuthorId(null, post.userId))
  const summary = post.summary ?? null
  const publishedAt = post.date ? new Date(post.date) : new Date()

  const existing = await prisma.travelPost.findUnique({ where: { postId } })
  if (existing) {
    await prisma.travelPost.update({
      where: { postId },
      data: { title: post.title, summary, visibility: 'PUBLIC', publishedAt, ...(authorId ? { authorId } : {}) },
    })
    return { id: existing.id, published: true }
  }

  if (!authorId) return null
  const created = await prisma.travelPost.create({
    data: {
      postId,
      authorId,
      visibility: 'PUBLIC',
      title: post.title,
      summary,
      publishedAt,
    },
  })
  return { id: created.id, published: true }
}

export async function unpublishPublicPost(postId: number): Promise<void> {
  try {
    await prisma.travelPost.deleteMany({ where: { postId } })
  } catch (err) {
    console.error('[travel-post.unpublishPublicPost] TravelPost 清理失败', { postId, err })
  }
}

// ============================================================
// 内容管理 2.0：把「文章可见性(Post.isPublic)」与「旅行圈分享」解耦。
// 分享状态的事实来源 = TravelPost 记录是否存在；由用户显式动作驱动，
// 不再由 isPublic 变化自动触发（见 post-service.updatePost/createPost）。
// ============================================================
export interface SharePostToCircleInput {
  travelId?: number | null
  visibility?: 'PUBLIC' | 'SPACE'
}

/**
 * 显式「分享到旅行圈」：只要求文章已发布；不要求公开（私密文章也可分享出公开副本）。
 * - 复用 TravelPost 作为旅行圈公开副本（独立于文章本身的可见性）。
 * - 幂等：已分享则更新，未分享则创建。
 */
export async function sharePostToCircle(
  postId: number,
  opts: SharePostToCircleInput = {},
): Promise<TravelPostSyncResult | null> {
  const post = await prisma.post.findUnique({
    where: { id: postId },
    select: {
      id: true, userId: true, type: true, title: true, summary: true, date: true, published: true,
    },
  })
  if (!post) throw new Error('文章不存在')
  if (post.type !== 'travel') throw new Error('仅旅行记录可分享到旅行圈')
  if (!post.published) throw new Error('请先发布文章，再分享到旅行圈')

  const authorId = post.userId ?? (await resolveAuthorId(null, post.userId))
  const summary = post.summary ?? null
  const publishedAt = post.date ? new Date(post.date) : new Date()
  const travelId = opts.travelId ?? null
  const visibility = opts.visibility || 'PUBLIC'

  const existing = await prisma.travelPost.findUnique({ where: { postId } })
  if (existing) {
    await prisma.travelPost.update({
      where: { postId },
      data: {
        title: post.title,
        summary,
        visibility,
        publishedAt,
        travelId,
        ...(authorId ? { authorId } : {}),
      },
    })
    return { id: existing.id, published: true }
  }

  if (!authorId) return null
  const created = await prisma.travelPost.create({
    data: {
      postId,
      authorId,
      visibility,
      title: post.title,
      summary,
      publishedAt,
      travelId,
    },
  })
  return { id: created.id, published: true }
}

/** 取消分享（移除旅行圈），保留文章本身 */
export async function unsharePost(postId: number): Promise<void> {
  try {
    await prisma.travelPost.deleteMany({ where: { postId } })
  } catch (err) {
    console.error('[travel-post.unsharePost] TravelPost 清理失败', { postId, err })
  }
}

/**
 * Space 业务服务
 */
import { createHash, randomBytes } from 'crypto'
import { prisma } from '../../db'
import { PrismaSpaceRepository } from './space.repository'
import { requireSpaceOwner, requireSpaceMember, requireSpaceRole, SpaceAccessError, type SpaceRole } from './permissions'
import { writeAuditLog } from '../audit/audit-log.service'

const SLUG_RE = /^[a-z0-9-]{2,80}$/

/**
 * 由空间名派生 ASCII slug。
 *
 * **P0 修复**：原先 slug 由前端生成，且前端的清洗规则**保留中文**
 * （`SpacePanel.tsx` 里 `/^[^a-z0-9\u4e00-\u9fa5]+/`），而服务端只接受
 * `^[a-z0-9-]{2,80}$` —— 于是「我们的小家」这类中文名空间 100% 创建失败（400）。
 * 真库佐证：34 个空间全是自动创建的 `personal-*`，没有一个用户自建空间。
 *
 * 现在服务端统一生成：中文名派生为空 → 回退随机 `sp-xxxxxxxx`。
 * 刻意不支持中文 slug：`/space/[slug]` 要进 URL 与分享链接，ASCII 更稳
 * （编码、大小写、复制粘贴都少一类问题）。
 */
export function slugifySpaceName(name: string): string {
  return (name || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60)
}

function randomSpaceSlug(): string {
  return `sp-${randomBytes(4).toString('hex')}`
}

const INVITE_CODE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

/** 生成人类友好的邀请码（8 位，形如 7XK2-M9PQ） */
export function generateInviteCode(): string {
  const bytes = randomBytes(8)
  let code = ''
  for (let i = 0; i < bytes.length; i++) {
    code += INVITE_CODE_ALPHABET[bytes[i] % INVITE_CODE_ALPHABET.length]
  }
  return `${code.slice(0, 4)}-${code.slice(4, 8)}`
}

export function hashInviteCode(code: string): string {
  return createHash('sha256').update(code.replace(/[^A-Z0-9]/gi, '').toUpperCase()).digest('hex')
}

export interface CreateSpaceInput {
  name: string
  slug: string
  description?: string
  /** 空间类型（COUPLE/FAMILY/FRIENDS/SOLO/OTHER）；缺省 OTHER */
  spaceType?: string
}

const SPACE_TYPES = ['COUPLE', 'FAMILY', 'FRIENDS', 'SOLO', 'OTHER'] as const

export function isSpaceType(value: unknown): value is (typeof SPACE_TYPES)[number] {
  return typeof value === 'string' && (SPACE_TYPES as readonly string[]).includes(value)
}

export interface UpdateSpaceInput {
  name?: string
  description?: string | null
  spaceType?: string
  coverMediaId?: number | null
}

export class SpaceService {
  constructor(private readonly repo: PrismaSpaceRepository) {}

  async createSpace(username: string, input: CreateSpaceInput): Promise<{ id: number; slug: string }> {
    const name = (input.name || '').trim()
    if (name.length < 2 || name.length > 200) {
      throw new Error('空间名称需为 2-200 个字符')
    }

    /**
     * slug 一律由服务端决定（P0 修复，见 slugifySpaceName 注释）。
     * 传入的 slug 仅在合法时作为首选，非法/缺失时自动派生，**不再抛错** ——
     * 前端已不再让用户填写这个字段，报错只会变成对用户莫名的「空间标识不合法」。
     */
    const explicit = (input.slug || '').trim().toLowerCase()
    const base = explicit && SLUG_RE.test(explicit) ? explicit : slugifySpaceName(name) || randomSpaceSlug()

    const spaceType = isSpaceType(input.spaceType) ? input.spaceType : 'OTHER'

    // slug 全局唯一：冲突时追加随机后缀重试（与 ensurePersonalSpace 同一套做法）
    for (let attempt = 0; attempt < 5; attempt++) {
      const slug = attempt === 0 ? base : `${base.slice(0, 68)}-${randomBytes(2).toString('hex')}`
      if (await this.repo.slugExists(slug)) continue
      try {
        const id = await this.repo.create({
          name,
          slug,
          description: input.description,
          ownerUsername: username,
          spaceType,
        })
        await writeAuditLog({
          username,
          action: 'CREATE',
          resourceType: 'Space',
          resourceId: String(id),
          spaceId: id,
          metadata: { name, slug, spaceType },
        }).catch(() => {})
        return { id, slug }
      } catch {
        // 并发下 slug 被占用：换一个再试
      }
    }
    throw new Error('空间标识生成失败，请重试')
  }

  async listMySpaces(username: string) {
    return this.repo.listForUser(username)
  }

  async getSpace(username: string, spaceId: number) {
    const access = await requireSpaceMember(username, spaceId)
    return this.repo.findById(spaceId, access.role)
  }

  /** 按 slug 取空间详情（仅空间成员；非成员抛 SpaceAccessError → 路由返回 403） */
  async getSpaceBySlug(username: string, slug: string) {
    const found = await this.repo.findBySlug(slug)
    if (!found) return null
    return this.getSpace(username, found.id)
  }

  /**
   * 仅解析 slug → id（**不做权限校验**）。
   * 用途：概览装配需要先拿到 id，权限统一在 `getSpace` 里校验一次，
   * 避免同一请求里查两遍成员表。调用方必须随后走带权限的读取。
   */
  async getSpaceIdBySlug(slug: string): Promise<number | null> {
    const found = await this.repo.findBySlug(slug)
    return found?.id ?? null
  }

  /** 更新空间自身（改名 / 改简介 / 改类型 / 换封面）：仅 OWNER */
  async updateSpace(actor: string, spaceId: number, input: UpdateSpaceInput): Promise<void> {
    await requireSpaceOwner(actor, spaceId)

    const patch: UpdateSpaceInput = {}
    if (input.name !== undefined) {
      const name = String(input.name).trim()
      if (name.length < 2 || name.length > 200) throw new Error('空间名称需为 2-200 个字符')
      patch.name = name
    }
    if (input.description !== undefined) {
      const desc = input.description === null ? null : String(input.description).trim()
      if (desc && desc.length > 500) throw new Error('简介最多 500 个字符')
      patch.description = desc || null
    }
    if (input.spaceType !== undefined) {
      if (!isSpaceType(input.spaceType)) throw new Error('空间类型不合法')
      patch.spaceType = input.spaceType
    }
    if (input.coverMediaId !== undefined) {
      patch.coverMediaId = input.coverMediaId === null ? null : Number(input.coverMediaId) || null
    }
    if (Object.keys(patch).length === 0) throw new Error('没有需要更新的内容')

    await this.repo.update(spaceId, patch)
    await writeAuditLog({
      username: actor,
      action: 'UPDATE',
      resourceType: 'Space',
      resourceId: String(spaceId),
      spaceId,
      metadata: patch as Record<string, unknown>,
    }).catch(() => {})
  }

  /**
   * 调整成员角色（仅 OWNER）。
   * 硬约束：不允许把**最后一个 OWNER** 降级，否则空间会变成没人能管的孤儿。
   */
  async updateMemberRole(actor: string, spaceId: number, memberUsername: string, role: SpaceRole) {
    await requireSpaceOwner(actor, spaceId)
    const name = (memberUsername || '').trim()
    if (!name) throw new Error('请输入成员用户名')
    if (!['OWNER', 'MEMBER', 'VIEWER'].includes(role)) throw new Error('角色不合法')

    const members = await this.repo.listMembers(spaceId)
    const target = members.find((m) => m.username === name && m.status === 'ACTIVE')
    if (!target) throw new Error('该成员不在空间中')

    if (target.role === 'OWNER' && role !== 'OWNER') {
      const owners = await this.repo.countActiveOwners(spaceId)
      if (owners <= 1) throw new Error('至少需要保留一位空间主人，请先转让主人身份')
    }

    await this.repo.addMember(spaceId, name, role)
    await writeAuditLog({
      username: actor,
      action: 'UPDATE_PERMISSIONS',
      resourceType: 'SpaceMember',
      resourceId: String(spaceId),
      spaceId,
      metadata: { member: name, from: target.role, to: role },
    }).catch(() => {})
  }

  async addMember(actor: string, spaceId: number, memberUsername: string, role: SpaceRole) {
    await requireSpaceOwner(actor, spaceId)
    const name = (memberUsername || '').trim()
    if (!name) throw new Error('请输入成员用户名')
    await this.repo.addMember(spaceId, name, role)
    await writeAuditLog({
      username: actor,
      action: 'INVITE_MEMBER',
      resourceType: 'SpaceMember',
      resourceId: String(spaceId),
      spaceId,
      metadata: { memberUsername: name, role },
    }).catch(() => {})
  }

  async listMembers(actor: string, spaceId: number) {
    await requireSpaceMember(actor, spaceId)
    return this.repo.listMembers(spaceId)
  }

  async removeMember(actor: string, spaceId: number, memberUsername: string) {
    await requireSpaceOwner(actor, spaceId)
    await this.repo.removeMember(spaceId, memberUsername)
    await writeAuditLog({
      username: actor,
      action: 'UPDATE_PERMISSIONS',
      resourceType: 'SpaceMember',
      resourceId: String(spaceId),
      spaceId,
      metadata: { removed: memberUsername },
    }).catch(() => {})
  }

  /** 成员自己退出空间（D1）：OWNER 不可退出（需删除空间），MEMBER/VIEWER 可退出 */
  async leaveSpace(actor: string, spaceId: number): Promise<void> {
    const access = await requireSpaceMember(actor, spaceId)
    if (access.isOwner) {
      throw new Error('空间主人不能退出，如需解散请删除空间')
    }
    await this.repo.removeMember(spaceId, actor)
    await writeAuditLog({
      username: actor,
      action: 'UPDATE_PERMISSIONS',
      resourceType: 'SpaceMember',
      resourceId: String(spaceId),
      spaceId,
      metadata: { left: actor },
    }).catch(() => {})
  }

  /** 生成邀请码（仅 OWNER） */
  async createInvite(actor: string, spaceId: number, role: SpaceRole = 'MEMBER', expiresInDays = 7) {
    await requireSpaceOwner(actor, spaceId)
    const code = generateInviteCode()
    const expiresAt = new Date(Date.now() + expiresInDays * 24 * 60 * 60 * 1000)
    const id = await this.repo.createInvite({
      spaceId,
      role,
      expiresAt,
      createdBy: actor,
      tokenHash: hashInviteCode(code),
      code,
    })
    await writeAuditLog({
      username: actor,
      action: 'INVITE_MEMBER',
      resourceType: 'SpaceInvite',
      resourceId: String(spaceId),
      spaceId,
      metadata: { inviteId: id, role, expiresAt: expiresAt.toISOString() },
    }).catch(() => {})
    return { id, code, role, expiresAt: expiresAt.toISOString() }
  }

  /** 使用邀请码加入空间 */
  async joinByInvite(username: string, code: string) {
    const normalized = (code || '').replace(/[^A-Z0-9]/gi, '').toUpperCase()
    if (normalized.length < 6) {
      throw new Error('邀请码格式不正确')
    }
    const invite = await this.repo.findInviteByHash(hashInviteCode(normalized))
    if (!invite) {
      throw new Error('邀请码无效')
    }
    if (invite.usedAt) {
      throw new Error('该邀请码已被使用')
    }
    if (invite.expiresAt.getTime() < Date.now()) {
      throw new Error('该邀请码已过期')
    }

    // 防止重复加入/自邀
    const existing = await prisma.spaceMember.findUnique({
      where: { spaceId_username: { spaceId: invite.spaceId, username } },
    })
    if (existing && existing.status === 'ACTIVE') {
      throw new Error('你已经在该空间中')
    }
    await this.repo.addMember(invite.spaceId, username, invite.role)
    await this.repo.markInviteUsed(invite.id)

    await writeAuditLog({
      username,
      action: 'INVITE_MEMBER',
      resourceType: 'SpaceMember',
      resourceId: String(invite.spaceId),
      spaceId: invite.spaceId,
      metadata: { joinedByInvite: true, role: invite.role },
    }).catch(() => {})

    return {
      spaceId: invite.spaceId,
      spaceName: invite.space.name,
      role: invite.role,
    }
  }

  /** 查看空间邀请列表（成员可看，明文邀请码仅创建者可见） */
  async listInvites(actor: string, spaceId: number) {
    const access = await requireSpaceMember(actor, spaceId)
    const invites = await this.repo.listInvites(spaceId)
    if (!access.isOwner) {
      // 非创建者不返回明文邀请码
      return invites.map((inv) => ({
        id: inv.id,
        spaceId: inv.spaceId,
        role: inv.role,
        expiresAt: inv.expiresAt,
        createdBy: inv.createdBy,
        usedAt: inv.usedAt,
        createdAt: inv.createdAt,
        status: inv.status,
      }))
    }
    return invites
  }

  /** 撤销邀请（仅 OWNER） */
  async revokeInvite(actor: string, spaceId: number, inviteId: number) {
    await requireSpaceOwner(actor, spaceId)
    await this.repo.revokeInvite(inviteId)
    await writeAuditLog({
      username: actor,
      action: 'UPDATE_PERMISSIONS',
      resourceType: 'SpaceInvite',
      resourceId: String(spaceId),
      spaceId,
      metadata: { inviteId },
    }).catch(() => {})
  }

  async deleteSpace(actor: string, spaceId: number): Promise<void> {
    await requireSpaceOwner(actor, spaceId)
    await this.repo.delete(spaceId)
    await writeAuditLog({
      username: actor,
      action: 'DELETE',
      resourceType: 'Space',
      resourceId: String(spaceId),
      spaceId,
    }).catch(() => {})
  }

  /** 空间动态（成员可看）：复用 AuditLog，零改库 */
  async getActivity(actor: string, spaceId: number, limit = 30) {
    await requireSpaceMember(actor, spaceId)
    return this.repo.listActivity(spaceId, limit)
  }

  /**
   * 取（或创建）该用户的「个人空间」。
   *
   * 为什么需要：`Memory.spaceId` 是必填列，`createMemory` 还要求空间成员角色。
   * 但前台「新建旅行」建出的 Travel `spaceId` 为空（注册流程也不创建任何 Space），
   * 于是 `POST /api/travels/:id/memories` 会直接 400「该旅行尚未关联空间」——
   * 个人旅行**根本无法添加回忆与照片**，这正是真机反馈"没法进一步设置"的根因之一。
   *
   * 语义：个人空间 = 该用户作为 OWNER 的第一个空间；没有就建一个 SOLO 空间。
   * 选择"复用已有 OWNER 空间"而不是每次新建，是为了不产生一堆空空间；
   * 也刻意不新建后回写 Travel.spaceId（避免改动既有旅行归属）。
   */
  async ensurePersonalSpace(username: string, userId?: number | null): Promise<number> {
    const mine = await prisma.spaceMember.findFirst({
      where: { username, status: 'ACTIVE', role: 'OWNER' },
      orderBy: { joinedAt: 'asc' },
      select: { spaceId: true },
    })
    if (mine) return mine.spaceId

    // slug 需全局唯一：用 userId/username 派生，冲突时附加随机后缀重试
    const base = `personal-${userId ?? username}`.toLowerCase().replace(/[^a-z0-9-]/g, '-').slice(0, 60)
    for (let attempt = 0; attempt < 3; attempt++) {
      const slug = attempt === 0 ? base : `${base}-${randomBytes(3).toString('hex')}`
      try {
        const id = await this.repo.create({
          name: '我的旅行空间',
          slug,
          description: '个人旅行记忆空间（自动创建）',
          ownerUsername: username,
          ownerUserId: userId ?? null,
        })
        await prisma.space.update({ where: { id }, data: { spaceType: 'SOLO' } }).catch(() => {})
        await writeAuditLog({
          username,
          action: 'CREATE',
          resourceType: 'Space',
          resourceId: String(id),
          spaceId: id,
          metadata: { name: '我的旅行空间', slug, auto: 'ensurePersonalSpace' },
        }).catch(() => {})
        return id
      } catch {
        // slug 冲突或并发创建：重试
      }
    }
    // 兜底：并发下可能已被别的请求建好，再查一次
    const again = await prisma.spaceMember.findFirst({
      where: { username, status: 'ACTIVE', role: 'OWNER' },
      orderBy: { joinedAt: 'asc' },
      select: { spaceId: true },
    })
    if (again) return again.spaceId
    throw new Error('无法创建个人空间')
  }
}

export const spaceService = new SpaceService(new PrismaSpaceRepository())

/**
 * Timeline：把旅行记录与回忆按年份聚合，形成"我们的时间线"。
 * 数据来源（自动合并、按日期排序、按 slug 去重）：
 *  1. 旧版旅行记录 Post（type='travel'，含已上传的游记与其日期）
 *  2. 新版旅行 Travel（startDate）
 *  3. 回忆 Memory（happenedAt）
 *  4. 统一时间线条目 TimelineItem（若有）
 */
import { prisma } from '../../db'
import { scopedWhere } from '../../visibility'
import { skipDbOnBuild } from '../../db-guard'

export interface TimelineEntry {
  id: number
  type: 'travel' | 'memory'
  title: string
  date: string
  description?: string
  location?: string | null
  slug?: string
  cover?: string | null
  travelTitle?: string
  mood?: string | null
}

export interface TimelineYear {
  year: number
  entries: TimelineEntry[]
}

function toDate(value: Date | string | null | undefined): Date | null {
  if (!value) return null
  const d = value instanceof Date ? value : new Date(value)
  return isNaN(d.getTime()) ? null : d
}

/** Post 旧表 id 与 Travel 新表 id 可能重复，用负数偏移避免 React key 冲突 */
const POST_ID_OFFSET = -1000000

export async function getTimeline(userId?: number | null): Promise<TimelineYear[]> {
  if (skipDbOnBuild()) return []

  const [items, travels, posts, memories] = await Promise.all([
    prisma.timelineItem
      .findMany({
        where: userId ? { userId } : {},
        orderBy: { happenedAt: 'asc' },
        take: 500,
      })
      .catch(() => []),
    prisma.travel.findMany({
      where: { ...scopedWhere(userId, 'ownerId'), visibility: { in: ['SPACE', 'PUBLIC'] } } as any,
      select: { id: true, title: true, slug: true, startDate: true, description: true, cover: true },
      orderBy: { startDate: 'asc' },
      take: 500,
    }),
    prisma.post.findMany({
      where: { ...scopedWhere(userId), type: 'travel', published: true } as any,
      select: { id: true, title: true, slug: true, date: true, summary: true, location: true, cover: true },
      orderBy: { date: 'asc' },
      take: 500,
    }),
    prisma.memory.findMany({
      where: userId
        ? { OR: [{ createdById: userId }, { visibility: 'PUBLIC' }] }
        : { visibility: 'PUBLIC' },
      select: {
        id: true,
        title: true,
        happenedAt: true,
        content: true,
        mood: true,
        location: { select: { name: true } },
        travel: { select: { title: true } },
      },
      orderBy: { happenedAt: 'asc' },
      take: 500,
    }),
  ])

  // 新版 Travel 优先：Post 中与 Travel slug 相同的记录视为同一段旅行，去重
  const travelSlugs = new Set(travels.map((t) => t.slug))

  const grouped = new Map<number, TimelineEntry[]>()

  const push = (date: Date, entry: TimelineEntry) => {
    const year = date.getFullYear()
    if (!grouped.has(year)) grouped.set(year, [])
    grouped.get(year)!.push(entry)
  }

  // 1. 统一时间线条目（TRIP → 旅行，其余 → 回忆）
  for (const item of items) {
    const date = toDate(item.happenedAt)
    if (!date) continue
    push(date, {
      id: item.id,
      type: item.type === 'TRIP' ? 'travel' : 'memory',
      title: item.title,
      date: date.toISOString(),
      description: item.description || undefined,
    })
  }

  // 2. 新版旅行 Travel（按 startDate 自动排序）
  for (const t of travels) {
    const date = toDate(t.startDate)
    if (!date) continue
    push(date, {
      id: t.id,
      type: 'travel',
      title: t.title,
      date: date.toISOString(),
      description: t.description || undefined,
      slug: t.slug,
      cover: t.cover,
    })
  }

  // 3. 旧版旅行记录 Post（生产库的 4 篇游记在此；按 date 自动排序）
  for (const p of posts) {
    if (p.slug && travelSlugs.has(p.slug)) continue // 已在 Travel 中展示
    const date = toDate(p.date)
    if (!date) continue
    push(date, {
      id: p.id + POST_ID_OFFSET,
      type: 'travel',
      title: p.title,
      date: date.toISOString(),
      description: p.summary || undefined,
      location: p.location,
      slug: p.slug,
      cover: p.cover,
    })
  }

  // 4. 回忆 Memory（happenedAt）
  for (const m of memories) {
    const date = toDate(m.happenedAt)
    if (!date) continue
    push(date, {
      id: m.id,
      type: 'memory',
      title: m.title,
      date: date.toISOString(),
      description: m.content ? m.content.slice(0, 200) : undefined,
      location: m.location?.name ?? null,
      mood: m.mood ?? null,
      travelTitle: m.travel?.title,
    })
  }

  // 年份倒序，同年份内按日期正序（旅程先后）
  return Array.from(grouped.entries())
    .sort((a, b) => b[0] - a[0])
    .map(([year, entries]) => ({
      year,
      entries: entries.sort((a, b) => a.date.localeCompare(b.date)),
    }))
}

/**
 * Travel 数据访问（Repository）—— 旅行为回忆提供时间线容器（§29-§30）
 */
import { prisma } from '../../db'

export type TravelStatus = 'PLANNED' | 'ONGOING' | 'COMPLETED'
export type TravelVisibility = 'PRIVATE' | 'SPACE' | 'PUBLIC'
export type TravelType = 'ALONE' | 'COUPLE' | 'FAMILY' | 'FRIENDS' | 'BFF' | 'GROUP' | 'OTHER'

export interface TravelRecord {
  id: number
  spaceId: number
  title: string
  slug: string
  description: string | null
  startDate: string | null
  endDate: string | null
  coverMediaId: number | null
  status: TravelStatus
  visibility: TravelVisibility
  travelType: TravelType
  companions: unknown | null
  createdAt: string
  updatedAt: string
}

export interface CreateTravelInput {
  spaceId: number
  title: string
  slug: string
  description?: string | null
  startDate?: Date | string | null
  endDate?: Date | string | null
  status?: TravelStatus
  visibility?: TravelVisibility
  travelType?: TravelType
  companions?: unknown
}

export type UpdateTravelPatch = Partial<Omit<CreateTravelInput, 'spaceId'>>

function serialize(t: any): TravelRecord {
  return {
    id: t.id,
    spaceId: t.spaceId,
    title: t.title,
    slug: t.slug,
    description: t.description,
    startDate: t.startDate ? new Date(t.startDate).toISOString() : null,
    endDate: t.endDate ? new Date(t.endDate).toISOString() : null,
    coverMediaId: t.coverMediaId,
    status: t.status,
    visibility: t.visibility,
    travelType: t.travelType ?? 'ALONE',
    companions: t.companions ?? null,
    createdAt: t.createdAt.toISOString(),
    updatedAt: t.updatedAt.toISOString(),
  }
}

export class PrismaTravelRepository {
  async create(input: CreateTravelInput): Promise<number> {
    const t = await prisma.travel.create({
      data: {
        spaceId: input.spaceId,
        title: input.title,
        slug: input.slug,
        description: input.description ?? null,
        startDate: input.startDate ? new Date(input.startDate) : null,
        endDate: input.endDate ? new Date(input.endDate) : null,
        status: (input.status ?? 'PLANNED') as any,
        visibility: (input.visibility ?? 'SPACE') as any,
        travelType: (input.travelType ?? 'ALONE') as any,
        companions: input.companions ?? undefined,
      },
      // 只回读 id：避免引擎对 Json 列（companions）select-back 序列化出错
      select: { id: true },
    })
    return t.id
  }

  async findById(id: number): Promise<TravelRecord | null> {
    const t = await prisma.travel.findUnique({ where: { id } })
    return t ? serialize(t) : null
  }

  async slugExists(spaceId: number, slug: string, excludeId?: number): Promise<boolean> {
    const row = await prisma.travel.findFirst({
      where: { spaceId, slug, ...(excludeId ? { NOT: { id: excludeId } } : {}) },
      select: { id: true },
    })
    return row !== null
  }

  async listForSpace(spaceId: number): Promise<TravelRecord[]> {
    const rows = await prisma.travel.findMany({
      where: { spaceId },
      orderBy: [{ startDate: 'desc' }, { id: 'desc' }],
    })
    return rows.map(serialize)
  }

  async update(id: number, patch: UpdateTravelPatch): Promise<TravelRecord | null> {
    const data: any = {}
    if (patch.title !== undefined) data.title = patch.title
    if (patch.slug !== undefined) data.slug = patch.slug
    if (patch.description !== undefined) data.description = patch.description ?? null
    if (patch.startDate !== undefined) data.startDate = patch.startDate ? new Date(patch.startDate) : null
    if (patch.endDate !== undefined) data.endDate = patch.endDate ? new Date(patch.endDate) : null
    if (patch.status !== undefined) data.status = patch.status as any
    if (patch.visibility !== undefined) data.visibility = patch.visibility as any
    if (patch.travelType !== undefined) data.travelType = patch.travelType as any
    if (patch.companions !== undefined) data.companions = patch.companions
    if (Object.keys(data).length === 0) return this.findById(id)
    // 只回读 id 再反查：update 的 select-back 同样会踩 Json 列序列化问题（配合 jsonStrings 双保险）
    await prisma.travel.update({ where: { id }, data, select: { id: true } })
    return this.findById(id)
  }

  async remove(id: number): Promise<void> {
    await prisma.travel.delete({ where: { id } })
  }
}

export const prismaTravelRepository = new PrismaTravelRepository()

import { prisma } from '../../db'
import { findProvinceByLocation } from '../../province-map'
import { absoluteMediaUrl, storageKeyToUrl } from '../../media-url'

/**
 * 统计口径（**唯一事实源**）。
 *
 * 为什么单独抽出来：`/api/me` 与 `/api/dashboard` 各写了一份统计，而且读的是**不同的表** ——
 *  /api/me 读 `Travel`，/api/dashboard 读 `Post(type='travel')`（旧文章模型）。
 * 结果是同一批旅行在两个页面上数字不一样，"我的"显示 0 而看板显示 4。
 *
 * 现在的规则（两处共用这一份）：
 *  1. `Travel.ownerId = 我` 的旅行为主口径（App 里「+ 新建旅行」写的就是它）；
 *  2. **当我没有 Travel 但名下有旧文章时**，用旧文章兜底 —— 存量单管理员时期的数据
 *     是从后台发的文章，不能让用户看到一片 0；
 *  3. 目的地按 `location` 去重（拍板口径：城市）。
 *
 * ⚠️ 任何"统计旅行数/地方数/照片数"的新页面都必须调这里，不要再自己写 where。
 */

export interface TravelStatSource {
  /** 主口径来源：我名下的 Travel 行数 */
  travelRows: number
  /** 兜底来源：我名下已发布的旧文章数 */
  legacyPosts: number
  /** 实际采用的来源 */
  used: 'travel' | 'legacy'
}

export interface TravelArchiveStats {
  travelCount: number
  placeCount: number
  photoCount: number
  /** 有起止日期的旅行累计天数；无日期数据时为 null */
  travelDays: number | null
  provinceCount: number
  /** 数据来自哪张表（排查用；也便于前端在兜底态给一句说明） */
  source: TravelStatSource
}

/** 单条 media → 缩略图优先、回退原图 */
function thumbOf(m: StatMedia | null | undefined): string | null {
  const variants = Array.isArray(m?.variants) ? m.variants : []
  const thumb = variants.find((v) => v.variant === 'THUMBNAIL') ?? variants[0]
  return storageKeyToUrl(thumb?.storageKey ?? m?.storageKey ?? null)
}

/** 两个日期相差的整天数（b - a） */
export function diffInDays(a: Date, b: Date): number {
  return Math.round((b.getTime() - a.getTime()) / 86_400_000)
}

/** 统计查询的最小结构类型（与 loadMyTravels 的 select 同构，替代此前的 any）。
    variant 为可选：loadMyTravels 的 select 只取 storageKey（THUMBNAIL 过滤在 where 完成），
    而 profile.service 传入的行带 variant 字段。 */
interface StatMediaVariant {
  variant?: string
  storageKey: string
}
interface StatMedia {
  storageKey: string | null
  variants: StatMediaVariant[]
}
interface StatMemory {
  media: StatMedia[]
  mediaLinks: { media: StatMedia | null }[]
}
interface StatTravelRow {
  cover: string | null
  coverMedia: StatMedia | null
  days: { memories: StatMemory[] }[]
}

/** 一本旅行涉及的照片 URL（封面 + 所有回忆的主图与关联图，去重） */
export function travelPhotoUrls(t: StatTravelRow): string[] {
  const out = new Set<string>()
  const cover = thumbOf(t.coverMedia) ?? absoluteMediaUrl(t.cover ?? null)
  if (cover) out.add(cover)
  for (const day of t.days || []) {
    for (const mem of day.memories || []) {
      for (const m of mem.media || []) {
        const u = thumbOf(m)
        if (u) out.add(u)
      }
      for (const link of mem.mediaLinks || []) {
        const u = thumbOf(link?.media)
        if (u) out.add(u)
      }
    }
  }
  return Array.from(out)
}

/** 我名下旅行（含封面变体、按天回忆照片）——/api/me 与统计共用同一份查询 */
export async function loadMyTravels(userId: number) {
  return prisma.travel.findMany({
    where: { ownerId: userId } as any,
    orderBy: [{ startDate: 'desc' }, { id: 'desc' }],
    select: {
      id: true,
      title: true,
      slug: true,
      location: true,
      startDate: true,
      endDate: true,
      status: true,
      cover: true,
      companions: true,
      coverMedia: {
        select: {
          storageKey: true,
          variants: { where: { variant: 'THUMBNAIL' }, select: { storageKey: true } },
        },
      },
      days: {
        select: {
          memories: {
            select: {
              media: {
                select: {
                  id: true,
                  storageKey: true,
                  variants: { where: { variant: 'THUMBNAIL' }, select: { storageKey: true } },
                },
              },
              mediaLinks: {
                select: {
                  media: {
                    select: {
                      id: true,
                      storageKey: true,
                      variants: { where: { variant: 'THUMBNAIL' }, select: { storageKey: true } },
                    },
                  },
                },
              },
            },
          },
        },
      },
    },
  })
}

/** 旧文章兜底：Post(type='travel', published)，返回与统计同构的最小字段 */
async function loadLegacyTravelPosts(userId: number) {
  return prisma.post.findMany({
    where: { userId, type: 'travel', published: true },
    orderBy: { date: 'desc' },
    select: { id: true, title: true, slug: true, location: true, date: true, cover: true, images: true },
  })
}

function parseImageTokens(images: string | null | undefined): string[] {
  if (!images) return []
  try {
    const parsed = JSON.parse(images)
    return Array.isArray(parsed) ? parsed.map((v) => String(v)).filter(Boolean) : []
  } catch {
    return []
  }
}

function resolveImageToken(token: string): string | null {
  const raw = /^\d+$/.test(token) ? `/api/images/${token}` : token
  return absoluteMediaUrl(raw)
}

/**
 * 计算旅行档案统计。两个数据源都读出来后再决定用哪个 ——
 * 不能只看"Travel 表是否为空"就下结论，还要把旧文章数一起带上（排查时能看到全貌）。
 */
export async function getTravelArchiveStats(userId: number): Promise<TravelArchiveStats> {
  const [travels, legacyPosts] = await Promise.all([
    loadMyTravels(userId).catch(() => [] as Awaited<ReturnType<typeof loadMyTravels>>),
    loadLegacyTravelPosts(userId).catch(() => [] as Awaited<ReturnType<typeof loadLegacyTravelPosts>>),
  ])

  const used: TravelStatSource['used'] = travels.length > 0 ? 'travel' : 'legacy'
  const source: TravelStatSource = { travelRows: travels.length, legacyPosts: legacyPosts.length, used }

  if (used === 'travel') {
    const placeCount = new Set(
      travels.map((t) => t.location?.trim()).filter((v): v is string => !!v),
    ).size

    const allPhotoUrls = new Set<string>()
    for (const t of travels) {
      for (const u of travelPhotoUrls(t)) allPhotoUrls.add(u)
    }

    let travelDays = 0
    let hasDatedTravel = false
    for (const t of travels) {
      if (!t.startDate) continue
      hasDatedTravel = true
      travelDays += Math.max(1, diffInDays(t.startDate, t.endDate ?? t.startDate) + 1)
    }

    const provinceIds = new Set<string>()
    for (const t of travels) {
      if (!t.location) continue
      const p = findProvinceByLocation(t.location)
      if (p) provinceIds.add(p.id)
    }

    return {
      travelCount: travels.length,
      placeCount,
      photoCount: allPhotoUrls.size,
      travelDays: hasDatedTravel ? travelDays : null,
      provinceCount: provinceIds.size,
      source,
    }
  }

  // 兜底：存量旧文章（单管理员时期从后台发的旅行记录）
  const placeSet = new Set(legacyPosts.map((p) => p.location?.trim()).filter((v): v is string => !!v))
  const photoSet = new Set<string>()
  for (const p of legacyPosts) {
    // 封面可能是图片 ID（纯数字）或完整 URL，两种都要能解析
    if (p.cover) {
      const raw = String(p.cover)
      const coverUrl = absoluteMediaUrl(/^\d+$/.test(raw) ? `/api/images/${raw}` : raw)
      if (coverUrl) photoSet.add(coverUrl)
    }
    for (const token of parseImageTokens(p.images)) {
      const u = resolveImageToken(token)
      if (u) photoSet.add(u)
    }
  }
  const provinceIds = new Set<string>()
  for (const p of legacyPosts) {
    if (!p.location) continue
    const prov = findProvinceByLocation(p.location)
    if (prov) provinceIds.add(prov.id)
  }

  return {
    travelCount: legacyPosts.length,
    placeCount: placeSet.size,
    photoCount: photoSet.size,
    travelDays: null,
    provinceCount: provinceIds.size,
    source,
  }
}

/**
 * Travel 读模型映射：数据库行 → 对外 DTO 的**纯函数**（P2-32 拆分产物）。
 *
 * 抽出的理由：这些函数只做「形状转换 + 字段归一（媒体 URL / 金额 / 日期）」，
 * 不读库、不判可见性。放在 service 里时无法单独测试，且让 service 一半篇幅
 * 是字段搬运。抽走后 service 只剩查询与写入编排，规则/映射可分别演进。
 *
 * 约定（与拆分前逐字节一致，改动会破坏前端契约）：
 *  · 媒体 URL 一律走 storageKeyToUrl / absoluteMediaUrl（**不要手拼 /uploads/**，
 *    否则原生壳页面源是 https://localhost，相对地址会解析到本地壳 → 图片全挂）；
 *  · 金额入库是整数「分」，出口才转「元」；
 *  · 日期一律 Date → ISO 字符串，非法值给 null。
 */
import { centsToYuan } from './money'
import { absoluteMediaUrl, storageKeyToUrl } from '../../media-url'
import type {
  ExpenseRecord,
  TravelDayRecord,
  TravelDayTimelineItem,
  TravelDetail,
  TravelPublicDetail,
  TravelSummary,
} from './travel.types'

/** 解析 tags：新数据是 JSON 数组；历史数据可能是逗号分隔 */
export function safeParseTags(raw: string | null | undefined): string[] | null {
  if (!raw) return null
  try {
    const parsed = JSON.parse(raw)
    return Array.isArray(parsed) ? parsed.filter((v) => typeof v === 'string') : null
  } catch {
    // 旧数据可能为逗号分隔
    return raw.split(',').map((v) => v.trim()).filter(Boolean)
  }
}

/** Date（或可被 Date 解析的值） → ISO 字符串；null / 非法日期 → null */
export function iso(v: Date | null | undefined): string | null {
  if (!v) return null
  const d = v instanceof Date ? v : new Date(v)
  return isNaN(d.getTime()) ? null : d.toISOString()
}

/** 预算归一：非有限数或负数一律视为"未设置" */
export function isoBudget(v: unknown): number | null {
  const n = Number(v)
  if (!Number.isFinite(n) || n < 0) return null
  return n
}

/** 单条 media → 优先缩略图，无变体回退原图（减流量，用于旅行地图左侧照片画廊） */
function thumbUrlOf(m: any): string | null {
  const thumb = m?.variants?.find((v: any) => v.variant === 'THUMBNAIL')
  return storageKeyToUrl(thumb?.storageKey ?? m?.storageKey ?? null)
}

/** 旅行列表项：同时汇总「回忆照片轮播」与「封面（缩略图优先，回退 legacy cover）」 */
export function mapTravelSummary(t: any): TravelSummary {
  // 收集该旅行的回忆照片（去重），用于旅行地图左侧照片轮播
  const seen = new Set<string>()
  const photos: string[] = []
  for (const day of t.days || []) {
    for (const mem of day.memories || []) {
      for (const m of mem.media || []) {
        const url = thumbUrlOf(m)
        if (url && !seen.has(url)) {
          seen.add(url)
          photos.push(url)
        }
      }
    }
  }

  // 封面：优先 coverMedia（缩略图→原图），回退 legacy cover 字段（统一绝对化）
  const coverThumb = t.coverMedia?.variants?.find((v: any) => v.variant === 'THUMBNAIL')?.storageKey
  const coverMediaKey = t.coverMedia?.storageKey
  const coverUrl =
    storageKeyToUrl(coverThumb ?? coverMediaKey ?? null) ?? absoluteMediaUrl(t.cover ?? null)

  return {
    id: t.id,
    title: t.title,
    slug: t.slug,
    description: t.description,
    startDate: iso(t.startDate),
    endDate: iso(t.endDate),
    status: t.status,
    dayCount: t._count.days,
    // 花费合计：整数分求和（无浮点误差），出边界时转回元
    expenseTotal: centsToYuan(
      (t.expenses || []).reduce((s: number, e: { amountCents?: number | null }) => s + (e.amountCents ?? 0), 0),
    ),
    cover: coverUrl ?? t.cover ?? null,
    coverMediaId: t.coverMediaId ?? null,
    photos,
    tags: t.tags ? safeParseTags(t.tags) : null,
    location: t.location ?? null,
    updatedAt: iso(t.updatedAt),
    visibility: t.visibility ?? 'SPACE',
    spaceId: t.spaceId ?? null,
    ownerId: t.ownerId ?? null,
    confirmedAt: iso(t.confirmedAt),
  }
}

/** 旅行列表（批量） */
export function mapTravelList(rows: any[]): TravelSummary[] {
  return rows.map(mapTravelSummary)
}

/** 旅行详情（含天 / 行程项 / 花销） */
export function mapTravelDetail(travel: any): TravelDetail {
  return {
    id: travel.id,
    title: travel.title,
    slug: travel.slug,
    description: travel.description,
    startDate: iso(travel.startDate),
    endDate: iso(travel.endDate),
    status: travel.status,
    days: (travel.days || []).map((d: any): TravelDayRecord => ({
      id: d.id,
      date: iso(d.date),
      title: d.title,
      summary: d.summary,
      sortOrder: d.sortOrder,
      itinerary: (d.itineraryItems || []).map((it: any) => ({
        id: it.id,
        title: it.title,
        startTime: iso(it.startTime),
        endTime: iso(it.endTime),
        type: it.type,
        notes: it.notes,
        locationName: it.location?.name ?? null,
      })),
    })),
    expenses: mapExpenseRecords(travel.expenses || []),
    updatedAt: iso(travel.updatedAt),
    visibility: travel.visibility ?? 'SPACE',
    spaceId: travel.spaceId ?? null,
    ownerId: travel.ownerId ?? null,
  }
}

/** 花销行 → 对外结构（金额「分」→「元」） */
export function mapExpenseRecords(rows: any[]): ExpenseRecord[] {
  return rows.map((e: any) => ({
    id: e.id,
    amount: centsToYuan(e.amountCents),
    currency: e.currency,
    category: e.category,
    payer: e.payer,
    note: e.note,
    happenedAt: iso(e.happenedAt),
    /** 绑定的行程项（null = 未绑定）；前端据此在行程行下展示费用 */
    itineraryItemId: e.itineraryItemId ?? null,
  }))
}

/** 花销 tab：流水 + 合计（合计在整数分上求和，永不丢精度） */
export function mapExpenseList(rows: any[]): { expenses: ExpenseRecord[]; total: number } {
  return {
    expenses: mapExpenseRecords(rows),
    total: centsToYuan(rows.reduce((s: number, e: { amountCents: number }) => s + e.amountCents, 0)),
  }
}

/** 按天叙事时间线的天列表（旅行 → 每天 → 行程 → 回忆 → 照片） */
export function mapTravelTimelineDays(days: any[]): TravelDayTimelineItem[] {
  /** v3.1 M3-D1：照片优先缩略图（减流量），无变体回退原图 */
  const thumbUrl = (m: any) => storageKeyToUrl(m?.variants?.[0]?.storageKey ?? m?.storageKey ?? null)

  return days.map((d: any) => {
    const memories = (d.memories || []).map((mem: any) => {
      const primary = (mem.media || []).map((m: any) => ({ id: m.id, url: thumbUrl(m) }))
      const linked = (mem.mediaLinks || []).map((l: any) => ({ id: l.media.id, url: thumbUrl(l.media) }))
      const seen = new Set<number>()
      const photos = [...primary, ...linked].filter((p: any) => (seen.has(p.id) ? false : (seen.add(p.id), true)))
      return {
        id: mem.id,
        title: mem.title,
        content: mem.content ?? null,
        mood: mem.mood ?? null,
        happenedAt: iso(mem.happenedAt),
        photos,
      }
    })
    const seen = new Set<number>()
    const photos = memories
      .flatMap((mem: any) => mem.photos)
      .filter((p: any) => (seen.has(p.id) ? false : (seen.add(p.id), true)))
    return {
      id: d.id,
      date: iso(d.date),
      title: d.title,
      summary: d.summary,
      sortOrder: d.sortOrder,
      itinerary: (d.itineraryItems || []).map((it: any) => ({
        id: it.id,
        title: it.title,
        startTime: iso(it.startTime),
        endTime: iso(it.endTime),
        type: it.type,
        notes: it.notes,
        locationName: it.location?.name ?? null,
        expenses: (it.expenses || []).map((e: any) => ({
          id: e.id,
          amount: centsToYuan(e.amountCents),
          currency: e.currency,
          category: e.category,
          payer: e.payer ?? null,
          note: e.note ?? null,
          happenedAt: iso(e.happenedAt),
        })),
      })),
      memories,
      photos,
    } satisfies TravelDayTimelineItem
  })
}

/** 公开旅行详情（Markdown 已由 service 渲染好，这里只做形状转换） */
export function mapTravelPublicDetail(t: any, contentHtml: string): TravelPublicDetail {
  const coverThumb = t.coverMedia?.variants?.find((v: any) => v.variant === 'THUMBNAIL')?.storageKey
  const coverMediaKey = t.coverMedia?.storageKey
  const coverUrl = storageKeyToUrl(coverThumb ?? coverMediaKey ?? null) ?? absoluteMediaUrl(t.cover ?? null)

  return {
    id: t.id,
    title: t.title,
    slug: t.slug,
    description: t.description,
    startDate: iso(t.startDate),
    endDate: iso(t.endDate),
    status: t.status,
    contentHtml,
    tags: t.tags ? safeParseTags(t.tags) : null,
    location: t.location,
    cover: t.cover,
    coverUrl: coverUrl ?? null,
    coverMediaId: t.coverMediaId ?? null,
    travelType: t.travelType ?? 'ALONE',
    companions: t.companions ?? null,
    budget: isoBudget(t.budget),
    confirmedAt: iso(t.confirmedAt),
  }
}

/**
 * Travel 写路径的**规则与计划**（P2-32 拆分产物）。
 *
 * 抽出的理由：原 travel.service 里「校验/归一 + 日期计划 + 权限判定」与
 * 「prisma 调用」混在一起，导致同一段日期算法在 ensureTravelDays 与
 * syncTravelDayDates 里各写一遍，且无法单测。这里把**可计算的部分**收敛为
 * 纯函数（plan*），service 只负责读库 + 按计划落库 —— 也顺带让事务里
 * 的写操作变成"先算后写"，失败点更少。
 *
 * 只有 makeUniqueTravelSlug / canManageTravel 需要读库（唯一性/成员关系查询）。
 */
import { prisma } from '../../db'
import { makeTravelSlug } from './slug'

/** 行程项类型白名单（与前端胶囊一一对应） */
export const ITINERARY_TYPES = ['SPOT', 'RESTAURANT', 'HOTEL', 'TRANSPORT', 'ACTIVITY', 'OTHER']

/** 行程类型归一：未知值一律落 SPOT（避免脏值进库后前端无法渲染） */
export function normalizeItineraryType(value: string | null | undefined): string {
  return ITINERARY_TYPES.includes(value || '') ? (value as string) : 'SPOT'
}

/** 单本旅行「天」的生成上限：避免误填超长区间产生海量空天 */
export const MAX_TRAVEL_DAY_SPAN = 60

/** 预算上限（元）：超过这个数视为误填，拒绝入库 */
export const BUDGET_MAX_YUAN = 100_000_000

/**
 * 解析行程时间（2026-10-17 修正时区语义）
 * ============================================================================
 * 行程的「开始 / 结束」是**墙上时间**（wall clock：行程表上写的 17:00），不是时间点。
 * 之前用 `d.setHours()` 按**服务器时区**解释，客户端再用 `getHours()` 按**设备时区**
 * 读回 —— 两边时区不一致时整体平移。
 *
 * 真实故障：UTC+8 的设备选了 17:00–21:00，服务端（容器 TZ=UTC）存成 17:00Z，
 * 设备按 +8 渲染 → 显示成次日 01:00，21:00 → 05:00。这就是
 * 「选下午5点到晚上9点，回头变成凌晨1点到5点」的根因；也是
 * 「之前添加的行程时间全都乱了」的根因（每条都被平移了同样的量）。
 *
 * 修法：**写入与读取都用 UTC 字段承载墙上时间**（1970-01-01 基准日），与设备/服务器
 * 时区完全解耦：存 17:00，任何时区读出来都是 17:00，确定且可预期。
 * 附带效果：**历史数据自动修复** —— 库里那些 16:50Z / 20:30Z 的记录恰好就是
 * 当初写入的墙上时间，改用 UTC 读取后即正确显示。
 */
export function parseTimeOrDate(value: string | undefined | null): Date | null {
  if (!value) return null
  const m = value.trim().match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?$/)
  if (m) {
    const h = Math.min(23, Math.max(0, parseInt(m[1], 10)))
    const min = Math.min(59, Math.max(0, parseInt(m[2], 10)))
    const sec = m[3] ? Math.min(59, Math.max(0, parseInt(m[3], 10))) : 0
    return new Date(Date.UTC(1970, 0, 1, h, min, sec))
  }
  const d = new Date(value)
  return isNaN(d.getTime()) ? null : d
}

/** 取本地零点：日期对齐按「天」比较，不能带时分秒，否则同一天会被判成不同 */
export function localMidnight(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate())
}

/** 本地零点 + n 天（跨月/跨年/夏令时交给 Date 处理） */
export function localMidnightPlusDays(d: Date, days: number): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate() + days)
}

/**
 * 旅行区间 → 应生成的天数上限内的日期列表（ensureTravelDays 的计划）。
 * 未填/非法开始日、区间倒置 → 空数组（调用方按「至少 1 天」兜底）。
 */
export function planTravelDayDates(
  startDate?: string | null,
  endDate?: string | null,
): Date[] {
  const s = startDate ? new Date(startDate) : null
  if (!s || Number.isNaN(s.getTime())) return []
  const e = endDate ? new Date(endDate) : null
  const start = localMidnight(s)
  const end = e && !Number.isNaN(e.getTime()) ? localMidnight(e) : start
  const days = Math.round((end.getTime() - start.getTime()) / 86_400_000)
  if (days < 0) return []
  const out: Date[] = []
  for (let i = 0; i <= Math.min(days, MAX_TRAVEL_DAY_SPAN - 1); i++) {
    out.push(localMidnightPlusDays(start, i))
  }
  return out
}

/** 区间跨度（天，含首尾），上限 MAX_TRAVEL_DAY_SPAN */
export function planDaySpan(startDate: Date, endDate: Date | null): number {
  const start = localMidnight(startDate)
  const end = endDate && !Number.isNaN(endDate.getTime()) ? localMidnight(endDate) : start
  return (
    Math.max(0, Math.min(Math.round((end.getTime() - start.getTime()) / 86_400_000), MAX_TRAVEL_DAY_SPAN - 1)) + 1
  )
}

export interface DayAlignmentPlan {
  /** 需要就地改日期的天（id → 目标日期） */
  updates: { id: number; date: Date }[]
  /** 区间比现有天数长时需要补出的日期（按「第 existing+j 天」顺序） */
  extraDates: Date[]
}

/**
 * 「天」的日期对齐计划（syncTravelDayDates 的纯计算部分）。
 *
 * 语义（有意选择"就地对齐"而不是"删了重建"）：
 *  · 第 i 天的日期 = 开始日 + i 天；
 *  · 区间变长 → 补出缺失的天；变短 → **保留**多出来的天（里面可能已有回忆/照片，删掉等于毁数据），
 *    只是不再改动它们的日期；
 *  · 日期本来就一致的天空转（不发无意义的 UPDATE）。
 */
export function planDayAlignment(
  days: { id: number; date: Date | string | null; sortOrder: number }[],
  startDate: Date,
  endDate: Date | null,
): DayAlignmentPlan {
  const start = localMidnight(startDate)
  const span = planDaySpan(startDate, endDate)
  const updates: { id: number; date: Date }[] = []

  for (let i = 0; i < Math.min(days.length, span); i++) {
    const target = localMidnightPlusDays(start, i)
    const day = days[i]
    const same = day.date && new Date(day.date).toDateString() === target.toDateString()
    if (same) continue
    updates.push({ id: day.id, date: target })
  }

  const extraDates: Date[] = []
  for (let i = days.length; i < span; i++) {
    extraDates.push(localMidnightPlusDays(start, i))
  }

  return { updates, extraDates }
}

/** 「DAY 01」式标题：序号从 1 起、两位补零 */
export function dayTitle(index: number): string {
  return `DAY ${String(index + 1).padStart(2, '0')}`
}

/** 标题归一（后台编辑）：空白即拒绝，超长拒绝 —— 错误文案是接口契约，勿改 */
export function normalizeTravelTitle(raw: string): string {
  const title = raw.trim()
  if (!title) throw new Error('旅行名称不能为空')
  if (title.length > 120) throw new Error('旅行名称过长（最多 120 字）')
  return title
}

/** 预算严格校验（后台编辑）：非法即抛错（进度条算出负百分比比"没填"更糟） */
export function normalizeBudgetStrict(raw: number | null): number | null {
  if (raw === null) return null
  const n = Number(raw)
  if (!Number.isFinite(n) || n < 0) throw new Error('预算需为不小于 0 的数字')
  if (n > BUDGET_MAX_YUAN) throw new Error('预算数值过大')
  return n
}

/**
 * 预算宽容归一（同步队列/旧后台路径）：非法值返回 'invalid'，
 * 由调用方**静默丢弃**而不是把脏值写进库。
 */
export function normalizeBudgetLoose(raw: unknown): number | null | 'invalid' {
  if (raw === null) return null
  const n = Number(raw)
  if (!Number.isFinite(n) || n < 0 || n > BUDGET_MAX_YUAN) return 'invalid'
  return n
}

/**
 * slug 唯一化：`南京之行` 第二次创建时追加 `-2`、`-3`…（最多试 50 次）。
 *
 * 为什么必须做：`Travel.slug` 有唯一约束，而标题是用户自由输入的天然重复项。
 * 早先重复标题会让 prisma.create 抛 P2002，接口 500，前台只看到"创建失败"。
 * @param excludeId 编辑场景下排除自己，避免"只改了日期也被判为重复"
 */
export async function makeUniqueTravelSlug(base: string, excludeId?: number): Promise<string> {
  const taken = async (slug: string) => {
    const found = await prisma.travel.findFirst({
      where: excludeId ? { slug, id: { not: excludeId } } : { slug },
      select: { id: true },
    })
    return !!found
  }
  if (!(await taken(base))) return base
  for (let i = 2; i <= 50; i++) {
    const candidate = `${base}-${i}`
    if (!(await taken(candidate))) return candidate
  }
  // 极端情况兜底：加时间戳，几乎不可能再撞
  return `${base}-${Date.now()}`
}

/** 新建旅行时的 slug（标题 → slug → 唯一化） */
export function travelSlugBase(title: string): string {
  return makeTravelSlug(title)
}

// ============================================================
// 3.6 子资源所有权校验：判断用户是否可管理该旅行。
// 规则：直接归属（ownerId）或所属空间（spaceId）的活跃 OWNER/MEMBER。
// 与 requireCapability（角色）分层：requireCapability 拦 VIEWER，这里拦「别的空间/别人名下的内容」（IDOR）。
// ============================================================
export async function canManageTravel(travelId: number, userId: number | null | undefined): Promise<boolean> {
  if (!userId) return false
  const travel = await prisma.travel.findUnique({
    where: { id: travelId },
    select: { ownerId: true, spaceId: true },
  })
  if (!travel) return false
  if (travel.ownerId === userId) return true
  if (travel.spaceId) {
    const member = await prisma.spaceMember.findFirst({
      where: { spaceId: travel.spaceId, userId, status: 'ACTIVE', role: { in: ['OWNER', 'MEMBER'] } },
      select: { id: true },
    })
    if (member) return true
  }
  return false
}

/**
 * 封面媒体必须属于这本旅行（防"把别人的照片设成自己的封面"的 IDOR）。
 * Media 表本身没有 travelId，只能顺着「回忆 → 旅行」反查（主照片与多对多关联两条路径）。
 */
export async function assertCoverMediaBelongs(travelId: number, mediaId: number): Promise<void> {
  const media: any = await prisma.media.findUnique({
    where: { id: mediaId },
    select: {
      memory: { select: { travelId: true } },
      memoryLinks: { select: { memory: { select: { travelId: true } } } },
    },
  })
  if (!media) throw new Error('照片不存在')
  const owners: (number | null)[] = [
    media.memory?.travelId ?? null,
    ...(media.memoryLinks || []).map((l: any) => l.memory?.travelId ?? null),
  ]
  if (!owners.includes(travelId)) throw new Error('这张照片不属于该旅行')
}

/** 由天反查所属旅行 ID（子资源所有权校验用） */
export async function findTravelIdByDayId(dayId: number): Promise<number | null> {
  const day = await prisma.travelDay.findUnique({ where: { id: dayId }, select: { travelId: true } })
  return day?.travelId ?? null
}

/** 由行程项反查所属旅行 ID（子资源所有权校验用） */
export async function findTravelIdByItineraryItemId(itemId: number): Promise<number | null> {
  const item = await prisma.itineraryItem.findUnique({
    where: { id: itemId },
    select: { travelDay: { select: { travelId: true } } },
  })
  return item?.travelDay?.travelId ?? null
}

/** 由花费反查所属旅行 ID（子资源所有权校验用） */
export async function findTravelIdByExpenseId(expenseId: number): Promise<number | null> {
  const expense = await prisma.expense.findUnique({ where: { id: expenseId }, select: { travelId: true } })
  return expense?.travelId ?? null
}

