  token?: string
  username?: string
  requirePasswordChange?: boolean
  ttlSeconds?: number
  error?: string
}

export interface TokenPayload {
  username: string
  role?: string
  userId?: number
  sid?: string
}

export interface LoginMeta {
  userAgent?: string | null
  ip?: string | null
  /** 'app' 表示移动端原生壳登录，签发持久会话（免 5h 过期）；默认 'web' */
  clientType?: 'app' | 'web'
}

export const DEFAULT_SESSION_SECONDS = 5 * 60 * 60 // 5 小时（Web 默认）
export const REMEMBER_SESSION_SECONDS = 7 * 24 * 60 * 60 // 7 天（Web 记住我）
/**
 * App 会话 90 天（P1-10：原 365 天过长，设备丢失/令牌泄露的窗口过大）。
 * 客户端无需重新登录：GET /api/check-auth 会在剩余 < 30 天时静默续期（同一 sid 重签）。
 */
export const APP_SESSION_SECONDS = 90 * 24 * 60 * 60
/** App 会话静默续期阈值：剩余有效期低于该值时续期 */
export const APP_SESSION_RENEW_BEFORE_SECONDS = 30 * 24 * 60 * 60

export function hashIp(ip: string | null | undefined): string | null {
  if (!ip) return null
  return createHash('sha256').update(String(ip)).digest('hex')
}

export class AuthService {
  constructor(
    private readonly userRepo: UserRepository,
    private readonly tokenService: TokenService,
    private readonly sessionRepo: PrismaSessionRepository,
  ) {}

  async login(
    username: string,
    password: string,
    rememberMe: boolean = false,
    meta: LoginMeta = {},
  ): Promise<LoginResult> {
    await this.userRepo.initializeFromEnv()

    const user = await prisma.user.findUnique({ where: { username } })

    if (!user) {
      return { success: false, error: '用户名或密码错误' }
    }

    if (!user.passwordHash) {
      return { success: false, error: '系统尚未配置访问密码' }
    }

    const valid = await verifyPassword(password, user.passwordHash)
    if (!valid) {
      return { success: false, error: '用户名或密码错误' }
    }

    const ttlSeconds = meta.clientType === 'app'
      ? APP_SESSION_SECONDS
      : rememberMe ? REMEMBER_SESSION_SECONDS : DEFAULT_SESSION_SECONDS
    const sid = randomUUID()
    const expiresAt = new Date(Date.now() + ttlSeconds * 1000)

    await this.sessionRepo.create({
      id: sid,
      username: user.username,
      userId: user.id,
      expiresAt,
      userAgent: meta.userAgent ?? null,
      ipHash: hashIp(meta.ip),
    })

    const token = await this.tokenService.sign(
      { username: user.username, role: 'admin', userId: user.id, sid },
      ttlSeconds,
    )

    return {
      success: true,
      token,
      username: user.username,
      requirePasswordChange: user.requirePasswordChange,
      ttlSeconds,
    }
  }

  /**
   * 注册新账号（内测开放注册）：用户名唯一，注册成功即自动登录。
   */
  async register(
    username: string,
    password: string,
    rememberMe: boolean = false,
    meta: LoginMeta = {},
  ): Promise<LoginResult> {
    const name = String(username || '').trim()
    if (!/^[\w\u4e00-\u9fa5]{2,20}$/.test(name)) {
      return { success: false, error: '用户名需为 2-20 位中文/字母/数字/下划线' }
    }
    // 密码策略统一（P1-12）：与 setup/重置/改密同一套规则（≥8 + 弱口令黑名单）
    const passwordCheck = validatePassword(password)
    if (!passwordCheck.valid) {
      return { success: false, error: passwordCheck.message }
    }

    const exists = await prisma.user.findUnique({ where: { username: name } })
    if (exists) {
      return { success: false, error: '该用户名已被注册' }
    }

    const passwordHash = await hashPassword(password)
    let user
    for (let attempt = 0; attempt < 5; attempt++) {
      try {
        const accountId = generateAccountIdForUser({ username: name })
        user = await prisma.user.create({
          data: { username: name, passwordHash, requirePasswordChange: false, accountId },
        })
        break
      } catch (e: any) {
        if (e && e.code === 'P2002') {
          const exists = await prisma.user.findUnique({ where: { username: name } })
          if (exists) return { success: false, error: '该用户名已被注册' }
          continue
        }
        return { success: false, error: '注册失败，请稍后重试' }
      }
    }
    if (!user) return { success: false, error: '注册失败，请稍后重试' }

    const ttlSeconds = meta.clientType === 'app'
      ? APP_SESSION_SECONDS
      : rememberMe ? REMEMBER_SESSION_SECONDS : DEFAULT_SESSION_SECONDS
    const sid = randomUUID()
    const expiresAt = new Date(Date.now() + ttlSeconds * 1000)

    await this.sessionRepo.create({
      id: sid,
      username: user.username,
      userId: user.id,
      expiresAt,
      userAgent: meta.userAgent ?? null,
      ipHash: hashIp(meta.ip),
    })

    const token = await this.tokenService.sign(
      { username: user.username, role: 'admin', userId: user.id, sid },
      ttlSeconds,
    )

    return {
      success: true,
      token,
      username: user.username,
      requirePasswordChange: false,
      ttlSeconds,
    }
  }

  /**
   * App 会话静默续期（P1-10）：同一 sid 重新签发 JWT，并同步延长数据库会话有效期。
   * 返回 null 表示会话已失效/被撤销（调用方不应续期）。
   * 只改有效期，**不新建 sid**：这样设备列表里仍是一条会话，撤销语义不变。
   */
  async renewSession(sid: string, ttlSeconds: number): Promise<string | null> {
    const session = await this.sessionRepo.findById(sid)
    if (!session) return null
    if (session.revokedAt) return null
    if (session.expiresAt.getTime() <= Date.now()) return null

    const expiresAt = new Date(Date.now() + ttlSeconds * 1000)
    await this.sessionRepo.extendExpiry(sid, expiresAt)
    return this.tokenService.sign(
      {
        username: session.username,
        role: 'admin',
        ...(session.userId ? { userId: session.userId } : {}),
        sid,
      },
      ttlSeconds,
    )
  }

  async verifyToken(token: string): Promise<TokenPayload | null> {
    return this.tokenService.verify(token)
  }

  async verifyTokenWithoutBlacklist(token: string): Promise<TokenPayload | null> {
    return this.tokenService.verifyWithoutBlacklist(token)
  }

  async logout(token: string): Promise<void> {
    const payload = await this.tokenService.verifyWithoutBlacklist(token)
    if (payload?.sid) {
      await this.sessionRepo.revoke(payload.sid)
    }
    await this.tokenService.blacklistToken(token)
  }

  async sendResetCode(email: string, ip?: string | null): Promise<{ success: boolean; error?: string; remainingSeconds?: number; delivered?: boolean }> {
    if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      return { success: false, error: '请输入有效的邮箱地址' }
    }

    // B11：按邮箱精确定位用户（旧实现读「首用户的设置」，非首用户永远无法找回密码）
    const user = await this.userRepo.findByEmail(email)
    if (!user) {
      return { success: false, error: '该邮箱未绑定账号' }
    }

    if (!user.emailVerified) {
      return { success: false, error: '该邮箱未验证，请联系管理员' }
    }

    const status = await getResetCodeStatus(email)
    if (!status.canSend) {
      return { success: false, error: `请在 ${status.remainingSeconds} 秒后重试`, remainingSeconds: status.remainingSeconds }
    }

    const code = generateVerificationCode()
    await storeResetCode(email, code, ip ? hashIp(ip) : null)

    // 验证码不回显给客户端；未配置 SMTP 时仅写入服务端日志
    const delivered = await sendMail(
      email,
      '【甜途】密码重置验证码',
      `您的验证码是 ${code}，5 分钟内有效。`
    )
    return { success: true, delivered }
  }

  async verifyResetCode(email: string, code: string): Promise<{ success: boolean; error?: string }> {
    if (!email || !code || code.length !== 6) {
      return { success: false, error: '参数错误' }
    }

    const user = await this.userRepo.findByEmail(email)
    if (!user) {
      return { success: false, error: '该邮箱未绑定账号' }
    }

    const valid = await verifyResetCode(email, code)
    if (!valid) {
      return { success: false, error: '验证码错误或已过期' }
    }

    return { success: true }
  }

  async resetPassword(email: string, code: string, newPassword: string): Promise<{ success: boolean; error?: string }> {
    if (!email || !code || code.length !== 6) {
      return { success: false, error: '参数错误' }
    }

    const passwordCheck = validatePassword(newPassword)
    if (!passwordCheck.valid) {
      return { success: false, error: passwordCheck.message }
    }

    // B11：按邮箱精确定位用户；只改这一个人的密码（旧实现改的是「首用户」）
    const user = await this.userRepo.findByEmail(email)
    if (!user) {
      return { success: false, error: '该邮箱未绑定账号' }
    }

    const valid = verifyResetCode(email, code)
    if (!valid) {
      return { success: false, error: '验证码错误或已过期' }
    }

    const passwordHash = await hashPassword(newPassword)
    await this.userRepo.updatePasswordById(user.id, passwordHash)

    await consumeResetCode(email)

    // 密码重置后撤销该账号全部会话，强制重新登录
    await this.sessionRepo.revokeAllForUser(user.username)

    return { success: true }
  }

}

import { getPostService, getMomentService, getLikeService } from '../container'
import { findProvinceByLocation } from '../province-map'
import { prisma } from '../db'
import { scopedWhere } from '../visibility'
import { getTravelArchiveStats } from '../modules/travel/travel-stats'

export interface DashboardStats {
  provinceStats: Array<{ name: string; count: number }>
  provincesVisitedCount: number
  travelCount: number
  totalPhotos: number
  /** 城市去重口径（与「我的」页一致） */
  placeCount: number
  momentCount: number
  totalLikes: number
  travelPosts: any[]
  /** 多元场景：旅行类型分布（独旅/情侣/家庭/朋友/闺蜜/结伴） */
  travelTypeStats: Array<{ type: string; count: number }>
}

/**
 * 数据看板统计。
 *
 * ⚠️ 口径（R3 统一）：`travelCount` / `totalPhotos` / 省份分布**不再自己读 `Post(type='travel')`**，
 * 而是走 `lib/modules/travel/travel-stats.ts` —— 与「我的」页同一份事实源。
 *
 * 为什么必须改：两处原先各读一张表（这里读旧文章、/api/me 读 Travel），
 * 于是同一批旅行在「我的」显示 0、在「数据看板」显示 4，用户直接反馈"统计都是 0/对不上"。
 */
export async function getDashboardStats(userId?: number | null): Promise<DashboardStats> {
  const momentService = getMomentService()
  const likeService = getLikeService()

  let travelPosts: any[] = []
  let momentCount = 0
  let totalLikes = 0
  try {
    ;[travelPosts, { total: momentCount }, totalLikes] = await Promise.all([
      postServiceListFor(userId),
      momentService.getMoments(1, 1, userId),
      likeService.getTotalCount(),
    ] as const)
  } catch (e) {
    console.error('[Dashboard] 数据获取失败，使用空数据渲染:', e)
  }

  // 统一口径的统计（Travel 为主，旧文章兜底）
  let archive = { travelCount: 0, placeCount: 0, photoCount: 0, provinceCount: 0 }
  let provinceStats: Array<{ name: string; count: number }> = []
  if (userId) {
    try {
      archive = await getTravelArchiveStats(userId)
      // 省份分布：按 unified 口径的旅行 location 聚合
      const provinceCounts = new Map<string, { name: string; count: number }>()
      for (const post of travelPosts) {
        if (!post.location) continue
        const province = findProvinceByLocation(post.location)
        if (!province) continue
        const existing = provinceCounts.get(province.id)
        if (existing) existing.count += 1
        else provinceCounts.set(province.id, { name: province.name, count: 1 })
      }
      provinceStats = Array.from(provinceCounts.values()).sort((a, b) => b.count - a.count)
    } catch (e) {
      console.error('[Dashboard] 统计口径失败，降级为空:', e)
    }
  }

  // 多元场景：从 Travel 模型统计旅行类型分布（新模型才有 travelType）
  let travelTypeStats: Array<{ type: string; count: number }> = []
  try {
    const grouped = await prisma.travel.groupBy({
      by: ['travelType'],
      where: { ...scopedWhere(userId, 'ownerId') } as any,
      _count: { _all: true },
    })
    travelTypeStats = (grouped as any[])
      .filter((g) => g.travelType)
      .map((g) => ({ type: g.travelType, count: g._count._all }))
      .sort((a, b) => b.count - a.count)
  } catch (e) {
    console.error('[Dashboard] 旅行类型统计失败，降级为空:', e)
  }

  return {
    provinceStats,
    provincesVisitedCount: archive.provinceCount,
    travelCount: archive.travelCount,
    totalPhotos: archive.photoCount,
    placeCount: archive.placeCount,
    momentCount,
    totalLikes,
    travelPosts,
    travelTypeStats,
  }
}

/**
 * 看板里的"旅行列表"仍走 `getPostsHybrid`（旧文章），用于下面的列表渲染。
 * 但**统计数字不从这里取** —— 那是上面 `getTravelArchiveStats` 的职责。
 * 拆成独立函数是为了让"列表"与"统计"两种用途一眼可辨，避免下次又混用。
 */
async function postServiceListFor(userId?: number | null): Promise<any[]> {
  const postService = getPostService()
  return postService.getPostsHybrid('travel', userId)
}

import { randomUUID } from 'crypto'
import path from 'path'
import TurndownService from 'turndown'
import mammoth from 'mammoth'
import { MarkdownRenderer } from '../infrastructure/markdown'

export interface LintIssue {
  severity: 'error' | 'warn' | 'info'
  field: string
  message: string
}

export interface EmbeddedImage {
  name: string
  buffer: Buffer
  mimeType: string
}

export interface ImportedDocument {
  title: string
  slug: string
  date: string
  content: string
  tags: string[]
  description?: string
  cover?: string
  frontMatter: Record<string, any>
  embeddedImages: EmbeddedImage[]
  issues: LintIssue[]
  isValid: boolean
}

const ALLOWED_EXTENSIONS = ['md', 'markdown', 'txt', 'html', 'htm', 'docx']
const REJECTED_EXTENSIONS = ['doc']
const SLUG_REGEX = /^[a-z0-9-]+$/

export class DocumentImportService {
  constructor(
    private readonly markdownRenderer: MarkdownRenderer,
  ) {}

  async import(file: { name: string; buffer: Buffer; mimeType: string }): Promise<ImportedDocument> {
    const ext = path.extname(file.name).slice(1).toLowerCase()

    if (REJECTED_EXTENSIONS.includes(ext)) {
      throw new Error(`不支持的文件格式: .${ext}，请转换为 .docx 后再导入`)
    }

    if (!ALLOWED_EXTENSIONS.includes(ext)) {
      throw new Error(`不支持的文件格式: .${ext}`)
    }

    const markdownContent = await this.convertToMarkdown(ext, file)
    const { data: frontMatter, content: bodyContent } = this.markdownRenderer.extractFrontMatter(markdownContent)

    const h1Guess = this.extractFirstH1(bodyContent)
    const baseName = path.basename(file.name, path.extname(file.name))

    const title = (frontMatter.title as string) || h1Guess || baseName
    const slug = (frontMatter.slug as string) || this.generateSlug(title)
    const date = (frontMatter.date as string) || new Date().toISOString()
    const tags = Array.isArray(frontMatter.tags) ? frontMatter.tags : []
    const description = frontMatter.description as string | undefined
    const cover = frontMatter.cover as string | undefined

    const embeddedImages: EmbeddedImage[] = []

    const issues = await this.lint(bodyContent, { title, slug, date })
    const isValid = !issues.some(i => i.severity === 'error')

    return {
      title,
      slug,
      date,
      content: bodyContent,
      tags,
      description,
      cover,
      frontMatter,
      embeddedImages,
      issues,
      isValid,
    }
  }

  private async convertToMarkdown(ext: string, file: { buffer: Buffer }): Promise<string> {
    switch (ext) {
      case 'md':
      case 'markdown':
      case 'txt':
        return file.buffer.toString('utf-8')

      case 'html':
      case 'htm': {
        const html = file.buffer.toString('utf-8')
        const turndown = new TurndownService({
          headingStyle: 'atx',
          codeBlockStyle: 'fenced',
        })
        return turndown.turndown(html)
      }

      case 'docx': {
        const result = await mammoth.convertToHtml({
          arrayBuffer: file.buffer.buffer as ArrayBuffer,
        })
        const turndown = new TurndownService({
          headingStyle: 'atx',
          codeBlockStyle: 'fenced',
        })
        return turndown.turndown(result.value)
      }

      default:
        throw new Error(`不支持的文件格式: .${ext}`)
    }
  }

  private async lint(
    content: string,
    meta: { title: string; slug: string; date: string }
  ): Promise<LintIssue[]> {
    const issues: LintIssue[] = []

    if (!SLUG_REGEX.test(meta.slug)) {
      issues.push({
        severity: 'error',
        field: 'slug',
        message: 'Slug 只能包含小写字母、数字和连字符',
      })
    }

    const h1Count = this.countH1(content)
    if (h1Count > 1) {
      issues.push({
        severity: 'error',
        field: 'content',
        message: `H1 标题数量为 ${h1Count}，建议只保留一个`,
      })
    }

    if (h1Count === 0) {
      issues.push({
        severity: 'warn',
        field: 'content',
        message: '未检测到 H1 标题',
      })
    }

    const jumps = this.detectHeadingJumps(content)
    if (jumps.length > 0) {
      issues.push({
        severity: 'warn',
        field: 'content',
        message: `检测到标题层级跳级: ${jumps.join(', ')}`,
      })
    }

    const unlabeled = this.countUnlabeledCodeBlocks(content)
    if (unlabeled > 0) {
      issues.push({
        severity: 'warn',
        field: 'content',
        message: `${unlabeled} 个代码块未标注语言（\`\`\` 后缺少语言标识）`,
      })
    }

    const wordCount = this.countBodyWords(content)
    if (wordCount < 100) {
      issues.push({
        severity: 'warn',
        field: 'content',
        message: `内容字数不足 100 字（当前约 ${wordCount} 字）`,
      })
    }

    return issues
  }

  private extractFirstH1(content: string): string | undefined {
    const lines = content.split('\n')
    const inCodeBlock = { value: false }
    for (const line of lines) {
      if (line.trim().startsWith('```')) {
        inCodeBlock.value = !inCodeBlock.value
        continue
      }
      if (inCodeBlock.value) continue
      const m = line.match(/^#\s+(.+)$/)
      if (m) return m[1].trim()
    }
    return undefined
  }

  private countH1(content: string): number {
    const lines = content.split('\n')
    let count = 0
    const inCodeBlock = { value: false }
    for (const line of lines) {
      if (line.trim().startsWith('```')) {
        inCodeBlock.value = !inCodeBlock.value
        continue
      }
      if (inCodeBlock.value) continue
      if (/^#\s+/.test(line)) count++
    }
    return count
  }

  private detectHeadingJumps(content: string): string[] {
    const lines = content.split('\n')
    const jumps: string[] = []
    let prevLevel = 0
    const inCodeBlock = { value: false }
    for (const line of lines) {
      if (line.trim().startsWith('```')) {
        inCodeBlock.value = !inCodeBlock.value
        continue
      }
      if (inCodeBlock.value) continue
      const m = line.match(/^(#{1,6})\s/)
      if (m) {
        const level = m[1].length
        if (prevLevel > 0 && level > prevLevel + 1) {
          jumps.push(`H${prevLevel} → H${level}`)
        }
        prevLevel = level
      }
    }
    return jumps
  }

  private countUnlabeledCodeBlocks(content: string): number {
    const lines = content.split('\n')
    let count = 0
    const inCodeBlock = { value: false }
    for (const line of lines) {
      const trimmed = line.trim()
      if (trimmed.startsWith('```')) {
        if (!inCodeBlock.value) {
          const lang = trimmed.replace(/^```/, '').trim()
          if (lang.length === 0) count++
        }
        inCodeBlock.value = !inCodeBlock.value
      }
    }
    return count
  }

  private countBodyWords(content: string): number {
    const stripped = content
      .replace(/```[\s\S]*?```/g, '')
      .replace(/`[^`]*`/g, '')
      .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
      .replace(/\[[^\]]*\]\([^)]*\)/g, '')
      .replace(/^#+\s*/gm, '')
      .replace(/[*_~`>-]/g, '')
      .replace(/\s+/g, ' ')
      .trim()

    const chineseChars = (stripped.match(/[\u4e00-\u9fa5]/g) || []).length
    const englishWords = stripped
      .replace(/[\u4e00-\u9fa5]/g, ' ')
      .split(/\s+/)
      .filter((w) => w.length > 0).length

    return chineseChars + englishWords
  }

  private generateSlug(title: string): string {
    const base = title
      .toLowerCase()
      .trim()
      .replace(/[\u4e00-\u9fa5]+/g, (m) => {
        return Array.from(m).map(() => '').join('')
      })
      .replace(/[^a-z0-9\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-')
      .replace(/^-|-$/g, '')

    const suffix = randomUUID().slice(0, 6)

    if (base.length === 0) {
      return `post-${suffix}`
    }

    return `${base}-${suffix}`
  }
}

import { prisma } from '../db'
import { ImageRepository } from '../repositories/image-repository'
import { PostRepository, UpdatePostInput } from '../repositories/post-repository'
import {
  validateAndSanitizeImage,
  MAX_IMAGE_COUNT,
} from '../infrastructure/media-validation'

export interface ImageFile {
  name: string
  buffer: Buffer
  mimeType: string
}

/**
 * 媒体操作的执行者（P0-4）。
 *
 * 为什么必须显式传入：POST /api/upload 原先只校验「已登录」，postId 直接进服务层，
 * 于是任意登录用户都能给**别人的文章**塞图（IDOR），也能凭 /api/images/N 删别人的图。
 * 归属校验放在服务层（而不是只靠路由），后续任何新调用方都躲不过。
 */
export interface MediaActor {
  /** 当前登录用户 id（匿名不该走到写路径，类型上允许以便统一判权） */
  userId: number | null | undefined
  /** 站点主人：可管理全站图片；其他用户只能管自己文章下的图 */
  isSiteOwner: boolean
}

/**
 * 统一的媒体权限错误。
 *
 * 调用方把它映射成 403（写）或 404（读/删）——**绝不能在响应里区分
 * 「图片不存在」与「图片不属于你」**，否则等于给攻击者一个存在性探测接口。
 */
export class MediaAccessError extends Error {
  constructor(message = '无权操作该图片') {
    super(message)
    this.name = 'MediaAccessError'
  }
}

/** actor 能否管理某篇文章下的图片：站长，或文章作者本人 */
function canManagePost(postOwnerId: number | null | undefined, actor: MediaActor | undefined): boolean {
  if (!actor) return true // 兼容：未传 actor 的旧调用方（admin 导入发布路由）保持原行为
  if (actor.isSiteOwner) return true
  if (actor.userId == null) return false
  // 历史数据 userId 为空（schema 注释：归首个管理员）时只有站长能动
  return postOwnerId != null && postOwnerId === actor.userId
}

/**
 * 读取文章归属（不受可见性过滤）。
 *
 * 为什么不复用 PostRepository.findById：它的 select 里**没有 userId**
 * （mapPostMeta 会永远拿到 null），拿不到归属就没法判权。这里只查一列。
 */
async function findPostOwnerId(postId: number): Promise<number | null | undefined> {
  const post = await prisma.post.findUnique({
    where: { id: postId },
    select: { userId: true },
  })
  return post ? post.userId ?? null : undefined
}

export class ImageService {
  constructor(
    private readonly imgRepo: ImageRepository,
    private readonly postRepo: PostRepository,
  ) {}

  async upload(postId: number, files: ImageFile[], actor?: MediaActor): Promise<{ urls: string[] }> {
    if (!files || files.length === 0) {
      throw new Error('未上传任何文件')
    }
    if (files.length > MAX_IMAGE_COUNT) {
      throw new Error(`单次最多上传 ${MAX_IMAGE_COUNT} 张图片`)
    }

    const post = await this.postRepo.findById(postId)
    if (!post) {
      // 与「不是你的文章」同错：不泄露 postId 是否存在
      throw new MediaAccessError('文章不存在或无权限')
    }

    // P0-4 归属校验，必须在写任何数据之前：否则任意登录用户可给他人文章塞图
    if (actor) {
      const ownerId = await findPostOwnerId(postId)
      if (!canManagePost(ownerId, actor)) {
        throw new MediaAccessError('文章不存在或无权限')
      }
    }

    // 逐张校验 + 重新编码（剥离元数据），任一失败则整体拒绝
    const sanitized: Array<{ buffer: Buffer; mimeType: string }> = []
    for (const file of files) {
      try {
        const result = await validateAndSanitizeImage(file.buffer, file.mimeType)
        sanitized.push({ buffer: result.buffer, mimeType: result.mimeType })
      } catch (err: any) {
        throw new Error(`${file.name}: ${err.message}`)
      }
    }

    const createdIds: number[] = []

    for (let i = 0; i < sanitized.length; i++) {
      const file = sanitized[i]
      const maxOrder = await this.imgRepo.getMaxOrder(postId)
      const nextOrder = maxOrder + 1
      const result = await this.imgRepo.create(postId, file.buffer, file.mimeType, nextOrder)
      createdIds.push(result.id)
    }

    let existingIds: number[] = []
    const postDetail = await this.postRepo.findById(postId)
    if (postDetail && postDetail.images) {
      try {
        const parsed = postDetail.images
        existingIds = parsed
          .map((v: string) => {
            const match = v.match(/\/api\/images\/(\d+)/)
            return match ? parseInt(match[1], 10) : NaN
          })
          .filter((v: number) => !isNaN(v))
      } catch {}
    }

    const allIds = [...existingIds, ...createdIds]

    const needCoverUpdate =
      !postDetail?.cover ||
      postDetail.cover === '' ||
      postDetail.cover.startsWith('/uploads/')

    const updateData: UpdatePostInput = {
      images: allIds.map(id => `/api/images/${id}`),
    }
    if (needCoverUpdate && allIds.length > 0) {
      updateData.cover = `/api/images/${allIds[0]}`
    }

    await this.postRepo.update(postId, updateData)

    const urls = createdIds.map(id => `/api/images/${id}`)
    return { urls }
  }

  async delete(url: string, actor?: MediaActor): Promise<void> {
    if (!url || !url.startsWith('/api/images/')) {
      throw new Error('无效的资源路径')
    }

    const imageId = parseInt(url.replace('/api/images/', ''), 10)
    if (isNaN(imageId)) {
      throw new Error('无效的图片 ID')
    }

    const image = await this.imgRepo.findById(imageId)
    if (!image) {
      throw new Error('图片不存在')
    }

    const postId = image.postId

    /**
     * P0-4：删除前先校验归属（原先任何登录用户都能凭 URL 删任何人的图）。
     * 无权与不存在抛同一个错误，由路由映射 404，不给存在性探测。
     */
    if (actor) {
      const ownerId = await findPostOwnerId(postId)
      if (!canManagePost(ownerId, actor)) {
        throw new MediaAccessError('图片不存在或无权限')
      }
    }

    await this.imgRepo.delete(imageId)

    const remaining = await this.imgRepo.findByPostId(postId)
    const remainingIds = remaining.map(r => r.id)

    const post = await this.postRepo.findById(postId)
    if (post) {
      const newCover = post.cover === url
        ? (remainingIds.length > 0 ? `/api/images/${remainingIds[0]}` : undefined)
        : post.cover

      await this.postRepo.update(postId, {
        images: remainingIds.map(id => `/api/images/${id}`),
        cover: newCover,
      })
    }
  }
}

import { MomentRepository, MomentRecord } from '../repositories/moment-repository'
import { CacheService } from '../infrastructure/cache'
import { checkContent } from '../modules/content/policy'
import { recordSyncTombstone } from '../api/sync-tombstone'

export interface MomentDTO {
  id: number
  content: string
  tags: string[] | null
  createdAt: string
  updatedAt: string
  userId: number | null
  isPublic: boolean
}

export interface MomentPage {
  data: MomentDTO[]
  total: number
  page: number
  pageSize: number
  hasMore: boolean
}

export class MomentService {
  private readonly CACHE_TTL = 120

  constructor(
    private readonly momentRepo: MomentRepository,
    private readonly cache: CacheService,
  ) {}

  async getMoments(page: number = 1, pageSize: number = 20, userId?: number | null): Promise<MomentPage> {
    const cacheKey = `moments:${page}:${pageSize}:u${userId ?? 'anon'}`
    const cached = await this.cache.get<MomentPage>(cacheKey)
    if (cached) return cached

    const result = await this.momentRepo.list(page, pageSize, userId)
    const pageData: MomentPage = {
      data: result.data,
      total: result.total,
      page,
      pageSize,
      hasMore: result.hasMore,
    }
    await this.cache.set(cacheKey, pageData, this.CACHE_TTL, ['moments'])
    return pageData
  }

  async getRecentMoments(limit: number = 10, userId?: number | null): Promise<MomentDTO[]> {
    const cacheKey = `moments:recent:${limit}:u${userId ?? 'anon'}`
    const cached = await this.cache.get<MomentDTO[]>(cacheKey)
    if (cached) return cached

    const result = await this.momentRepo.list(1, limit, userId)
    await this.cache.set(cacheKey, result.data, this.CACHE_TTL, ['moments'])
    return result.data
  }

  async createMoment(content: string, tags: string[] | null, userId?: number | null, isPublic?: boolean): Promise<{ id: number }> {
    const trimmed = content.trim()
    // v3.1 M3-B3：统一内容策略（长度/敏感词/外链限制）
    const check = checkContent(trimmed, { maxLength: 2000, maxLinks: 0 })
    if (!check.ok) {
      throw new Error(check.reason || '内容不合法')
    }
    const result = await this.momentRepo.create(trimmed, tags, userId, isPublic)
    await this.invalidateCache()
    return result
  }

  async deleteMoment(id: number, userId?: number | null): Promise<void> {
    const existing = await this.momentRepo.findById(id, userId)
    if (!existing) {
      throw new Error('记录不存在')
    }
    await this.momentRepo.delete(id)
    // B4：删除墓碑（best-effort）—— 供 GET /api/sync/changes 下发，客户端删本地行
    await recordSyncTombstone('Moment', id, userId ?? null)
    await this.invalidateCache()
  }

  private async invalidateCache(): Promise<void> {
    await this.cache.deleteByTag('moments')
  }
}

import { PhotoMessageRepository, PhotoMessageRecord } from '../repositories/photo-message-repository'
import { CacheService } from '../infrastructure/cache'

export interface PhotoMessageDTO {
  id: number
  imageKey: string
  content: string
  createdAt: string
}

const MAX_CONTENT_LENGTH = 500

export class PhotoMessageService {
  private readonly CACHE_TTL = 30

  constructor(
    private readonly repo: PhotoMessageRepository,
    private readonly cache: CacheService,
  ) {}

  /** 每一张照片独立一套聊天记录，按 imageKey 隔离 */
  async getMessages(imageKey: string, userId?: number | null): Promise<PhotoMessageDTO[]> {
    const key = normalizeKey(imageKey)
    const cacheKey = `photo-msg:${key}:u${userId ?? 'anon'}`
    const cached = await this.cache.get<PhotoMessageDTO[]>(cacheKey)
    if (cached) return cached

    const messages = await this.repo.listByImage(key, 500, userId)
    await this.cache.set(cacheKey, messages, this.CACHE_TTL, ['photo-msg'])
    return messages
  }

  async addMessage(imageKey: string, content: string, userId?: number | null, isPublic?: boolean): Promise<PhotoMessageDTO> {
    const key = normalizeKey(imageKey)
    const trimmed = content.trim()
    if (!trimmed) throw new Error('留言内容不能为空')
    if (trimmed.length > MAX_CONTENT_LENGTH) {
      throw new Error(`留言过长（最多 ${MAX_CONTENT_LENGTH} 字）`)
    }

    const result = await this.repo.create(key, trimmed, userId, isPublic)
    await this.cache.deleteByTag('photo-msg')

    return {
      id: result.id,
      imageKey: key,
      content: trimmed,
      createdAt: new Date().toISOString(),
    }
  }
}

function normalizeKey(imageKey: string): string {
  const trimmed = (imageKey || '').trim()
  if (!trimmed) throw new Error('缺少图片标识')
  return trimmed.length > 500 ? trimmed.slice(0, 500) : trimmed
}

import { revalidatePath } from 'next/cache'
import { PostRepository, type FindAllParams, type PaginatedResult, type CreatePostInput, type UpdatePostInput, type PostMetaDB, type PostDB, type VideoInfo } from '../repositories/post-repository'
import { unpublishPublicPost, sharePostToCircle, unsharePost } from '../modules/social/travel-post.service'
import { CacheService } from '../infrastructure/cache'
import { MarkdownRenderer, type TocItem } from '../infrastructure/markdown'
import { prisma } from '../db'

export interface PostDTO {
  id: number
  slug: string
  title: string
  date: string
  description?: string
  cover?: string
  images: string[]
  videos: VideoInfo[]
  tags: string[]
  location?: string
  type: string
  published: boolean
}

export interface PostDetailDTO extends PostDTO {
  content: string
  contentHtml: string
  readMinutes: number
  toc: TocItem[]
}

export class PostService {
  private readonly CACHE_TTL = 300

  constructor(
    private readonly postRepo: PostRepository,
    private readonly cache: CacheService,
    private readonly markdownRenderer?: MarkdownRenderer,
  ) {}

  async getPublishedPosts(
    type: string,
    filters: { page?: number; pageSize?: number; search?: string; location?: string },
    userId?: number | null
  ): Promise<PaginatedResult<PostMetaDB>> {
    const cacheKey = `posts:${type}:${JSON.stringify(filters)}:u${userId ?? 'anon'}`
    const cached = await this.cache.get<PaginatedResult<PostMetaDB>>(cacheKey)
    if (cached) return cached

    const result = await this.postRepo.findAll({
      ...filters,
      type,
      published: true,
      userId,
    })

    await this.cache.set(cacheKey, result, this.CACHE_TTL, ['posts', `posts:${type}`])
    return result
  }

  async getAllPosts(type?: string, userId?: number | null): Promise<PostMetaDB[]> {
    const cacheKey = type ? `posts:all:${type}:u${userId ?? 'anon'}` : `posts:all:u${userId ?? 'anon'}`
    const cached = await this.cache.get<PostMetaDB[]>(cacheKey)
    if (cached) return cached

    const posts = type
      ? await this.postRepo.findAllByType(type, userId)
      : (await this.postRepo.findAll({ userId })).data

    // 内容管理 2.0：附带是否已分享到旅行圈（TravelPost 是否存在）
    const decorated = await this.decorateCircleShared(posts)

    await this.cache.set(cacheKey, decorated, this.CACHE_TTL, ['posts'])
    return decorated
  }

  /** 为一组文章打上「是否已分享到旅行圈」标记（admin 列表用） */
  private async decorateCircleShared(posts: PostMetaDB[]): Promise<PostMetaDB[]> {
    if (!posts || posts.length === 0) return posts
    const ids = posts.map((p) => p.id)
    const rows = await prisma.travelPost.findMany({
      where: { postId: { in: ids } },
      select: { postId: true },
    })
    const shared = new Set(rows.map((r) => r.postId))
    return posts.map((p) => ({ ...p, circleShared: shared.has(p.id) }))
  }

  async getPostBySlug(type: string, slug: string, userId?: number | null): Promise<PostDetailDTO | null> {
    const cacheKey = `post:${type}:${slug}:u${userId ?? 'anon'}`
    const cached = await this.cache.get<PostDetailDTO>(cacheKey)
    if (cached) return cached

    const post = await this.postRepo.findBySlug(type, slug, userId)
    if (!post) return null

    const dto = await this.toDetailDTO(post)
    await this.cache.set(cacheKey, dto, this.CACHE_TTL, ['posts'])
    return dto
  }

  async getPostById(id: number, userId?: number | null): Promise<PostDetailDTO | null> {
    const cacheKey = `post:id:${id}:u${userId ?? 'anon'}`
    const cached = await this.cache.get<PostDetailDTO>(cacheKey)
    if (cached) return cached

    const post = await this.postRepo.findById(id, userId)
    if (!post) return null

    const dto = await this.toDetailDTO(post)
    await this.cache.set(cacheKey, dto, this.CACHE_TTL, ['posts'])
    return dto
  }

  async getPostsByLocation(location: string, userId?: number | null): Promise<PostMetaDB[]> {
    const cacheKey = `posts:location:${location}:u${userId ?? 'anon'}`
    const cached = await this.cache.get<PostMetaDB[]>(cacheKey)
    if (cached) return cached

    const posts = await this.postRepo.findByLocation(location, userId)
    await this.cache.set(cacheKey, posts, this.CACHE_TTL, ['posts'])
    return posts
  }

  async getPostCountByType(type: string, userId?: number | null): Promise<number> {
    const cacheKey = `posts:count:${type}:u${userId ?? 'anon'}`
    const cached = await this.cache.get<number>(cacheKey)
    if (cached !== null) return cached

    const count = await this.postRepo.countByType(type, userId)
    await this.cache.set(cacheKey, count, this.CACHE_TTL, ['posts'])
    return count
  }

  async getDistinctLocations(userId?: number | null): Promise<string[]> {
    const cacheKey = `posts:locations:u${userId ?? 'anon'}`
    const cached = await this.cache.get<string[]>(cacheKey)
    if (cached) return cached

    const locations = await this.postRepo.getDistinctLocations(userId)
    await this.cache.set(cacheKey, locations, this.CACHE_TTL, ['posts'])
    return locations
  }

  async getRecentPosts(limit: number = 10, type?: string, userId?: number | null): Promise<PostMetaDB[]> {
    const cacheKey = `posts:recent:${limit}:${type || 'all'}:u${userId ?? 'anon'}`
    const cached = await this.cache.get<PostMetaDB[]>(cacheKey)
    if (cached) return cached

    const result = await this.postRepo.findAll({
      type,
      published: true,
      page: 1,
      pageSize: limit,
      userId,
    })
    const posts = result.data
    await this.cache.set(cacheKey, posts, this.CACHE_TTL, ['posts'])
    return posts
  }

  /** 按 slug 获取内容（DB-only，兼容旧调用名） */
  async getPostBySlugHybrid(type: string, slug: string, userId?: number | null): Promise<PostDetailDTO | null> {
    return this.getPostBySlug(type, slug, userId)
  }

  /** 获取某类内容（当前为旅行记录），DB-only（旧 content/ 兼容层已移除） */
  async getPostsHybrid(type: string, userId?: number | null): Promise<PostMetaDB[]> {
    const cacheKey = `posts:hybrid:${type}:u${userId ?? 'anon'}`
    const cached = await this.cache.get<PostMetaDB[]>(cacheKey)
    if (cached) return cached

    const posts = await this.postRepo.findAllByType(type, userId)
    await this.cache.set(cacheKey, posts, this.CACHE_TTL, ['posts', `posts:${type}`])
    return posts
  }

  /** 全站搜索（当前以旅行记录为主，返回最近 50 条） */
  async searchAllPosts(keyword: string, userId?: number | null): Promise<PostMetaDB[]> {
    const posts = await this.postRepo.search(keyword, 'travel', userId)
    return posts.slice(0, 50)
  }

  async createPost(input: CreatePostInput): Promise<{ id: number }> {
    const result = await this.postRepo.create(input)
    // 内容管理 2.0：isPublic 变化不再自动同步到旅行圈，改为显式「分享」动作驱动
    await this.invalidateCache(input.type)
    this.invalidateIsrCache()
    return result
  }

  async updatePost(id: number, input: UpdatePostInput): Promise<void> {
    await this.postRepo.update(id, input)
    // 内容管理 2.0：isPublic 变化不再自动同步到旅行圈，改为显式「分享」动作驱动
    if (input.type) {
      await this.invalidateCache(input.type)
    } else {
      await this.invalidateAllCache()
    }
    this.invalidateIsrCache()
  }

  /** 显式分享到旅行圈（解耦后：由文章卡片「分享」按钮驱动） */
  async shareToCircle(
    postId: number,
    opts: { travelId?: number | null; visibility?: 'PUBLIC' | 'SPACE' } = {},
  ) {
    const result = await sharePostToCircle(postId, opts)
    await this.invalidateAllCache()
    this.invalidateIsrCache()
    return result
  }

  /** 取消分享（移除旅行圈），保留文章本身 */
  async unshareToCircle(postId: number): Promise<void> {
    await unsharePost(postId)
    await this.invalidateAllCache()
    this.invalidateIsrCache()
  }

  async deletePost(id: number): Promise<void> {
    await this.postRepo.delete(id)
    await unpublishPublicPost(id).catch(() => {})
    await this.invalidateAllCache()
    this.invalidateIsrCache()
  }

  private async invalidateCache(type: string): Promise<void> {
    await this.cache.deleteByTag('posts')
    await this.cache.deleteByTag(`posts:${type}`)
  }

  private async invalidateAllCache(): Promise<void> {
    await this.cache.deleteByTag('posts')
  }

  /** 内容变更后失效 Next.js ISR 缓存，使前台页面尽快反映最新内容。 */
  private invalidateIsrCache(): void {
    try {
      revalidatePath('/')
      revalidatePath('/travel')
      revalidatePath('/album')
      revalidatePath('/travel/[slug]', 'page')
    } catch {
      // 构建期或无权调用时忽略，ISR 到期后会自动重新生成
    }
  }

  private async toDetailDTO(post: PostDB): Promise<PostDetailDTO> {
    let contentHtml = post.contentHtml
    let readMinutes = 1
    let toc: TocItem[] = []

    if (this.markdownRenderer) {
      try {
        const rendered = await this.markdownRenderer.render(post.content, { extractToc: true })
        contentHtml = rendered.html
        readMinutes = rendered.readMinutes
        toc = rendered.toc
      } catch {
      }
    }

    return {
      id: post.id,
      slug: post.slug,
      title: post.title,
      date: post.date,
      description: post.description,
      cover: post.cover,
      images: post.images ?? [],
      videos: post.videos ?? [],
      tags: post.tags ?? [],
      location: post.location,
      type: post.type,
      published: post.published,
      content: post.content,
      contentHtml,
      readMinutes,
      toc,
    }
  }
}

import { SignJWT, jwtVerify, type JWTPayload } from 'jose'
import type { TokenBlacklistRepository } from '../repositories/token-blacklist-repository'

import { resolveJwtSecret } from '../jwt-secret'

// 与 middleware 共用同一套密钥校验（占位值/长度 <32 生产直接拒绝启动，见 lib/jwt-secret.ts）
const JWT_SECRET = new TextEncoder().encode(resolveJwtSecret('token-service'))

const DEFAULT_TTL = 5 * 60 * 60 // 5 hours

export interface TokenPayload extends JWTPayload {
  username: string
  role?: string
  userId?: number
  /** Database-backed session id */
  sid?: string
}

export interface TokenServiceConfig {
  ttl?: number
  issuer?: string
}

class TokenBlacklist {
  private blacklist = new Map<string, number>()
  private maxSize = 10000

  add(tokenId: string, expireAt: number): void {
    if (this.blacklist.size >= this.maxSize) {
      this.evict()
    }
    this.blacklist.set(tokenId, expireAt)
  }

  isBlacklisted(tokenId: string): boolean {
    const expireAt = this.blacklist.get(tokenId)
    if (!expireAt) return false
    if (Date.now() > expireAt) {
      this.blacklist.delete(tokenId)
      return false
    }
    return true
  }

  remove(tokenId: string): void {
    this.blacklist.delete(tokenId)
  }

  private evict(): void {
    let oldestKey: string | null = null
    let oldestExpire = Infinity

    this.blacklist.forEach((expireAt, key) => {
      if (expireAt < oldestExpire) {
        oldestExpire = expireAt
        oldestKey = key
      }
    })

    if (oldestKey) {
      this.blacklist.delete(oldestKey)
    } else {
      const firstKey = this.blacklist.keys().next().value
      if (firstKey) {
        this.blacklist.delete(firstKey as string)
      }
    }
  }
}

const blacklist = new TokenBlacklist()

export class TokenService {
  private readonly secret: Uint8Array
  private readonly ttl: number
  private readonly issuer: string

  constructor(config: TokenServiceConfig = {}) {
    this.secret = JWT_SECRET
    this.ttl = config.ttl || DEFAULT_TTL
    this.issuer = config.issuer || 'travel-notes'
  }

  /**
   * 由服务端容器注入持久化黑名单仓库。
   * 通过注入而非构造参数，避免客户端组件（如 /admin/setup）经 auth-utils
   * 传递依赖时把 Prisma（Node 内置模块）打进浏览器包。
   */
  attachBlacklistRepository(repo: TokenBlacklistRepository): void {
    this.blacklistRepo = repo
  }

  private blacklistRepo?: TokenBlacklistRepository

  async sign(payload: Omit<TokenPayload, 'iat' | 'exp' | 'jti'>, ttlSeconds?: number): Promise<string> {
    const now = Math.floor(Date.now() / 1000)
    const tokenId = crypto.randomUUID()
    const expireAt = now + (ttlSeconds || this.ttl)

    return new SignJWT({
      ...payload,
      jti: tokenId,
    })
      .setProtectedHeader({ alg: 'HS256', typ: 'JWT' })
      .setIssuedAt(now)
      .setExpirationTime(expireAt)
      .setIssuer(this.issuer)
      .sign(this.secret)
  }

  async verify(token: string): Promise<TokenPayload | null> {
    try {
      const { payload } = await jwtVerify(token, this.secret, {
        issuer: this.issuer,
      })

      if (payload.jti) {
        const jti = payload.jti as string
        if (blacklist.isBlacklisted(jti)) {
          return null
        }
        // 内存未命中时兜底查询持久化黑名单，保证进程重启后注销仍然生效
        if (this.blacklistRepo && (await this.blacklistRepo.isBlacklisted(jti))) {
          const expireMs = typeof payload.exp === 'number' ? payload.exp * 1000 : Date.now() + DEFAULT_TTL * 1000
          blacklist.add(jti, expireMs)
          return null
        }
      }

      return payload as TokenPayload
    } catch {
      return null
    }
  }

  async verifyWithoutBlacklist(token: string): Promise<TokenPayload | null> {
    try {
      const { payload } = await jwtVerify(token, this.secret, {
        issuer: this.issuer,
      })
      return payload as TokenPayload
    } catch {
      return null
    }
  }

  async blacklistToken(token: string): Promise<void> {
    const payload = await this.verifyWithoutBlacklist(token)
    if (payload && payload.jti && payload.exp) {
      const expireMs = payload.exp as number * 1000
      blacklist.add(payload.jti as string, expireMs)
      if (this.blacklistRepo) {
        await this.blacklistRepo.add(payload.jti as string, new Date(expireMs))
      }
    }
  }

  async refresh(token: string, ttlSeconds?: number): Promise<string | null> {
    const payload = await this.verify(token)
    if (!payload) return null

    const { jti, exp, iat, ...rest } = payload
    return this.sign(rest as Omit<TokenPayload, 'iat' | 'exp' | 'jti'>, ttlSeconds)
  }

  getBlacklistStats(): { size: number } {
    return { size: (blacklist as any).blacklist.size }
  }
}

export const tokenService = new TokenService()

export async function signToken(payload: Omit<TokenPayload, 'iat' | 'exp' | 'jti'>, ttlSeconds?: number): Promise<string> {
  return tokenService.sign(payload, ttlSeconds)
}

export async function verifyToken(token: string): Promise<TokenPayload | null> {
  return tokenService.verify(token)
}

export async function blacklistToken(token: string): Promise<void> {
  return tokenService.blacklistToken(token)
}

export async function refreshToken(token: string, ttlSeconds?: number): Promise<string | null> {
  return tokenService.refresh(token, ttlSeconds)
}

import { apiUrl } from '@/lib/api-base'
import {
  RESUMABLE_CHUNK_SIZE,
  isValidUploadId,
  resumeStorageKey,
} from '@/lib/infrastructure/video-upload-shared'

/**
 * 视频断点续传客户端。
 *
 * - 5MB 分片、双并发；分片文件按索引独立落盘，乱序到达也能正确拼装。
 * - 断点记忆：localStorage 存 uploadId（按 文件名+大小+mtime 指纹），刷新/重试先查
 *   status 再续传缺失分片；服务端会话过期则自动重新 init。
 * - onProgress 汇报 (百分比, 已传字节, 总字节)，粒度 = 已完成分片。
 */
export interface ResumableUploadResult {
  url: string
  filename: string
  size: number
  mimeType: string
  transcode: 'queued' | 'skipped'
}

export interface ResumableUploadOptions {
  onProgress?: (percent: number, uploadedBytes: number, totalBytes: number) => void
  signal?: AbortSignal
}

async function jsonAction(payload: Record<string, unknown>, signal?: AbortSignal): Promise<any> {
  const res = await fetch(apiUrl('/api/admin/videos/resumable'), {
    method: 'POST',
    credentials: 'include',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
    signal,
  })
  const json = await res.json().catch(() => ({}))
  if (!res.ok) throw new Error(json?.error || `请求失败(${res.status})`)
  return json
}

export async function uploadVideoResumable(
  file: File,
  opts: ResumableUploadOptions = {},
): Promise<ResumableUploadResult> {
  const { onProgress, signal } = opts
  const fingerprint = `${file.name}:${file.size}:${file.lastModified}`
  const storageKey = resumeStorageKey(fingerprint)

  // 1. 断点恢复：先试 localStorage 里的 uploadId
  let uploadId: string | null = null
  let uploaded = new Set<number>()
  let totalChunks = 0
  const savedId = typeof localStorage !== 'undefined' ? localStorage.getItem(storageKey) : null
  if (savedId && isValidUploadId(savedId)) {
    try {
      const st = await jsonAction({ action: 'status', uploadId: savedId }, signal)
      if (st?.exists) {
        uploadId = savedId
        totalChunks = st.totalChunks
        uploaded = new Set<number>(st.uploaded || [])
      }
    } catch {
      // 会话失效，走重新 init
    }
  }

  // 2. init（无有效会话时）
  if (!uploadId) {
    const init = await jsonAction(
      { action: 'init', filename: file.name, size: file.size, mimeType: file.type || 'video/mp4' },
      signal,
    )
    uploadId = init.uploadId
    totalChunks = init.totalChunks
    uploaded = new Set()
    const newId: string = init.uploadId
    try { localStorage.setItem(storageKey, newId) } catch {}
  }
  // TS 收窄在异步闭包内失效，这里固化非空值供分片上传闭包使用
  const activeUploadId: string = uploadId as string

  const report = () => {
    const bytes = Math.min(uploaded.size * RESUMABLE_CHUNK_SIZE, file.size)
    onProgress?.(file.size === 0 ? 100 : Math.round((bytes / file.size) * 100), bytes, file.size)
  }
  report()

  // 3. 分片上传（双并发；已传分片跳过 = 断点续传）
  const pending: number[] = []
  for (let i = 0; i < totalChunks; i++) {
    if (!uploaded.has(i)) pending.push(i)
  }

  const uploadChunk = async (index: number): Promise<void> => {
    if (signal?.aborted) throw new DOMException('aborted', 'AbortError')
    const start = index * RESUMABLE_CHUNK_SIZE
    const blob = file.slice(start, Math.min(start + RESUMABLE_CHUNK_SIZE, file.size))
    const form = new FormData()
    form.append('uploadId', activeUploadId)
    form.append('index', String(index))
    form.append('chunk', blob, `${index}.part`)
    const res = await fetch(apiUrl('/api/admin/videos/resumable'), {
      method: 'POST',
      credentials: 'include',
      body: form,
      signal,
    })
    if (!res.ok) {
      const err = await res.json().catch(() => ({}))
      throw new Error(err?.error || `分片 ${index} 上传失败(${res.status})`)
    }
    uploaded.add(index)
    report()
  }

  const CONCURRENCY = 2
  let cursor = 0
  const workers = Array.from({ length: Math.min(CONCURRENCY, pending.length) }, async () => {
    while (cursor < pending.length) {
      const index = pending[cursor++]
      await uploadChunk(index)
    }
  })
  await Promise.all(workers)

  // 4. complete（拼装 + 校验 + 落盘）
  const result = await jsonAction({ action: 'complete', uploadId }, signal)
  try { localStorage.removeItem(storageKey) } catch {}
  return result as ResumableUploadResult
}

export async function abortResumableUpload(uploadId: string): Promise<void> {
  try {
    await jsonAction({ action: 'abort', uploadId })
  } catch {}
}
